INSERT INTO `books` (`id`, `api_id`, `title`, `author_name`, `category_name`, `summary`, `price`, `total_pages`, `published_date`, `tags`, `publisher`, `cover_image`, `created_at`, `updated_at`) VALUES
	(2, '678231c279bd51cee772b6e8', 'The Art of Clear Thinking', 'Patrick King', 'Self-Improvement,', 'Berpikir jernih adalah kunci untuk mencapai kebenaran, kebijaksanaan, dan pengetahuan. Namun, sering kali kita tidak bisa berpikir jernih. Kita—dan orang-orang yang memengaruhi kita dalam mengambil keputusan—jarang melihat dunia sebagaimana adanya. Kita membangun keyakinan berdasarkan asumsi, bias, dan persepsi. Akibatnya, kita menyimpulkan sesuatu tanpa berpikir panjang dan salah menilai hal, padahal seharusnya kita bisa mengambil keputusan dengan lebih baik.The Art of Clear Thinking membahas secara mendalam ilusi pikiran yang kita temui sehari-hari, dan cara meruntuhkannya. Buku ini memberikan alat untuk menghilangkan kabut dari mata kita dan berpikir secara lebih tajam. Kita akan mengetahui: • Kunci kejujuran intelektual dan hambatan terbesarnya (yang ada dalam kendali kita). • Betapa cacat serta biasnya persepsi, perspektif, dan perasaan kita. • Logika nyata dan logika palsu yang orang coba gunakan untuk membodohi kita. • Cara berpikir mandiri tanpa dipengaruhi orang lain. • Prinsip-prinsip dari beberapa pemikir terbesar dalam sejarah: Descartes, Darwin, Einstein, dan banyak lagi.Patrick King adalah penulis buku laris internasional dan pelatih keterampilan sosial. Bukunya telah terjual lebih dari 1 juta eksemplar di seluruh dunia. Tulisannya mengambil berbagai sumber, mulai dari penelitian ilmiah, pengalaman akademis, sampai pengalaman nyata.', 'Rp 79,000', '162 pages', '30 October 2024', 'Self Transformation, buku pengembangan diri, Self-Improvement, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94666/624221039.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(4, '6782320f79bd51cee772b711', 'Satu Data Polri', 'Divisi Teknologi Informasi Kepolisian NRI', 'Social Sciences', 'Di era digital yang semakin berkembang, tantangan terkait teknologi informasi bagi institusi penegak hukum seperti Polri menjadi semakin kompleks. Koordinasi antar-satuan kerja dan satuan wilayah di seluruh Indonesia memunculkan kebutuhan mendesak akan integrasi data dalam tubuh kepolisian. Dengan integrasi data, pengambilan keputusan berbasis data bisa dilakukan dengan cepat dan akurat melalui bantuan teknologi canggih seperti kecerdasan buatan (artificial intelligence).Buku ini membahas langkah strategis Polri dalam membangun sistem manajemen data yang terintegrasi. Buku ini juga menjadi saksi bagaimana Polri berupaya mempercepat transformasi digital untuk dapat menjadi organisasi yang lebih modern dan responsif. Selain itu, buku ini juga menceritakan bagaimana Polri terus berinovasi untuk mempermudah masyarakat dalam mengakses layanan publik, mulai dari kebijakan hingga infrastruktur digital.Satu Data Polri adalah langkah kecil menuju cita-cita besar dalam manajemen teknologi informasi dan komunikasi di Polri. Lewatbuku ini, Polri berkomitmen untuk menciptakan institusi yang humanis, profesional, dan presisi. Buku ini juga diharapkan menjadisumbangan pemikiran bagi masa depan institusi Polri serta kemajuan bangsa Indonesia.', 'Rp 179,000', '148 pages', '30 October 2024', 'Social Science, nonfiksi, Social Sciences', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94707/624222025.jpg', '2026-02-10 01:32:50', '2026-02-19 02:44:19'),
	(6, '678231f379bd51cee772b702', 'Rumah Kaca di Ujung Bumi', 'Kim Choyeop', 'AsianLit - Korea', 'Tahun 2058. Bumi hancur akibat serangan dust—debu beracun yang mematikan. Manusia berlindung di dalam kota-kota kubah dan berusaha bertahan hidup dengan segala cara. Kakak adik Naomi dan Amara berkelana dari satu reruntuhan kota ke reruntuhan kota lain dalam upaya mencari tempat berlindung, sampai akhirnya tiba di Frim Village, sebuah desa di tengah hutan tempat manusia hidup tanpa perlindungan kubah dan tanaman bisa tumbuh subur. Apakah keajaiban ini ada hubungannya dengan ahli botani misterius yang mendekam di rumah kaca di puncak bukit?Tahun 2129. Ah-yeong, peneliti tumbuhan di Pusat Riset Ekologi Dust, berusaha meneliti asal-usul tumbuhan merambat bernama mossvana yang mewabah di kota Haewol. Tumbuhan beracun dan konon bisa berpendar biru di tengah malam itu mengingatkan Ah-yeong pada pemandangan misterius yang pernah ia lihat di kebun tetangganya ketika ia masih kecil—kebun penuh ilalang lebat yang memancarkan cahaya kebiruan.Penelitian Ah-yeong mempertemukannya dengan Naomi yang berhasil bertahan hidup melewati Era Dust. Banyak sekali yang ingin ditanyakannya kepada Naomi. Bagaimana Naomi dan Amara berhasil bertahan hidup di luar kota kubah? Apakah Frim Village sungguh ada? Kenapa Naomi dan Amara meninggalkan desa surgawi itu? Dan benarkah mossvana yang menyelamatkan umat manusia dari kehancuran?', 'Rp 89,000', '376 pages', '30 October 2024', 'Asian Lit, Korea, Novel, AsianLit', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94692/624188002.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(7, '6782321279bd51cee772b713', 'Pembusukan Demokrasi', 'Pius Pandor, CP', 'Philosophy', 'Buku ini menawarkan argumen terkait persoalan representasi populis dan strategi politik yang kaum populis lakukan dalam mentransformasi makna rakyat, mayoritas, dan pemilihan perwakilan. Dengan menggunakan lensa diarki dan realisme politik, buku ini menyimpulkan bahwa representasi populis melanggar batas luar nilai-nilai demokrasi (kebebasan, pluralisme, dan kesamaan).“Tata politik itu dari kodratnya harus autentik dan akuntabel. Populisme dapat mengaburkan keduanya. Kepentingan buku Pius Pandor ini berada dalam domain konteks politik negeri ini yang di sana-sini didera kekaburan. Tak ayal lagi, buku ini menjadi bacaan wajib bila ingin mengembalikan politik bangsa kita ke ranah akuntabilitas dan autentisitasnya.”—Prof. Dr. FX. Armada RiyantoProfesor dalam bidang filsafat politik di STFT Widya Sasana Malang“Populisme menyajikan dilema bagi demokrasi: di satu sisi ia mendegradasi pranata politik formal, di lain sisi ia bisa mengartikulasikan general will yang menuntut perubahan. Ia sering dipakai sebagai instrumen manipulatif para autokrat, tapi sesekali ia juga muncul dalam imajinasi politik demokrasi. Buku yang ditulis Pius Pandor ini memikirkan batasbatas populisme dan memeriksa implikasinya terhadap demokrasi melalui pemikiran ahli politik dari Italia, Nadia Urbinati. Buku ini hadir di saat yang tepat untuk Indonesia, yang politiknya menjadi ladang subur kaum populis. Dimulai sebagai studi ilmu filsafat, buku ini juga sangat relevan untuk mereka yang berminat dalam ilmu politik dan sosiologi.”—Dr. Robertus RobetSosiolog Universitas Negeri Jakarta“Dua kontribusi utama buku Pius Pandor: Pertama, dari segi isi, buku ini adalah literatur politik pertama dalam bahasa Indonesia yang membahas ambivalensi populisme di tengah gemerlap proyek demokrasi. Kedua, dari segi pendekatan, buku ini adalah sebuah kajian pertama dalam bahasa Indonesia yang menggabungkan pendekatan filsafat politik (normative political theory) yang berfokus pada soal-soal normatif (das Sollen) dan ilmu politik (empirical political theory) yang berfokus pada realitas empirik politik (das Sein). Apakah penulis berhasil membedah demokrasi dengan gabungan dua disiplin ilmu yang berbeda itu? Jawabannya ada di dalam buku ini.”—Dr. Phil. Norbertus Jegalus, M.A.Alumnus Geschwister-Scholl-Institut fur Politikwissenschaft,Ludwig-Maximilian-Universitat, Munchen, Jerman“Dalam konteks Indonesia, di mana populisme semakin mengakar, buku ini menjadi referensi yang sangat relevan bagi para akademisi, praktisi politik, dan pembuat kebijakan yang ingin memahami lebih dalam fenomena populisme dan implikasinya bagi demokrasi.”—Yanuar Nugroho, Ph.D.Dosen STF Driyarkara Jakarta; Deputi II Kepala Staf Kepresidenan RI 2015–2019', 'Rp 179,000', '374 pages', '30 October 2024', 'philosophy, filsafat', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94709/624222026.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(8, '6782324b79bd51cee772b731', 'Sambal dan Ranjang (CU 2024)', 'Tenni Purwanti', 'Short Stories', 'Suamiku memiliki kebiasaan sebelum tidur. Ia harus makan malam lengkap dengan sambal cobek di atas ranjang. Aku sebetulnya agak kewalahan dengan kebiasaan ini. Tapi sebagai istri, aku harus menuruti keinginan suamiku. Istri idaman adalah perempuan yang pandai membuat sambal, begitu pernah ibuku berpesan.Aku tak pernah tahu kalau sambal juga termasuk afrodisiak. Suamiku mengaku, setiap kali melahap sambal buatanku, ia selalu ingin bercinta denganku.TENNI PURWANTI, seorang jurnalis, menghadirkan kisah-kisah perempuan dalam kumpulan cerita pendek perdananya, Sambal dan Ranjang. Tentang pergolakan perempuan, kesehatan mental, dan trauma. Cerita-ceritanya ibarat sambal, pedas, gerah, tetapi membuat ketagihan dan minta tambah.', 'Rp 89,000', '184 pages', '30 October 2024', 'Cerpen, Short Stories, Cerita Pendek, Kumpulan cerita pendek', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94739/624202029.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(9, '678231bd79bd51cee772b6e5', 'Solusi Pendanaan Usaha', 'Bonar Silalahi', 'Business & Economic', '“Salah satu tantangan dari menjadi pengusaha adalah mendapatkan pembiayaan yang cocok dari sumber yang tepat. Disajikan dengan penulisan yang mudah dipahami, buku ini dapat menjadi sumber informasi mengenai pendanaan usaha, dan dapat langsung diterapkan. Selamat menikmati perjalanan sebagai pengusaha yang tangguh, pantang menyerah, dan menjadi berkat bagi sesama, nusa, serta bangsa.”— Edwin SoeryadjayaPengusaha“Buku ini berisi siklus hidup usaha dan petunjuk bagaimana pengusaha mendanai usahanya, dari saat memulai usaha hingga memasuki tahapkorporasi. Walaupun pendanaan sangat penting, mencari pendanaan usaha sering kali menjadi hal yang memusingkan. Namun, jika Anda tahu cara mendapatkan pendanaan dari sumber yang tepat pada setiap siklus usaha,mendapatkan pendanaan bisa menjadi lebih mudah. Dari pengalamannya bertemu banyak pengusaha, Bonar menyajikan semuanya secara sederhana. Semoga berhasil dan menjadi berkat.”— Tony HambaliPengusahaDitulis berdasarkan pengalaman penulis yang bergelut dalam bidang pendanaan usaha selama 30 tahun lebih. Menjelaskanberbagai sumber pendanaan yang bisa diakses, cara menjangkaunya, serta apa saja yang perlu dipersiapkan dan dipertimbangkan pengusaha untuk mendanai usahanya.', 'Rp 139,000', '192 pages', '30 October 2024', 'Bisnis, Ekonomi, buku bisnis, Business, Business Management', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94663/624203018.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(11, '678231cf79bd51cee772b6ef', 'CoComelon: Bermain Petak Umpet', 'Moonbug Entertainment', 'Activity Books', 'Ketemu! Buku cari dan temukan penuh warna ini cocok untuk mengisi kegiatan si kecil. Ada berbagai macam benda yang bisa dicari dan dihitung, serta banyak aktivitas keren lainnya. Buku ini cocok untuk para penjelajah kecil yang ingin bermain sekaligus belajar!', 'Rp 69,000', '40 pages', '30 October 2024', 'Anak-anak, Anak, picture books, buku anak gramedia, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94673/624114013.jpg', '2026-02-10 01:32:50', '2026-02-19 11:12:52'),
	(12, '678231fa79bd51cee772b706', 'Pulau Misterius (The Mysterious Island)', 'Jules Verne', 'Classics', 'Setelah membajak balon udara dari sebuah kamp Konfederasi, lima tawanan dan seekor anjing melarikan diri dari Perang Saudara Amerika. Sekitar delapan ribu kilometer kemudian, mereka jatuh dari awan ke sebuah pulau vulkanik yang belum dipetakan di tengah Samudra Pasifik. Melalui kerja sama, rekayasa, pengetahuan ilmiah, dan tekad, mereka berusaha membangun koloni dari nol. Namun pulau yang kaya akan sumber daya ini menyimpan rahasia gelap. Kelima orang itu mendapati mereka tidak sendirian. Seseorang mengintai mereka. Seseorang yang sudah mereka kenal dan akan berperan penting dalam nasib mereka kelak.', 'Rp 199,000', '768 pages', '23 October 2024', 'Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94696/624189002.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(13, '678231f779bd51cee772b704', 'Tak Apa-Apa Jika Harus Berhenti', 'Julia Keller', 'Self-Improvement,', '“Jika Anda berpikir untuk berhenti bekerja atau bercerai, jangan—setidaknya sebelum Anda membaca buku ini.” ―Joseph T. Hallinan, jurnalis pemenang Pulitzer dan penulis buku best seller Why We Make MistakesIngin berhenti? Bagus. Belajarlah menjalani hidup tanpa rasa takut—di tempat kerja, di rumah, dalam menjalin relasi.Scottie Pippen, mantan bintang NBA, menolak untuk kembali turun ke lapangan. Pangeran Harry dan Meghan Markle keluar dari keluarga kerajaan. Jutaan orang keluar dari pekerjaan mereka untuk mencari kebahagiaan dan kesuksesan sesuai definisi mereka masing-masing. Apakah ini suatu kesalahan? Julia Keller, jurnalis pemenang Pulitzer, tidak berpendapat demikian. Dan nyatanya, bisa jadi pilihan ini justru menyelamatkan hidup Anda.Dalam buku ini, Keller membongkar mitos ketekunan sampai ke akarnya. Karena tidak selamanya tabah itu bagus. Bertahan tidak selalu membuahkan hasil. Dan berhenti malah bisa menjadi wujud cinta pada diri sendiri. Tak Apa-Apa Jika Harus Berhenti mengingatkan Anda bahwa untuk menjalani kehidupan yang bermakna dan memuaskan, Anda harus mampu berkata “tidak”— berhenti total. Anda akan mengetahui: • seni berhenti sementara; • cara memanfaatkan berhenti untuk memunculkan terobosan-terobosan penting; • mengapa Anda tidak bisa sukses jika hanya mengandalkan apa yang Anda miliki; • cara mengelola rasa bersalah dan malu.Karya ini merupakan hasil serangkaian penelitian ilmiah mutakhir dan percakapan dengan orang-orang yang telah membuat perubahan besar dalam hidup mereka. Keller membuat Anda percaya diri untuk berhenti.', 'Rp 119,000', '346 pages', '23 October 2024', 'buku pengembangan diri, Self-Improvement, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94694/624221042.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(14, '6782325279bd51cee772b735', 'Hati-hati dengan Hati (CU 2024)', 'dr. Hans Tandra', 'Diet & Health', 'Perlemakan hati (fatty liver) tidak bisa dianggap main-main, dampaknya bisa mengarah ke pengerutan atau sirosis hati (liver cirrhosis). Jaringan hati yang sudah rusak tak bisa diperbaiki lagi, yang berujung pada kanker dan kematian.Berfokus pada perlemakan hati, buku ini juga akan membahas akibat yang ditimbulkannya. Masalah di hati pun bisa berdampak pada masalah di jantung, ginjal, serangan strok, dan bahkan kanker, karena organ hati mengendalikan seluruh metabolisme tubuh manusia.Dengan mempraktikkan gaya hidup sehat yang bermula dari hati yang sehat, semua kualitas hidup yang sehat akan menjadi milik kita.', 'Rp 85,000', '160 pages', '23 October 2024', 'kesehatan, Diet & Health, Health, Healthy', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94743/624206009.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(16, '6782324e79bd51cee772b733', 'Mengendalikan Asam Urat (CU 2024)', 'dr. Hans Tandra', 'Diet & Health', 'Tak sekadar menyebabkan nyeri dan bengkak di satu bagian hingga ke seluruh tubuh, asam urat yang tak terkendali bisa berdampak ke organ tubuh lainnya serta merusak dinding pembuluh darah, yang kemudian memicu serangan jantung dan strok. Sebaliknya, penyakit lainnya pun bisa ikut menyulut naiknya asam urat, seperti gagal ginjal, diabetes, obesitas, atau kanker.Upaya mengalahkan asam urat yang tinggi harus dilakukan secara menyeluruh: melalui mengatur diet dan gaya hidup, menurunkan berat badan yang berlebihan, serta memerangi penyakit seperti diabetes, hipertensi, dan kolesterol tinggi. Fakta mengenai penyakit ini harus dipahami agar kita bisa menjadi pemenang dalam melawan penyakit ini, terbebas dari rasa nyeri, dan menikmati hidup yang sehat.', 'Rp 79,000', '124 pages', '23 October 2024', 'kesehatan, Diet & Health, Health, Healthy', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94741/624206007.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(17, '6782324d79bd51cee772b732', 'Air Kata-kata (CU 2024)', 'Sindhunata', 'Poetry', 'bukan aku tapikesepianmu yang salah(Kutukan Asu)Jika kata-kata diibaratkan air, maka sejatinya ia mengalir bebas ke berbagai arah. Seperti juga puisi-puisi di buku ini. Sindhunata menulis tentang yang suci sampai yang kotor, yang atas sampai yang bawah, yang rasional sampai yang irasional. Beberapa terdengar seperti doa, yang lain seperti sumpah serapah, lainnya lagi seperti mantra. Tidak berhenti sebagai puisi, beberapa telah beralih wahana menjadi lagu hiphop. Salah satunya berjudul “Cintamu Sepahit Topi Miring” yang telah ditonton lebih dari 8 juta viewers di Youtube.', 'Rp 89,000', '212 pages', '23 October 2024', 'puisi sindhunata, buku puisi, Kumpulan Puisi, Poetry, Puisi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94740/624202018.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(18, '6782310c79bd51cee772b687', 'Mindfulness-Based Business (English Edition)', 'Sudhamek AWS', 'Business & Economic', '“The author of this book, Sudhamek, is not only a successful businessman, he also possesses a high humanitarian social concern. This book is a fine weave between business theory and noble aspirations that form its main message.”–Ahmad Syafii Maarif“Before reading this book, I have truly believed that business and spirituality are two things that cannot be united. Like oil and water. Between the worldly and the heavenly. However, the mindfulness-based business that Sudhamek presents in this book has changed my belief— and I’m sure many others — that business and strong faith can coexist. The thought breakthrough provided in this book is crucial for everyone, especially business players.”–Andy F. Noya, Journalist and Host of Kick Andy“‘Can we conduct business without abandoning morality (religious teachings)?’, such was the question posed by Sudhamek’s father to his children. This book answers, ‘Yes’, even ‘Certainly’ or ‘Must’. Based on his experience building the Garudafood Group, Sudhamek provides tips on the steps needed to achieve it. Worth reading by practitioners as well as business management researchers.”–Prof. Boediono, Ph.D., The Eleventh Vice President of the Republic of Indonesia, 2009-2014“This book discusses the life journey of Sudhamek in building the Garudafood Group into one of the notable food and beveragecompanies in modern Indonesian business. He reveals how a business philosophy is developed and used to achieve that goal. Asthe main leader of this company, for decades he systematically implemented normative guidelines that he believes are the bestmethod called mindfulness-based business (MBB). It discusses how mindfulness practices are integrally and continuously combined in business activities, in line with moral and ethical principles. To achieve satisfaction and welfare for all stakeholders involved.”–Prof. Dorodjatun Kuntjoro-Jakti, Ph.D., Professor Emeritus, Faculty of Economics and Business, University of Indonesia“Combining business, ethical principles, and humanity is like combining fire and water. Business is like fire: pragmatic, results-driven, with strong economic motives, conquering and expanding. Ethics and humanity are like water: refreshing, providing hope and life, not solely serving economic metrics. Few entrepreneurs can skillfully handle these paradoxical elements in a balanced manner. Sudhamek can. His business approach reflects a mindful soul. A soul constantly seeking ways to ensure that his business benefits more people. A soul that does not stop at the sometimes ruthless and greedy instinct of profit-taking.”–Teddy P. Rachmat, Founder of Triputra Group“Through this book, we are taken into the thoughts and journey of Sudhamek in building Garudafood, especially in the last 19 years, with the philosophy of mindfulness-based business (MBB). It’s like being invited on a spiritual journey, reflecting on whether the rest of our lives will be spent building businesses solely chasing profits, or instead focusing on the extent of benefits and goodness we can create and share with many. Through this book, hopefully more businesses adopt the MBB philosophy, so we can leave a better world for the next generation.”–William Tanuwijaya, Founder and CEO of Tokopedia', 'Rp 259,000', '252 pages', '16 October 2024', 'Bisnis, Business Management, Business, buku bisnis, humaniora, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94568/624203012.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(19, '678231f879bd51cee772b705', 'Sekelebatan Memori Patah Hati', 'Yayasan Klub Buku Petra', 'Poetry', 'Gagasan tentang antologi puisi Bacapetra telah terlontar jauh sebelum situs sastra yang berbasis di Ruteng, Nusa Tenggara Timur ini memasuki usia kelima pada 2024. Sebagai situs sastra yang lahir dan bekerja dari “pinggiran”, perkembangan Bacapetra terbilang mengesankan. Karya-karya ditayangkan secara rutin sesuai jadwal selama lima tahun terakhir. Tanpa terputus. Para kontributor datang dari berbagai latar belakang wilayah, gender, maupun karier kepenulisan sehingga keberagaman perspektif tak perlu diragukan lagi. Mutu karya—biarlah sidang pembaca yang memutuskan—senantiasa menjadi perhatian khusus dalam setiap tayangan. Singkatnya, Bacapetra telah berada di jalur yang benar. Cita-cita para pendirinya sedikit demi sedikit mulai terwujud. Jika visi adalah gambar utuh sebuah puzzle, sebagian kepingan misi telah dikumpulkan dan ditata di tempat yang seharusnya. *Dewan Juri Antologi Bacapetra.co*', 'Rp 79,000', '232 pages', '16 October 2024', 'sastra indonesia, puisi kehidupan, sastra, buku puisi, Kumpulan Puisi, Puisi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94695/624202026.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(20, '678231f179bd51cee772b701', 'Menapak Jejak Dukungan Pemerintah dalam Pembiayaan Infrastruktur', 'Aldillah Arumandani', 'Social Sciences', '"Saya tak menyangka, 16 tahun sejak meninggalkan Pusat Pengelolaan Risiko Fiskal (PPRF), Public Private Partnership dan private financing semakin menjadi arus utama. Instrumen dukungannya juga sangat bervariasi. Saya melihat sebagian nama teman-teman di PPRF dulu menjadi bagian dari penulis buku ini, sebagian lainnya nama-nama baru, yang semoga sudah ditulari dengan daya juang dan ketangguhan mengusung inovasi pembiayaan baru. Selamat!"Rionald Silaban, Direktur Jenderal Kekayaan Negara"Saya dan rekan-rekan Kementerian Kominfo beruntung dan merasa terhormat mendapat kesempatan untuk membangun proyek infrastruktur dengan menerapkan konsep Kerja Sama Pemerintah dan Badan Usaha (KPBU) dengan skema Availability Payment. Saya juga mengucapkan terima kasih dan selamat atas kerja rekan-rekan yang mendokumentasikan pengalaman kita menjalankan proyek KPBU dalam bentuk buku." Rudiantara, Menteri Komunikasi dan Informatika (2014-2019)"Buku ini merupakan bukti bahwa pembiayaan infrastruktur di Indonesia telah mencapai tahap yang lebih matang dan berorientasi pada keberlanjutan. Sebagai bagian dari entitas yang bertanggung jawab atas proyek-proyek energi besar, saya sangat mengapresiasi Kementerian Keuangan yang terus mendorong dan memperhatikan aspek sustainability dalam pembiayaanproyek-proyek infrastruktur."Emma Sri Martini, Direktur Keuangan Pertamina"Buku ini memberikan gambaran yang jelas tentang bagaimana prinsip-prinsip keuangan yang solid dapat diterapkan dalam pengelolaan proyek infrastruktur, termasuk sektor energi. Buku ini juga menyoroti pentingnya kolaborasi antar-sektor untuk menciptakan solusi yang inovatif dan efisien."Sinthya Roesly, Direktur Keuangan PT PLN', 'Rp 219,000', '390 pages', '16 October 2024', 'Social Science, nonfiksi, Social Sciences', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94691/624222024.jpg', '2026-02-10 01:32:50', '2026-02-10 01:32:50'),
	(24, '6782323279bd51cee772b724', 'Petualangan Sukab', 'Seno Gumira Ajidarma', 'Literary', 'WASPADA!AWASI TANGAN ANDA!Saudara-saudara sebangsa dan setanah air, sebagai kelanjutan masalah penemuan tangan, diketahui bahwa ternyata banyak tangan telah dipotong, dibawa pergi, dan tidak diketahui di mana rimbanya, kecuali beberapa yang ditemukan secara kebetulan. Saudara-saudara sebangsa dan setanah air, Pemberitahuan ini disampaikan, karena tidak bisa dipastikan pemotongan tangan tersebut sudah berhenti.WASPADA! AWASI TANGAN ANDA!', 'Rp 99,000', '174 pages', '25 December 2024', 'Novel, sastra, novel sastra, sastra indonesia, Seno Gumira Ajidarma', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94726/petualangan_sukab.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(25, '6782323479bd51cee772b725', 'Nemesis #1: City of Evils', 'Lexie Xu', 'Mysteries & Thrillers', 'Pandora, server milik Yamada Graha Internet (YGnet), menyimpan data-data rahasia tentang beberapa keluarga konglomerat ternama di Indonesia. Server ini pun diincar oleh sekelompok orang. Bahkan manajer Cyber Security dan manajer HR perusahaan tersebut ikut mendalangi rencana pencurian datanya.Namun, niat jahat mereka diketahui oleh Natasha Samudra, satu-satunya senior engineer di Divisi Cyber Security. Natasha tak pernah punya teman seumur hidupnya. Kecuali satu teman online-nya, seorang hacker yang disebut sebagai G.Karena mengalami kesulitan untuk mencuri data-data dalam Pandora, sang manajer Cyber Security berusaha merekrut Natasha. Pada saat bersamaan, perusahaan mengalami pergantian manajemen. Ada empat general manager baru yang ditunjuk untuk mengawasi YGnet. Rei Yamada, selalu tampil cool dan punya daya ingat fotografis. Red Hadiputra, pintar sekaligus womanizer. Ryan Winata, agak kasar, seenaknya, dan suka menentang peraturan. Juga Rhys Gunawan, mantan penyanyi indie yang diidolakan oleh Natasha.Bersama keempat pria ini, Natasha harus menghadapi para penjahat yang ternyata lebih jahat daripada yang dia duga.', 'Rp 129,000', '472 pages', '18 December 2024', 'Thriller, Lexie Xu, Mystery & Thrillers, Thrillers, novel thriller, LexieXu, lokal', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94727/624175002.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(26, '6782323079bd51cee772b723', 'Satu Pendendam (One of Us is Back)', 'Karen M. McManus', 'Mysteries & Thrillers', 'Bayview High seakan tidak bisa dibuat tenang. Salah satu papan reklame digital di pusat kota menayangkan iklan yang menarik perhatian. SAATNYA PERMAINAN BARU, BAYVIEW. Hanya itu kata-katanya, warna merah dengan latar belakang putih bersih. Lalu selebaran dengan kalimat yang sama pun ada di mana-mana.Kemudian salah satu Kru Bayview menghilang. Permainan yang disebut di papan reklame itu menjadi urusan serius bagi anggota Kru Bayview yang lain. Permainan yang tak satu pun dari mereka mengerti aturannya. Semua orang bisa menjadi targetnya.Masalahnya, Simon selalu mengatakan hal yang benar tentang rahasia---semua pasti akan terbongkar. Dan Bayview masih punya banyak rahasia yang disembunyikan. Rahasia yang berujung pada dendam.', 'Rp 119,000', '424 pages', '11 December 2024', 'Thriller, Mystery & Thrillers, Thrillers, novel thriller, Thrilers Novel, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94725/624160008.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(27, '6782322d79bd51cee772b721', 'Bauksit Indonesia', 'Prof. Dr. Ir. Irwandy Arif, M. Sc', 'Science & Nature', 'Bauksit Indonesia memaparkan secara menyeluruh bauksit sebagai salah satu sumber daya alam yang memiliki peran esensial dalam era transisi energi. Melalui riset yang komprehensif, Penulis mampu memetakan potensi sumber daya dan cadangan bauksit yang tersedia cukup banyak di Indonesia. Dipaparkan secara lengkap pengembangan bauksit, mulai dari genesa atau pembentukan kualitas, proses penambangan, pemanfaatan, hingga pengelolaan residunya. Selain itu, pengolahan dan pemurnian bauksit menjadi alumina, serta proses lanjutan pengolahan alumina menjadi aluminium, juga dijelaskan secara terperinci.Hal lain yang dipaparkan di buku ini adalah pengolahan dan pemurnian bauksit menjadi produk yang bernilai lebih tinggi. Proses hilirisasi tersebut mampu meningkatkan nilai ekonomi bauksit serta mentransformasi bauksit menjadi produk yang lebih kompleks. Beberapa peluang emas lain terkait pengolahan dan pengembangan bauksit, antara lain:prospek peningkatan nilai tambah komoditas bauksit sangat menjanjikan, terutama melalui pengolahan bauksit menjadi alumina dan aluminium;potensi sumber daya dan cadangan bauksit di Indonesia mampu memenuhi kebutuhan bauksit, baik di tingkat nasional maupun internasional;dengan meningkatnya permintaan global terhadap aluminium yang ringan dan tahan korosi, Indonesia berpotensi menjadi pemasok penting dalam rantai pasok bauksit di dunia;menggeliatnya sektor pertambangan bauksit dapat menarik investor dan menguatkan perekonomian nasional secara keseluruhan.Buku ini menjadi referensi penting yang wajib dimiliki oleh pihak-pihak yang terlibat dalam industri pertambangan bauksit, baik sebagai landasan perencanaan strategi bisnis serta pengambilan kebijakan maupun pedoman yang bermanfaat dalam praksis.', 'Rp 299,000', '346 pages', '11 December 2024', 'Sciences & Nature, Nature, Science & Nature', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94723/624220002.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(28, '6782323a79bd51cee772b728', 'Dewa Angkara Murka', 'Aya Widjaja', 'MetroPop', 'Namanya Dewangkara Maheswara. Namun, anak buahnya sepakat mengganti namanya menjadi Dewa Angkara Murka. Selain tukang murka, dia juga suka bertitah bagai dewa. Apa pun yang diinginkan harus tercapai saat itu juga. Termasuk saat Dewang “memerintah” Mosha menjadi “pasangannya” supaya dia batal dijodohkan.Mosha awalnya menolak. Namun, undangan pernikahan dari Kyle—rekan kerja sekaligus mantan pacar—membuat hati Mosha terbakar. Selama lima tahun pacaran, Kyle bilang dia tidak percaya komitmen. Tak lama setelah putus, Kyle malah menikah. Tentu saja Mosha sakit hati.Mosha akhirnya membuat perjanjian dengan iblis—eh, Dewang. Adakah cara yang lebih jitu untuk membalas mantan selain menghadiri pernikahannya dengan membawa pasangan yang jauh lebih keren? “Kita nggak mungkin dibilang setingan karena nggak masuk akal karyawan nyuruh bosnya nemenin dia ke kondangan mantan.”', 'Rp 109,000', '416 pages', '11 December 2024', 'Romance Novels, Metropop, kisah romantis, romance novel, novel remaja, romantis, novel roman, Roman, Novel, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94730/624171011.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(29, '6782320779bd51cee772b70d', 'Saat untuk Bermurah Hati (A Time for Mercy)', 'John Grisham', 'Mysteries & Thrillers', 'Clanton, Mississippi. Tahun 1990.Jake Brigance terlibat dalam sebuah persidangan yang rumit ketika pengadilan menunjuknya sebagai pengacara untuk Drew Gamble, anak laki-laki pemalu yang berusia enam belas tahun. Drew dituduh membunuh seorang deputi setempat. Banyak orang di Clanton menginginkan persidangan yang cepat serta hukuman mati atas Drew, namun Jake mendapati ada lebih banyak cerita daripada yang terlihat dari luar. Komitmen kuat Jake untuk menyelamatkan Drew dari hukuman mati membuatnya harus mempertaruhkan kariernya, keamanan finansialnya, serta keselamatan keluarganya.', 'Rp 199,000', '752 pages', '04 December 2024', 'Thriller, Mystery & Thrillers, John Grisham, Thrillers, novel thriller', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94703/624185008.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(30, '6782323d79bd51cee772b72a', 'PATIWANGI', 'Oka Rusmini', 'Poetry', 'Dalam sajak-sajak Oka Rusmini, warna lokal mencapai perluasan karena dibangun dari akar-akar tradisi yang mencerminkan kedudukan manusia di tengah alam dan budaya tempatan. Dunia esoterik tidak hadir dalam keterasingan tetapi hadir secara meriah dan tajam karena ia tidak hanya menyajikan segi-segi eksotisme, tetapi justru mengasah kritik sosial yang mencerminkan kepedulian terhadap dunia nyata.Korrie Layun Rampan, Angkatan 2000 dalam Sastra Indonesia, 2000.Menulis bagi saya adalah semacam upacara penunda kematian. Dengan sajak, saya bisa berdialog dengan hidup. Berkompromi dan berpikir tentangnya: menyadari bahwa saya benar-benar manusia.Oka Rusmini, Prolog, 2006.', 'Rp 99,000', '250 pages', '27 November 2024', 'sastra indonesia, sastra, buku puisi, Kumpulan Puisi, Poetry, Puisi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94732/624202033.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(31, '6782323c79bd51cee772b729', 'PANDORA', 'Oka Rusmini', 'Poetry', 'Biografi tubuh inilah yang terasa dalam 40 sajak di kumpulan puisi Pandora ini. Lihatlah bagaimana ia mengurutkan sajak-sajak di buku ini. Dari mulai Ulat, Kepompong, Kupu-kupu, 1967, dan sajak-sajak yang mengeksplorasi tema anak (Embrio, Schipol, Pasha, Den Haag), hingga Rahib dan Jejak. Deretan sajak itu tampak seperti sebuah metamorfosis tubuh.Tubuh, di tangan penyair ini, keluar dan bahkan meloncat dari bentuk estetiknya. Ia memperlakukan tubuh bagai sebuah menu santapan (Di meja makan kusantap tubuhku, kuteguk air mataku—sajak “Kepompong”).Inilah ketangkasan seorang Oka. Ia menulis, memendam Bali, mencangkul masa lalu, membenturkan tradisi, meringkus pengalaman hidup, dan dengan tanpa sungkan menggasak tubuhnya sendiri demi memperoleh sebuah ars poetica. Inilah “sayap kuat” sajak-sajak Oka, penulis yang menurut saya, menjadi salah satu wakil terpenting penyair Indonesia mutakhir.Yos Rizal Suriaji, “Sebuah Menu Bernama Tubuh”, 2008.… Melalui estetika kekerasan, Pandora menyentakkan kita dari kemapanan, menyadarkan kita pada yang kita sembunyikan di bawah basa-basi, keseharian, dan menohok kemunafikan manusia (yang tega ”menanyakan warna kulit Tuhan”). Pada saat yang sama, kita juga dihadapkan pada suatu kosmologi yang menerima kekerasan sebagai bagian yang tak terpisahkan dari kehidupan itu sendiri.Sejauh manusia mampu menggali hikmah dari penderitaannya, sejauh itu pula kita siap menyantap hidangan yang disediakan oleh Oka Rusmini.Prof. Melani Budianta, ”Pandora: Sebuah Estetika Kekerasan”, majalah Tempo, 2008.', 'Rp 69,000', '96 pages', '27 November 2024', 'buku puisi, Kumpulan Puisi, Poetry, Puisi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94731/624202034.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(34, '6782323f79bd51cee772b72b', 'SAIBAN', 'Oka Rusmini', 'Poetry', 'Sebagai sebuah karya sastra, Saiban indah dinikmati dan berharga direnungi. Karya ini tak hanya sumbangan penting bagi khazanah sastra Indonesia, tapi juga berkontribusi bagi kajian sosiologi- antropologi yang berbasis budaya Bali-Hindu. Saiban mengukuhkan jejak Oka sebagai penyair kita yang karya-karyanya layak dikenal oleh para pembaca yang lebih luas, termasuk melalui karya terjemahan.Anton Kurnia, cerpenis dan esais.***Bagi umat Hindu di Bali, tradisi mebanten atau memberikan sesaji merupakan aktivitas sehari-hari. Setiap selesai memasak, orang Bali yang beragama Hindu pasti mempersembahkan sebagian hasil masakannya kepada Tuhan. Persembahan ini dikenal sebagai banten saiban atau jotan.Bagi Oka Rusmini, banten saiban pada hakikatnya bukan sesaji dalam bentuk materi, melainkan sesaji dalam arti rasa syukur yang harus dimiliki oleh setiap orang karena hari ini telah tersedia sepiring nasi untuk melanjutkan hidup. Ditulis pada kurun 2008-2014, buku puisi Saiban berbicara banyak hal tentang cinta, hidup yang berdenyut, dan menawarkan banyak hal.Buku puisi ini adalah semacam upacara tersendiri bagi Oka Rusmini. Suatu ungkapan rasa syukur yang tidak ada habisnya yang ia haturkan kepada Kosmis.', 'Rp 69,000', '82 pages', '27 November 2024', 'sastra indonesia, sastra, buku puisi, Kumpulan Puisi, Poetry, Puisi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94733/624202032.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(35, '678231da79bd51cee772b6f5', 'Atlas Dunia Dinosaurus', 'Quarto Publishing', 'Picture Books', 'Ayo berkenalan dengan para dinosaurus luar biasa yang hidup dalam buku aktivitas atlas ini. Temui setiap dinosaurus yang tinggal di habitatnya, hiasi peta dengan stiker warna-warni, dan jawab kuisnya!', 'Rp 179,000', '32 pages', '27 November 2024', 'Anak-anak, Anak, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94679/624120026.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(36, '678231d979bd51cee772b6f4', 'Atlas Dunia Hewan', 'Quarto Publishing', 'Picture Books', 'Temukan hewan-hewan paling menarik di Bumi di atlas penuh warna ini! Cari setiap hewan di habitatnya, hiasi peta dengan stiker warna-warni, dan lengkapi kuis dalam panduan penjelajah untuk menjadi ahli hewan liar!', 'Rp 179,000', '32 pages', '27 November 2024', 'Anak-anak, Anak, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94678/624120027.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(37, '6782322f79bd51cee772b722', 'Segaris Masa Transformasi Bisnis Petrokimia Gresik', 'Grastayana Suki', 'Business Management & Leadership', '“Di tengah-tengah tantangan go global, kami berkomitmen untuk menjadi perusahaan yang inovatif, adaptif, dan responsif terhadap dinamika pasar global yang semakin berubah. Melalui transformasi bisnis yang sedang berjalan, kami terus memperkuat praktik-praktik berkelanjutan dalam setiap aspek operasional.”—T. Nugroho Purwanto, Komisaris Utama PTPetrokimia Gresik“Ide dan kreativitas tidak memiliki struktur hierarki atau jabatan. Siapa pun harus bersama-sama berpikir inovatif sehingga tidak terpaku hanya pada bidangnya.”—Dwi Satriyo Annurogo, Direktur Utama Petrokimia Gresik', 'Rp 369,000', '430 pages', '25 November 2024', 'buku bisnis, Bisnis, Business, Business Management', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94724/Hum_-_Segaris_Masa_Transformasi_Bisnis.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(38, '6782306179bd51cee772b62c', 'Buku Berjendela: Yuk, Tebak! Hewan', 'Clever Media Group', 'Activity Books', 'Di buku ini, kau bisa menebak hewan apa yang bersembunyi di balik jendela buku. Dari peternakan sampai hutan dan habitat lain, temukan hewan-hewan favoritmu dalam buku interaktif ini!', 'Rp 179,000', '10 pages', '20 November 2024', 'Anak-anak, Anak, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94476/Anak_-_Yuk,_Tebak!_Hewan.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(39, '6782306579bd51cee772b62e', 'Buku Berjendela: Yuk, Tebak! Emosi', 'Clever Media Group', 'Activity Books', 'Di buku ini, anak-anak bisa belajar mendefinisikan emosi apa yang dirasakan: sedih, takut, senang, marah... Anak-anak juga bisa tahu penyebabnya dan bagaimana mengatasi perasaan itu dengan bantuan buku interaktif ini!', 'Rp 179,000', '10 pages', '20 November 2024', 'Anak-anak, Anak, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94478/Anak_-_Yuk,_Tebak!_Emosi.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(40, '6782306379bd51cee772b62d', 'Buku Berjendela: Yuk, Tebak! Dinosaurus', 'Clever Media Group', 'Activity Books', 'AYO BERTUALANG KE MASA LALU UNTUK BERTEMU DINOSAURUS! Dari Tyrannosaurus rex sampai Elasmosaurus, ada berbagai jenis dinosaurus dan reptil purba yang bisa kautemui di buku berjendela ini!', 'Rp 179,000', '10 pages', '20 November 2024', 'Anak-anak, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94477/Anak_-_Yuk,_Tebak!_Dinosaurus.jpg', '2026-02-17 06:46:45', '2026-02-17 06:46:45'),
	(41, '6782313e79bd51cee772b6a1', 'Happy Learning Math: Zachary the Zebra Takes a Nap', 'WS Education', 'Activity Books', 'Zachary the Zebra is tired from running away from his predators. He wants to take a nap.But is it safe for him to fall a sleep?Follow the zebra’s exciting day in the savannah and learn about subitising and comparing quantities.Read fun facts about plains zebras!Jump start your child’s advancement in numeracy with the Happy Learning Math series. Your child will delight in the fun stories about animals and encounter Math concepts, such as ordinal numbers, counting, skip counting, addition, subtraction and more.Materials for interactive play and links to printables are also included, turning each book into a hands-on experiential learning tool. Fun Science facts are also weaved into each story to spark your child’s curiosity about the world.This book comes with bonus fun and interactive elements to reinforce your child’s learning of Math concepts! HANDS-ON ACTIVITIES • LINKS TO PRINTABLES', 'Rp 199,000', '32 pages', '11 September 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94595/624116018.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(42, '6782312b79bd51cee772b697', 'I\'m a Future Water Expert!', 'WS Education', 'Picture Books', 'What causes rainfall? Can frogs really fall from the sky? Where do puddles go? Can I make a cloud at home? Can wastewater be turned into water we can drink? Curious to find out the answers to these questions? Join Clara the cloud on an exciting journey and learn all about water.', 'Rp 169,000', '56 pages', '11 September 2024', 'Pictures Book, ensiklopedia anak, picture books, ensiklopedia, Picture book', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94585/624116012.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(43, '6782313579bd51cee772b69c', 'Happy Learning Math: Abby the Anteater Feasts on the Ants', 'WS Education', 'Activity Books', 'Abby the Anteater is upset that her mother eats more ants than her.She quickly learns a painful lesson when she rushes for an extra serving.Follow the anteaters’ eventful day at the grassland and learn to skip count by five and ten.Read fun facts about giant anteaters!Jump start your child’s advancement in numeracy with the Happy Learning Math series. Your child will delight in the fun stories about animals and encounter Math concepts, such as ordinal numbers, counting, skip counting, addition, subtraction and more.Materials for interactive play and links to printables are also included, turning each book into a hands-on experiential learning tool. Fun Science facts are also weaved into each story to spark your child’s curiosity about the world.This book comes with bonus fun and interactive elements to reinforce your child’s learning of Math concepts! HANDS-ON ACTIVITIES • LINKS TO PRINTABLES', 'Rp 199,000', '32 pages', '11 September 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94590/624116019.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(44, '6782313879bd51cee772b69e', 'Happy Learning Math: Olive and Oscar the Orangutans Swing on the Trees', 'WS Education', 'Activity Books', 'Olive and Oscar the Orangutans race each other to find the tree with the most fruits.Who will win the race?Follow the orangutans’ fruitful day in the rainforest and learn to skip count by two.Read fun facts about Sumatran orangutans!Jump start your child’s advancement in numeracy with the Happy Learning Math series. Your child will delight in the fun stories about animals and encounter Math concepts, such as ordinal numbers, counting, skip counting, addition, subtraction and more.Materials for interactive play and links to printables are also included, turning each book into a hands-on experiential learning tool. Fun Science facts are also weaved into each story to spark your child’s curiosity about the world.This book comes with bonus fun and interactive elements to reinforce your child’s learning of Math concepts! HANDS-ON ACTIVITIES • LINKS TO PRINTABLES', 'Rp 199,000', '32 pages', '11 September 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94592/624116016.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(45, '6782313c79bd51cee772b6a0', 'Happy Learning Math: Riley the Rhinoceros Crashes Into the Trees', 'WS Education', 'Activity Books', 'Riley the Rhinoceros is playing hide and seek with her calf, Ryker. She hears noises in the forest. Could that be Ryker? Riley charges towards the sounds. She does not see the tress and crashes into them!Follow the rhinoceros’ playful adventure in the rainforest and learn about ordinal numbers and counting to ten.Read fun facts about Sumatran rhinoceros!Jump start your child’s advancement in numeracy with the Happy Learning Math series. Your child will delight in the fun stories about animals and encounter Math concepts, such as ordinal numbers, counting, skip counting, addition, subtraction and more.Materials for interactive play and links to printables are also included, turning each book into a hands-on experiential learning tool. Fun Science facts are also weaved into each story to spark your child’s curiosity about the world.This book comes with bonus fun and interactive elements to reinforce your child’s learning of Math concepts! HANDS-ON ACTIVITIES • LINKS TO PRINTABLES', 'Rp 199,000', '32 pages', '11 September 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94594/624116014.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(46, '6782313779bd51cee772b69d', 'Happy Learning Math: Casey the Crocodile Loses Her Teeth', 'WS Education', 'Activity Books', 'Casey the crocodile is having toothaches. Her friend, a plover bird, offers to help her pull out her bad teeth.But, is it a good idea to fly into a crocodile\'s mouth?Follow the crocodile’s dreadful week by the river and learn how to add and subtract.Read fun facts about Nile crocodiles!Jump start your child’s advancement in numeracy with the Happy Learning Math series. Your child will delight in the fun stories about animals and encounter Math concepts, such as ordinal numbers, counting, skip counting, addition, subtraction and more.Materials for interactive play and links to printables are also included, turning each book into a hands-on experiential learning tool. Fun Science facts are also weaved into each story to spark your child’s curiosity about the world.This book comes with bonus fun and interactive elements to reinforce your child’s learning of Math concepts! HANDS-ON ACTIVITIES • LINKS TO PRINTABLES', 'Rp 199,000', '32 pages', '11 September 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94591/624116017.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(47, '6782313a79bd51cee772b69f', 'Happy Learning Math: Poppy and The Puff the Pandas Share Their Bamboos', 'WS Education', 'Activity Books', 'Puff and Poppy the Pandas find a bamboo forest.But are there enough bamboos for both pandas?Follow the giant pandas’ delightful journey through the mountainous forest and learn division by two. Read fun facts about giant pandas!Jump start your child’s advancement in numeracy with the Happy Learning Math series. Your child will delight in the fun stories about animals and encounter Math concepts, such as ordinal numbers, counting, skip counting, addition, subtraction and more.Materials for interactive play and links to printables are also included, turning each book into a hands-on experiential learning tool. Fun Science facts are also weaved into each story to spark your child’s curiosity about the world.This book comes with bonus fun and interactive elements to reinforce your child’s learning of Math concepts! HANDS-ON ACTIVITIES • LINKS TO PRINTABLES', 'Rp 199,000', '32 pages', '11 September 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94593/624116015.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(48, '6782317879bd51cee772b6c0', 'My Little Pony: Buku Mewarnai dan Aktivitas Super Besar', 'Hasbro', 'Activity Books', 'Minta bantuan orang dewasa untuk menggunting garis putus-putus dan merangkai karakter berdiri para poni!', 'Rp 59,000', '64 pages', '04 September 2024', 'Anak-anak, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94626/624118007.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(49, '678231b379bd51cee772b6e0', 'Hei, Intern!', 'Hamalem', 'MetroPop', 'Hidup Ullie berubah sejak magang menjadi asisten Fabian, direktur galak yang suka semena-mena. Kuping Ullie sampai pengang karena cowok itu bolak-balik memanggilnya lewat pelantang.Tak peduli betapa kerasnya Ullie berusaha, hidupnya tetap bagai telur di ujung tanduk.Tapi Ullie bertekad menang melawan penindasan Fabian. Meski harus datang paling awal, pulang paling akhir, mengerjakan tugas random, hingga mengurus kebutuhan pribadi Fabian, Ullie tak akan menyerah!Hingga suatu hari, Fabian melontarkan ide absurd untuk menyuruh Ullie jadi pacar pura-pura dengan menjanjikan tambahan bonus. Menggiurkan sih… tapi gimana caranya tampak meyakinkan kalau dia sendiri benci banget sama Fabian?', 'Rp 89,000', '336 pages', '04 September 2024', 'Romance Novels, kisah romantis, romance novel, romantis, novel roman, Roman, Romance, Metropop', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94658/624171008.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(50, '678231c179bd51cee772b6e7', 'Dari Kei untuk Konferensi Meja Bundar', 'Stephanus G. Setitit', 'Biography,', '“Buku ini sarat isi dan makna, di mana salah satunya adalah tentang keteladanan hidup, yakni pengabdian tulus dan utuh yang telah diajarkan oleh tokoh yang dipaparkan dalam buku ini: mendiang Bon Setitit. Ketika saya lebih teliti membacanya, terdapat pesan ajaran tentang semangat cinta tanah air yang begitu tulus dan luar biasa, mengabaikan kepentingan diri sendiri. Hal itu tergambar secara jelas dalam perjalanan karier dan penghargaan yang diterimanya dari Pemerintah Kolonial Belanda. Keterlibatan dan keikutsertaannya pada Konferensi Meja Bundar, yang merupakan pilihan Pemerintah Belanda melalui Kementerian Luar Negeri, adalah bukti pengakuan dan penghargaan istimewa kepada beliau. Keteguhan hati dan rasa cinta tanah air tertanam kuat di dalam diri anak bangsa ini sehingga menjadi inspirasi dan panutan bagi generasi muda dalam usaha yang sungguh-sungguh menuju kejayaan bangsa di era Indonesia Emas yang akan datang.”—Surya Paloh, Chairman of Media Group“Saksi sejarah dalam sebuah konferensi internasional yang menentukan perjalanan hidup bangsa Indonesia seperti Konferensi Meja Bundar bukanlah sesuatu yang main-main melainkan sebuah ukiran sejarah dari peran orang-orang penting yang jumlahnya bisa dihitung dengan jari. Tidak banyak biografi seseorang yang cukup besar peranannya di awal kemerdekaan Republik Indonesia. Tidak banyak pula kita jumpai kisah perjuangan yang menceritakan peranan seorang tokoh yang berasal dari pulau terpencil di Indonesia Timur. Lebih jauh lagi, tidak banyak kisah heroik seseorang yang memiliki andil besar dalam mengisi kemerdekaan di tahun-tahun awal Indonesia merdeka yang dilengkapi berbagai dokumen autentik perbendaharaan pribadi keluarganya.—Marsekal Purnawirawan Chappy Hakim, Kepala Staf Angkatan Udara RI, 2002–2005', 'Rp 169,000', '296 pages', '04 September 2024', 'Internasional, Politics, Politic, indonesia, biografi, Biography', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94665/624222021.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(51, '678231a879bd51cee772b6da', 'Multi-Pathways for Car Electrification', 'Cyrillus Harinowo, Ph.D dan Ika Maya Sari Khaidir, S.E', 'Business & Economic', '“Perang” melawan pemanasan global telah menjadi fokus dunia selama beberapa tahun terakhir, khususnya pada industri otomotif. Sebagai salah satu penyumbang terbesar emisi gas rumah kaca, industri otomotif berusaha memperbaiki diri dengan menciptakan inovasi melalui pengembangan kendaraan ramah lingkungan.Kendaraan berbasis listrik—yang berkembang pesat—digadang-gadang menjadi solusi terbaik persoalan pemanasan global. Namun, dalam implementasinya, kendaraan listrik belum bisa menjadi jawaban utama. Selain karena pembangkit listrik mayoritas masih berbahan bakar fosil dan harga jual yang tinggi, kendaraan listrik belum bisa digunakan secara masif.Inilah yang memunculkan kebutuhan akan alternatif moda transportasi yang ramah lingkungan tetapi tidak berbasis listrik. Kendaraan hybrid, low cost green cars (LCGC), kendaraan berbahan bakar hidrogen, serta kendaraan berbahan bakar bioetanol dan biodiesel bisa menjadi jawaban. Alternatif-alternatif ini menunjukkan beberapa jalan yang bisa ditempuh untuk menuju era industri otomotif "hijau". Bagaimana Indonesia menempatkan diri dalam perkembangan industri “hijau” ini? Apakah Indonesia bisa mengambil bagian besar dalam produksi otomotif global, atau justru perlahan tertinggal dan tersingkir dari persaingan dunia?', 'Rp 199,000', '310 pages', '04 September 2024', 'Bisnis, Ekonomi, Economic, Business Management, Business, buku bisnis, Economics, Busines', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94652/624203017.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(52, '6782319f79bd51cee772b6d5', 'Merajut Harapan, Mengelola Ancaman', 'Prof. Dr. Irfan Idris, MA.', 'Self-Improvement,', 'Dalam Merajut Harapan, Mengelola Ancaman, Prof. Dr. Irfan Idris, M.A. membagikan catatan hariannya sebagai Direktur Pencegahan di Badan Nasional Penanggulangan Terorisme (BNPT) yang penuh tantangan sekaligus inspiratif dalam mengelola ancaman terorisme di Indonesia. Mulai dari pengalaman di lapangan hingga saat berinteraksi dengan berbagai kalangan, setiap bab di buku ini menghadirkan kisah yang lekat dengan keseharian tentang upaya deradikalisasi dan pencegahan ekstremisme.Buku ini menjadi dokumentasi sekaligus referensi yang menambah wawasan kita tentang bagaimana menciptakan lingkungan yang damai dan toleran. Ada momen-momen yang merupakan refleksi serta diskusi-diskusi yang disertai dengan berbagai strategi yang diharapkan menjadi solusi dalam perjuangan melawan radikalisme.Buku ini mengajak pembaca meresapi pentingnya mengedepankan perdamaian dan kerja sama. Mengingat kembali indahnya kebersamaan dan gotong royong serta menumbuhkan rasa cinta terhadap tanah air dapat menjadi benteng dalam melawan narasi kebencian. Merajut Harapan, Mengelola Ancaman adalah bacaan yang tepat bagi mereka yang peduli akan masa depan Indonesia yang damai dan harmonis.', 'Rp 139,000', '294 pages', '28 August 2024', 'Social & sciences, Social Science, Self-Improvement, nonfiksi, Social Sciences, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94647/624222017.jpg', '2026-02-17 06:50:45', '2026-02-17 06:52:00'),
	(53, '678231a179bd51cee772b6d6', 'Sang Putra Mahkota  (The King\'s Christmas Heir)', 'Lynne Graham', 'Harlequin', 'Ketika Lara Drummond menyelamatkan Gaetano di Santis dari badai salju, ia tak pernah membayangkan akan menikah dengan pria itu beberapa minggu kemudian. Apalagi mengingat pria itu menderita amnesia. Ia jatuh cinta dan yakin mereka akan bersama selamanya. Sayangnya, mereka berpisah setelah identitas Gaetano yang sebenarnya terkuak.Sebagai seorang raja, Gaetano harus selalu memprioritaskan negaranya. Dan itu termasuk tugasnya untuk memiliki ahli waris. Ia tak mengira bahwa wanita yang meninggalkannya dua tahun lalu telah melahirkan seorang putra baginya! Demi negara, Gaetano takkan membiarkan putranya terpisah dan demi hatinya, ia akan meyakinkan Lara untuk kembali padanya.', 'Rp 69,000', '224 pages', '28 August 2024', 'Romance Novels, romance novel, Novel dewasa, Romance, Harlequin', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94648/624180006.jpg', '2026-02-17 06:50:45', '2026-02-17 06:52:00'),
	(55, '6782322b79bd51cee772b720', 'Manifesto Flora (2024)', 'Cyntha Hariadi', 'Short Stories', '“Ia pencerita yang dingin, mengajak kita mengintip dalam sunyi. Keheningan yang mencekam, yang disampaikan oleh cerita yang nyaris tanpa dialog, tapi kemudian sejenis dentum bisa datang menghantam kapan saja. Bahkan di cerita seperti Dua Perempuan di Satu Rumah, dentum itu menjadi teror dan horor.” - Eka Kurniawan“Jika bahasa bermula dari kata, maka susastra bermula dari bahasa. Tetapi bahasa tidak akan menjadi susastra jika tak mampu menyeruak dari keberbahasaan mapan nan mati, tetapi masih dipakai juga sebagai mayat hidup yang disebut zombie - itulah yang membuat bahasa susastra menghidupkan kembali kata demi kata dengan pembermaknaan baru. Itulah yang dilakukan Cyntha Hariadi dengan Manifesto Flora.” - Seno Gumira Ajidarma', 'Rp 79,000', '174 pages', '28 August 2024', 'Cerpen, Kumpulan cerita pendek, Short Stories, sastra, novel sastra', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94722/624202023.jpg', '2026-02-17 06:50:45', '2026-02-17 06:52:00'),
	(56, '678231d379bd51cee772b6f1', 'Behind The Helmets: The Inside Story of 5 Disciplines (Hardcover)', 'Teguh Sri Pambudi,', 'Self-Improvement', 'Buku ini memberikan jawabannya. Buku yang terdiri dari lima bagian ini tidak secara ketat merinci dan membagi perjalanan Pama selama tiga dekade secara kronologis, tapi lebih menyoroti apa yang telah membuat Pama bertahan serta berkembang. Dengan demikian, buku ini bukan hanya tentang deretan cerita masa lalu, tapi juga tentang bagaimana masa lalu dibentuk sehingga menjadi landasan masa depannya. Selama tiga dekade, Pama bertransformasi dengan teguh, bertumpu pada lima kedisiplinan utama yang dijalankan secara konsisten: membangun kompetensi, mencapai keunggulan operasional (operational excellence), mendorong inovasi, menjalin kedekatan dengan pelanggan (customer intimacy), dan membangun budaya perusahaan (corporate culture) yang kuat. Kelima pilar ini menjadi fondasi yang kokoh, menopang setiap langkah Pama hingga akhirnya mampu menuju puncak, sekaligus memastikan Pama tidak hanya tumbuh besar, tapi juga tumbuh dengan cara yang benar.  Seperti kata bapak manajemen Peter Drucker, “The best way to predict the future is to create it,” Pama telah menciptakan masa depannya, dan buku ini adalah rekaman perjalanan sepanjang tiga dekade, yang menjadi landasan untuk masa depannya.', 'Rp 983,000', '350 pages', '28 August 2024', 'buku pengembangan diri, Self-Improvement, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94675/Hum_-_Behind_the_Helmets.jpg', '2026-02-17 06:50:45', '2026-02-17 06:52:00'),
	(57, '678231b579bd51cee772b6e1', 'Growth Thinking Lawan Rasa Puasmu! (SC)', 'Alberthiene Endah', 'Social Sciences', 'Grup Orang Tua tumbuh melalui perjalanan selama puluhan tahun yang diwarnai kesabaran, ketekunan, kepercayaan yang tinggi, dan kerja keras. Berawal pada 1948 sebagai produsen minuman kesehatan Cap Orang Tua di Medan dan kemudian Semarang, perusahaan yang didirikan Chu Sam Yak atau Chandra Djojonegoro ini melintasi waktu dengan branding produk yang semakin kokoh. Di bawah PT Perindustrian Bapak Djenggot, minuman kesehatan Cap Orang Tua menjadi produk kesehatan yang sangat dikenal di Indonesia.Kesuksesan ini dilanjutkan oleh generasi kedua, Hamid Djojonegoro, dengan masuk ke industri consumer goods pada 1975. Di bawah kepemimpinan Hamid, PT Perindustrian Bapak Djenggot kemudian memproduksi sejumlah produk kebutuhan sehari-hari, seperti kaos lampu, sikat dan pasta gigi, minuman kesehatan, wafer, permen, dan disinfektan, hingga kemudian merambah dunia ritel.Sempat berganti nama menjadi ADA (Attention, Direction, Action), dan berganti lagi menjadi Grup Orang Tua atau OT, Hamid membawa perusahaan ini berkembang besar dengan aneka produk yang sebagian besar menguasai market share di Indonesia. Cita-cita OT adalah menciptakan produk berkualitas premium dengan harga terjangkau untuk memberi nilai tambah dalam kehidupan masyarakat. Kini, Grup OT merupakan salah satu perusahaan consumer goods terbesar di Indonesia.Keberhasilan OT diraih berkat kerja keras dengan etos luar biasa, sikap pantang menyerah, kemauan bekerja untuk hasil yang excellent, dan keinginan belajar dari setiap kegagalan. Jangan berpuas diri dan harus terpacu menambah ilmu, itulah prinsip OT. Buku ini mengisahkan bagaimana perjuangan dilakukan oleh segenap insan OT di setiap lini hingga perusahaan ini menjadi kokoh.', 'Rp 465,000', '450 pages', '28 August 2024', 'Biography, bio, biografi, Social Science, Social Sciences, Business, Business Management', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94659/Hum_-_Growth_Thinking.jpg', '2026-02-17 06:50:45', '2026-02-17 06:52:00'),
	(58, '678231c479bd51cee772b6e9', 'How To Not Lose in Life', 'Melvin Hade', 'Self-Improvement', 'Bagaimana agar bisa menang dalam kehidupan ini?Ya, semua orang tentu punya tantangan dan rintangan masing-masing, namun bukan berarti kita hanya bisa berpangku tangan menerima segala kesulitan tersebut, bukan? Begitu juga sebaliknya saat meraih sukses, bagaimana agar bisa mempertahankan dan meningkatkannya, tak hanya puas dengan pencapaian saat ini.Kerja tidak akan mengkhianati hasil. Itulah yang ingin dibuktikan Penulis melalui buku ini. Berdasarkan pengalaman pribadi, 10 pola pikir yang secara signifikan telah mengubah kehidupan pribadi dan keluarga Penulis ini mampu membantu pembaca: - "menghadapi" masa-masa sulit dan saat-saat sibuk sejak dini ketika masih muda, bukan ketika sudah mendekati masa pensiun, - memberikan yang terbaik dalam kehidupan, mulai dari hal-hal terkecil, - menggunakan setiap kesempatan untuk menunjukkan seni dalam mempersiapkan, memberikan yang terbaik, dan pada akhirnya mewujudkan tujuan hidup, serta - mendapatkan perspektif dan inspirasi untuk mengubah arah hidup menjadi lebih baik.', 'Rp 129,000', '204 pages', '28 August 2024', 'Self-Improvement, Self-Acceptance, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94667/Hum_-_How_to_Not_Lose_in_Life.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(59, '67822ff479bd51cee772b5f1', 'What to Expect When You\\\'re Expecting', 'Heidi Murkoff', 'Parenting & Family,', 'Buku edisi terbaru ini berisi informasi termutakhir seputar kehamilan dan persalinan, serta dilengkapi saran dan tips praktis bagi calon ibu. Perkembangan janin selama minggu demi minggu dikupas tuntas, disertai informasi yang berguna bagi calon ayah.Dapatkan jawaban yang meyakinkan untuk pertanyaan:Kapan saya bisa melakukan tes kehamilan di rumah?Apakah saya harus makan untuk dua orang, padahal makan sedikit saja terasa mual?Apakah ikan aman dikonsumsi? Bagaimana dengan keju lunak?Olahraga apa yang aman untuk ibu hamil?Saya mengeluarkan flek darah. Berbahayakah itu?USG 4D, perlu atau tidak?Obat apa saja yang aman untuk ibu hamil dan menyusui?Akankah saya tahu ketika tiba saatnya saya melahirkan?Apakah melahirkan secara per vaginam lebih sakit daripada operasi Caesar?Bayi saya meninggal dalam kandungan. Apa yang harus saya lakukan?Kapan bisa berhubungan intim setelah melahirkan?', 'Rp 239,000', '744 pages', '28 August 2024', 'kehamilan, pregnancy, hamil, Orangtua, buku parenting, Parenting, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94417/624206003.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(60, '6782322979bd51cee772b71f', 'Sejuta Warna Pelangi', 'Clara Ng', 'Picture Books', 'Dengan mata telanjang, kanak-kanak melihat tujuh warna pelangi. Ajaklah mereka melihat dengan mata hati. Agar mereka tahu sesungguhnya pelangi punya sejuta warna-warni.', 'Rp 139,000', '220 pages', '28 August 2024', 'Clara Ng, Buku anak, Anak, Children Book, Children, Children Books, Picture book, picture books', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94721/624101003.jpg', '2026-02-17 06:50:45', '2026-02-17 06:50:45'),
	(61, '6782318179bd51cee772b6c5', 'Gentayangan', 'Intan Paramaditha', 'Literary', 'Iblis Kekasih telah memberimu sepasang sepatu merah, hadiah sekaligus kutukan. Kau terkutuk untuk bertualang, atau lebih tepatnya, gentayangan. Bernaung, tapi tak berumah.Buka halaman selanjutnya dan pilih jalan ceritamu sendiri: ke Berlin atau Amsterdam? Lima atau Tijuana? Akankah kau bertemu iblis di kuburan atau naik kereta yang tak berhenti? Sepatu merah membawamu ke jalur-jalur berbeda, sebagai pengelana, imigran gelap, kekasih, atau pembunuh. Kau akan melintasi orang-orang yang bergerak seperti dirimu—menyeberang, berlari, mencari rumah atau pintu darurat.Gentayangan: Pilih Sendiri Petualangan Sepatu Merahmu adalah novel interaktif karya Intan Paramaditha yang terbit pertama kali tahun 2017. Berkisah tentang perjalanan, ketercerabutan, dan batas-batas kemerdekaan, novel ini mendapatkan penghargaan Sastra Prosa Terbaik Pilihan Tempo. The Wandering, terjemahannya dalam bahasa Inggris oleh Stephen J. Epstein, diterbitkan oleh Harvill Secker (Penguin Random House UK) tahun 2020 dan mendapatkan penghargaan dari PEN Translates Award serta nominasi The Stella Prize. Gentayangan juga telah diterjemahkan ke dalam bahasa Polandia dan Turki.***** “Sebuah piranti cerdas menelusuri globalisasi ketika batas-batas ditutup untuk si miskin dan para pengungsi, sementara si kaya bisa membeli paspor yang mengizinkan mereka untuk tinggal (atau menyimpan uang) di mana saja.” - The Guardian“Kisah cemerlang tentang ilusi atas kehendak bebas, juga pertaruhan dan tekanan yang menyertai pilihan-pilihan berdasarkan identitas seseorang di dunia.” - The Saturday Paper“… Sebuah novel menyetrum tentang kosmopolitanisme dan pengembaraan global yang membuat kita terus berjalan.” - Book Riot', 'Rp 179,000', '504 pages', '28 August 2024', 'Literary, novel sastra, sastra, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94631/624202022.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(62, '678231b079bd51cee772b6de', 'Semoga Keberhasilan Selalu Menyertaimu', 'Jeon Seunghwan', 'Self-Improvement,', 'Hidup mungkin tak selalu cemerlang dan terang, terkadang kita tersesat dalam kegelapan.Di antara hari-hari buruk yang membuat kehidupan terasa runtuh, aku berharap engkau menemukan secercah harapan, yang akan menerangi segala hal yang kaulakukan.Semoga pelangi yang cerah muncul, dan bunga yang cantik tersenyum padamu.Aku akan mendoakanmu, agar segala sesuatu yang kaulakukan berjalan dengan baik.Semoga kau dicintai apa adanya, bahagia di mana pun kau berada, bertemu orang yang menyenangkan, dan menikmati segala hal yang kaulakukan.', 'Rp 119,000', '233 pages', '28 August 2024', 'buku pengembangan diri, Self-Improvement, Self-Acceptance, pengembangan diri, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94656/624221037.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(63, '6782316e79bd51cee772b6bb', 'My Little Pony: Bertukar Tanda Bakat (Cutie Mark Mix Up)', 'Hasbro', 'Picture Books', 'Kadang kau harus berjalan dengan sepatu kuda lain…Saat sendawa ajaib Sparky membuat Sunny dan Hitch bertukar Tanda Bakat, semuanya jadi kacau! Tapi bertukar kekuatan membuat kedua teman itu semakin dekat, karena mereka jadi memahami satu sama lain. Tapi, apa mereka bisa bertukar kembali?', 'Rp 39,000', '24 pages', '21 August 2024', 'Anak-anak, Anak, Children, Childrens Books, Children Books, Children Book, Pictures Book, picture books, buku anak gramedia, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94621/624118003.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(64, '6782311079bd51cee772b689', 'Ayo Belajar: Berteman', 'Pat-a-Cake', 'Board Books,', 'Ada banyak cara untuk berteman. Pelajari semuanya dalam buku berjendela ini.“Buku ini menyediakan pandangan yang lebih mendalam tentang kehidupan keluarga masa kini.” —Dr Jacqueline Harding-Vallance Konsultan Tumbuh Kembang Anak', 'Rp 139,000', '18 pages', '21 August 2024', 'Anak-anak, Anak, Pictures Book, picture books, buku anak gramedia, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94570/624116007.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(65, '6782318779bd51cee772b6c8', 'Buku Stiker Gliter: Putri Kerajaan', 'WS Kids (White Star Kids)', 'Activity Books', 'Halo, Tuan Putri!Kau akan pergi ke pesta di istana, piknik di hutan ajaib, dan menginap di rumah teman bangsawan. Tapi yang paling menyenangkan adalah kau bisa menentukan busana yang dipakai setiap putri kerajaan. Dengan lebih dari 250 stiker, kau bisa memilih gaun dan perhiasan yang cocok untuk setiap acara. Kau juga bisa menambahkan hewan-hewan lucu, bunga-bunga indah, dan berbagai dekorasi gliter untuk mempercantik kerajaan para putri ini!', 'Rp 139,000', '24 pages', '21 August 2024', 'Anak-anak, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94634/624120022.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(66, '6782318879bd51cee772b6c9', 'Buku Stiker Gliter: Unicorn', 'WS Kids (White Star Kids)', 'Activity Books', 'Ayo masuk ke kerajaan unicorn!Kau bisa bermain di perosotan pelangi dan mengunjungi kastel es unicorn. Tapi yang terpenting adalah kau bisa menghias surai menggunakan lebih dari 250 stiker. Kau juga bisa menambahkan peri, bunga, kristal, dan dekorasi gliter lain untuk membuat kerajaan unicorn lebih ajaib!', 'Rp 139,000', '24 pages', '21 August 2024', 'Anak-anak, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak, Stiker, Sticker, Sticker Book', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94635/624120020.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(67, '6782318579bd51cee772b6c7', 'Buku Stiker Gliter: Perancang Busana', 'WS Kids (White Star Kids)', 'Activity Books', 'Apa kau siap bermain dengan fesyen?Ayo menata busana dan buat hasil karyamu menjadi kenyataan! Cocokkan dan padukan rok, gaun, celana, dan atasan dengan berbagai warna dan corak. Kau tidak akan kehabisan ide dengan 250 stiker yang tersedia untuk membuat busana favoritmu. Kau juga bisa menambahkan aksesori seperti tas, kacamata, sepatu, dan perhiasan. Jangan lupa tambahkan gliter cantik supaya makin seru, ya!', 'Rp 139,000', '24 pages', '21 August 2024', 'Anak-anak, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94633/624120021.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(68, '678231a479bd51cee772b6d8', 'Solusi Alternatif terhadap Berbagai Permasalahan Bangsa', 'Dr. H. Cucun Ahmad Syamsurijal, S.Ag., MAP', 'Politics', 'Solusi Alternatif terhadap Berbagai Permasalahan Bangsa dirancang untuk memberikan panduan komprehensif menuju Indonesia Emas 2045. Buku ini mengidentifikasi dan mengurai berbagai permasalahan dan tantangan yang dihadapi bangsa Indonesia, serta memberikan solusi alternatif melalui agenda dan alur yang inovatif dan terukur.Dalam buku ini, dijabarkan langkah-langkah strategis untuk mengatasi berbagai isu krusial dan permasalahan, antara lain:- menyusun agenda yang terarah dan terukur untuk menggapai cita-cita menjadi negara maju,- mengefektifkan penyerapan ABPN- menyediakan Sumber Daya Manusia yang unggul, berkualitas, berani, dan tangguh- menyiasati bonus demografi sebagai mesin pendorong pertumbuhan ekonomi,- melestarikan nilai-nilai budaya bangsa,- membangun strategi peningkatan pendapatan masyarakat,- merancang pola pembangunan alternatif,- menciptakan kebijakan fiskal yang suportif,- memastikan koordinasi dan kolaborasi antarlembaga terbangun dengan baik,- memprioritaskan ekonomi berkelanjutan melalui kebijakan pembiayaan hijau, dan- memiliki kemampuan memitigasi berbagai tantangan global dan berbagai rencana cadangan.Buku ini tidak hanya menawarkan solusi yang bersifat teoretis, tetapi juga sungguh dapat diimplementasikan dalam jangka pendek maupun panjang. Dengan peran aktif dan sinergi antara pemerintah, sektor swasta, dan masyarakat sipil, proses transformasi bangsa dapat terus berlanjut. Kecuali memberikan inspirasi dan panduan, buku ini menyuarakan panggilan bertindak, membangun Indonesia yang adil, makmur, dan berdaya saing di kancah global.', 'Rp 159,000', '320 pages', '21 August 2024', 'Politics, Politic, humaniora, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94650/WhatsApp_Image_2024-07-15_at_10_55_19.jpeg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(69, '678231b179bd51cee772b6df', 'Sejuta Waktu untuk Mencintaimu', 'Achi TM', 'MetroPop', 'Hanya Andien Carissa Putri yang tahu bagaimana sakitnya ditinggal calon suami tepat di hari pernikahannya. Lelaki itu menghilang berbulan-bulan dan muncul sebagai tetangga bersama istrinya yang cantik dan sedang hamil muda!Saat Andien berusaha mempertahankan kewarasannya, Danish Adelard tiba-tiba muncul dan mengaku datang dari masa depan dengan segala ceritanya yang tidak masuk akal.Sanggupkah Andien menghindar ketika Danish terus menawarkan sejuta waktu untuk mencintainya serta memulihkan setiap luka-lukanya?  Mampukah Andien bertahan ketika dimensi waktu memisahkan mereka?', 'Rp 109,000', '416 pages', '21 August 2024', 'Romance Novels, romance novel, Romance, Metropop, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94657/624171007.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(70, '6782318379bd51cee772b6c6', 'Buku Stiker Gliter: Penari', 'WS Kids (White Star Kids)', 'Activity Books', 'Ikuti para balerina mempersiapkan tarian yang tidak terlupakan! Kau bisa memilih rok tutu, menghias rambut dan kostum mereka, serta memilih latar untuk tarian mereka. Dengan lebih dari 250 stiker, kau tidak akan kehabisan pilihan. Kau juga bisa menambah beberapa dekorasi gliter untuk membuat tarian mereka lebih memukau!', 'Rp 139,000', '24 pages', '21 August 2024', 'Anak-anak, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94632/624120019.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(71, '6782315879bd51cee772b6af', 'My Little Pony: Kreasi Izzy (Izzy Does It)', 'Hasbro', 'Picture Books', 'Semua poni tak sabar melihat hadiah ulang tahun yang akan dibuat Izzy untuk Sunny!', 'Rp 39,000', '32 pages', '14 August 2024', 'Anak-anak, Anak, Children, Childrens Books, Children\\\'s Book, Children Books, Children Book, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94609/624118002.jpg', '2026-02-17 06:52:00', '2026-02-17 06:53:48'),
	(72, '678231ac79bd51cee772b6dc', 'Lima Penyintas (Five Survive)', 'Holly Jackson', 'Mysteries & Thrillers', 'Delapan jam.Enam sahabat. Satu penembak...Red dan teman-temannya sedang dalam perjalanan darat untuk Liburan Musim Semi. Sayangnya, ban RV yang mereka kendarai mendadak bocor di tengah antah-berantah. Tanpa sinyal, tanpa bantuan. Anehnya, satu per satu ban RV pecah ditembak, membuat mereka tersadar: ini bukan kecelakaan.Ada seorang penembak di luar sana, bersembunyi dalam kegelapan mengintai mereka. Seseorang yang tahu identitas mereka dan memaksa keenam sahabat itu mengakui rahasia masing-masing—kalau tidak mau mati tertembak.Dalam RV yang sempit dan klaustrofobik, Red dan teman-temannya yang ketakutan berusaha terbebas dari teror sang penembak. Dalam kondisi semakin tertekan, mereka terpaksa mengakui rahasia tergelap mereka dan salah satu di antara mereka tidak akan selamat melewati malam itu.', 'Rp 109,000', '424 pages', '14 August 2024', 'Thriller, Mystery & Thrillers, Thrillers, novel thriller', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94654/624160006.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(73, '678231a279bd51cee772b6d7', 'Pertempuran dalam Lautan Bintang (To Sleep in a Sea of Stars #2)', 'Christopher Paolini', 'Science Fiction & Fantasy', 'Set elah penemuan relik yang menghubungkannya dengan kekuatan alien, Kira Navárez berada dalam situasi yang tak pernah terbayangkan. Dia bergabung dengan Wallfish, kapal ruang angkasa, menghadapi tidak hanya ancaman alien, tapi juga kekerasan dari UMC, komando militer manusia. Bersama Wallfish, Kira menjelajahi lautan bintang, bepergian melebihi kecepatan cahaya. Namun, kapal tua rongsok itu bukanlah sekutu yang tepat untuk melawan pasukan alien yang begitu besar.Terus-menerus bertarung dengan spesies alien yang menginginkan kehancuran manusia, Kira harus membuat kesepakatan dengan mereka. Kalau tidak, entitas itu akan memusnahkan dirinya dan seluruh dunia.Paolini mengisi universe ini dengan berbagai tokoh menarik serta realistis, dan bisa dibilang berhasil menghindari stereotipe orang jahat/baik, membuat kisahnya memiliki kedalaman emosi yang terasa nyata. —Booklist, starred review', 'Rp 169,000', '600 pages', '14 August 2024', 'Novel Fantasi, Science Fiction & Fantasy, Fantasy', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94649/624164007.jpg', '2026-02-17 06:52:00', '2026-02-17 06:53:48'),
	(74, '6782316779bd51cee772b6b7', 'My Little Pony: Izzy Pulang ke Rumah (Izzy Comes Home)', 'Hasbro', 'Picture Books', 'Akan Kutunjukkan Tempat Favoritku!Izzy dan Sunny mengunjungi Bridlewood dan menemukan arti rumah yang sebenarnya.', 'Rp 39,000', '32 pages', '14 August 2024', 'Anak-anak, Anak, Children, Childrens Books, Children Books, Children Book, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94617/624118004.jpg', '2026-02-17 06:52:00', '2026-02-17 06:52:00'),
	(81, '6782315e79bd51cee772b6b2', 'My Little Pony: Raih Kesuksesanmu (Make Your Mark)', 'Hasbro', 'Picture Books', 'Sihir telah kembali ke Equestria berkat Sunny Starcout dan teman-temannya. Tetapi, masih banyak hal yang harus dihadapi saat para poni dihadang tantangan-tantangan baru di dunia yang tidak pasti. Para poni harus bekerja sama untuk menyelamatkan sihir lagi.', 'Rp 39,000', '24 pages', '14 August 2024', 'Anak-anak, Anak, Children, Little Pony, Childrens Books, Children Books, Children Book, My Little Pony, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94612/624118001.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(82, '6782316979bd51cee772b6b8', 'My Little Pony: Tukar Tempat (Sister Switch)', 'Hasbro', 'Picture Books', 'Bagaimana ya rasanya menjadi orang lain? Ketika si kembar Pipp dan Zipp bertengkar, teman-teman poni menyarankan mereka untuk bertukar tempat!', 'Rp 39,000', '32 pages', '14 August 2024', 'Anak-anak, Anak, Children, Childrens Books, Children Books, Children Book, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94618/624118005.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(83, '678231a679bd51cee772b6d9', 'Hidup Tetap Berjalan dan Kita telah Lupa Alasannya', 'Ibe S. Palogai', 'Poetry', 'jika hidup kamu pernah dijadikan panutan buruk, itu bukan salah kamu.jika pernah ditangguhkan dalam keputusasaan dan diusir dari rumah yang kamu cintai, itu bukan salah kamu.jika pernah dikhianati teman-temanmu di tengah perjalanan, itu bukan salah kamu.jika pernah dijadikan alasan atas kesialan yang berulang, itu bukan salah kamu.jika pernah digunakan sebagai alat balas dendam seseorang kepada mantan kekasihnya, itu bukan salah kamu.jika pendapat kamu pernah ditertawai orang-orang, itu bukan salah kamu. jika pernah diremehkan orang tua sendiri, itu bukan salah kamu.jika pernah terbangun tengah malam dan menyalakan lampu di dalam kamar karena segala sesuatu di luar terasa gelap, itu bukan salah kamu.jika pernah terjebak di tengah cinta segitiga, itu bukan salah kamu. jika pernah menangis hingga tertidur, itu bukan salah kamu.– sobek halaman ini lalu luangkan waktu membakarnya.', 'Rp 59,000', '96 pages', '14 August 2024', 'puisi kehidupan, sastra, buku puisi, Kumpulan Puisi, Puisi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94651/624174001.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(84, '6782317f79bd51cee772b6c4', 'Misteri Perpustakaan yang Hilang (The Lost Library)', 'Rebecca Stead,', 'TeenLit', 'Suatu hari, perpustakaan kecil gratis muncul di Kota Martinville. Di dekatnya ada plang bertuliskan: AMBIL BUKU, TINGGALKAN BUKU. ATAU DUA-DUANYA! Evan mengambil dua buku dan mendapati buku-buku di perpustakaan tersebut berasal dari Perpustakaan Martinville yang terbakar dua puluh tahun lalu.Perpustakaan kecil gratis itu ternyata dibuat oleh hantu bernama Al dan dijaga oleh kucing manis bernama Mortimer. Al merupakan asisten pustakawan Perpustakaan Martinville sementara Mortimer dulu tinggal di sana. Setiap kali mengingat kebakaran Perpustakaan Martinville, hati Mortimer selalu berkata itu salahnya. Apa yang sebenarnya terjadi hari itu?', 'Rp 69,000', '240 pages', '07 August 2024', 'Science Fiction & Fantasy, slice of life, Fantasy, teenlit, Teen Novel, Teen, Remaja, novel remaja', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94630/624143003.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(86, '6782310a79bd51cee772b686', 'Inside Out: Rasakan Perasaanmu (Inside Out #2: Feeling Feelings)', 'Disney Pixar', 'Activity Books', 'Apa kau sedang merasa senang karena Joy mengendalikan Alat Kendali-mu? Apa kau baru saja mengatakan sesuatu yang memalukan dan Embarrassment sedang mengendalikanmu? Atau Anxiety sedang diam-diam menguasaimu?Emosi mana pun yang sedang kaurasakan, tulis semuanya di jurnal ini! Ayo analisis perasaanmu dibantu Joy, Sadness, Anger, Fear, Disgust, Anxiety, Envy, Embarrassment, dan Ennui. Dengarkan emosimu dan temukan jati dirimu.Gunakan jurnal ini untuk:membantumu merasa tenangmeningkatkan kepercayaan diriberlatih mengekspesikan dirimengenali dirimu sendiri', 'Rp 99,000', '144 pages', '07 August 2024', 'Aktivitas, Activities, Activity Book, Activity Books, disney', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94567/624110017.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(87, '6782317a79bd51cee772b6c1', 'Maktub', 'Paulo Coelho', 'Latin American Literature', 'Maktub berisi kumpulan cerita dan perumpamaan yang mengungkap misteri-misteri kehidupan. Maktub berarti “Telah tertulis”, dan pembaca diajak mengikuti perjalanan iman, refleksi diri, dan transformasi. Maktub bukanlah buku yang berisi nasihat, melainkan sebuah pertukaran pengalaman, jalan terang untuk melihat kehidupan sesama kita di seluruh dunia dengan cara yang baru dan meninggalkan pesan yang tak terlupakan.', 'Rp 69,000', '208 pages', '07 August 2024', 'Latin American, Literary, novel literatur, novel sastra, literatur, sastra, Literature, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94627/624186017.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(89, '6782314b79bd51cee772b6a8', 'Outlive: Memikir Ulang Sains dan Seni Umur Panjang', 'Peter Attia', 'Diet & Health ,', '"Outlive benar-benar mengubah pendekatan saya dalam memahami proses penuaan. Peter Attia adalah salah satu orang paling brilian yang pernah saya temui. Dia berhasil mengemas sejumlah gagasan yang amat bernilai untuk hidup ke dalam buku ini. Ini akan menjadi salah satu buku paling penting yang pernah Anda baca." —Steven D. Levitt, rekan penulis buku laris menurut New York Times, Freakonomics"Peter Attia menjelajahi sains yang tidak hanya memperpanjang hidup, tetapi juga memperpanjang hidup yang bermakna. Dia membangun relasi yang penting antara kesehatan secara keseluruhan dan kesehatan relasional." —Esther Perel, penulis buku laris menurut New York Times, psikoterapis, dan pembawa acara siniar Where Should We Begin?"Akhirnya, kita memiliki panduan terkini, menyeluruh, jelas, dan dapat diterapkan tentang bagaimana memaksimalkan kesehatan kita saat ini serta jangka panjang. Berbasis data dan situasi riil, inilah buku panduan kesehatan yang paling akurat dan komprehensif yang pernah diterbitkan hingga saat ini. Outlive tidak hanya informatif, tetapi juga penting." —Andrew Huberman, Ph.D., profesor neurobiologi di Stanford University School of Medicine, penggagas siniar The Huberman Lab"Dr. Peter Attia adalah sosok yang saya percayai sepenuhnya dalam hidup. Dia berbeda dari yang lain karena mengusahakan kualitas hidup dari semua sudut pandang—kesehatan fisik, emosional, mental, hubungan, dan spiritual. Buku luar biasa ini adalah panggilan untuk bertindak. Buku ini akan membekali Anda dengan perangkat yang Anda butuhkan untuk menjalani hidup yang panjang, bermakna, dan memuaskan." —Hugh Jackman"Dalam Outlive, Peter Attia menghadirkan cara pandang yang terukur atas topik yang sedemikian kompleks: umur panjang. Komprehensif sekaligus ketat, buku ini penuh gagasan yang mengejutkan tentang penyakit-penyakit penuaan, serta taktik dan teknik yang dapat membantu kita hidup lebih lama serta sehat. Tulisan Attia mencengangkan dan mencerahkan, serta memprovokasi cara baru untuk memikirkan umur panjang." —Siddhartha Mukherjee, penulis buku pemenang Pulitzer Prize The Emperor of All Maladies dan buku laris menurut New York Times, The Song of the Cell', 'Rp 169,000', '550 pages', '07 August 2024', 'Self Transformation, buku pengembangan diri, kesehatan, Diet & Health, Diet, Self-Improvement, Self-Acceptance, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94602/624206005.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(90, '6782311279bd51cee772b68a', 'Ayo Belajar: Rasa Cemas', 'Pat-a-Cake', 'Picture Books', 'Semua orang pernah merasa cemas, tapi sangat penting untuk membicarakan apa yang sedang kaurasakan.“Belajar mengenali emosi orang lain merupakan kunci perkembangan sosial dan emosional. Buku ini cocok sekali untuk mendorong anak-anak membicarakan perasaan mereka.” —Dr Jacqueline Harding-Vallance, Konsultan Tumbuh Kembang Anak', 'Rp 139,000', '18 pages', '07 August 2024', 'Anak-anak, Anak, Pictures Book, picture books, buku anak gramedia, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94571/624116008.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(91, '6782319d79bd51cee772b6d4', 'TEESOL Marketing Management: Terandal Pantang Gagal,Pulang Membawa Cuan', 'Dr. Arif Yosodipuro, MM', 'Business Management & Leadership', 'Ada istilah sales dan marketing. Secara makna, sale berarti penjualan. Orangnya disebut salesman atau salesgirl. Sedangkan marketing artinya pemasaran. Orangnya biasa disebut marketing excecutive. Marketing merupakan bagian utama dari perniagaan atau perdagangan. Apalah artinya menghasilkan berbagai produk kalau tidak ada yang memasarkan?Meskipun begitu, Anda tidak bisa asal memasarkan sesuatu. Anda memerlukan manajemen pemasaran yang tepat untuk memperoleh hasil yang maksimal dan meminimalkan kerugian. Maka dari itu, TEESOL Marketing Management hadir untuk membantu Anda memetakan dan mengeksekusi strategi pemasaran yang paling tepat bagi bisnis Anda.', 'Rp 99,000', '150 pages', '31 July 2024', 'Bisnis, Business Management, Business, buku bisnis, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94646/Cover_TEESOL_Marketing_Management_3.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(92, '6782322279bd51cee772b71b', 'Heartbreak Motel (Cover Film)', 'Ika Natassa', 'Romance', 'Dalam hidup yang tidak pernah berhenti menyimpan misteri dan menyembunyikan arti, tidak selalu memberikan jawaban atas setiap pertanyaan, dan waktu bergulir—satu jam, satu momen, satu hari, satu minggu, satu bulan—pertanyaan dan permasalahan baru terus lahir sebelum yang lama sempat terurai, Ava menemukan panggilan hati sebagai aktris sejak usianya enam belas tahun. Berpindah dari satu peran ke peran lain—ada yang dia pilih, ada yang memilihnya—Ava berupaya membuat semua yang tidak dipahaminya tentang takdir menjadi terasa masuk akal. Dia tidak peduli bahwa setiap selesai memikul peran, dia harus menyepi, jungkir balik memulihkan diri di satu tempat yang disebutnya Heartbreak Motel.Di ulang tahunnya yang ketiga puluh, dimulai dari tempat itu, pertanyaan-pertanyaan baru menyergapnya tumpang-tindih, dihadirkan oleh tiga lelaki yang mengisyaratkan sekaligus mengecoh masa lalu, masa kini, dan masa depannya.', 'Rp 99,000', '400 pages', '31 July 2024', 'Novel, novel roman, Romance, romance novel, Ika Natassa, Heartbreak Motel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94717/624171006.jpg', '2026-02-17 06:53:48', '2026-02-17 06:56:44'),
	(94, '6782317479bd51cee772b6be', 'A Reflection and Contemplation for Eternity', 'Martin Basiang', 'Self-Improvement', 'A Reflection and Contemplation for Eternity is a memoir of life undergone as a traveler in this earthly life and awareness of how short our life is, in comparison with the real life in eternity. Death is the last chapter in earthly life, but the first chapter in eternity. The crowning achievement in the creation of the world was the creation of man in the image of God. It is appointed unto man once to die, but after this, we must all appear before the judgment seat of God.The three Abrahamic religions (Judaism, Christianity, and Moslem) claimed that their Holy Book are Apocalypse Book (The Revelation of Book from God). Abraham is the same Father of the believers. Even though they have their own Holy Book, such as Judaism has The Torah and Nevi’m a Talmud, Christian has The Bible (the Old Testament and the New Testament), and Moslem has Al-Quran and Hadist. They all believe the same judge would be on the doomsday but with different or specific names, i.e. Messiah for Judaism, Jesus Christ for Christianity, and “Imam Mahdi” for Moslem.Salomon has been through all the pleasure and pride of this earthly life, but at last, he discovered the meaning of life with his great conclusion, “Fear God and keep His command for this is man’s all. For God will bring every work into judgment, whether good or evil”. (Ecclesiastes 12: 13−14).', 'Rp 312,000', '172 pages', '31 July 2024', 'Self Improvement, Self-Acceptance, Self-Improvement, Self Improve, Self Transformation, pengembangan diri, buku pengembangan diri', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94624/Hum_-_A_Reflection_and_Contemplation_for_Eternity.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(95, '6782316b79bd51cee772b6b9', 'Rembulan Cerminan Hatiku (The Moon Represents My Heart)', 'Pim Wangtechawat', 'Science Fiction & Fantasy', 'Keluarga Wang menyimpan rahasia—mereka bisa menjelajahi waktu. Saat Joshua dan Lily pergi ke masa lalu dan tak pernah kembali, kedua anak mereka, Tommy dan Eva, harus sendirian berusaha mengarungi kesedihan.Eva berusaha menemukan tempatnya pada masa sekarang, sementara Tommy makin jauh tertarik ke masa lalu yang diharapkannya menyimpan jawaban.Penuh rasa dan harapan, terjalin sepanjang puluhan tahun dan melintasi berbagai benua, diceritakan dalam prosa memikat, The Moon Represents My Heart merupakan karya perdana tak terlupakan mengenai ikatan dahsyat antara sebuah keluarga tak biasa dan kekuatan untuk melanjutkan hidup.“Eksplorasi indah tentang keluarga, cinta, dan kehilangan, buku ini memberikan penyampaian segar dan fun tentang genre perjalanan waktu yang dikombinasikan dengan kisah emosional imigran...” —Gemma Chan, aktris, Crazy Rich Asians, Eternals', 'Rp 109,000', '432 pages', '31 July 2024', 'Romance Novels, Science Fiction & Fantasy, Fantasy, romance novel, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94619/624186015.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(96, '6782316d79bd51cee772b6ba', 'Upacara Kehidupan', 'Sayaka Murata', 'AsianLit - Japan', 'Di dunia normal Maho, menghormati mereka yang sudah meninggal berarti menyantap mereka sambil mencari pasangan inseminasi untuk melahirkan kehidupan baru dalam Upacara Kehidupan. Sementara itu, Nana menjunjung budaya yang menganggap manusia sebagai material paling menakjubkan untuk didaur ulang menjadi barang bermutu tinggi.Di tempat lain, ada orang-orang seperti Yoshiko yang tidak pernah berciuman selama 75 tahun hidupnya meski memiliki suami, Sanae yang merasa tidak seperti makhluk hidup dan karena itu amat mengagumi manusia, serta Haruka yang harus memilih satu dari lima persona untuk digunakan dalam upacara pernikahannya.Ini adalah kumpulan cerita pendek tak biasa tentang hal-hal yang biasa dilakukan manusia. Dan dijungkirbalikkannya tradisi serta norma dalam kisah-kisah ini meninggalkan pertanyaan: sebenarnya apa arti menjadi manusia?', 'Rp 79,000', '240 pages', '31 July 2024', 'Asian Literature, Asian Lit, asian, novel asian, AsianLit', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94620/624186016.jpg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(97, '67822f3479bd51cee772b58a', 'Anjing Mengeong, Kucing Menggonggong', 'Eka Kurniawan', 'Literary', '“Berbuatlah sedikit dosa, Jamal,” kata Sato Reang kepada satu kawan sekelasnya. Jamal anak yang saleh, selalu sembahyang lima kali sehari, juga rajin mengaji. “Pahalamu sudah banyak. Bertumpuk-tumpuk. Tak akan habis dikurangi timbangan dosamu.” Ini kisah Sato Reang. Kadang ia demikian intim dengan dirinya, sehingga ini merupakan cerita tentang aku, tapi kali lain ia tercerabut, dan ini menjadi kisah tentang Sato Reang. Isi kepalanya riuh dan berisik, terutama sejak ia berumur tujuh tahun, ketika sang ayah berkata kepadanya, “Sudah saatnya kau menjadi anak saleh.”', 'Rp 159,000', '148 pages', '31 July 2024', 'Eka Kurniawan, Literary, novel sastra, sastra', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94314/624202021.jpg', '2026-02-17 06:53:48', '2026-02-17 06:56:44'),
	(98, '6782316379bd51cee772b6b5', 'Thriving on Turbulence', 'Dr. Faizal Rochmad Djoemadi, M. Sc.', 'Business Management & Leadership', 'Pada 2020, Pos Indonesia mengalami double crisis, yaitu krisis pandemi Covid-19 dan krisis bisnis/keuangan. Buku ini memotret sepak terjang perusahaan agar tetap tumbuh di tengah turbulensi lingkungan bisnis dengan satu bekal: agility.', 'Rp 174,000', '432 pages', '31 July 2024', 'Busines, Business, Business Management', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94615/Hum_-_Thriving_on_Turbulence.jpeg', '2026-02-17 06:53:48', '2026-02-17 06:53:48'),
	(101, '6782306e79bd51cee772b633', 'Lost Connections: Penyebab Depresi yang Sesungguhnya dan Solusinya yang Tak Terduga', 'Johann Hari', 'Self-Improvement,', '“Pandangan yang brilian, menstimulasi, dan radikal tentang kesehatan mental.” —Matt Haig, penulis The Midnight LibraryJurnalis Johann Hari mengalami depresi sejak kecil dan mulai mengonsumsi antidepresan saat remaja. Ia diberitahu—seperti seluruh generasinya—bahwa penyebabnya adalah ketidakseimbangan kimiawi di otaknya. Sebagai orang dewasa yang terlatih dalam ilmu sosial, ia mulai mempertanyakan hal ini, dan akhirnya menyadari bahwa hampir semua hal yang diberitahukan kepada kita tentang depresi dan kecemasan itu salah.Ia menemui ilmuwan sosial di seluruh dunia, yang mengungkap penyebab depresi dan kecemasan yang sebenarnya. Sebagian besar penyebabnya ternyata tidak terletak pada otak kita, tetapi cara kita hidup saat ini. Perjalanan Hari membawanya ke komunitas Amish di Indiana dan masyarakat yang melakukan perlawanan di Berlin, menunjukkan wawasan baru mengenai depresi secara jelas dan dramatis. Buku ini menawarkan solusi yang sangat berbeda dari solusi yang selama ini ditawarkan kepada kita: solusi yang menawarkan harapan nyata.', 'Rp 159,000', '386 pages', '31 July 2024', 'Self Transformation, buku psikologi, buku pengembangan diri, Psychology, Self-Improvement, Self-Acceptance, pengembangan diri, Psikologi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94483/624221022.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(102, '67822f9179bd51cee772b5bc', 'Cara Ikat Tali Sepatu', 'Moonbug Entertainment', 'Picture Books', 'Gunakan buku ini bersama anak agar ia belajar mengikat tali sepatu sendiri. Berlatih mengikat tali sepatu bisa mengasah keterampilan motorik halus dan koordinasi mata dan jari.', 'Rp 149,000', '32 pages', '31 July 2024', 'Baby Picture, Baby Picture Book, Pictures Book, picture books, Picture book', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94364/623114011.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(103, '678230de79bd51cee772b66e', 'A Philanthropist\'s Guide to Giving', 'Asia Philanthropy Circle', 'Self-Improvement', 'A Philanthropist’s Guide to Giving adalah buku pegangan bagi para pegiat filantropi dan yayasan yang ingin mempraktikkan filantropi yang strategis dan berdampak di Asia. Hanya sedikit sumber daya di kawasan Asia yang dapat menjadi referensi di sepanjang perjalanan filantropi. Panduan ini mencakup semua poin yang relevan di berbagai tahapan perjalanan—mulai dari merancang strategi filantropi atau melibatkan anggota keluarga dalam kegiatan memberi, hingga mengevaluasi dampak filantropi atau mengupayakan kolaborasi sambil memberi.Jika Anda sendiri yang memulai perjalanan filantropi, panduan ini dimaksudkan sebagai sumber referensi Anda untuk melangkah. Hal ini bertujuan menjawab pertanyaan-pertanyaan terpenting Anda dengan memperkenalkan kerangka kerja yang berbeda dan menyoroti pertimbangan-pertimbangan utama. Panduan ini tidak akan menentukan satu cara terbaik untuk melakukan filantropi, tetapi akan membuat Anda lebih percaya diri dan terinformasi dalam menyusun pendekatan Anda sendiri.Secara khusus, panduan ini dirancang sesuai karakteristik di Asia, berdasarkan pembelajaran dari Asia Philanthropy Circle (APC) dan para anggotanya. Buku ini telah menyaring pembelajaran penting dari tujuh tahun keterlibatan mendalam dengan anggota APC; menampilkan 31 studi kasus mengenai para pegiat filantropi yang berbasis di Asia, yang menghadirkan realitas kegiatan memberi di Asia kepada Anda.Dengan menghadirkan pendekatan berbeda terhadap filantropi, model dan contoh terbaik di kelasnya, serta wawasan praktis dari anggota APC dan pembelajaran dari proyek APC, Anda akan mendapat bekal yang cukup untuk mengeksplorasi dan memperluas kegiatan memberi di Asia.', 'Rp 109,000', '310 pages', '24 July 2024', 'Self-Improvement, Self-Acceptance, pengembangan diri, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94543/624221025.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(104, '6782315f79bd51cee772b6b3', 'Trending Topic', 'Niallgina', 'MetroPop', 'Maudya Wirasesa, aktris A-list yang selalu menempati trending topic, disukai oleh netizen berkat perannya di film bersama Ragil Adriano, hingga netizen menjuluki mereka sebagai Nation’s Favorite Couple.Handi Fachriansyah, psikolog dan presenter program acara kesehatan mental ‘PsyLife’, berhasil mencuri hati netizen sebagai idola baru kaum hawa berkat ketampanan dan kepiawaiannya dalam memahami perasaan orang lain. Namun, bagaimana jika Handi tidak hanya mencuri hati netizen, tetapi juga hati Maudya Wirasesa?Sayangnya, netizen tak menyukai kedekatan mereka. Netizen lebih menginginkan Maudy tetap bersama Ragil, dan menyingkirkan Handi dari fantasi mereka terhadap Maudy dan Ragil.Lantas, apakah Maudy dan Handi harus merelakan cinta mereka demi mengikuti kemauan netizen? Atau justru rela dibenci demi kehidupan yang mereka inginkan?', 'Rp 89,000', '328 pages', '24 July 2024', 'Romance Novels, romance novel, Romance, Metropop', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94613/624171005.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(105, '6782312479bd51cee772b693', 'CoComelon: Mewarnai dan Menempel', 'Moonbug Entertainment', 'Activity Books', 'BUKU MEWARNAI DENGAN STIKERBuku ini cocok untuk para seniman kecil!Kau bisa menempelkan stiker yang sesuai dengan gambar yang ingin kauwarnai. Mewarnai berdasarkan pola bisa melatih ketelitian dan keterampilan motorikmu, serta memberikan pengalaman yang menyenangkan bersama karakter-karakter favoritmu!', 'Rp 59,000', '24 pages', '24 July 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94581/624114012.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(106, '6782314f79bd51cee772b6aa', 'Think Straight', 'Darius Foroux', 'Self-Improvement,', '"Saya ingin tahu apa yang atasan pikirkan." "Apa yang terjadi jika saya gagal atau kehilangan pekerjaan?" "Apakah dia mencintaiku?" "Bagaimana jika saya kena kanker?" “Saya tidak bisa menyelesaikan apa pun. Apa salah saya?Pikiran adalah alat paling ampuh di muka bumi. Sayangnya, sering kali kepala kita justru dipenuhi 99% hal tak berguna: khawatir, stres, panik—dan masih banyak lagi.Think Straight: Berpikir Jernih membagikan cara untuk mengendalikan pikiran-pikiran tersebut. Dengan berlatih, kita mampu memutuskan apa yang kita pikirkan, bahkan memilih untuk tidak berpikir. Pengendalian ini bisa meningkatkan kehidupan, karier, relasi, dan bisnis kita.Buku ini ditulis sedemikian rupa agar bisa dibaca berulang kali dan layak dijadikan jangkar—terutama dalam masa-masa sulit.', 'Rp 79,000', '124 pages', '17 July 2024', 'Self Transformation, buku pengembangan diri, Self-Improvement, Self-Acceptance, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94604/624221031.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(107, '6782321a79bd51cee772b717', 'Negara Paripurna (2024)', 'Yudi Latif', 'Social Sciences,', '“Sangatlah melegakan dan membanggakan bahwa dalam keterpurukan yang sedang dialami oleh bangsa kita, muncul seorang intelektual muda, Yudi Latif, yang mampu menjabarkan dan memperkaya Pancasila sampai pada akar-akar sejarahnya. Buku ini patut disebarluaskan dan dijadikan bacaan wajib bagi setiap warga negara Indonesia.” –Kwik Kian Gie– Ekonom, Penggerak Pendidikan dan Mantan Menteri Koordinator Perekonomian“Buku ini menunjukkan posisi dan kelas Yudi Latif sebagai intelektual-aktivis yang memiliki panggilan moral-intelektual tinggi untuk memantapkan Pancasila sebagai jati diri bangsa Indonesia dengan pendekatan ilmiah. Saya yakin buku ini akan menjadi karya klasik yang selalu bisa jadi rujukan siapa pun yang ingin mengenal dan mendalami jati diri bangsa Indonesia. Buku ini wajib dimiliki dan dibaca oleh para aktivis sosial, politisi, dan penyelenggara pemerintahan.” –Prof. Dr. Komaruddin Hidayat– Mantan Rektor UIN Syarif Hidayatullah Jakarta“Dalam buku Negara Paripurna ini, Yudi Latif tidak hanya menunjukkan keluasan pengetahuan namun juga kejernihan dan ketajaman seorang intelektual merdeka yang dilahirkan bangsa ini. Membaca buku ini, kita disadarkan bahwa para pendiri bangsa, dengan keluasan wawasan, ketulusan niat, kesungguhan mencapai yang terbaik serta tanggung jawabnya kepada nusa dan bangsa, telah mewariskan kepada kita suatu dasar falsafah dan pandangan hidup negara yang begitu visioner. Sebuah buku yang bisa menjadi lentera untuk memandu bangsa ini keluar dari kegelapan dan keterpurukan.” –Prof. Dr. Ahmad Syafii Maarif– Mantan Ketua Umum PP Muhammadiyah dan Pendiri Maarif Institute“Yudi Latif mampu menafsirkan Pancasila secara kontekstual dan sarat dengan napas pluralisme dan inklusivisme. Ketuhanan Yang Maha Esa dia ‘reword’ menjadi Ketuhanan yang Berkebudayaan. Pancasila menjadi begitu hidup! Buku ini sungguh wajib dibaca oleh berbagai kalangan profesi, dihayati, dan kemudian kita jalani dalam kehidupan sehari-hari.” –Sudhamek AWS– Ketua Majelis Buddhayana Indonesia', 'Rp 200,000', '736 pages', '17 July 2024', 'Social & sciences, Social Science, Social Sciences', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94713/624221032.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(108, '6782315379bd51cee772b6ac', 'Aku yang Sudah Lama Hilang', 'Nago Tejena', 'Self-Improvement,', '“Diramu untuk memahami dirimu, ditulis untuk mengembalikan jiwa yang lama kamu abaikan.” —Jiemi Ardian, PsikiaterKapan terakhir kali kamu merasa bahagia? Bangun dengan perasaan ringan, memiliki semangat untuk pergi bekerja, serta dikelilingi oleh orang-orang yang kamu sayangi?Tak terasa kehidupan dewasa sering kali menguras diri kita secara perlahan. Tang- gung jawab yang bertambah banyak, berbagai masalah yang datang silih berganti, atau ekspektasi dari lingkungan sekitar yang membebani. Kita pun tetap berusaha melewati seluruh tantangan tersebut... tanpa menyadari kalau kita sedang perlahan menghilang dalam prosesnya.Apabila kamu sedang berada di posisi ini dan merasa bahwa ini waktu yang pas untuk kembali menemukan dirimu, maka kamu telah bertemu dengan buku yang tepat. Bersama buku ini, kita akan belajar untuk mulai mendengarkan pikiran dan perasaan dari dalam diri, memiliki hubungan yang baik dengan diri, serta membuat pilihan hidup yang terbaik untuk diri.Terdengar sedikit egois? Memang.', 'Rp 89,000', '208 pages', '10 July 2024', 'buku pengembangan diri, Self-Improvement, Self-Acceptance, pengembangan diri, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94606/624221030.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(109, '6782312879bd51cee772b695', 'Dua Puluh Sajak Cinta dan Satu Nyanyian Putus Harapan', 'Pablo Neruda', 'Poetry,', 'Pagi yang penuh badai di jantung musim panas.Awan berarak seperti saputangan putih perpisahan, angin melambai-lambaikan mereka di gerak tangannya.Jantung angin yang tidak terbilang jumlahnyaMengalah-alihkan kesunyian kita dalam cinta.Berdengung di sela pepohonan, agung bagai orkestra, seperti bahasa dipenuhi peperangan dan nyanyian.Angin dengan lihai menyapu daun-daun gugur membelokkan kawanan panah burung gemetar.Angin menjatuhkannya di gelombang tanpa buih, inti ringan tanpa bobot, dan permainan cahaya miring.Meredakan dan membenamkan ciuman-ciuman berat yang ganas bertarung di gerbang angin musim panas.', 'Rp 89,000', '56 pages', '10 July 2024', 'Sastra Amerika Latin, Latin American, buku puisi, Kumpulan Puisi, Poetry, Puisi, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94583/624186010.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(110, '6782302879bd51cee772b60d', 'The Miracle of Oral Albumin: Natural Channa striata Extract', 'Cipto Kokadir', 'Science & Nature', 'In 1941, amidst the Pearl Harbor attack, a noteworthy revelation regarding the lifesaving capabilities of albumin came to light. Research on the benefits of albumin for human health continues to this day.It was discovered that albumin can be found in an unexpected source: the snakehead fish, also known as Channa striata. The development of Channa striata as a source of albumin has opened the door to utilizing natural resources for albumin production.Onoiwa® (Channa striata extract) has been used therapeutically at major hospitals, maternal and children’s hospitals, geriatric clinics, diabetes wards, cancer wards, cardio wards, endocrine wards, emergency wards, and many more. The low- temperature extraction technology has resulted in highly effective albumin.Nucleus Farma has intensively engaged in research with numerous universities both in Indonesia and abroad. Clinical experiences by multiple medical doctors with over 12.000 patients have confirmed the benefit of this nutrient-rich superfood, oral albumin.This book, based on literature, presents a comprehensive explanation of albumin and its vital role in the human body. It is highly recommended for health practitioners, such as doctors, nurses, pharmacists, dietitians, and medical researchers, as well as anyone interested in studying albumin, oral albumin, and its benefits.', 'Rp 119,000', '212 pages', '10 July 2024', 'Sciences & Nature, Science & Nature, science', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94445/624220001.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(111, '6782315679bd51cee772b6ae', 'Merelakan Sam (You\'ve Reached Sam)', 'Dustin Thao', 'Romance', 'Meski baru berumur 17 tahun, Julie sudah punya rencana hidup yang tersusun rapi. Yang paling penting adalah pindah dan berkuliah di kota lain bersama pacarnya, Sam. Namun, Sam meninggal… dan segalanya berubah.Julie hancur lebur. Dia berjuang melupakan Sam serta kejadian tragis yang menewaskan cowok itu. Dia ingin sekali merasakan lagi kehadiran Sam dan mendengar suara cowok itu. Sampai suatu ketika, di tengah keputusasaannya, dia menghubungi ponsel Sam.Lalu, Sam menjawab telepon itu….Julie tahu ini seharusnya mustahil, tapi suara yang didengarnya memang suara Sam. Tak ada yang bisa menjelaskan, Sam pun tidak. Keajaiban ini memberinya kesempatan untuk mengucapkan selamat tinggal. Tapi, benarkah ini akan membantunya merelakan Sam? Atau justru akan makin sulit?', 'Rp 99,000', '376 pages', '10 July 2024', 'Romance Novels, kisah romantis, romance novel, romantis, novel roman, Roman, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94608/624160005.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(112, '6782314d79bd51cee772b6a9', 'Kitab Suci Kesatria Cahaya (Manual of the Warrior of the Light)', 'Paulo Coelho', 'Latin American Literature', 'Kesatria Cahaya kadang-kadang berperilaku seperti air, mengalir memutari penghalang-penghalang yang dijumpainya. Aliran air sungai menyesuaikan dirinya dengan alur apa pun yang tampak mungkin, tetapi sang sungai. tak pernah melupakan tujuannya, yakni laut. Meski sangat rapuh dari sumber mata airnya, perlahan tapi pasti dia mengumpulkan kekuatan demi kekuatan dari sungai-sungai lain yang dijumpainya.Kitab Suci Kesatria Cahaya adalah ajakan bagi kita semua untuk mewujudkan impian, menerima ketidakpastian dalam hidup, dan bangkit untuk menyongsong takdir pribadi kita yang unik. Ada sosok sang Kesatria Cahaya di dalam diri setiap orang. Jalan Kesatria Cahaya tak selalu mudah, tetapi dia menerima kegagalan-kegagalannya dan berjuang tak kenal lelah untuk memenuhi Legenda Pribadi-nya.', 'Rp 59,000', '152 pages', '10 July 2024', 'Sastra Amerika Latin, Latin American, Literatures, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94603/624186013.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(113, '6782321879bd51cee772b716', 'Catatan Harian Menantu Sinting', 'Rosi L. Simamora', 'Adult,', 'Aku Minar. Ini cerita cinta versi aku dan Sahat (dan... Mamak Mertua). Seru. Ngeselin. Gemesin. Sekaligus sangat menantang. Ditambah latar belakang keluarga besar Batak yang penuh drama dan asumsi, kisah-kisahku lebih sering berakhir konyol dan nyaris bikin aku frustrasi.Apalagi aku dan Mamak Mertua punya kepercayaan berbeda tentang cinta dan kebahagiaan, terutama kalau menyangkut Sahat, kesayangan kami berdua.Dengan bahasa yang ringan, cerita ini sengaja dikemas untuk membuat pembacanya terbahak-bahak.', 'Rp 79,000', '248 pages', '03 July 2024', 'Metropop, lokal, Novel dewasa', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94712/624171004.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(114, '678230d879bd51cee772b66b', 'Disney: Warnai Duniaku', 'Disney', 'Activity Books', 'Bergabunglah dengan karakter Disney•Pixar favoritmu dalam buku mewarnai keren ini! Temukan perbedaan bersama Woody, menghitung ikan bersama Nemo, mewarnai semua mobil di film Cars, dan masih banyak aktivitas menarik lainnya!', 'Rp 89,000', '64 pages', '03 July 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94540/624110016.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(115, '678230d479bd51cee772b669', 'Disney Learning: Disney Frozen: Belajar Matematika', 'Disney', 'Activity Books', 'AYO BERGABUNG BERSAMA ELSA, ANNA, DAN OLAF DALAM PERTUALANGAN BELAJAR MATEMATIKA YANG MENYENANGKAN!Buku ini dilengkapi berbagai aktivitas menyenangkan yang didesain untuk mengasah kemampuan matematika, membangun kepercayaan diri, dan menemani keseharian si kecil.KEMAMPUAN BERHITUNG: Belajar perjumlahan, pembagian, dan waktu.MEMECAHKAN MASALAH: Cari tahu bagaimana cara memecahkan puzzle angka.', 'Rp 79,000', '64 pages', '03 July 2024', 'Anak-anak, Aktivitas, Anak, disney frozen, disney, frozen, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94538/624110013.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(116, '6782307279bd51cee772b635', 'Disney Learning: Belajar Menulis Sambung', 'Disney', 'Activity Books', 'Ayo belajar menulis sambung bersama Miguel, Dante, Hector, dan teman-teman lain. Dari Aa sampai Zz—Abuelita sampai zona—buku ini akan membawamu menyeberangi Jembatan Marigold sambil menelusuri huruf besar dan kecil dalam menulis sambung. Jadi, tunggu apa lagi? Apa kau siap mempelajari dasar-dasar menulis sambung dan mendapat pujian di sekolah?', 'Rp 59,000', '32 pages', '03 July 2024', 'Anak-anak, Anak, buku anak gramedia, Buku anak, Aktivitas, Activity Book, Activity Books', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94485/624110008.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(117, '6782310679bd51cee772b684', 'CoComelon: Buku Asyik Mewarnai', 'Moonbug Entertainment', 'Activity Books', 'Selamat datang di dunia CoComelon yang ceria! Dalam buku stiker ini, kau bisa bersenang-senang dan mewarnai berbagai macam gambar serta bermain bersama bonus stiker di dalamnya!', 'Rp 39,000', '12 pages', '03 July 2024', 'Anak-anak, Anak, Activity Book, Activity Books, buku anak gramedia, Fiksi, Buku anak, Mewarnai, Stiker', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94565/624114011.jpg', '2026-02-17 06:56:44', '2026-02-17 06:56:44'),
	(121, '678230f679bd51cee772b67b', 'Win Your Inner Battles', 'Darius Foroux', 'Self-Improvement,', 'Apakah Anda ingin mengubah karier atau memulai bisnis? Tak mau kehilangan waktu istirahat karena mengejar tenggat? Ingin mengakhiri suatu hubungan, atau sekadar menjalani kehidupan yang memuaskan?Setiap orang punya tujuan dan ambisi dalam hidup, namun seringkali kita tidak mengejarnya karena rasa takut atau kurang percaya diri. Dalam Win Your Inner Battles, Penulis menunjukkan cara efektif untuk:menaklukkan rasa takut,meningkatkan rasa percaya diri,menghalau rasa khawatir, danmenjalani kehidupan sesuai keinginan kita.Penulis menegaskan bahwa seburuk apa pun keadaan kita, selalu ada jalan keluar. Bersiaplah untuk menjalani kehidupan sesuai keinginan Anda!', 'Rp 89,000', '192 pages', '26 June 2024', 'buku pengembangan diri, Self-Improvement, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94556/624221027.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(122, '6782310379bd51cee772b682', 'Hidangan di Atas Awan', 'Silvia Iskandar', 'Novel', 'Leo ketahuan menipu ayahnya! Selama beberapa tahun, biaya kuliah arsitektur di Australia dari ayahnya malah dipakai untuk belajar di akademi kuliner. Sejak itu hubungan mereka rusak. Mereka berhenti saling bicara, sementara sang ibu menjadi penengah yang turut dipersalahkan.Leo lalu pulang ke Indonesia, membawa mimpi dan rasa percaya diri bahwa ia sanggup meraih kesuksesan. Ia pun membangun Argo, restoran pertama, harga diri, dan cinta matinya. Menu-menu diracik, tenaga-tenaga ahli dipekerjakan, program-program promosi disiapkan.Namun, Argo tidak menarik pengunjung. Bangku-bangku kian hari kian sepi, pegawai mundur satu per satu, hingga akhirnya Argo bangkrut dan tutup.Dengan berat hati, Leo mengakui kekalahan. Ia mengurung diri di sudut apartemen kecilnya, mempertanyakan ego dan arogansinya. Ternyata membangun bisnis sukses seperti yang ayahnya lakukan tidaklah semudah membalik telapak tangan. Kini Leo dihadapkan pada dua pilihan; bangkit atau tenggelam dalam kekalahan.', 'Rp 89,000', '256 pages', '26 June 2024', 'slice of life, novel remaja, novel roman, Novel dewasa, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94563/624171003.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(123, '6782314079bd51cee772b6a2', 'Akselerasi Jokowi: Dari Batang Menjangkau Global (HC)', 'Kristin Samah', 'Social Sciences', 'Indonesia membutuhkan pertumbuhan ekonomi yang tinggi untuk mencapai kesejahteraan seluruh rakyat yang jumlahnya sudah mencapai 270 juta jiwa. Pertumbuhan ekonomi yang tinggi pada jumlah penduduk yang besar hanya bisa terwujud jika ada lapangan pekerjaan yang banyak. Di satu sisi, lapangan pekerjaan yang banyak hanya dimungkinkan lewat investasi yang besar.Kawasan Industri Terpadu Batang atau Grand Batang City adalah terobosan yang dilakukan Pemerintah Indonesia dalam membuka seluas-luasnya pintu investasi. Proyek kota industri di kawasan seluas 4.300 hektare ini menjadi babak baru dalam usaha mengukuhkan Indonesia sebagai kekuatan baru di Asia yang perlu diperhitungkan. Harapannya, Grand Batang City mampu meningkatkan daya saing Indonesia yang harus berhadapan dengan Vietnam, Thailand, dan Malaysia.', 'Rp 679,000', '300 pages', '26 June 2024', 'Social & sciences, Social Science, indonesia, Social Sciences', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94596/Hum_-_Akselerasi_Jokowi_Dari_Batang_Menjangkau_Global.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(126, '6782315179bd51cee772b6ab', 'Pelindung Sang Lady (The Bachelor)', 'Sabrina Jeffries', 'Historical Romance', 'Gwyn berusia tiga puluh dan belum menikah, bahkan baru hendak melakukan debutnya. Namun itu tidak berarti ia tak tahu apa-apa tentang pria. Ia pernah punya kekasih, namun sekarang pria itu malah memerasnya. Ia tak seratus persen jujur dengan keluarganya, namun mereka tahu pria itu berbahaya. Karena itulah Major Joshua Wolfe, mantan pahlawan perang, ditugaskan sebagai pengawalnya selama Gwyn di London.Joshua punya alasan sendiri untuk pergi ke London. Jika melindungi wanita yang menawan dan percaya diri, mengajarinya memanah dan berdebat dengannya adalah satu-satunya jalan untuk sampai ke sana, ia akan dengan senang hati melakukan semua itu. Namun bagaimana jika perasaannya yang berkembang untuk Gwyn merupakan bahaya sesungguhnya?', 'Rp 99,000', '376 pages', '26 June 2024', 'Historical Romance, Romance, Roman, novel roman, romantis, romance novel, kisah romantis, Romance Novels, Novel dewasa', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94605/Fiksi_-_Pelindung_Sang_Lady_(The_Bachelor).jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(127, '6782312979bd51cee772b696', 'Di Mana Donal? Mencari Tempat Bersantai', 'Disney', 'Picture Books', 'Yang Donal inginkan hanyalah tempat untuk bersantai, tetapi ke mana pun ia pergi selalu ramai! Carilah Donal beserta teman-teman dan keluarganya yang bepergian keliling dunia! Lihatlah ke halaman paling belakang untuk daftar karakter dan benda yang tersembunyi di setiap tempat.', 'Rp 69,000', '44 pages', '26 June 2024', 'Pictures Book, picture books, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94584/624110019.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(128, '6782314679bd51cee772b6a5', 'Agensi Rumah Tangga', 'Almira Bastari', 'MetroPop', 'PHK! Tiga huruf yang mengguncang dunia Katia yang selama ini bangga banget kerja di startup. Berbulan-bulan menganggur, terjepit cicilan KPR, ditambah ocehan ibunya yang pensiunan PNS, Katia nekat membuat rumahnya menjadi yayasan penyalur pembantu.“Agensi Rumah Tangga, solusi untuk rumah tangga Anda. Ada yang bisa saya bantu?” adalah tagline Katia. Mengadu keberuntungan dengan cara memilih siapa yang paling cocok untuk tiap calon majikan, membuat hidup Katia yang pengangguran makin penuh drama, mulai dari pembantu genit, suka pinjam duit, sampai yang suka berkelit!Apakah Katia akan selalu berhasil menempatkan tiap ART ke majikan yang tepat, agar bisa dapat uang cepat, demi menyelamatkan rumah yang cicilannya nyaris telat?', 'Rp 89,000', '272 pages', '26 June 2024', 'Metropop, novel roman, Novel, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94599/624171001.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(129, '6782311d79bd51cee772b690', 'Jini, Jinny', 'Jeong You-Jeong', 'AsianLit - Korea', 'Suatu malam, Lee Jini, salah seorang penjaga simpanse di Pusat Riset Primata, menerima telepon yang meminta bantuan untuk mengamankan seekor bonobo yang melarikan diri. Begitu berhadapan dengan bonobo yang dimaksud, anehnya Jini merasa pernah bertemu dengan bonobo itu. Namun, mustahil bonobo itu sama dengan bonobo yang pernah ditemuinya berbulan-bulan lalu di belahan dunia lain.Dalam perjalanan pulang ke Pusat Riset Primata bersama si bonobo kecil, yang berhasil diamankan dan untuk sementara diberi nama Jinny, mobil yang ditumpangi Jini mengalami kecelakaan. Ketika tersadar kembali, Jini mendapati jiwanya mendekam dalam tubuh Jinny si bonobo kecil. Entah bagaimana dan entah apa yang terjadi, Jini kini adalah Jinny.Jini tahu ia harus kembali ke tubuhnya sendiri yang saat ini terbaring tak sadarkan diri di rumah sakit. Namun, satu-satunya orang yang bisa membantunya adalah Kim Min-ju, pria pengangguran sekaligus gelandangan, juga satu-satunya saksi kecelakaan maut tersebut.Jini hanya punya waktu tiga hari untuk kembali ke tubuhnya sendiri, sebelum jantungnya berhenti berdetak.', 'Rp 99,000', '414 pages', '26 June 2024', 'Korea, Fiksi, Novel, AsianLit', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94577/624186012.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(130, '678230e979bd51cee772b674', 'Disney Pixar - Inside Out 2: Tidurlah, Anxiety!', 'Disney Pixar', 'Picture Books', 'Setelah menjalani hari yang panjang, saatnya Riley pergi tidur. Tapi bukan hanya dia yang butuh istirahat—semua Emosinya juga perlu! Ketika Disgust jaga malam di Ruang Pengendali, Joy, Sadness, Anger, dan Fear menutup hari. Emosi baru Riley, Embarrassment, Envy, dan Ennui mengantuk. Mereka satu per satu tertidur sampai Kantor Pusat menjadi hening.Tapi, ternyata ada satu Emosi yang tidak bisa tidur: Anxiety! Anxiety resah, merasa cemas, dan tidak bisa menenangkan pikirannya. Tak lama, keresahannya membangunkan para Emosi lain. Bisakah mereka membantu teman yang resah ini untuk tidur?', 'Rp 59,000', '40 pages', '26 June 2024', 'Anak-anak, Anak, Pictures Book, picture books, buku anak gramedia, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94549/624110015.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(131, '6782311779bd51cee772b68d', 'The Ex Talk', 'Rachel Lynn Solomon', 'Romance', 'Shay Goldstein nyaris satu dekade menjadi produser di stasiun radio Seattle, dan ia tak bisa membayangkan kerja di tempat lain. Tapi akhir-akhir ini ia terus berselisih dengan kolega terbarunya, Dominic Yun, yang baru saja mendapatkan gelar master dan merasa paling tahu tentang siaran radio. Ketika stasiun radio mereka mengalami kesulitan dan membutuhkan konsep baru, Shay mengajukan acara yang disetujui bosnya dengan penuh semangat: The Ex Talk, acara seputar hubungan asmara yang dipandu dua mantan pacar. Bos mereka memutuskan Shay dan Dominic adalah pasangan pemandu acara yang sempurna, mengingat betapa mereka saling membenci. Tak seorang pun dari mereka mau berbohong pada para pendengar radio, tapi pilihan mereka hanya ini atau PHK. Tidak butuh waktu lama hingga acara mereka menarik hati para pendengar, dan The Ex Talk pun menjadi siniar yang sangat populer. Seiring semakin besar jumlah pendengar mereka, semakin besar juga kebohongan mereka. Terutama ketika Shay dan Dominic mulai saling jatuh hati terhadap satu sama lain.', 'Rp 169,000', '392 pages', '26 June 2024', 'kisah romantis, romance novel, novel remaja, romantis, novel roman, Novel dewasa, Roman, Novel, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94574/624184006.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(132, '6782314779bd51cee772b6a6', 'Kronik Sebuah Kematian (Chronicle of A Death Foretold)', 'Gabriel García Márquez', 'Latin American Literature', 'Seorang pria pulang ke kota asalnya untuk mengulik pembunuhan yang terjadi lama berselang. Dua puluh tujuh tahun silam, Bayardo San Roman mengembalikan istrinya yang cantik, Angela Vicario, kepada mertuanya, hanya beberapa jam setelah menikah, dengan alasan si istri tidak perawan. Pedro dan Pablo Vicario, kakak kembar Angela, lantas pergi mencari Santiago Nasar, kekasih Angela yang dituding sebagai biang keladi permasalahan ini.Sebelum membunuh Santiago, si kembar Vicario mengumumkan niat mereka itu kepada seisi kota. Semua orang tahu persis akan ada pembunuhan, tapi kenapa tidak seorang pun bertindak dan berusaha mencegahnya? Makin lama urusannya makin pelik dan berujung pada akhir yang sungguh tak bisa dijelaskan.', 'Rp 69,000', '128 pages', '26 June 2024', 'Sastra Amerika Latin, Latin American, Gabriel Garcia Marquez, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94600/624186011.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(133, '6782315479bd51cee772b6ad', 'Bias, Obsesi', 'Rin Usami', 'AsianLit - Japan', 'Akari amat sangat terpesona oleh Ueno Masaki, salah satu anggota grup populer mazama-ZA. Melalui blog yang ditulisnya dengan mendetail, ia berusaha menganalisis setiap gerak-gerik Masaki agar bisa menyelami setiap sisi kehidupan pemuda itu. Baginya, Masaki bukan sekadar idola, melainkan jangkar di tengah lautan ketidakpastian. Siapa sangka, di balik sosok penggemar yang penuh dedikasi ini, bersembunyi seorang remaja canggung yang tidak memiliki semangat untuk menjalani hidup.Dunia Akari terguncang ketika kabar mengenai Masaki yang memukul penggemar viral di media sosial. Seiring reputasi Masaki yang kian memburuk, hidup Akari pun ikut hancur. Namun, alih-alih mencari cara melepaskan diri demi menyelamatkan kewarasannya, Akari justru semakin terobsesi dengan sang idola.', 'Rp 69,000', '160 pages', '26 June 2024', 'AsianLit, novel asian, asian, Asian Lit, Asian Literature, Asian Philosophy, japan literature', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94607/Fiksi_-_Bias_Obsesi.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(134, '6782307079bd51cee772b634', 'Conversations on Love', 'Natasha Lunn', 'Self-Improvement,', '"Buku yang mungkin akan mengubah hidup Anda." —Sunday Times"Buku yang memukau dan penuh makna." —Pandora SykesSetelah bertahun-tahun merasa bahwa cinta selalu berada di luar jangkauan, jurnalis Natasha Lunn mencoba memahami bagaimana cinta bekerja dan berkembang sepanjang hidup. Dia menemui para penulis, terapis, tokoh budaya, dan pakar untuk mempelajari pengalaman mereka, mulai mendalami kompleksitas cinta, kemudian bertanya: Bagaimana kita menemukan cinta? Bagaimana kita mempertahankannya? Dan bagaimana kita bisa bertahan ketika kehilangannya?Melalui dialog di buku ini, Lunn mengeksplorasi bentang emosi yang luas: sensasi cinta baru, kekuatan persahabatan yang saling peduli, ketegaran yang dibutuhkan saat kehilangan, dan dinamika hubungan jangka panjang yang terus berkembang. Lunn menekankan bahwa cinta mencakup jauh lebih dari sekadar hubungan romantis. Dia menyoroti pentingnya cinta platonis, ikatan keluarga, dan cinta diri.', 'Rp 149,000', '368 pages', '26 June 2024', 'Self Transformation, buku pengembangan diri, Self-Improvement, Self-Acceptance, cinta, pengembangan diri, love, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94484/624221023.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(135, '6782314979bd51cee772b6a7', 'Perjalanan Mustahil Samiam dari Lisboa: Sepasang Elang dari Diyarbakir', 'Zaky Yamani', 'Literary', 'Saat sendirian di sebuah kedai di Konstantinopel, Samiam Nogueira dipukul sampai pingsan dan diculik. Kaki tangan Takhta Suci ternyata berhasil mengendus keberadaannya. Petualang yang telah melangkahkan kakinya jauh dari tanah kelahirannya di Lisboa itu kembali terpisah dari cinta sejatinya, Bianca. Kebersamaan mereka direnggut paksa oleh kekuatan-kekuatan yang tak terbayangkan sebelumnya.Samiam harus menempuh perjalanan sebagai budak, jauh sampai ke pedalaman Arabia. Sementara Bianca dan ayahnya, João Nogueira, dipaksa mengikuti misi rahasia mematikan yang dirancang Kekaisaran Ottoman. Mereka tidak tahu sedang terlibat permainan yang didalangi kekuatan-kekuatan besar di Timur Tengah.Apakah Samiam bisa membebaskan diri dari perbudakan dan kembali menemukan Bianca dan João? Apakah mereka bisa meloloskan diri dari jeratan konspirasi brutal kekuatan- kekuatan yang sedang bertarung di Timur Tengah?Apakah perjalanan ini akan menjadi semakin mustahil bagi Samiam?', 'Rp 89,000', '256 pages', '26 June 2024', 'Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94601/Fiksi_-_Perjalanan_Mustahil_Samiam_2.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(136, '6782306979bd51cee772b630', 'Disney Learning: Disney Princess: Menulis ABC', 'Disney', 'Activity Books', 'Belajar ABC itu menyenangkan! Ayo menulis huruf besar dan kecil bersama Tiana, mencocokkan huruf dan cara baca bersama Ariel, serta bermain aktivitas bersama Jasmine. Jadi, tunggu apa lagi? Jelajahi dunia ABC bersama!', 'Rp 79,000', '64 pages', '26 June 2024', 'Aktivitas, Activity Book, Activity Books, disney', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94480/624110009.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(137, '6782310e79bd51cee772b688', 'Ducktales: Mewarnai & Aktivitas', 'Disney', 'Activity Books', 'Disney DuckTales Mewarnai & Aktivitas Bonus PuzzlePetunjuk: 1. Minta bantuan orang dewasa untuk menggunting.2. Susun potongan gambar sampai menjadi gambar utuh.', 'Rp 89,000', '84 pages', '26 June 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94569/624110018.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(138, '6782306a79bd51cee772b631', 'Disney Learning: Pixar: Membaca ABC', 'Disney Pixar', 'Activity Books', 'Siap-siap untuk petualangan membaca ABC! Ayo belajar menulis huruf besar dan huruf kecil bersama Woody dan Bo, berlatih memperkuat ingatanmu bersama Lighting McQueen, dan menyelami berbagai permainan dan aktivitas ABC yang seru.', 'Rp 79,000', '64 pages', '26 June 2024', 'Aktivitas, Activities, Activity Book, Activity Books', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94481/624110010.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(139, '678231cc79bd51cee772b6ed', 'Fransiskus, Manusia Pendoa (Cover 2024)', 'Mario Escobar', 'Lomba Ulasan Sewindu Bincang Buku,', 'Pertama dari Jesuit, Pertama dari Amerika LatinJorge Mario Bergoglio, yang sekarang menjadi Paus Fransiskus, adalah seorang pendoa sekaligus pekerja. Ia adalah sosok bersahaja yang selalu mementingkan orang lain. Meski tampak polos dan sederhana, Paus Fransiskus memiliki latar belakang teologis yang tidak tanggung-tanggung. Ia adalah seorang tokoh besar, tetapi masih menempuh perjalanan dengan kereta bawah tanah dan bus seperti kebanyakan warga biasa. Tak kenal lelah dalam memerangi kemiskinan dan marginalisasi, ia menjadi pembawa harapan bagi kaum miskin dan tertindas.Kerendahan hati, semangat, dan ketabahannya dalam memimpin Gereja, khususnya menghadapi rupa-rupa tantangan zaman, lahir dari kehidupan doa yang mendalam. Doa, bagi Paus Fransiskus, adalah perpaduan antara keberanian, kerendahan hati, dan penyembahan. Doa selalu mengubah kenyataan: jika kenyataan di sekitar kita tidak berubah, setidaknya hati kita berubah. Dan, tidak ada doa yang tidak didengarkan; Allah selalu menanggapi doa-doa kita.Buku ini merupakan biografi seorang sosok lemah lembut yang tiba-tiba menjadi salah satu orang paling berpengaruh di planet ini. Dalam buku ini, tampak bagaimana doa sungguh menjadi sumber kekuatan utama bagi hidup dan pelayanannya. Mungkinkah musim semi bagi Gereja Katolik akhirnya tiba setelah dilanda musim dingin yang sangat panjang?', 'Rp 79,000', '216 pages', '19 June 2024', 'buku pengembangan diri, Paus Fransiskus, Religion, buku religi, Self-Improvement, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94671/624218003.jpg', '2026-02-17 06:58:50', '2026-02-17 07:00:56'),
	(140, '6782310179bd51cee772b681', 'Prenatal Gentle Yoga: Kunci Melahirkan dengan Lancar, Aman, Nyaman, dan Minim Trauma (Edisi Terbaru 2024)', 'Yesie Aprillia', 'Parenting & Family', 'Persepsi umum orang tentang proses persalinan adalah sakit dan berisiko. Padahal sebenarnya, lewat gentle birth, Anda bisa mengalami proses persalinan yang lancar, aman, nyaman, dan minim trauma.Agar proses gentle birth berjalan dengan lancar, Anda perlu berlatih prenatal gentle yoga yang dirancang khusus bagi ibu hamil. Latihan ini bermanfaat untuk mempersiapkan Anda secara fisik, mental, dan spiritual, di antaranya mengurangi morning sickness saat trimester pertama kehamilan, memperbaiki postur tubuh untuk menciptakan ruang yang maksimal bagi perkembangan janin di rahim, dan menjaga kondisi tubuh tetap bugar hingga proses persalinan.Prenatal Gentle Yoga: Kunci Melahirkan dengan Lancar, Aman, Nyaman, dan Minim Trauma dilengkapi dengan panduan gambar step-by-step agar Anda bisa melakukan latihan sendiri di rumah untuk menyiapkan proses kelahiran yang seaman dan senyaman mungkin bagi ibu dan bayi.', 'Rp 154,000', '324 pages', '19 June 2024', 'buku parenting, Parenting, Yoga', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94562/624214004.jpg', '2026-02-17 06:58:50', '2026-02-17 06:58:50'),
	(141, '678230d679bd51cee772b66a', 'Inside Out 2: Jadi Diri Sendiri! Buku Aktivitas', 'Disney Pixar', 'Activity Books', 'Buku aktivitas ini berisi berbagai permainan menyenangkan, aktivitas seru, teka-teki misterius, dan masih banyak lagi!', 'Rp 59,000', '28 pages', '19 June 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94539/624110014.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(142, '678230be79bd51cee772b65e', 'Menu Sat-Set ala Mbak Wiwiek untuk Hidangan Sehari-hari Keluarga & Jualan', 'Wiwik Nur Halimah', 'Culinary', 'Dibalik keterbatasan tersimpan kekuatan. Itulah tekad dan semangat pemilik akun Instagram @wiwie_nurhalimah. Ia membuat followernya kagum dan penasaran karena dari dapur sederhana setiap hari muncul ide menu yang terbukti sehat dan nikmat. Tak heran hanya butuh waktu satu tahun jumlah followernya melonjak dari 1.000 menjadi 444.000.Buku Menu Sat Set ala Mbak Wiwie ini berisi inspirasi hidangan sehari-hari untuk keluarga dan jualan. Beberapa diantaranya adalah konten viral dalam postingannya seperti Es Teler KW, Es Jelly Kurma, Mie Ayam, Soto Ayam Cemplang-Cemplung, Tumis Pare Anti Pahit. Semua resep hanya membutuhkan waktu tak lebih dari 30 menit hingga 1 jam untuk membuatnya.Buku ini memuat 50 resep yang terbagi atas 6 bab:Hidangan Nasi dan Mi,Sup, Soto, dan Hidangan Berkuah,Hidangan Lauk Ayam, Daging, dan IkanHidangan Lauk PendampingHidangan Sayur, danHidangan Selingan.Yuk segera praktikkan resep Mbak Wiwie!', 'Rp 129,000', '136 pages', '19 June 2024', 'Easy Cook, Home Cooking, Cooking, cookbook, Cook, Culinary', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94526/624205008.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(143, '678230da79bd51cee772b66c', 'Kasus Pembunuhan Honjin', 'Seishi Yokomizo', 'AsianLit - Japan', 'Keluarga Ichiyanagi merupakan keluarga pemilik honjin yang sudah ada sejak Zaman Edo. Bunyi koto dan suara jeritan ganjil membahana pada malam pesta pernikahan sang ahli waris. Pasangan pengantin baru ditemukan tewas dibantai dengan tubuh bersimbah darah di ruang duduk paviliun mereka. Di dekat bantal, terdapat koto pusaka Keluarga Ichiyanagi, serta partisi lipat berlapis daun emas yang berhiaskan bercak darah berbentuk tiga jari. Salju yang turun dan menumpuk tebal telah mengubur seluruh permukaan halaman, membuat ruang duduk paviliun tersebut seutuhnya menjadi ruang tertutup...Selain Kasus Pembunuhan Honjin yang menjadi judul buku sekaligus ajang kemunculan pertama Kindaichi Kosuke setelah pulang dari Amerika, simak juga dua novelet lain dalam buku ini, yaitu Kenapa Sumur Timba Berderit dan Kasus Kedai Minum Kucing Hitam.', 'Rp 119,000', '416 pages', '19 June 2024', 'Asian Literature, Asian Lit, asian, novel asian, AsianLit, Literatures, jepang', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94541/624185006.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(144, '6782320279bd51cee772b70a', 'Masih Ingatkah Kau Jalan Pulang (Cover 2024)', 'Sapardi Djoko Damono,', 'Poetry', 'Masih ingatkah kau jalan pulang?Tak ada jalandan tak ada pulangkita di atap langitnun di bawah rata belaka suatu saat birudi saat lain merah kesumba.Jadi kau tidak ingat lagi tak percaya lagiakan jalan pulang?Apakah pergi harusjuga pulang?apakah pergiharus juga berpikiruntuk pulang?Apakah pulang hanya ada kalau kita pergi?Apakah pulangdan pergi harus berpasangan?', 'Rp 90,000', '110 pages', '19 June 2024', 'Puisi, buku puisi, Poetry, sastra, Sapardi Djoko Damono, rintik sedu', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94700/624202017.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(145, '678231c879bd51cee772b6eb', 'Mari Bermimpi (Cover 2024)', 'Paus Fransiskus', 'Religion & Spirituality,', 'Kutipan inspiratif dari MARI BERMIMPI “Kita hidup pada suatu masa pencobaan. Kenyataannya, kita semua diuji dalam hidup. Dengan cara itulah kita tumbuh. Dalam ujian hidup, Anda menyingkapkan hati Anda sendiri: seberapa kuatkah ia, seberapa berbelas kasih, seberapa besar, atau seberapa kecil.”“Renungkanlah apa yang telah kita lihat selama krisis Covid-19 ini. Mereka semua adalah martir: laki-laki dan perempuan yang menyerahkan hidupnya demi melayani orang-orang yang paling membutuhkan. Merekalah saksi tentang keintiman dan kelembutan.”“Dalam krisis, sikap kita yang ‘fungsional’ itu tergoyahkan dan kita harus merombak dan menyesuaikan peran dan kebiasaan kita, supaya dapat keluar dari krisis sebagai pribadi yang lebih baik.”“Kita membutuhkan ekonomi yang memberi semua orang akses ke buah-buah penciptaan, ke kebutuhan dasar hidup: tanah, tempat tinggal, pekerjaan. Kita membutuhkan politik yang dapat merangkul dan berdialog dengan kaum miskin, kaum tersingkir, dan kaum rentan.”“Kita butuh gerakan masyarakat yang paham bahwa kita saling membutuhkan, yang punya rasa tanggung jawab kepada orang lain dan kepada dunia. Kita perlu mempermaklumkan bahwa berbuat baik, beriman, dan bekerja bagi kebaikan bersama adalah tujuan-tujuan hidup yang mulia.”“Inilah saatnya memiliki impian besar, meninjau ulang prioritas-prioritas kita—apa yang kita anggap bernilai, apa yang kita inginkan, apa yang kita cari—dan berkomitmen untuk berperilaku dalam hidup sehari-hari berdasarkan apa yang kita impikan.”', 'Rp 79,000', '226 pages', '19 June 2024', 'buku pengembangan diri, Paus Fransiskus, Religion, Self-Improvement, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94669/624218001.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(146, '6782311979bd51cee772b68e', 'Kisah Jarum dan Kulit', 'Gu Byeong-Mo', 'AsianLit - Korea', 'Kisah adaptasi yang terinspirasi dari dongeng Tukang Sepatu dan Liliput.Ada makhluk-makhluk kecil yang membantu tukang sepatu yang sudah tua dan miskin membuat sepatu-sepatu indah untuk dijual. Sebagai ucapan terima kasih, istri tukang sepatu membuatkan pakaian untuk makhluk-makhluk itu. Begitu mereka mengenakan pakaian tersebut, makhluk-makhluk itu tidak pernah muncul lagi. Dongeng aslinya berhenti sampai di sana. Novel ini bercerita tentang apa yang terjadi pada makhluk-makhluk kecil itu setelahnya.Ahn dulu adalah salah satu makhluk tanpa nama tersebut. Kini, ia sudah berubah wujud menyerupai manusia. Namun, ada satu hal yang berbeda. Ahn tidak bertambah tua seperti manusia lain. Selama menjalani hidup selama ratusan—mungkin ribuan—tahun ia selalu berdoa agar hari terakhirnya di dunia segera tiba.Sampai ia bertemu dengan Mia, “saudara”-nya sesama makhluk tanpa nama dulu, dan mungkin satu-satunya yang masih tersisa di dunia. Namun, Mia jatuh cinta pada manusia.', 'Rp 69,000', '176 pages', '19 June 2024', 'Asian Lit, novel asian, Fiksi, Novel, AsianLit, Korea', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94575/624186009.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(147, '678231ca79bd51cee772b6ec', 'Fransiskus, Paus dari Dunia Baru (Cover 2024)', 'Andrea Tornielli', 'Religion & Spirituality,', '“Doakanlah saya, saya memohon kepadamu, berdoalah bagi saya...”Pelataran Basilika Santo Petrus, Vatikan, dipenuhi hamparan luas payung- payung yang mengembang. Ribuan orang, seraya menahan udara dingin yang menggigit serta terpaan air hujan selama berjam-jam, menantikan saat cerobong asap Kapel Sistina memberikan tanda-tanda yang diharapkan...Pada saat jarum jam menunjuk pukul 19.05, segumpal asap putih membum- bung. Awalnya asap putih itu sangat tipis, tetapi kemudian berangsur-angsur menjadi lebih tebal dan bersih. Asap putih itu pun mulai membumbung dengan kencang dari cerobong asap, mengirimkan pesan yang jelas kepada orang-orang yang terpesona dan mulai bersorak-sorai. Paus telah terpilih, wa- laupun dunia belum tahu nama dan wajahnya. Pada saat itu hujan berhenti. Penantian itu seperti tak berkesudahan. Akhirnya, jendela besar teras utama Basilika Santo Petrus terbuka...Dialah Kardinal dari Buenos Aires, Jorge Mario Bergoglio. Dialah Jesuit pertama yang menjadi Uskup Roma dan yang pertama dalam sejarah Gereja menggunakan nama Fransiskus, si Miskin dari Asisi. Dialah Paus yang dengan rendah hati mengatakan, “Saya menginginkan Gereja yang miskin dan untuk orang miskin!”', 'Rp 79,000', '248 pages', '19 June 2024', 'buku pengembangan diri, Paus Fransiskus, Religion, buku religi, Self-Improvement, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94670/624218004.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(148, '6782310879bd51cee772b685', 'Selamat Menunaikan Ibadah Puisi (Hard Cover)', 'Joko Pinurbo', 'Poetry', 'Dari kamar mandi yang jauh dan sunyisaya ucapkan Selamat Menunaikan Ibadah Puisi.*Sabda sudah menjadi saya. Saya akan dipecah-pecah menjadi ribuan kata dan suara.*Tubuhku kenangan yang sedang menyembuhkan lukanya sendiri.*Menggigil adalah menghafal rutemenuju ibu kota tubuhmu.*Lupa: mata waktu yang tidur sementara.*Tuhan yang merdu, terimalah kicau burung dalam kepalaku.*Kita adalah cinta yang berjihad melawan trauma.', 'Rp 119,000', '208 pages', '19 June 2024', 'Joko Pinurbo, buku puisi, Kumpulan Puisi, Puisi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94566/624202019.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(149, '6782312279bd51cee772b692', 'Bacelius Ruru - Tiga Dekade Perjalanan Karier', 'Bacelius Ruru', 'Social Sciences', 'Buku Bacelius Ruru: Tiga Dekade Perjalanan Karier tidak sekadar berkisah tentang perjalanan seorang birokrat, tetapi juga bisa menjadi referensi historis kebijakan pemerintah di bi­dang ekonomi dan keuangan sejak awal tahun 80-an hingga terbentuknya Kementerian Badan Usaha Milik Negara (BUMN).Ia berada pada rantai sejarah yang terangkai ketika pemerintah me­nge­luarkan berbagai paket kebijakan deregulasi dan debirokratisasi yang mengubah kebijakan ekonomi nasional. Ia menjadi tokoh sentral yang mewakili pemerintah saat membahas Undang-Undang Nomor 8 Tahun 1995 tentang Pasar Modal, yang menjadi milestone pengem­bangan dan perkembangan pasar modal Indonesia hingga saat ini.Bacelius Ruru adalah sumber yang kompeten untuk men­ceritakan se­jarah BUMN pada umumnya, proses awal privatisasi, pem­bentukan hold­ing company, restrukturisasi, termasuk sistem pembinaan dan peng­awasan yang bersifat “dualisme” antara Departemen Keuangan dan Departemen Teknis.Tonggak sejarah lainnya terjadi ketika ia mewakili pemerintah dalam menyusun dan menyelesaikan Undang-Undang Nomor 19 Tahun 2003 tentang BUMN, yang menjadi dasar Kementerian BUMN dalam melaksanakan tugas, fungsi, dan kewenangannya. Termasuk dan tidak kalah pentingnya pene­rapan prinsip-prinsip good corporate governance di BUMN.', 'Rp 450,000', '456 pages', '19 June 2024', 'nonfiksi, Social Science, Social Sciences, Politics, Politic, Biography, bio, biografi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94580/624222013.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(150, '6782311b79bd51cee772b68f', 'Princess, Bajak Laut & Alien', 'Clara Ng,', 'Novel', 'MIKAL ingin memahami kenapa ayahnya harus diambil secepat itu secara tragis. Pikiran itu kerap memberatkan hati, membuatnya menjalani hari dengan muram. Namun ketika terperangkap di Son Nokta, dunia tanpa titik akhir, Mikal bertemu Princess, yang sekalipun matanya bolong sebelah, selalu ceria dan optimistis.AGUNG ingin memahami apa maksud hadirnya di dunia ketika kekurangan fisik, kemalangan, dan nasib buruk selalu menyertai langkahnya. Agung kerap bertanya, “Kalau Tuhan benci sekali padaku, buat apa aku lahir?” Perjalanan berliku Agung untuk mencari jawaban itu mempertemukannya dengan Bajak Laut dan sebuah kesempatan untuk menjadi seorang penguasa.TROY ingin memahami tentang rasa keterasingan, bagaikan Alien yang tidak pernah meninggalkannya sedari kecil. Ketika Troy berpikir dunianya mulai cerah dan hangat berkat cinta dan dukungan seorang sahabat jiwanya, tragedi merenggut itu dari Troy. Seketika dan tiba-tiba. Disertai sesal yang mengekal, Troy kembali menjadi Alien, terasing di sekitar yang bising dan hidup.Seperti meneropong sebuah kaleidoskop, ayo intip ke dunia kanak-kanak dan dewasa yang saling bertabrakan dan jungkir balik.', 'Rp 99,000', '336 pages', '19 June 2024', 'Remaja, Teen, Novel Fantasi, Teen Novel, Teen Novels, Fantasy, novel remaja, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94576/624150001.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(151, '6782311579bd51cee772b68c', 'Yang Tertinggal Darinya (Reminders of Him)', 'Colleen Hoover', 'Romance', 'Dunia Kenna Rowan jungkir balik setelah sebuah kecelakaan mobil menewaskan pria yang ia cintai dan membuat dirinya dipenjara. Kini setelah bebas, Kenna kembali ke kota tempat segalanya bermula, berharap ia dapat menemui putri kecil yang tak pernah sempat dikenalnya. Sayangnya, tak seorang pun memberinya celah untuk menemui, apalagi mengenal putrinya. Karena bagi mereka, ia adalah ancaman.Satu-satunya harapan Kenna adalah Ledger Ward, pemilik bar setempat sekaligus penghubungnya dengan sang putri. Namun, jika orang-orang tahu Ledger bersedia mengenal Kenna lebih jauh dan bersimpati kepadanya, impian untuk mengenal putrinya akan terancam.Kenna hanya menginginkan pengampunan. Ia pun tak ingin menyeret Ledger ke dalam masalah karena seiring waktu, pria itu berarti baginya. Dan ia bersedia melakukan apa saja demi putrinya, bahkan jika berarti selamanya ia takkan bisa mengenal anak itu, juga merelakan cinta kedua yang datang ke kehidupannya….', 'Rp 109,000', '456 pages', '12 June 2024', 'Romance Novels, Colleen Hoover, romance novel, Novel dewasa, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94573/624184005.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(152, '678230f479bd51cee772b67a', 'Segala Sesuatu yang Perlu Anda Ketahui tentang Pemasaran', 'John Jessup,', 'Marketing & Public Relation,', 'Buku yang merupakan pengantar yang sempurna bagi para mahasiswa maupun orang awam ini mengupas semua konsep yang Anda butuhkan untuk memahami isu-isu mendasar tentang pemasaran.Dilengkapi diagram yang membantu pemahaman mengenai konsep-konsep pemasaran, rekomendasi bacaan lebih lanjut, dan fitur-fitur yang mudah dicerna tentang para profesional pemasaran penting, ide-ide krusial, serta perusahaan-perusahaan terkemuka, buku ini memudahkan pembelajaran Anda tentang pemasaran. Buku ini mengulas seluruh spektrum gagasan dan pendekatan pemasaran, termasuk kampanye pemasaran perusahaan-perusahaan besar seperti Aplle, Kellogg’s, Guinness, dan McDonald’s.Pada saat Anda selesai membaca buku ini, Anda akan mampu menjawab pertanyaan-pertanyaan seperti:Apa itu bauran pemasaran?Bagaimana saya mengidentifikasi keinginan dan kebutuhan konsumen?Bagaimana pemasar melakukan riset?Apa yang membuat sebuah merek menjadi hebat?', 'Rp 279,000', '326 pages', '12 June 2024', 'Management, Bussines & Management, Business Management, marketing, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94555/624203011.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(153, '6782311379bd51cee772b68b', 'Petaka Keluarga Inugami', 'Seishi Yokomizo', 'AsianLit - Japan', 'Kisah pembunuhan klasik yang mencekam, mahakarya salah satu penulis misteri paling terkenal di Jepang.Pada tahun 1940-an, pemimpin Keluarga Inugami yang kaya raya meninggal, dan para anggota keluarganya menantikan pembacaan surat wasiat dengan tidak sabar. Namun, tak lama setelah isi surat wasiat yang mengejutkan itu terungkap, serangkaian tragedi berdarah pun dimulai.Detektif Kindaichi Kosuke harus menguak rahasia-rahasia gelap tentang hubungan terlarang, kekejaman tak terbayangkan, dan identitas tersembunyi untuk mencari sang pembunuh serta menghentikan petaka yang melanda Keluarga Inugami.Seri Detektif Kindaichi', 'Rp 99,000', '376 pages', '12 June 2024', 'Asian Literature, Asian Lit, asian, novel asian, JLit, AsianLit, Literatures, novel thriller, Thrillers, Mystery & Thrillers, Thriller', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94572/624185005.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(154, '6782310479bd51cee772b683', 'Nirmala', 'Jutta Nymphius', 'TeenLit', 'nir.ma.la: (a) tanpa cacat cela; bersih; suci; tidak bernodaSejak dipecat, Papa selalu mabuk dan sering memukul Mama dan Kay. Gara-gara itu, Kay menyimpan banyak amarah dalam dirinya dan melampiaskannya ke para adik kelas di sekolah. Kay sampai terancam dikeluarkan dari sekolah. Untungnya Frau Holler, wali kelas Kay, percaya Kay anak baik dan membantunya agar tidak dikeluarkan.Untuk itu, Kay harus mengurus Greta, murid pindahan berkebutuhan khusus. Kay sebenarnya kesal sekali dengan Greta yang lamban. Kay bahkan bersekongol dengan Sven untuk diam-diam merundung Greta. Mampukah ketulusan dan kehangatan Greta mengubah Kay?', 'Rp 69,000', '152 pages', '12 June 2024', 'novel remaja, teenlit, novel anak, Novel, terjemahan', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94564/624150005.jpg', '2026-02-17 07:00:56', '2026-02-17 07:03:02'),
	(155, '678230fd79bd51cee772b67f', 'English Classics: To The Lighthouse', 'Virginia Woolf', 'English Classics', '“Friendships, even the best of them, are frail things. One drifts apart.”', 'Rp 59,000', '272 pages', '12 June 2024', 'English Classic, Classic Novels, English Classics, Classic, Classic Novel, klasik, classics, Novel klasik', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94560/624125006.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(156, '6782319b79bd51cee772b6d3', 'The Star Diaries: Catatan Perjalanan Angkasa Luar (Sampul 2024)', 'Stanislaw Lem', 'Science Fiction & Fantasy', 'Kisah ini berpusat pada seorang penjelajah angkasa luar: Ijon Tichy. Dalam penjelajahannya ke berbagai galaksi, Tichy menjadi delegasi untuk Perserikatan Planet-Planet, menyelinap masuk ke planet robot gila, mencoba menduplikasi dirinya sendiri dalam operasi penyelamatan sejarah peradaban manusia, hingga masuk ke planet rahasia di mana segala sesuatu yang ada dalam diri manusia dapat diprogram dengan eksak. Dalam perjumpaannya dengan peradaban futuristik yang jauhnya ratusan juta mil itulah, sains, rasionalitas, kehendak bebas, keyakinan, dan kesucian menjadi pertanyaan besar.***Stanislaw Lem adalah penulis fiksi ilmiah berkebangsaan Polandia. Melalui berbagai karakter yang satir dan lucu, ia menulis tentang filsafat, futurologi, dan kritik sastra. Karya-karya peraih Peraih Franz Kafka Prize ini telah diterjemahkan ke lebih dari 50 bahasa.', 'Rp 119,000', '354 pages', '12 June 2024', 'science, Science Fiction, Science Fiction & Fantasy, Fiction', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94645/624202020.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(157, '678230fb79bd51cee772b67e', 'English Classics: Tales of Space and Time', 'H. G. Wells', 'English Classics', '“…how small the vastest of human catastrophes may seem, at a distance of a few million miles.”', 'Rp 59,000', '296 pages', '12 June 2024', 'English Classic, Classic Novels, English Classics, Classic, Classic Novel, klasik, classics, Novel klasik', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94559/624125005.jpg', '2026-02-17 07:00:56', '2026-02-17 07:00:56'),
	(158, '6782319779bd51cee772b6d1', 'Hujan Bulan Juni (Edisi 50 Tahun GPU)', 'Sapardi Djoko Damono', 'Poetry', 'AKU INGINaku ingin mencintaimu dengan sederhana: dengan kata yang tak sempat diucapkan kayu kepada api yang menjadikannya abuaku ingin mencintaimu dengan sederhana: dengan isyarat yang tak sempat disampaikan awan kepada hujan yang menjadikannya tiadaSapardi Djoko Damono, 1989***Sajak-sajak 1971 umumnya adalah sajak-sajak yang bila dibaca penyair lain akan menimbulkan seru, “Mengapa saya tidak menulis seperti itu tentang itu!”. Dengan kata lain, merupakan puisi-puisi yang harus (karena layak) dicemburui... (Goenawan Mohamad)...ia telah menciptakan genre baru dalam kesusastraan Indonesia, yang sampai kini belum ada nama yang sesuai untuknya... Ia seorang penyair yang orisinal dan kreatif, yang eksperimen-eksperimennya—inovasi yang sangat mengejutkan dalam segala kesederhanaannya... (A.Teeuw)', 'Rp 125,000', '128 pages', '12 June 2024', 'Sapardi Djoko Damono, Puisi, buku puisi, sajak, sastra, sastra indonesia', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94643/624202014.jpg', '2026-02-17 07:00:56', '2026-02-17 07:03:02'),
	(159, '6782305d79bd51cee772b62a', 'Disney Pixar: Berhitung 123', 'Disney', 'Activity Books,', 'Belajar berhitung 123 itu keren! Ayo belajar angka bersama para Incredibles, menulis angka bersama Joy, dan bermain berbagai aktivitas angka bersama Sulley. Ayo segera kejar kemenanganmu!', 'Rp 79,000', '64 pages', '12 June 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94474/624110006.jpg', '2026-02-17 07:00:56', '2026-02-17 07:03:02'),
	(161, '678230dc79bd51cee772b66d', 'Nonik Jamu', 'Rina Suryakusuma', 'Romance,', 'Kinanti memiliki mimpi.Mimpi menjadi seorang peracik jamu.Ia menikah dengan Pandu Buana Widyanata atau Ng Tiong Bik, anak dari pemilik Gudang Rempah, dengan harapan sederhana agar jalan untuk mencapai impiannya semakin mulus dan lancar.Tapi arah langkah memang bukan pada genggamannya semata.Dengan cara yang menyakitkan, Kinanti menyadari bahwa tak semua rencana akan menggapai tujuannya.Arumi memiliki getir.Rasa getir itu bagai bensin yang menjadi bahan bakar dan tujuan hidupnya.Ia bertekad membalas sakit hati orangtuanya sekaligus mewujudkan seuntai mimpi yang pernah tertunda.Jalan Arumi memang tak mudah, tapi dendam adalah kompasnya.Ini adalah kisah tentang dua wanita berbeda, dari generasi berbeda, yang lahir dan besar di kota yang juga berbeda.Tapi mereka sama-sama memiliki mimpi.Dan mereka memiliki keteguhan mutlak untuk menggapainya, apa pun taruhannya, berapa pun bayarannya.', 'Rp 79,000', '272 pages', '12 June 2024', 'lokal, novel roman, Novel, romance novel, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94542/624172007.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(162, '678230f979bd51cee772b67d', 'English Classics: The Lost World', 'Sir Arthur Conan Doyle', 'English Classics', '“Brain, character, soul—only as one sees more of life does one understand how distinct is each.”', 'Rp 69,000', '320 pages', '12 June 2024', 'English Classic, Classic Novels, English Classics, Classic, Classic Novel, klasik, classics, Novel klasik', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94558/624125007.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(163, '6782319979bd51cee772b6d2', 'Catatan Kaki dari Gaza (Sampul 2024)', 'Joe Sacco', 'Comics', 'CATATAN KAKI DARI GAZA ADALAH SUATU PENYELIDIKAN MENYELURUH DAN ORISINAL ATAS KEJAHATAN ISRAEL YANG DITUTUP-TUTUPI DI TEMPAT TERPANAS DI DUNIA: JALUR GAZASuatu tragedi pada tahun 1956 di Jalur Gaza membuat Joe Sacco, wartawan-kartunis, terjun langsung ke wilayah paling sengit di Bumi itu. Selagi ia menyelidiki peristiwa berdarah tersebut, terjadi penggusuran besar-besaran pada rumah warga, serangan Israel yang membunuh penduduk sipil. Dalam suatu riset, Sacco bahkan nyaris terserempet peluru Israel.Dalam pencarian atas kebenaran, Joe Sacco pun melanglang dari satu tragedi ke tragedi lain, me- nyampaikan pesan para gerilyawan, dan mencatat tangis para ibu yang kehilangan rumah, suami, dan anak-anak yang dibunuh prajurit Israel secara brutal.Catatan Kaki dari Gaza adalah karya paling ambisius Joe Sacco. Jurnalisme visual khas Joe Sacco menggambarkan tragedi kemanusiaan di atas tanah yang dipertahankan dengan darah dan air mata syuhada. Buku ini menjadi dokumentasi yang penting atas peristiwa pembunuhan rakyat sipil di Jalur Gaza yang kerap menjadi sekadar satu catatan kaki dalam sejarah. Sejarah pembantaian rakyat sipil yang selalu berulang di tanah Palestina.***“Sacco berbakat besar. Reporter yang jeli... sekaligus seniman mumpuni dengan gambar-gambar kaya nuansa yang meniti jalur di antara gaya kartun dan naturalisme.” —Charles Shaar Murray, Independent“Prestasi terbesar Sacco adalah menggambarkan penindasan memilukan dan horor dalam bentuk yang menenangkan sekaligus meresahkan.” —David Thompson, Observer“Salah seorang kartunis paling orisinal dalam dua dasawarsa terakhir.” —Duncan Campbell, Guardian', 'Rp 189,000', '432 pages', '12 June 2024', 'Komik, jurnalistik', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94644/624202003.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(164, '678230ee79bd51cee772b677', 'Panduan Jalan-Jalan Aman Bersama Mama Macan', 'Kai Elian', 'Young Adult', 'Mama marah besar karena Michi mau ikut ujian masuk universitas di Kota X! Michi dilarang pergi, tapi dia nekat berangkat diam-diam ditemani Levi, sahabatnya. Namun pada hari keberangkatan, secara ajaib Mama berubah jadi kucing!Lewat mimpi aneh pada malam sebelumnya, Michi tahu bahwa hanya ciuman cinta sejati dari setiap anggota keluarganya yang bisa mengubah Mama kembali jadi manusia. Sayangnya Rene, kakak Michi, tinggal terpisah dari keluarga. Demi mengembalikan Mama, mereka berempat memulai perjalanan ke tempat tinggal Rene di Kota X.Sifat Mama yang keras membuat perjalanan itu tidak mudah. Apalagi di tengah jalan, mereka dikejar-kejar tiga orang misterius yang mengancam nyawa mereka sekeluarga!', 'Rp 99,000', '336 pages', '05 June 2024', 'Remaja, Teen Novel, Teen Novels, novel remaja, Young Adult', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94552/624151003.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(165, '678230ec79bd51cee772b676', 'TeenLit: A Publicity Stunt', 'Hening Swastika', 'TeenLit', 'Klub Jurnalistik Matapena harus memiliki minimal tiga anggota baru agar tidak dibubarkan oleh pihak sekolah. Setelah berkutat dengan berbagai strategi, Mayra mendaftar sebagai School Crew di Snoop. Ia berharap namanya yang tercantum di halaman khusus anak muda Batavia Pos itu akan menarik calon anggota baru Matapena.Padahal, Mayra sudah kelas XII. Ia harus kucing-kucingan dengan Kak Sonya agar bisa tetap liputan dan berkontribusi menulis. Namun nilai-nilainya jadi turun, persahabatannya dengan Arin dan Yumi terganggu, dan yang paling ia benci: editornya di Snoop, Rig, terus menagih naskah layaknya rentenir.Menjelang penutupan pendaftaran, aksi publisitas Mayra itu makin membuat semua hal dalam kehidupannya berantakan. Dengan segala konflik yang terjadi, Mayra akhirnya mempertanyakan diri sendiri. Apa sih yang sebenarnya dia cari?', 'Rp 89,000', '312 pages', '05 June 2024', 'Remaja, slice of life, Teen Novel, Teen Novels, novel remaja', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94551/624150004.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(166, '678230f079bd51cee772b678', 'Momo (Sampul 2024)', 'Michael Ende', 'Science Fiction & Fantasy', 'Di tengah reruntuhan amfiteater di tepi kota, hiduplah gadis cilik tunawisma bernama Momo.Momo memiliki bakat khusus. Masalah apa saja, kalau diceritakan pada Momo, seketika muncul jalan keluar terbaik.Suatu hari, gerombolan tuan kelabu menakutkan datang dan diam-diam mencuri waktu para penduduk. Mereka ingin mengambil alih kota. Satu per satu teman Momo pun berhenti datang karena dipaksa mengisi waktu dengan beragam kesibukan. Mereka tak lagi punya waktu untuk sekadar bercanda.Hanya Momo yang tidak terpengaruh oleh kekuatan tuan-tuan kelabu.Bagaimana Momo menolong teman-temannya dan penduduk kota dari cengkeraman para tuan kelabu? Karena waktu yang dihabiskan bersama teman-teman, tidak berarti buang waktu, kan?', 'Rp 89,000', '336 pages', '05 June 2024', 'Fantasy, klasik, terjemahan, Novel klasik, Science Fiction & Fantasy, Novel Fantasi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94553/624164006.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(167, '678230f279bd51cee772b679', 'Koperasi (Nonsyariah) dalam Perspektif Hukum Indonesia', 'F.X. Joniono Rahardjo, S.H', 'Law', 'Dalam gerakan Koperasi Indonesia, hukum masih dianggap kurang begitu penting oleh banyak penggiat, bahkan oleh pengelola koperasi itu sendiri, sehingga perhatian mereka pada hukum sangat kurang. Pendidikan hukum pun sangat jarang diadakan, terutama pendidikan hukum mengenai pengelolaan koperasi.Mungkin karena dianggap kurang penting, literatur dan pustaka tentang perkoperasian begitu minim. Padahal, regulasi dan kebijakan tentang perkoperasian sangat cepat berubah. Terutama pasca-lahirnya UU Cipta Kerja pada 2020. Pemerintah saat ini telah menyelesaikan penyusunan dan tengah menunggu pembahasan RUU Perkoperasian baru yang merupakan RUU Perubahan Ketiga Undang-Undang No. 25 Tahun 1992 tentang Perkoperasian.Buku ini akan mengupas secara detail peraturan tentang perkoperasian di Indonesia, baik berupa undang-undang, Peraturan Pemerintah, maupun Peraturan Menteri, khususnya Menteri Koperasi dan Usaha Kecil dan Menengah.', 'Rp 139,000', '382 pages', '05 June 2024', 'Hukum, law', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94554/624203010.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(168, '678230e779bd51cee772b673', 'Rilakkuma Egg - Buku Mewarnai', 'San X', 'Activity Books', 'Halo! Rilakkuma, Korilakkuma, dan Kiiroitori suka sekali telur. Ayo sama-sama memasak telur sambil mewarnai! Jangan lupa tempelkan stiker-stikernya ya!', 'Rp 49,000', '24 pages', '05 June 2024', 'Anak-anak, Aktivitas, Anak, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94548/624120004.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(169, '678230e579bd51cee772b672', 'Rilakkuma Stay Up Late - Buku Stiker Aktivitas', 'San X', 'Activity Books', 'Ayo bermain bersama Rilakkuma dan teman-teman. Kalian bisa mengerjakan berbagai aktivitas seru di buku ini: menyusun puzzle, menggambar, mewarnai, berhitung, mencari perbedaan, dan banyak aktivitas seru lainnya. Dan ada lebih dari 70 stiker untuk ditempelkan!', 'Rp 69,000', '24 pages', '05 June 2024', 'Anak-anak, Aktivitas, Anak, Rilakkuma, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94547/624120005.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(170, '678230ff79bd51cee772b680', 'Sistem Hortikultura: Desain Pascapanen dan Pengendalian Kualitas Berkelanjutan', 'Kusumiyati, SP.', 'Agriculture', '“Budaya pangan sehat (healthy food) mengalami peningkatan pada masyarakat Indonesia dalam dua puluh tahun terakhir, bahkan tumbuh 7,85 persen selama pandemi COVID-19. Peningkatan tersebut dipengaruhi tren gaya hidup sehat, tren hidup seimbang, tren kembali ke alam (back to nature), peningkatan pendapatan, perbaikan pendidikan, diet berbasis tanaman (plant-based) maupun tuntutan konsumsi ramah lingkungan (green consumption). Implikasinya, permintaan terhadap pangan sehat, terutama sayuran dan buah-buahan segar mengalami peningkatan yang signifikan. Penasaran? Buku ini menarik untuk dibaca dan dijadikan referensi.” —Annisa Pohan Yudhoyono, S.E., M.M. Pembina Ikawati ATR/BPN“Peningkatan permintaan dan konsumsi hortikultura di Indonesia dan dunia juga dipengaruhi oleh perkembangan paradigma hijau yang direalisasikan dalam SDGs #2. Budaya dan konsumsi hortikultura yang berkualitas dan ramah lingkungan terdorong oleh arus utama industri dan ekonomi hijau, biru, dan sirkular. Konsekuensinya, peningkatan semua hal tersebut membutuhkan ekosistem yang kondusif dan skema sistem yang berkelanjutan, yang mampu meminimalkan kehilangan dan sampah pangan. Oleh karena itu, kemandirian produksi domestik penting untuk ditingkatkan dan ketergantungan pada impor harus direduksi.” —Prof. Dr. Dewi Sukma, S.P., M.Si. Ketua Umum Perhorti“Terkait pascapanen, buku ini layak dibaca dan dijadikan referensi karena pascapanen hortikultura yang efektif, adaptif, dan integratif sangat diperlukan dalam menjaga dan mewujudkan kualitas, kuantitas, dan kontinuitas hasil. Inovasi desain dan teknologi rekayasa pascapanen hortikultura menjadi keniscayaan karena metode dan teknik yang diterapkan selama ini semakin tidak memadai menghadapi tekanan risiko dari perubahan iklim ekstrem, pandemi, dan bencana alam. Kehadiran inovasi pascapanen yang cerdas dan hemat (frugal innovation) sangat penting dalam resiliensi dan mitigasi pangan.” —Prof. Dr. Jajang Sauman, Ir., M.S. Guru Besar Hortikultura Universitas Padjadjaran', 'Rp 209,000', '250 pages', '05 June 2024', 'Sciences & Nature, Science & Nature, science', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94561/624231001.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(171, '6782305879bd51cee772b627', 'Ayo Belajar Mengenal Emosi - Buku Stiker Aktivitas', 'Kathy Gordon & Louise Forshaw', 'Activity Books', 'Buku ini membantu anak mengekspresikan emosi yang mereka rasakan lewat stiker-stiker seru.', 'Rp 69,000', '24 pages', '05 June 2024', 'Anak-anak, Aktivis, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94471/624116006.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(172, '678230f879bd51cee772b67c', 'Etiket Bekerja: Menjadi Likeable Person di Tempat Kerja', 'Benari Saraswardini', 'Self-Improvement', 'Dunia kerja membutuhkan karyawan yang adaptif, kompeten, dan profesional. Namun, itu bukanlah tolok ukur mutlak. Beberapa perusahaan masih menjunjung tinggi nilai-nilai moral, terutama aspek sikap dan perilaku karyawan. Oleh karena itu, etiket menjadi salah satu aspek penting yang harus dipelajari.Etiket adalah kualitas diri yang perlu dimiliki seseorang, terutama di dunia kerja, agar dapat menjadi likeable. Menjadi likeable berarti memiliki reputasi yang baik dan dipercaya orang lain. Hal itu akan membuka peluang baru. Networking akan meluas. Karier pun melejit!Jadi, apakah Anda siap menjadi karyawan yang likeable?***“Mudah diaplikasikan, teruji, dan terbukti berhasil diterapkan dalam kehidupan nyata.”—Jamil Azzaini, Inspirator SuksesMulia“Buku yang cocok untuk Anda yang ingin menjadi versi tertinggi dari diri sendiri, serta membangun personal branding yang baik.” —Merry Riana, Entrepreneur, Investor, Content Creator“Bukan hanya berisi teori, buku ini adalah alat untuk memperkuat citra profesional dan memperluas networking.”—Thano Tanubrata, CEO BDO Indonesia', 'Rp 139,000', '178 pages', '05 June 2024', 'buku pengembangan diri, Self-Improvement, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94557/624221028.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(173, '678230eb79bd51cee772b675', 'Yang Dihantui (She Is a Haunting)', 'Trang Thanh Tran', 'Mysteries & Thrillers', 'Ketika mengunjungi ayahnya di Vietnam, hanya ada satu hal di benak Jade Nguyen: ia harus mau pura-pura jadi keluarga bahagia di rumah kolonial Prancis yang sedang direstorasi Ba, ayahnya.Namun, rumah itu punya rencana sendiri. Malam demi malam, Jade terbangun dengan tubuh serasa lumpuh. Dinding seolah bergumam, sementara sisa-sisa serangga berserakan di berbagai tempat tak wajar. Jade juga menemukan jejak-jejak aneh nenek moyangnya di taman. Dan pada malam hari, gadis itu tidak bisa mengabaikan hantu pengantin cantik yang meninggalkan pesan misterius: Jangan makan.Ba dan Lily, adik Jade, tidak percaya ada banyak keanehan itu. Maka dengan bantuan teman eksentriknya, Jade bertekad membuktikan bahwa rumah ini berencana menghancurkan mereka. Saat membongkar kebusukan rumah tersebut, Jade juga harus menghadapi kenyataan siapa dirinya sebenarnya dan apa yang harus ia lakukan demi menyelamatkan mereka semua.“Ramuan memuaskan antara horor tradisional dan tema serta masalah modern. Hantu dan manusia dalam karya penuh nuansa ini sama-sama memikat dan mematikan.”—Kirkus Reviews, starred review', 'Rp 109,000', '432 pages', '29 May 2024', 'novel thriller, Thrillers, Mystery & Thrillers, Thriller', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94550/Fiksi_-_She_Is_A_Haunting.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:49'),
	(174, '6782307479bd51cee772b636', 'Book\'s Kitchen', 'Kim Jee-hye', 'AsianLit - Korea', '“Beristirahatlah sejenak sambil mencium aroma buku baru.”Setelah menjual perusahaan startup-nya, Yu-jin memilih melakukan sesuatu yang tidak termasuk dalam rencana hidupnya. Ia membeli tanah di Soyang-ri dan membuka “Soyang-ri Book’s Kitchen”, book café sekaligus penginapan. Tempat yang dikelilingi pegunungan yang damai dan danau yang indah, tempat seseorang bisa membaca buku dan menulis sepuas hati, tempat orang-orang bisa bertukar cerita dan saling menghibur, tempat seseorang bisa mengistirahatkan hati yang kacau dan menemukan kedamaian.Orang-orang yang tersesat dalam hidup berdatangan ke Soyang-ri Book’s Kitchen, baik sengaja maupun tidak sengaja. Mereka tiba dengan pikiran galau, tetapi ketika meninggalkan Soyang-ri Book’s Kitchen, mereka pergi dengan hati yang lebih ringan dan pemahaman yang lebih mendalam tentang diri mereka sendiri.', 'Rp 79,000', '280 pages', '29 May 2024', 'Asian Literature, Asian Lit, asian, novel asian, AsianLit, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94486/624186008.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(175, '6782306c79bd51cee772b632', 'Masquerade Hotel', 'Keigo Higashino', 'AsianLit - Japan', 'Terjadi beberapa pembunuhan misterius di Tokyo yang diduga pihak kepolisian sebagai kasus pembunuhan berantai. Belum diketahui siapa tersangkanya dan siapa target berikutnya. Satu-satunya hal yang terungkap dari kode yang ditinggalkan pelaku adalah pembunuhan berikutnya akan terjadi di sebuah hotel mewah, Hotel Cortesia Tokyo!Nitta Kosuke, polisi muda yang brilian tapi angkuh, diperintahkan terjun ke dalam operasi penyamaran di hotel tersebut. Orang yang ditugasi melatihnya menjadi staf hotel yang meyakinkan adalah Yamagishi Naomi, staf front desk. Namun, keduanya sama sekali tidak akur. Naomi dituntut untuk memberikan pelayanan terbaik dan mengutamakan kenyamanan para tamu, sedangkan Nitta memiliki naluri untuk mencurigai dan membuka kedok setiap orang yang berpotensi menjadi tersangka.Sementara tamu mencurigakan berturut-turut datang ke hotel, mampukah mereka berdua menguak kebenaran kasus dan mencegah si pembunuh melancarkan aksinya?', 'Rp 139,000', '468 pages', '29 May 2024', 'Keigo Sensei, Asian Literature, Asian Lit, Thriller, Mystery & Thrillers, Thrillers, asian, novel asian, novel thriller, Keigo Higashino, AsianLit', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94482/624185004.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:49'),
	(176, '678230e379bd51cee772b671', 'Semangat Terus, Donal Bebek!', 'Disney', 'Comics', 'Selamat ulang tahun, Donal! Donal Bebek sudah 90 tahun, lho. Mau tahu bagaimana lucunya Donal dan kawan-kawan beradaptasi di dunia modern yang canggih dan serbadigital? Ayo kita cari tahu di komik Donal Bebek edisi spesial ini! Semangat terus, Donal Bebek!Nikmati 5 episode dalam 1 buku: - Appbrakadabra! - Harga Ketenaran! - Harap Tenang! - Sesusah Apa, Sih? - Bebek Paling Mujur Sedunia', 'Rp 169,000', '112 pages', '29 May 2024', 'Anak-anak, Anak, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94546/Anak_-_Semangat_Terus,_Donal_Bebek!.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:02'),
	(177, '678230d279bd51cee772b668', 'Dinosaurus: Buku Aktivitas!', 'Andy Passchier', 'Activity Books', 'Kembali ke masa lalu dengan buku aktivitas dinosaurus prasejarah ini! Kalian bisa memandu Protoceratops melewati labirin gurun, menyelesaikan titik-ke-titik untuk melihat Dilophosaurus yang sangat cepat, dan temukan berbagai fakta menakjubkan tentang dinosaurus.', 'Rp 89,000', '96 pages', '29 May 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94537/624120015.jpg', '2026-02-17 07:03:02', '2026-02-17 07:03:49'),
	(181, '678230d079bd51cee772b667', 'Robot: Buku Aktivitas!', 'Andy Passchier', 'Activity Books', 'Uji kemampuan memecahkan teka-tekimu dengan mengerjakan berbagai aktivitas robot di buku ini.', 'Rp 89,000', '96 pages', '29 May 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94536/624120016.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(182, '6782307d79bd51cee772b63b', 'CoComelon: Ayo Mewarnai!', 'Moonbug Entertainment', 'Activity Books', 'Ayo asah kreativitasmu dengan buku mewarnai ini! Dilengkapi dengan 60 stiker, imajinasimu pasti akan tersalurkan. Jadi, tunggu apa lagi?', 'Rp 69,000', '40 pages', '29 May 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94491/624114008.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(183, '678230c279bd51cee772b660', 'Ivanda Cherlin’s Cook Book', 'Ivanda Cherlin', 'Culinary', 'Ivanda Cherlin, penulis buku ini adalah perempuan multi tasking dan multi talenta. Selain sebagai ibu rumah tangga, makeup artist, entrepreneur, juga content creator. Pemilik akun instagram @ivandacherlin dengan 180.000 lebih follower yang selalu tampil dengan masakan simpel, modern, menggugah selera.Buku ini berisi 60 resep andalan Ivanda yang juga menu favorit putra putrinya, terbagi atas 3 bab:MAIN COURSE, antara lain: BEEF ENOKI DON, DORITOS CHICKEN, SALMON PASTA, SALMON MENTAI BAKED RICE, GYUDON BEEF BOWL, TUNA GIMBAB, TUNA MAYO ONIGIRI, MUSUBI RICE BOWL.DESSERT, antara lain: TIRAMISU FRENCH TOAST, APPLE PIE, ES KRIM GORENG, BAKED MILK, CHOCOLATE MOUSSE, TAHULU (CRUNCHY GLASS CANDY), MILO & OREO MOCHI BITES, LECHE FLAN.SNACK, antara lain: EGG ENGLISH MUFFIN, TAMAGO SANDO, ROTI MILO, CRISPY SHRIMP BALL, SOY HONEY GLAZE CHICKEN, KOREAN CORN CHEESE, BAKSO GORENG, SPAM FRIES, dll.Yuk praktikkan resepnya untuk memanjakan buah hati Anda.', 'Rp 129,000', '138 pages', '29 May 2024', 'Easy Cook, Home Cooking, Cooking, cookbook, Cook, Culinary', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94528/624205009.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(185, '67822ff679bd51cee772b5f2', 'What to Expect The First Year: Panduan Lengkap Merawat dan Mengoptimalkan Tumbuh Kembang Bayi', 'Heidi Murkoff', 'Parenting & Family,', 'Bayi lahir tanpa disertai instruksi cara merawatnya. Padahal itulah yang dibutuhkan orangtua. Buku laris ini menawarkan segala sesuatu yang kita butuhkan untuk merawat (dan membesarkan) bayi, disertai tips praktis dan saran realistis tentang segala sesuatu yang berhubungan dengan bayi.Pembahasan dalam buku ini mencakup analisis pertumbuhan dan perkembangan bayi setiap bulan, pemberian nutrisi setiap tahap usia, strategi menidurkan bayi yang terbukti berhasil, serta cara terbaik dan menyenangkan untuk menstimulasi bayi. Ada juga tips paling praktis (cara memompa ASI, memandikan bayi, menyendawakan bayi, mengatasi kolik, dll.), nasihat medis terkini (jenis-jenis imunisasi, suplemen vitamin, penanganan penyakit yang sering terjadi, dll.), bimbingan memasuki masa transisi menjadi orangtua baru, dan masih banyak lagi.Dapatkan jawaban yang meyakinkan untuk pertanyaan:Bagaimana membuat bayi bisa membedakan malam dan siang?Apakah bayi yang disusui sudah mendapat cukup nutrisi?Apa yang ada di popok bayi?Kenapa bayi saya belum bisa duduk?Bisakah bayi yang sedang kolik segera berhenti menangis?Haruskah memberi bayi makanan organik?', 'Rp 239,000', '784 pages', '22 May 2024', 'Orangtua, buku parenting, Parenting, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94418/624206004.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(186, '6782307679bd51cee772b637', 'Misteri Dian yang Padam (Edisi 50 Tahun GPU)', 'S. Mara Gd', 'Mysteries & Thrillers', 'Dian Ambarwati, gadis asal Ngawi yang berusia dua puluh tahun, datang ke Surabaya untuk memulai lembaran baru dalam hidupnya. Dua bulan setelah kepindahannya, ia ditemukan mati di bawah tanaman kol banda di suatu tempat yang sepi oleh seorang gelandangan.Siapakah yang menyudahi hidupnya? Bekas pacarnyakah yang di Ngawi, yang ditinggalkannya setelah ramai bertengkar selama dua hari? Ataukah kekasihnya yang baru, yang berusia sepuluh tahun lebih tua dan sudah bertunangan dengan gadis lain? Mungkinkah juga ia dibunuh oleh tunangan kekasihnya yang pernah bersumpah akan mematahkan batang lehernya?Kapten Polisi Kosasih dan sahabatnya Gozali dibuat bingung karena satu per satu orang yang mereka curigai ternyata mempunyai alibi yang kuat. siapakah yang menghendaki kematian Dian Ambarwati? Benarkah kematiannya hanyalah kasus penodongan biasa? Benarkah Dian Ambarwati adalah seorang gadis yang polos dan suci seperti yang disangka semua orang, ataukah dia mempunyai latar belakang yang lebih rumit daripada yang diduga?', 'Rp 79,000', '248 pages', '22 May 2024', 'Mystery & Thrilers, Thriller, Mystery & Thrillers, S. Mara Gd., Thrillers, novel thriller, novel misteri, Thrilers Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94487/624172006.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(187, '6782307779bd51cee772b638', 'Di Sini Cinta Pertama Kali Bersemi (Edisi 50 Tahun GPU)', 'Mira W.', 'Romance', '“Sejak kecil tak pernah ada wanita dalam hidupku, Melia. Bahkan ibuku pun tidak kukenal. Ketika aku menemukanmu, aku tidak ingin ada perempuan lain dalam hidupku. Salahkah aku? Berdosakah mencintai seorang gadis seperti kamu di mata Tuhan-mu?”“Cinta tak pernah salah, Leo. Tetapi nafsu adalah dosa. Jangan kotori lagi cinta kita. Kalau kita harus berpisah, biarlah kita berpisah dengan membawa cinta yang semurni ketika pertama kali bersemi.”***Cinta Melia menghancurkan hidup Leo.Cinta Leo menghancurkan rumah tangga Melia.Mengapa?Kapan sebenarnya cinta pertama kali bersemi?Di mana?', 'Rp 69,000', '232 pages', '22 May 2024', 'Romance Novels, romance novel, romantis, novel roman, Roman, Mira W, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94488/624172005.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(188, '6782319279bd51cee772b6ce', 'The Art of War (Sampul 2024)', 'Andri Wang', 'Self-Improvement,', 'The Art of War-Sun Zi adalah buku perang pertama di dunia. Buku yang terdiri atas 5.900 huruf klasik Tiongkok ini disajikan kembali oleh Andri Wang dengan penjelasan yang akan memudahkan pembaca dalam memahaminya.战 贵 胜Tidak hanya dibaca oleh kalangan angkatan bersenjata, buku ini juga menjadi pedoman bagi para pelaku bisnis dalam menjawab persaingan masa kini yang begitu ketat. Strategi dan taktik perang yang relevan untuk persaingan sepanjang masa ini akan membantu kita dalam memenangkan segala kompetisi.', 'Rp 59,000', '144 pages', '22 May 2024', 'Self-Improvement, Self-Acceptance, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94640/624221024.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(189, '6782308c79bd51cee772b643', 'CICA', 'Cyntha Hariadi', 'Poetry', 'semakin besar kami menyadari maksud baik orangtua orang-orang yang ditandai sebagai sapi dan kambing karena layak diperah dan dimasukkan daftar hitam adalah orang-orang yang menyerupai kamisepanjang hidup kami mempersiapkan diriyang niat sekolah tinggi-tinggi, yang ulet bekerja sampai pagi yang liat menumpuk hartasupaya semua bisa terbang menyelamatkan diridi udara, kami melayang-layang bahagiapesawat yang kami tumpangi membawa ke mana pun kami suka hanya satu yang orangtua kami rahasiakansekali pesawat ini lepas ia tak lagi mendaratmulailah kami hidup antara langit dan bumi tak tahu mana kepala mana kakisenantiasa rindu asal, kepalang pergi mendoakan tanah yang menyimpan ari-ari kamiCICA berisi 96 puisi yang ditulis sejak 2016 hingga 2020 oleh Cyntha Hariadi. Ada kenangan yang tersimpan, pertanyaan atas identitas, juga peristiwa yang berusaha dihapus oleh kekuasaan dalam larik-larik puisi di buku ini.', 'Rp 79,000', '174 pages', '22 May 2024', 'sastra, buku puisi, Poetry, Puisi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94499/624202008.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(190, '6782319479bd51cee772b6cf', 'Digital Minimalism: Mempertahankan Fokus di Tengah Dunia yang Gaduh', 'Cal Newport', 'Self-Improvement,', 'Minimalisme digital memungkinkan orang bercakap-cakap lama tanpa melirik ponsel; tenggelam dalam buku yang bagus atau lari pagi yang santai; serta menikmati waktu bersama teman dan kerabat tanpa merasakan ketergesaan untuk mengecek surel. Minimalisme digital memungkinkan orang tetap mengikuti perkembangan berita tanpa merasa kewalahan dengan banyaknya informasi yang tersedia. Minimalisme digital memungkinkan orang terbebas dari jebakan FOMO—fear of missing out—karena tahu kegiatan apa yang memberikan makna dan kepuasan bagi hidup mereka.Cal Newport memaparkan secara menarik betapa mendesaknya hal itu dalam dunia kita yang dibombardir teknologi. Minimalisme digital berarti memikirkan ulang hubungan kita dengan media sosial, menemukan kembali keasyikan dari dunia non-digital, dan terhubung kembali dengan batin kita secara teratur lewat momen-momen kesendirian. Ia memaparkan strategi untuk menyatukan praktik-praktik ini dalam hidup, dimulai dengan proses “bersih-bersih digital” selama tiga puluh hari yang telah membantu ribuan orang merasa lebih memegang kendali dan tidak kewalahan.•••“Buku ini adalah panggilan yang mendesak bagi siapa pun yang sungguh- sungguh ingin memegang kendali atas hidupnya.” Ryan Holiday, penulis Stillness Is the Key“Saya menantang Anda melahap buku yang luar biasa ini sekali baca. Saya melakukannya, dan langsung mulai menerapkan isinya." Greg McKeown, penulis Essentialism“Ajakan Cal untuk memiliki interaksi yang bermakna dan memusatkan perhatian sepenuhnya pada saat ini sungguh dibutuhkan oleh dunia.” Daniel Levitin, penulis The Organized Mind', 'Rp 139,000', '384 pages', '22 May 2024', 'Self-Improvement, Self-Acceptance, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94641/624221015.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(191, '6782304779bd51cee772b61e', 'Elisa Lumbantoruan: Simplify Complexity', 'Riniwaty Makmur', 'Biography', 'Pada usia 42 tahun Elisa Lumbantoruan telah menjadi CEO jaringan perusahaan IT dunia PT Hewlett-Packard Indonesia. Prestasi ini membuat ia ditarik oleh menteri BUMN waktu itu untuk bergabung di PT Garuda Indonesia (Persero). Bagi Elisa, pemimpin harus beretika. Ia dikenal mempraktikkan servant leadership atau kepemimpinan yang melayani. Praktik kepemimpinan ini sukses memotivasi puluhan ribu karyawan saat ia menjabat CEO PT ISS Indonesia.Elisa Lumbantoruan berasal dari Siborongborong di Tapanuli Utara. Kedua orangtuanya adalah guru sekolah dengan sembilan orang anak. Perjalanan hidup kemudian mengantarkannya ke Bogor saat SMA. Elisa berprinsip harus bisa beradaptasi dengan situasi apa pun. Kemampuan beradaptasi diperlukan untuk menyederhanakan kompleksitas atau simplify complexity yang menjadi prinsip hidupnya. Elisa juga memperkenalkan strategi marketing “menciptakan medan tempur kita sendiri” yang sukses diterapkannya di berbagai perusahaan.“Saya bisa simpulkan buku ini sungguh berbobot, dan membacanya seperti ungkapan pepatah, ‘akan membukakan Anda pintu ke dunia yang lain’. Sofyan Djalil, Mantan Menteri Negara dan Menteri Koordinator“Setiap orang perlu belajar dari mentor yang sukses dan profesional. Saya sendiri telah merasakan pengalaman yang berharga memiliki mentor seperti Pak Elisa yang kariernya sangat mengagumkan. Dia juga seorang pemimpin yang dihormati dengan reputasi sangat baik di kalangan profesional industri IT.” Cin Cin Go, Country & Technology Leader IBM Indonesia', 'Rp 154,000', '236 pages', '15 May 2024', 'Biography, bio, biografi, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94462/624222011.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(192, '6782318c79bd51cee772b6cb', 'Petunjuk Hidup Tenteram dan Bahagia (Edisi 50 Tahun GPU)', 'Dale Carnegie', 'Self-Improvement,', 'BUKU INI DAPAT MENGUBAH ANDA! ANDA DAPAT MENGALAHKAN RASA CEMAS, GELISAH, DAN SEDIH!Tiap orang tahu bahwa rasa cemas, gelisah, dan sedih itu berbahaya. Apakah semua perasaan itu dapat diatasi? Di buku ini, Dale Carnegie membuktikan bahwa semua perasaan itu dapat diatasi. Dia telah membuktikannya dengan cara-cara yang teruji. Beribu-ribu pria dan wanita dari segala lapisan masyarakat telah merasakan hasilnya. Dale Carnegie memberi Anda petunjuk-petunjuk praktis yang dapat Anda pergunakan sekarang juga.Petunjuk Hidup Tenteram dan Bahagia memaparkan kebenaran-kebenaran besar. Buku ini berisi petunjuk-petunjuk yang mengagumkan dan mudah di­laksanakan. Pendek kata, buku ini dapat mengubah hidup Anda! Bacalah halaman pertama, yang menyajikan Sepuluh Ke­untungan yang dapat Anda peroleh dari buku inil', 'Rp 115,000', '468 pages', '15 May 2024', 'Self-Improvement, Self-Acceptance, pengembangan diri, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94637/624221021.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(193, '6782318e79bd51cee772b6cc', 'Anak Bajang Mengayun Bulan (Sampul 2024)', 'Sindhunata', 'Literary', 'Ia sedaging dan sedarah dengan adiknya, mengapa ia harus menjadi tampan dan adiknya menjadi buruk rupa? Mengapa bukan dia yang mewujud jelek, dan adiknya yang mewujud tampan? Apakah ini karena perbuatan nasib? Kalau demikian, alangkah tidak adil dan semena-menanya nasib ini dalam memilihkan takdir bagi ciptaannya. Ataukah dengan kesemena-menaannya itu, nasib hendak menentukan jalan yang berbeda bagi dia dan adiknya? Seandainya ada jalan yang berbeda, bagaimanakah nasib harus mempertanggungjawabkan kebahagiaan yang seharusnya boleh dinikmati dengan adil oleh siapa saja?***Anak Bajang Mengayun Bulan karya Sindhunata menampilkan kisah sebuah keluarga menjalani sukacita dan tragedi dalam kehidupan. Melalui para tokohnya, kita diajak kembali memaknai cinta, nafsu, kesempurnaan, kegagalan, yang baik, dan yang buruk. Sebuah kisah yang menampilkan perjuangan sejati dan keikhlasan untuk mencintai sampai habis.', 'Rp 163,000', '568 pages', '15 May 2024', 'sastra, novel sastra, sastra indonesia', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94638/624202016.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(194, '6782319079bd51cee772b6cd', 'Aku Ini Binatang Jalang (Edisi 50 Tahun GPU)', 'Chairil Anwar', 'Poetry', 'KESABARANAku tidak bisa tidurOrang ngomong, anjing nggonggong Dunia jauh mengaburKelam mendinding batuDihantam suara bertalu-taluDi sebelahnya api dan abuAku hendak berbicaraSuaraku hilang, tenaga terbang Sudah! tidak jadi apa-apa!Ini dunia enggan disapa, ambil perduliKeras membeku air kaliDan hidup bukan hidup lagiKuulangi yang dulu kembaliSambil bertutup telinga, berpicing mata Menunggu reda yang mesti tibaMaret 1943Aku Ini Binatang Jalang adalah kumpulan puisi terlengkap karya penyair terbesar Indonesia Chairil Anwar. Selama ini puisi-puisinya tersebar dalam beberapa buku seperti Deru Campur Debu, Kerikil Tajam dan Yang Terampas dan Yang Putus. Sebagian lagi ada dalam Tiga Menguak Takdir dan Chairil Anwar Pelopor Angkatan 45. Selain keseluruhan sajak asli, dalam koleksi ini juga dimuat untuk pertama kalinya surat-surat Chairil—yang menggambarkan “keadaan jiwa”-nya—kepada karibnya H.B. Jassin. Dalam hidupnya yang singkat, Chairil Anwar telah menghasilkan puisi-puisi yang akan terus hidup seribu tahun lagi.', 'Rp 66,000', '144 pages', '15 May 2024', 'Chairil Anwar, Puisi, buku puisi, sastra, sastra indonesia, Poetry', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94639/624202015.jpg', '2026-02-17 07:03:49', '2026-02-17 07:04:30'),
	(195, '6782307f79bd51cee772b63c', 'Cocomelon: Dot to Dot Buku Aktivitas', 'Moonbug Entertainment', 'Activity Books', 'Dengan buku aktivitas Dot-to-Dot CoComelon ini, anak-anak bisa belajar berhitung dan mewarnai. Menghubungkan titik-titik juga dapat meningkatkan keterampilan motorik halus mereka.', 'Rp 39,000', '24 pages', '15 May 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94492/624114009.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(196, '6782307979bd51cee772b639', 'Cocomelon: Kembali ke Sekolah', 'Moonbug Entertainment', 'Activity Books', 'Ayo kembali ke sekolah bersama CoComelon! Buku mewarnai ini akan mengingatkanmu betapa menyenangkannya pergi ke sekolah!', 'Rp 39,000', '16 pages', '15 May 2024', 'Anak-anak, Aktivitas, Anak, Activities, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94489/624114010.jpg', '2026-02-17 07:03:49', '2026-02-17 07:03:49'),
	(197, '6782302479bd51cee772b60b', 'Menemani, Bukan Memarahi: Mendampingi Anak Menjadi Dirinya Sendiri', 'Ichiro Kishimi', 'Parenting & Family,', 'Anak yang terus-terusan dimarahi orangtuanya tidak akan pernah bisa menyayangi dirinya sendiri dan pada akhirnya tidak dapat hidup bahagia. Berbeda dengan benda mati, diri kita adalah sesuatu yang tak tergantikan dan tidak bisa dibeli baru. Sebenci apa pun seseorang terhadap dirinya, dia harus tetap bertahan dengannya.Untuk memastikan anak dapat hidup dengan baik, dukungan terus-menerus dari orangtua sangat diperlukan. Tak ada orangtua yang sempurna. Namun, itu bukan alasan untuk berhenti berusaha. Membesarkan anak adalah pekerjaan seumur hidup, dengan berbagai dinamikanya. Meskipun tidak sempurna, Anda bisa belajar menjalin hubungan sebagai orangtua dan anak yang setara menurut teori psikologi Adler.Dalam Menemani, Bukan Memarahi Anda akan mempelajari:Strategi memahami perilaku anakApa yang harus Anda lakukan dan hindari dalam pengasuhan anakApa yang sebaiknya dan sebaiknya tidak Anda ucapkan kepada anakSemua itu bisa membantu Anda dalam menerapkan pola asuh yang menyenangkan. Ditulis oleh Ichiro Kishimi, penulis buku bestseller Berani Tidak Disukai, buku ini merangkum dinamika dan makna tumbuh bersama sebagai orangtua dan anak.', 'Rp 79,000', '161 pages', '15 May 2024', 'Self Transformation, buku parenting, Parenting, Self-Improvement, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94443/624214003.jpg', '2026-02-17 07:03:49', '2026-02-17 07:04:30'),
	(201, '6782303779bd51cee772b615', 'Perkara Keramat', 'Raisa Kamila', 'Literary', 'Banyak yang berubah di Banda Aceh, selepas tsunami 2004. Termasuk kehidupan si Jagoan Kembar—Hasan dan Husein. Kehilangan Ayah dan Mamak, mengungsi sementara bersama Om Jack di Medan, sekaligus menghadapi perubahan-perubahan sosial di kotanya. Termasuk menyaksikan sebuah Kedai Mieso H. Idris harus berhadapan dengan seorang Bernama Putroe Faradiba—yang mengaku sebagai keturunan Sultan Sulaiman Syah, yang makamnya muncul selepas tsunami. Semua orang mengimani itu adalah sebuah makam keramat dari seorang yang namanya dihapus dari sejarah Aceh. Lebih dari itu, ada banyak yang mempertanyakan sekaligus ingin mencari simpul mana yang benar.Perkara Keramat novel perdana Raisa Kamila ini dengan gaya satir menelanjangi bagaimana sebuah masyarakat yang mudah silau oleh simbol agama; bagaimana perseteruan hadir di lapisan masyarakat oleh hal-hal yang kadang sepele.', 'Rp 79,000', '136 pages', '15 May 2024', 'Literary, novel literatur, sastra indonesia, novel sastra, literatur, sastra, Literature, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94453/624202012.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(202, '67822feb79bd51cee772b5ec', 'Program Pembelajaran Paket E-Module', 'Windiyati Wahjudi Nugroho,', 'Education & Teaching', 'Dunia pendidikan mengalami transformasi seiring perkembangan teknologi pada abad ke-21. Dengan kemajuan tersebut, berbagai kreasi baru yang inovatif pun muncul. Teknologi dapat membantu dan mengatasi berbagai beban belajar sehingga dapat dimanfaatkan untuk menciptakan bahan pembelajaran yang praktis.Program Pembelajaran Paket E-Module WY-MT: Ways to Yield Better Material Transformation bukan sekadar modul pembelajaran. Ini adalah terobosan baru untuk memenuhi kebutuhan capaian belajar, baik untuk jenjang pendidikan formal, nonformal, informal, serta pendidikan dan pelatihan vokasi di berbagai bidang. Buku ini memberi panduan lengkap untuk meningkatkan kualitas proses pembelajaran serta berpotensi untuk berkembang di masyarakat karena up to date dan mudah diterapkan untuk setiap generasi, termasuk gen Z.', 'Rp 109,000', '88 pages', '15 May 2024', 'teaching, education, buku pendidikan, humaniora, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94412/624207001.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(203, '6782300379bd51cee772b5f9', 'Duri dan Kutuk', 'Cicilia Oday', 'Literary', 'Rumah tua di samping rumah Adam yang telah lama terbengkalai itu kini ditempati penghuni baru. Eva, perempuan bertangan dingin dalam menumbuhkan dan merawat aneka tanaman, menyulap keangkeran rumah menjadi Toko Firdauz dengan pekarangan rimbun. Adam remaja tanggung dengan gairah seksual sedang bergejolak, kerap menyaksikan Eva dan aneka tanamannya dari balik jendela kamar.Tiada yang bisa menyangka, di tengah gairah seksual yang bergejolak, Adam menyaksikan sulur-sulur mawar masuk kamar dan memenuhi fantasi akan sosok perempuan yang ditumbuhi duri dan akar. Sebaliknya, Eva selalu saja diikuti kutukan atas apa yang tumbuh pada tubuhnya. Adam menyimpan rahasia atas tubuh Eva, sekaligus imajinasi liar setiap malamnya.Dalam Duri dan Kutuk terbentang selusur kisah perempuan yang sepanjang hidupnya kerap diusik duri dan terkepung kutuk.', 'Rp 109,000', '196 pages', '08 May 2024', 'sastrawan, sastra indonesia, novel sastra, sastra', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94425/624202007.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(204, '6782303579bd51cee772b614', 'Disney Frozen: Ayo Mewarnai Buku Aktivitas', 'Disney', 'Activity Books', 'Ayo bermain bersama Elsa, Anna, dan teman-teman mereka! Warnai buku ini, bantu Sven dan Kristoff melewati labirin, hitung daun bersama Olaf, dan lakukan berbagai permainan seru lainnya!', 'Rp 79,000', '64 pages', '08 May 2024', 'Aktivitas, Activity Book, Activity Books, buku anak gramedia, Buku anak, Mewarnai', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94452/624110005.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(205, '67822fc579bd51cee772b5d8', 'Garis Depan Perubahan: Dinamika Regulasi Ketenagakerjaan', 'Haiyani Rumondang', 'Social Sciences', 'Dunia ketenagakerjaan terus mengalami perubahan seiring perkembangan zaman dan teknologi. Oleh karena itu, dibutuhkan penyesuaian dalam berbagai aspek, termasuk aspek regulasi ketenagakerjaan. Hal ini menjadi tantangan bagi semua pihak yang berkecimpung dalam bidang ketenagakerjaan.Penting untuk memberikan pemahaman kepada masyarakat bahwa pemerintah terus berupaya mempertemukan kepentingan kedua pihak—yakni pengusaha dan pekerja—melalui berbagai kebijakan yang dituangkan dalam regulasiketenagakerjaan. Dalam proses penyusunan regulasi atau peraturan perundang- undangan, pemerintah melibatkan partisipasi publik, mulai dari akademisi, serikat pekerja, hingga organisasi pengusaha.Dinamika dalam proses penyusunan regulasi selalu menunjukkan adanya pro dan kontra, bahkan ketika suatu regulasi sudah diundangkan. Idealnya, semua pihak harus mengedepankan prinsip asas musyawarah mufakat. Namun hal itu tidak mudah dilakukan di negara yang demokratis seperti Indonesia.Buku ini mencoba mengurai dinamika dan fakta lahirnya kebijakan terkait regulasi ketenagakerjaan, khususnya kebijakan terbaru tentang Cipta Kerja. Harapannya, pembaca yang budiman dapat memahami bahwa dalam membuat sebuah kebijakan—meski terdapat tujuan yang sama—akan selalu terdapat perbedaan yang harus dibicarakan atau didiskusikan dengan mengedepankan musyawarah mufakat.', 'Rp 199,000', '120 pages', '08 May 2024', 'tenaga kerja, ketenagakerjaan, Social Science, indonesia, nonfiksi, Social Sciences', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94392/624222006.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(206, '6782305179bd51cee772b623', 'Kesendirian Mahaluas (The Great Alone)', 'Kristin Hannah', 'Adult', 'Alaska tahun 1974. Indah, namun liar dan tak kenal ampun.Ernt Allbright berubah drastis sepulangnya dari perang Vietnam. Dengan impulsif Ernt membawa pindah keluarganya ke Alaska untuk hidup dari alam. Kondisi mental yang tidak stabil membuatnya sering melakukan kekerasan kepada Cora, istrinya. Leni, putri mereka yang berumur 13 tahun, terjebak dalam pasang-surut hubungan orangtuanya yang penuh badai.Ketika musim dingin semakin dekat dan kegelapan menyelimuti Alaska, kondisi mental Ernt semakin memburuk. Di pondok kecil mereka yang tertutup salju, di tengah kegelapan selama delapan belas jam setiap hari, Leni dan ibunya menyadari kebenaran yang menakutkan itu: mereka sendirian. Di alam liar ini tak ada yang bisa menyelamatkan mereka, kecuali diri mereka sendiri.', 'Rp 189,000', '688 pages', '08 May 2024', 'Novel dewasa, Thrilers Novel, Novel, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94467/624186007.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(207, '6782302a79bd51cee772b60e', 'Prinsip-Prinsip Etika: Landasan Teori untuk Memecahkan Kasus-Kasus Dilema Moral', 'Haryatmoko', 'Philosophy', 'Kesadaran dan akal budi membuat manusia menjadi makhluk yang istimewa; yang mampu berpikir dan berkehendak bebas dalam menjalani hidupnya. Namun, keistimewaan itu juga disertai dengan “kutukan” berupa dilema moral yang kerap kali membingungkan, membuat kita terombang-ambing di tengah lautan pilihan, dan mengaburkan arah menuju hidup yang lebih baik. Persoalan itu semakin sulit diurai pada masa revolusi digital, di mana nilai-nilai keutamaan menjadi hal yang samar di dunia maya.Di tengah kekacauan itu, etika hadir sebagai mercusuar yang memandu tindakan, mengurai persoalan benar atau salah, dan membedakan keutamaan dari kejahatan. Etika juga membantu kita memilah pilihan- pilihan yang samar; bukan sekadar memisahkan yang baik dari yang jahat, melainkan menentukan yang kurang jahat dari yang paling jahat.Buku Prinsip-Prinsip Etika: Landasan Teori untuk Memecahkan Kasus- Kasus Dilema Moral menjelaskan aspek-aspek praktis dari berbagai teori etika untuk diimplementasikan dalam kehidupan nyata. Dilengkapi contoh praktis dan studi kasus, buku ini memberi pemahaman mendalam kepada pembaca untuk mengatasi dilema moral dengan penuh pertimbangan, empati, dan komitmen.', 'Rp 119,000', '208 pages', '08 May 2024', 'philosophy, filsafat, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94446/624222009.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(208, '6782305679bd51cee772b626', 'Rumus Ciuman Sempurna (The Kiss Quotient)', 'Helen Hoang', 'Romance', 'Stella Lane jago merancang algoritma namun sangat payah dalam berkencan. Stella mengidap Asperger yang membuatnya kesulitan dalam berinteraksi dan ciuman ala prancis membuatnya merasa seperti ikan hiu yang giginya dibersihkan ikan pilot. Kesimpulan yang ia dapatkan: ia butuh banyak latihan—dengan seorang profesional. Karena itulah ia menyewa pendamping laki-laki bernama Michael Phan. Pria blasteran Vietnam and Swedia itu setuju untuk membantunya mencentang semua kotak di rencana pelajarannya.Tidak butuh waktu lama hingga Stella tidak hanya menyukai ciuman-ciuman Michael, tapi juga mendambakan hal-hal lain yang Michael buat ia rasakan. Matematika tidak lagi terasa sebagai satu-satunya hal yang menyatukan semesta, dan pola yang muncul dalam hubungannya dengan Michael meyakinkan Stella bahwa cinta adalah logika paling masuk akal...', 'Rp 99,000', '352 pages', '01 May 2024', 'Romance Novels, cinta, romance novel, cerita cinta, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94470/624184004.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(209, '6782305a79bd51cee772b628', 'Menyelamatkan Teetee (Parolee Teetee)', 'Antje Herden', 'Middle Grade Readers', 'Ada rumor yang beredar di kalangan anak-anak bahwa tas cokelat besar menggelembung milik Frau Teetee itu ajaib. Tas yang bisa mengabulkan keinginan. Tas itu bisa mengeluarkan apa pun yang kaubutuhkan.Namun, suatu hari Teetee menghilang tanpa jejak. Anak-anak akhirnya menyadari wanita tua anggun itu telah diculik! Tujuh anak dengan sifat bertolak belakang yang biasanya jarang berinteraksi, bersatu untuk mencari tahu apa yang terjadi kepada Teetee.Mereka pun membentuk tim dan berdiskusi di Pusat Komando. Letaknya di depan toko kelontong Herr Mansur, di bangku dengan banyak bantal warna-warni. Ketujuh anak itu meluncurkan operasi penyelamatan yang penuh petualangan.Lorong bawah tanah dengan rintihan menyedihkan, vila tua dengan para penghuni yang menakutkan, surat kontrak aneh yang ditinggalkan. Akankah mereka berhasil menyelamatkan Teetee setelah melewati semua itu?', 'Rp 69,000', '208 pages', '01 May 2024', 'Anak-anak, Anak, novel anak, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94472/624143002.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(210, '6782305279bd51cee772b624', 'Kiky\'s Delivery Service', 'Eiko Kadono', 'AsianLit - Japan', 'Sesuai tradisi penyihir, pada usia tiga belas tahun Kiki harus pindah ke kota lain. Dia harus meninggalkan Ibu, Ayah, serta kota kelahirannya. Kiki hanya akan ditemani Jiji si kucing hitam.Ibu sudah melarangnya tinggal di kota besar, tapi Kiki kepalang suka pada kota Koriko, karena menara jamnya sangat tinggi dan letaknya dekat laut. Tapi astaga... warga kota Koriko tidak menyambut Kiki dengan hangat. Apakah Kiki bakal bisa bertahan di kota ini, padahal dia cuma bisa satu sihir: terbang dengan sapu?', 'Rp 79,000', '200 pages', '24 April 2024', 'Fantasy, AsianLit, novel asian, asian, Asian Lit, Asian Literature', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94468/Fiksi_-_Titipan_Kilat_Penyihir.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(211, '6782303179bd51cee772b612', 'Mendengarkan dengan Hati', 'Patrick King', 'Self-Improvement', 'Saat ini, seni mendengarkan secara mendalam adalah sebuah kekuatan super. Jika Anda dapat membuat seseorang merasa didengarkan, Anda tidak akan menemui kesulita untuk meraih hatinya. Dan itu tidak sesulit dan serumit yang Anda bayangkan.How to Listen with Intention adalah buku tentang hubungan. Suatu hubungan harus bersifat memberi dan menerima—apakah Anda menerima lebih dari yang Anda berikan? Apakah Anda membuat orang merasa nyaman untuk terbuka kepada Anda? Apakah Anda mendengarkan dengan baik, atau tanpa Anda sadari Anda adalah orang yang narsis dalam atau hubungan? Inilah waktunya untuk mengajukan pertanyaan-pertanyaan sulit ini dan mempelajari keterampilan yang tidak hanya membantu orang saat dibutuhkan, tetapi juga menciptakan persahabatan baru dengan siapa saja—lagipula, siapa yang tidak tidak suka didengarkan?', 'Rp 89,000', '170 pages', '24 April 2024', 'Self Transformation, buku pengembangan diri, Self-Improvement, Self-Acceptance, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94450/Hum_-_Mendengarkan_dengan_Hati.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(212, '678230c079bd51cee772b65f', 'Buku Penuntun Membuat Pola Busana Tingkat Dasar', 'Soekarno', 'Fashion & Beauty', 'Dunia busana tumbuh dengan sangat pesat. Setiap saat dapat diciptakan tren baru yang segera diminati pasar. Pertumbuhan yang luar biasa ini sering kali tidak ditunjang dengan sumber daya yang memadai, meskipun kini telah banyak didirikan sekolah mode maupun kursus menjahit. Guru dan peserta kursus menjahit dan sekolah mode yang membutuhkan referensi, sering kali terbentur pada minimnya buku tentang pola busana yang baik.Untuk memenuhi kebutuhan akan pengetahuan tentang cara pembuatan pola busana yang baik, buku ini dibuat oleh penulisnya. Materi yang ada di dalamnya merupakan kumpulan diktat yang diberikan selama bertahun-tahun pada anak didiknya di berbagai lembaga pendidikan. Selain pembuatan dan pecah pola, buku ini juga menawarkan banyak materi dan informasi lain yang pasti dibutuhkan oleh para siswa sekolah mode dan menjahit, guru-guru, serta para pemerhati dunia busana.Berbagai macam informasi berharga mengenai pola busana bisa diperoleh melalui buku ini, di antaranya:Cara pengambilan ukuranPembuatan pola dasar aneka metodePembuatan pola dari bermacam-macam busana seperti rok, blus, celana panjang, kulot, gaun, hingga kebayaPerubahan modelPerencanaan bahanPembuatan pola busana anak-anakPengenalan teknik pembuatan sketsa busana', 'Rp 110,000', '228 pages', '24 April 2024', 'Fashion', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94527/Edisi_50TH_GPU_BUKU_PENUNTUN_MEMBUAT_POLA_BUSANA_TINGKAT_DASAR_C_1_4_2024.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(213, '6782304479bd51cee772b61c', 'CoComelon: 5 Minutes Stories', 'Moonbug Entertainment', 'Picture Books', 'Bergabunglah bersama JJ dan keluarga, serta teman-temannya di berbagai petualangan seru! Mulai dari bermain bersama Cody, naik bus sekolah, hingga bermain game bersama saudaranya. Di buku ini ada 12 cerita seru yang diambil dari video CoComelon populer yang cocok untuk dibacakan dalam waktu 5 menit!', 'Rp 109,000', '192 pages', '24 April 2024', 'Buku anak, buku anak gramedia, Anak, Anak-anak, Activity Books, Activity Book', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94460/Cocomelon_-_5_Minute_Stories.jpg', '2026-02-17 07:04:30', '2026-02-17 07:05:04'),
	(214, '678230c579bd51cee772b661', '25 Nuansa Soto Khas Indonesia (Edisi 50 Tahun GPU)', 'Tim Boga GPU', 'Culinary', 'Dengan bangga menawarkan 25 resep asli soto dan sop yang khas, mewakili beragam selera aneka daerah di seantero negeri.Ada yang memanfaatkan bahan utama ayam atau daging sapi, kadang daging kambing ataupun ikan; ada yang bersantan, ada pula yang tampil cerah ataupun pekat oleh bumbu. Kesemuanya sanggup menggoda selera.Pas untuk hidangan dimeja makan keluarga, cocok pula sebagai pilihan di perjamuan istimewa. Selanjutnya, kami serahkan pada Anda.....', 'Rp 110,000', '58 pages', '24 April 2024', 'Nusantara, indonesia, masakan indonesia, buku masak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94530/EDISI_50TH_GPU_25_Nuansa_Soto_Khas_Indonesia_C_1_4_2024.jpg', '2026-02-17 07:04:30', '2026-02-17 07:05:04'),
	(215, '6782304579bd51cee772b61d', '40 Tahun Mengabdi di Dunia Diplomasi', 'Darmansjah Djumala,', 'Politics', '40 Tahun Mengabdi di Dunia Diplomasi: Serpihan Memori Para Diplomat Indonesia berisi pengalaman dan pemikiran para diplomat RI alumnus Sekolah Dinas Luar Negeri (Sekdilu) Angkatan X selama 40 tahun (1984–2024) menjalani karier sebagai diplomat sekaligus aparatur sipil negara (ASN). Setiap topik yang dipilih digali dari pengalaman paling berkesan para Penulis selama bekerja di Kementerian Luar Negeri (Kemlu RI). Memahami diplomasi adalah memahami konteks sejarah waktu dan tantangan zaman. Dalam diplomasi, optimisme tidak jarang berbenturan dengan realitas dan pesimisme yang menggelayuti kemajuan langkah politik luar negeri. Harapan dan cita-cita bersama diujikan pada realitas.Buku ini mampu memberikan perspektif penting yang mendukung terbangunnya pemahaman yang tepat mengenai makna dan arah politik luar negeri ke depan. Perspektif itu dapat memperluas wawasan para pembaca, khususnya praktisi, pemerhati, dosen, serta mahasiswa yang menekuni hubungan internasional atau pebisnis.“Berbagai kisah para diplomat yang tertuang dalam buku ini memberikan sudut pandang di balik layar dapur diplomasi, menjadi contoh nyata diplomacy in practice, serta menjadi bagian dari rekam jejak perjalanan diplomasi Indonesia.” —Retno L.P. Marsudi Menteri Luar Negeri Indonesia 2014–sekarang“Buku ini memuat tulisan yang beragam, baik isi, lokasi cerita, maupun penulisnya. Di bawah tema human interest, pembaca dibawa pour des reason d’horizon, berkeliling dunia ke tempat 29 mantan diplomat senior Indonesia bertugas. Saya berharap buku ini dapat menambah wawasan pembaca tentang dinamika kehidupan internasional.” —Dr. Hassan Wirajuda Menteri Luar Negeri RI 2001–2009“Dengan format bunga rampai, buku karya Angkatan ke-10 ini menyuguhkan keberagaman isi maupun tema, visi maupun gaya. Apakah itu suatu pemikiran yang mendalam; pengalaman yang inspiratif; atau cerita yang menarik mengenai politik, keamanan, ekonomi, ataupun budaya; semuanya ada. Buku ini dapat menjadi bacaan bagi sesama rekan untuk bernostalgia serta para diplomat dan khalayak umum yang ingin belajar.” —Soemadi D.M. Brotodiningrat Mantan Duta Besar RI di Tokyo, Washington DC, dan Wakil Tetap RI untuk PBB di New York', 'Rp 255,000', '300 pages', '24 April 2024', 'Politics, Politic, indonesia', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94461/Hum_-_40_Tahun_Mengabdi_Di_Dunia_Diplomasi.jpg', '2026-02-17 07:04:30', '2026-02-17 07:05:04'),
	(216, '67822f7279bd51cee772b5ab', 'Inovasi Kebijakan dan Evaluasi Insentif Perpajakan Indonesia', 'Badan Kebijakan Fiskal,', 'Social Sciences', 'Insentif perpajakan memainkan peran krusial dalam membentuk dan mendorong aktivitas ekonomi di berbagai negara. Keberadaan insentif ini dapat merangsang investasi, inovasi, serta pertumbuhan sektor-sektor tertentu dalam perekonomian. Karena dampak yang luas itu, penting bagi kita untuk memberikan perhatian terhadap desain, implementasi, dan dampak nyata dari insentif perpajakan.Evaluasi insentif perpajakan adalah langkah kritis untuk memastikan efektivitas dan efisiensi dari kebijakan ini. Tanpa evaluasi yang cermat, ada risiko bahwa insentif yang telah diberikan tidak memberikan hasil yang sesuai dengan tujuan awalnya. Oleh karena itu, evaluasi insentif perpajakan bukanlah sekadar pilihan, melainkan merupakan bagian integral dari siklus kebijakan.Evaluasi insentif perpajakan memerlukan kolaborasi berbagai pihak, seperti pemerintah, akademisi, praktisi perpajakan, serta masyarakat sipil. Setiap aspek memiliki perspektif unik yang dapat melengkapi informasi yang diperlukan untuk penilaian yang holistik. Evaluasi yang inklusif dan kolaboratif juga dapat membantu mengidentifikasi celah dalam desain dan implementasi insentif, serta memastikan adanya akuntabilitas yang lebih baik dalam pengambilan keputusan perpajakan.Buku ini merupakan upaya nyata dalam mengumpulkan berbagai pandangan dan penelitian terkait evaluasi insentif perpajakan dengan menghadirkan sepuluh artikel yang membahas evaluasi insentif dari berbagai aspek yang relevan. Artikel-artikel ini mencakup topik seperti dampak insentif terhadap pertumbuhan ekonomi, penerimaan pajak, transformasi ekonomi, dukungan terhadap UMKM, pembiayaan hijau, hilirisasi, pengarusutamaan gender, serta implikasi pajak internasional. Melalui koleksi artikel yang beragam, buku ini bertujuan memberikan wawasan yang mendalam tentang pentingnya evaluasi insentif perpajakan dalam konteks beragam tantangan dan peluang ekonomi saat ini.', 'Rp 140,000', '356 pages', '24 April 2024', 'Bisnis, Financial, FInansial, Finance, buku bisnis', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94347/Hum_-_Inovasi_Kebijakan_dan_Evaluasi_Insentif_Perpajakan_Indonesia.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(217, '678230cb79bd51cee772b664', 'Lima Sekawan : Di Pulau Harta (Edisi 50 Tahun)', 'Enid Blyton', 'Middle Grade Readers', 'Lima Sekawan terdiriatas empat anak bernama Julian, Dick, George, dan Anne, serta seekor anjing bernama Timmy. Mereka berlima sering melakukan penjelajahan ke tempat yang asing. Serunya, perjalanan Lima Sekawan sering kali berujung pada sebuah misteri yang harus mereka pecahkan. Kisah Di Pulau Harta ini adalah petualangan pertama Lima Sekawan. Pada suatu liburan, Julian, Dick, dan Anne diberi saran oleh kedua orangtua mereka untuk berkunjung ke rumah sang paman di pesisir Inggris. Di sinilah mereka bertiga bertemu dengan George dan Timmy untuk pertama kalinya. Keluarga George memiliki tanah yang luas, termasuk sebuah pulau karang kecil yang berada tak jauh dari pantai. Pulau Kirrin ini dikelilingi karang-karang tajam. Tak seorang pun warga yang berani mendekati pulau karena takut perahunya karam. Ada bangkai kapal tua muncul di Pulau Kirrin! Tapi di manakah gerangan harta karunnya? Lima Sekawan mengikuti semua petunjuk yang ada tapi ternyata mereka tidak sendirian! Ada orang lain yang ikut memburu harta karun…', 'Rp 49,000', '232 pages', '24 April 2024', 'Novel, novel anak, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94533/Lima_Sekawan_Di_Pulau_Harta_50_cov-1.jpg', '2026-02-17 07:04:30', '2026-02-17 07:04:30'),
	(218, '678230cd79bd51cee772b665', 'Titipan Kilat Penyihir (2024)', 'Eiko Kadono', 'AsianLit - Japan', 'Sesuai tradisi penyihir, pada usia tiga belas tahun Kiki harus pindah ke kota lain. Dia harus meninggalkan Ibu, Ayah, serta kota kelahirannya. Kiki hanya akan ditemani Jiji si kucing hitam.Ibu sudah melarangnya tinggal di kota besar, tapi Kiki kepalang suka pada kota Koriko, karena menara jamnya sangat tinggi dan letaknya dekat laut. Tapi astaga… warga kota Koriko tidak menyambut Kiki dengan hangat. Apakah Kiki bakal bisa bertahan di kota ini, padahal dia cuma bisa satu sihir: terbang dengan sapu?', 'Rp 79,000', '200 pages', '24 April 2024', 'novel anak, Novel, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94534/Titipan_Kilat_Penyihir_cov-1.jpg', '2026-02-17 07:04:30', '2026-02-17 07:05:04'),
	(221, '6782303e79bd51cee772b619', 'Buku Pertamaku: Sains', 'Barbara Taylor,', 'Activity Books', 'Dengan berbagai topik menarik, dan ilustrasi cerah, dunia sains menjadi lebih menyenangkan untuk dipelajari. Sains tercipta untuk semua orang, termasuk KAU!', 'Rp 99,000', '48 pages', '24 April 2024', 'Anak-anak, Anak, Activity Book, Activity Books, Pictures Book, picture books, buku anak gramedia, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94457/Anak_-_Buku_Pertamaku_Sains.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(222, '678230c979bd51cee772b663', 'Keluarga Cemara #1 (Edisi 50 Tahun GPU)', 'Arswendo Atmowiloto', 'Slice of Life', 'Kisah sebuah keluarga yang memilih hidup dengan hanya bermodalkan kejujuran. Keluarga yang amat sangat sederhana, terdiri atas Abah, kepala keluarga yang bekerja sebagai penarik becak dan buruh apa saja; Emak, sang ibu yang membuat opak untuk dijajakan putrinya; Euis, si sulung yang kelas enam SD, pernah mengalami masa jaya orangtuanya sebagai pengusaha; Ara atau Cemara yang baru masuk TK; serta Agil si bungsu.Kalau air mata bisa menjadi simbol kebahagiaan, inilah kisah itu.Keluarga Cemara 1 ini merupakan kompilasi yang terdiri atas tiga judul: Keluarga Cemara, Musik Musim Hujan, dan Kupon Kemenangan.', 'Rp 99,000', '288 pages', '24 April 2024', 'Novel, novel anak, novel remaja, Arswendo Atmowiloto, Keluarga', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94532/Keluarga_cemara_50_cov_(1)-1.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(223, '6782304979bd51cee772b61f', 'Mengarang & Mewarnai: Alien & Robot', 'Miles Kelly Publishing', 'Activity Books', 'Apakah kau ingin mengarang cerita, tapi tidak tahu harus mulai dari mana? Buku ini akan membantmumu membuat cerita-cerita hebat, dan kau juga bisa mewarnai gambar di dalamnya! Ayo mengarang tiga cerita tentang alien! Untuk mempermudah, sudah disediakan kalimat-kalimat pembuka yang siap menyulut kreativitasmu!', 'Rp 39,000', '32 pages', '24 April 2024', 'Anak-anak, Aktivitas, Anak, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94463/Anak_-_MM_Alien_Robot.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(224, '6782300c79bd51cee772b5fe', 'Brilliant Kitchen', 'Erni Bryan', 'Culinary', 'Buku ini disusun atas permintaan para follower setia @ernibryan di Instagramnya (dengan jumlah follower 122 ribu) yang ingin sekali resep-resep yang penulis share dibukukan agar lebih mudah dan nyaman dibawa saat bereksperimen di dapur. Sebuah buku panduan bagi Anda yang baru mau belajar baking hingga bisa menghasilkan karya brilliant atau cemerlang dari dapur Anda sendiri.Penulis memang gemar mencoba membuat kue-kue cantik ini itu sejak mengenal social media, dan di-posting ke social media. Di tahun 2015. Dan hal tersebut lalu berlanjut dan berkembang hingga menjadi content creator hingga sekarang. Belum afdol rasanya, kalau hasil karya penulis belum di-share ke social media. Sekaligus mau mengedukasi ke para follower bahwa siapapun bisa membuat kue yang cantik dan lezat. Konten yang penulis bagikan berupa video tutorial membuat kue-kue yang tidak hanya cantik namun juga menjadi inpsirasi untuk dijual.Kegemaran bikin kue yang sudah penulis jalani selama kurang lebih 3 tahun ini ternyata banyak memberikan inspirasi kepada follower untuk bisa bikin juga. Bahkan simple recipe yang penulis bagikan dijadikan ide jualan mereka. Selama 3 tahun ini, ratusan resep yang sudah penulis bagikan dan akhirnya bisa penulis bukukan beberapa resep favorit follower.Buku yang bisa menginspirasi lebih banyak orang lagi untuk bisa bikin kue-kue cantik yang lezat, baik kue teradisional Indonesia, Asia maupun kue-kue Eropa, dan Modern. Sebuah buku yang diharapkan Penulisnya dapat memberikan kesuksesan buat Anda yang menjadikan resep ini sebagai ide jualan.', 'Rp 119,000', '106 pages', '24 April 2024', 'Home Cooking, Cooking, Masakan Rumahan, masakan indonesia, buku masak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94430/BBK_-_Brilliant_Kitchen.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(225, '6782303c79bd51cee772b618', 'Buku Pertamaku: Pertama ke Sekolah', 'Catherine Veitch,', 'Activity Books', 'Bantu anak mempersiapkan diri untuk sekolah dengan buku ini. Jelajahi ruang kelas, tempat bermain, aula sekolah, dan masih banyak tempat lainnya. Perkenalkan hal-hal baru kepada anak dengan cara mudah dan menyenangkan!', 'Rp 99,000', '48 pages', '24 April 2024', 'Anak-anak, Anak, Activity Book, Activity Books, Pictures Book, picture books, buku anak gramedia, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94456/Anak_-_Buku_Pertamaku_Hari_Pertama_Sekolah.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(226, '6782304079bd51cee772b61a', 'Buku Pertamaku: Selamatkan Bumi', 'Alex Woolf,', 'Activity Books', 'Ayo jelajahi planet yang kita tinggali dan cari tahu cara merawatnya. Setiap halaman buku ini dipenuhi informasi-informasi penting. Ada juga poster yang memuat cara-cara memelihara lingkungan (reduce, reuse, recycle).', 'Rp 99,000', '48 pages', '24 April 2024', 'Anak-anak, Anak, Activity Book, Activity Books, Pictures Book, picture books, buku anak gramedia, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94458/Anak_-_Buku_Pertamaku_Selamatkan_Bumi.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(227, '6782301f79bd51cee772b608', 'Seperti Sungai yang Mengalir (Like the Flowing River)', 'Paulo Coelho', 'Latin American Literature', 'Seperti Sungai yang Mengalir berisi kumpulan renungan dan cerita pendek Paulo Coelho, kisah-kisah yang menggugah tentang kehidupan dan kematian, suratan takdir dan pilihan, cinta yang hilang dan ditemukan. Kadang humoris, kadang serius, tapi selalu dalam. Buku ini, seperti semua karya Coelho lainnya, mengeksplorasi arti menjalani hidup dengan sepenuh-penuhnya.', 'Rp 89,000', '303 pages', '09 April 2024', 'Inspiration, Inspirational, inspirasi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94440/Fiksi_-_Seperti_Sungai_yang_Mengalir.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(228, '678230bc79bd51cee772b65d', 'Sang Alkemis (Edisi 50 Tahun GPU)', 'Paulo Coelho', 'Latin American Literature', 'Setiap beberapa puluh tahun, muncul sebuah buku yang mengubah hidup para pembacanya selamanya. Novel Paulo Coelho yang memikat ini telah memberikan inspirasi bagi jutaan orang di seluruh dunia. Kisah yang sangat sederhana, namun menyimpan kebijaksanaan penuh makna, tentang anak gembala bernama Santiago yang berkelana dari rumahnya di Spanyol ke padang pasir Mesir untuk mencari harta karun terpendam di Piramida-Piramida. Di perjalanan dia bertemu seorang perempuan Gipsi, seorang lelaki yang mengaku dirinya Raja, dan seorang alkemis––semuanya menunjukkan jalan kepada Santiago untuk menuju harta karunnya.Tak ada yang tahu isi harta karun itu, atau apakah Santiago akan berhasil mengatasi rintangan-rintangan sepanjang jalan. Namun perjalanan yang semula bertujuan untuk menemukan harta duniawi berubah menjadi penemuan harta di dalam diri.Kaya, menggugah, dan sangat manusiawi, kisah Santiago menunjukkan kekuatan mimpi-mimpi dan pentingnya mendengarkan suara hati kita.', 'Rp 69,000', '224 pages', '09 April 2024', 'Literatures, Literature, Sang Alkemis, The Alchemist', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94525/The_Alchemist_50_cov-1.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(229, '678230ba79bd51cee772b65c', 'Fairish (Edisi 50 Tahun GPU)', 'Esti Kinasih', 'TeenLit', '“Lo pura-pura jadi pacar gue ya, Rish? Biar gue nggak dikerubutin cewek-cewek centil itu,” pinta Davi.“Tapi... konsekuensinya, Dav,” ujar Irish pelan.“Lo punya cowok?” Kali ini ganti Davi yang tersentak kaget.“Atau… lagi ada yang lo suka?”Irish buru-buru menggeleng. “Bukan gitu. Kalo mereka nyangka kita beneran...”“Biarin aja. Bagus malah!” Davi menggenggam kedua tangan Irish.Akhirnya Irish menerima permintaan Davi meskipun dengan setengah hati. Tapi setelah dijalani, Irish senang kok menjadi satu- satunya cewek yang paling dekat dengan Davi, walau cuma untuk sementara dan tanpa ada ikatan apa-apa.Irish emang nggak secantik Kristen Stewart. Dia cuma cewek biasa, yang di sekolah pun sama sekali nggak ngetop. Karena itu Davi merasa aman, soalnya dia merasa nggak bakalan naksir Irish. Tapi saat muncul cowok lain yang bikin Irish terpikat, kok Davi jadi nggak rela kehilangan Irish, ya?', 'Rp 89,000', '304 pages', '09 April 2024', 'novel remaja, teenlit, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94524/fairish_50_cov-1.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(230, '6782304279bd51cee772b61b', 'Mr. Ripley yang Lihai (The Talented Mr. Ripley)', 'Patricia Highsmith', 'Mysteries & Thrillers', 'Tom Ripley sedang dikejar utang ketika nasib baik berpihak kepadanya. Seorang kenalan menawarinya perjalanan gratis ke Itali untuk membujuk Dickie Greenleaf agar mau pulang kepada ayahnya yang kaya. Ternyata Ripley sangat menyukai Dickie dan gaya hidupnya. Dia ingin menjadi seperti Dickie—persis seperti Dickie. Dengan pembawaannya yang ramah, menyenangkan, dan manipulatif, Tom berniat mencapai tujuannya, dengan cara apa pun. Apa pun.', 'Rp 129,000', '416 pages', '09 April 2024', 'crime, Mystery & Thrilers, Mystery & Thrillers, Mysteries, Mystery', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94459/Fiksi_-_Mr__Ripley_yang_Lihai_(The_Talented_Mr__Ripley).jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(231, '678230b879bd51cee772b65b', 'Lupus: Tangkaplah Daku, Kau Kujitak! (Edisi 50 Tahun GPU)', 'Hilman', 'Romance', 'Lupus adalah cowok manis tapi jail, murid kelas 2 di SMA Merah Putih. Rambutnya berjambul, mirip John Taylor (vokalis grup band Duran Duran). Lupus senang mengunyah permen karet dan hobi main tebak- tebakan.Banyak kejadian kocak yang dialami Lupus. Misalnya, kencan pertama Lupus gagal hanya karena dia lupa menanyakan alamat pacarnya. Terus waktu ada razia rambut gondrong di sekolah, Lupus panik banget. Tapi dia punya 1001 cara untuk lolos dari razia.Tapi sebandel-bandelnya Lupus, dia tetap anak yang berbakti pada maminya, juga kakak yang sayang banget pada Lulu, adik semata wayangnya. Tapi apa kata Lulu? “Mami sih lebih cemas kehilangan sendok daripada kehilangan kamu, Pus!”Whoaaa! Lupus cuma bisa mingkem.', 'Rp 69,000', '160 pages', '09 April 2024', 'romance novel, novel roman, Novel, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94523/Lupus_tangkaplah_daku_50_cov-1.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(232, '6782303379bd51cee772b613', 'Rampok Memori dan Bintang Sambit (We Could Be Heroes)', 'Mike Chen', 'Slice of Life', 'Jamie Sorenson bukan sekadar rampok bank. Ia si Rampok Memori yang bisa mengintip dan mengosongkan ingatan. Ancam, ambil uang, hapus memori, angkat kaki. Biasanya begitu, tetapi aksi terakhirnya nyaris jadi bencana dan ia dikejar-kejar Bintang Sambit, pahlawan super kesayangan San Delgado yang bisa terbang.Zoe Wong tukang antar makanan pada siang hari, tetapi identitas rahasianya sebagai Bintang Sambit membuatnya merasa lebih berarti. Dengan kecepatan super, kekuatan yang tidak kalah super, dan kemampuan melayangnya, reputasinya sebagai kurir sekaligus pahlawan tak bercela.Setelah bahu-membahu menyelamatkan orang-orang dari kebakaran, Jamie dan Zoe sadar mereka memiliki kesamaan: terbangun tanpa ingatan akan identitas mereka di apartemen asing dua tahun yang lalu. Maka, keduanya memutuskan bekerja sama menggali petunjuk tentang masa lalu mereka.Namun sepenting itukah masa lalu? Mungkinkah sebenarnya diri mereka cukup ditentukan oleh pilihan yang mereka ambil saat ini, bukan dulu?', 'Rp 129,000', '392 pages', '03 April 2024', 'Mike Chen, slice of life, novel remaja, novel roman, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94451/Fiksi_-_Rampok_Memori_dan_Bintang_Sambit_(We_Could_Be_Heroes).jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(233, '6782303879bd51cee772b616', 'Istana Merah (The Red Palace)', 'June Hur', 'Mysteries & Thrillers', 'Joseon (Korea), 1758.Anak haram pada masa itu hanya punya sedikit pilihan hidup, terutama untuk anak perempuan. Namun, berkat kerja keras dan tekun belajar, Hyeon, gadis berusia delapan belas tahun, berhasil menjadi perawat di istana. Dengan selalu patuh dan giat bekerja, ia berharap sang ayah akhirnya mau mengakui dirinya.Namun, Hyeon tiba-tiba terjerumus ke dalam politik istana yang kelam dan berbahaya saat dalam waktu semalam, empat wanita tewas terbunuh. Tersangkanya teman dekat dan gurunya sendiri. Maka dengan tekad bulat untuk membuktikan sang guru tidak bersalah, Hyeon diam-diam melakukan penyelidikan.Ia lalu bertemu Eojin, inspektur polisi muda yang juga memburu si pembunuh. Ketika bukti-bukti mulai mengarah pada sang Putra Mahkota, Hyeon dan Eojin harus bekerja sama membongkar berbagai rahasia mematikan di istana.“Thriller politik menegangkan, cerita cinta yang indah, dan kisah menuju kedewasaan, semua dikemas dengan unik dalam buku ini.” —School Library Journal, starred review', 'Rp 109,000', '368 pages', '03 April 2024', 'asian, Korea, Thrilers Novel, Novel, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94454/Fiksi_-_Istana_Merah_(The_Red_Palace).jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(234, '678230b179bd51cee772b657', 'Selimut Debu (2024)', 'Agustinus Wibowo', 'Nonfiction', '[Agustinus] tak ingin hanya menjadi penonton isi dunia. Ia mau terlibat sepenuhnya dalam perjalanan itu. Ia tak sekadar melihat pemandangan, berpindah dari satu tempat ke tempat lain, tetapi juga mengenal budaya dan berinteraksi dengan masyarakat setempat. –Kompas– Afghanistan. Nama negeri itu sudah bersinonim dengan perang tanpa henti, kemiskinan, maut, bom bunuh diri, kehancuran, perempuan tanpa wajah, dan ratapan pilu. Nama yang sudah begitu tidak asing, namun tetap menyimpan misteri yang mencekam.Pada setiap langkah di negeri ini, debu menyeruak ke rongga mulut, kerongkongan, lubang hidung, kelopak mata. Bulir-bulir debu yang hampa tanpa makna, tetapi menjadi saksi pertumpahan darah bangsa-bangsa, selama ribuan tahun.Aura petualangan berembus, dari gurun gersang, gunung salju, padang hijau, lembah kelam, langit biru, danau ajaib, hingga ke sungai yang menggelegak hebat. Semangat terpancar dari tatap mata lelaki berjenggot lebat dalam balutan serban, derap kaki kuda yang mengentak, gemercik teh, tawa riang para bocah, impian para pengungsi, peninggalan peradaban, hingga letupan bedil Kalashnikov.Agustinus Wibowo menapaki berbagai penjuru negeri perang ini sendirian, untuk menyibak misteri prosesi kehidupan di tanah magis yang berabad-abad ditelantarkan, dijajah, dan dilupakan. Menyibak cadar negeri cantik nan memikat, Afghanistan.', 'Rp 139,000', '461 pages', '03 April 2024', 'nonfiksi, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94519/selimut_debu_cov_2024-1.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(235, '678230b379bd51cee772b658', 'Garis Batas (2024)', 'Agustinus Wibowo', 'Amore', 'Petualangan Agustinus Wibowo di buku ini seakan mengajak kita untuk masuk dan melihat sendiri tempat-tempat yang selama ini tersembunyi di peta dunia. –Andy Noya Negeri apa di seberang sungai sana? Penduduk desa Afghan setiap hari memandang ke “luar negeri” yang hanya selebar sungai jauhnya. Memandangi mobilmobil melintas, tanpa pernah menikmati rasanya duduk dalam mobil. Mereka memandangi rumah-rumah cantik bak vila, sementara tinggal di dalam ruangan kumuh remang-remang yang terbuat dari batu dan lempung. Mereka memandangi gadis-gadis bercelana jins tertawa riang, sementara kaum perempuan mereka sendiri buta huruf dan tak bebas bepergian.Negeri seberang begitu indah, namun hanya fantasi. Fantasi tiga dimensi yang menemani mimpi-mimpi mereka. Fantasi orang-orang yang hidup di seberang garis batas.Fantasi yang sama membawa Agustinus Wibowo bertualang ke negeri-negeri Asia Tengah yang misterius. Tajikistan. Kirgizstan. Kazakhstan. Uzbekistan. Turkmenistan. Negeri-negeri yang namanya semua berakhiran “Stan”. Perjalanan ini bukan hanya mengajak Anda mendaki gunung salju, menapaki padang rumput, menyerap kemegahan khazanah tradisi dan kemilau peradaban Jalan Sutra, ataupun bernostalgia dengan simbol-simbol komunisme Uni Soviet, tetapi juga menguak misteri tentang takdir manusia yang terpisah dalam kotak-kotak garis batas', 'Rp 149,000', '510 pages', '03 April 2024', 'agustinus wibowo, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94520/garis_batas_cov_2024-1.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(236, '678230af79bd51cee772b656', 'Titik Nol (2024)', 'Agustinus Wibowo', 'Literary', 'Jauh. Mengapa setiap orang terobsesi oleh kata itu? Marco Polo melintasi perjalanan panjang dari Venesia hingga negeri Mongol. Para pengelana lautan mengarungi samudra luas. Para pendaki menyabung nyawa menaklukkan puncak.Juga terpukau pesona kata “jauh”, si musafir menceburkan diri dalam sebuah perjalanan akbar keliling dunia. Menyelundup ke tanah terlarang di Himalaya, mendiami Kashmir yang misterius, hingga menjadi saksi kemelut perang dan pembantaian. Dimulai dari sebuah mimpi, ini adalah perjuangan untuk mencari sebuah makna.Hingga akhirnya setelah mengelana begitu jauh, si musafir pulang, bersujud di samping ranjang ibunya. Dan justru dari ibunya yang tidak pernah ke mana-mana itulah, dia menemukan satu demi satu makna perjalanan yang selama ini terabaikan.Agustinus telah menarik cakrawala yang jauh pada penulisan perjalanan (travel writing) di Indonesia. Penulisan yang dalam, pengalaman yang luar biasa, membuat tulisan ini seperti buku kehidupan. Titik Nol merupakan cara bertutur yang benar-benar baru dalam travel writing di negeri ini. —Qaris Tajudin, editor Tempo dan penulis novel.', 'Rp 159,000', '556 pages', '03 April 2024', 'sastra, Literary, agustinus wibowo', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94518/titik_nol_cov_2024-1.jpg', '2026-02-17 07:05:04', '2026-02-17 07:05:04'),
	(242, '6782302679bd51cee772b60c', 'Berawal dari Skandal (First Comes Scandal)', 'Julia Quinn', 'Historical Romance', 'Georgiana Bridgerton tidak menentang pernikahan. Namun ia mengira ia akan punya suara dalam menentukan pernikahannya. Tapi dengan reputasi yang terancam rusak akibat skandal, Georgie diberi dua pilihan: hidup sebagai perawan tua atau menikah dengan begundal yang menghancurkan hidupnya. Ia tidak pernah mengira akan mendapatkan pilihan ketiga.Sebagai anak keempat seorang earl, Nicholas Rokesby bertekad untuk membangun hidupnya sendiri. Dan ia punya kehidupan di Edinburgh, tempat ia nyaris menyelesaikan studi kedokterannya, dan ia tak punya waktu—atau minat—untuk mencari istri. Tapi ketika ia mengetahui hidup Georgie Bridgerton nyaris hancur, ia tahu apa yang harus ia lakukan.Mungkin lamarannya bukanlah lamaran paling romantis, tapi Nicholas tak pernah menyangka bahwa Georgie akan menolaknya. Georgie berkeras dirinya tidak ingin belas kasihan siapa pun, lagi pula ia tak yakin mereka bisa menganggap satu sama lain sebagai lebih dari teman. Tapi selagi melakukan pendekatan, mereka menemukan irama baru dalam interaksi mereka. Berawal dari skandal, diikuti pernikahan. Kemudian datanglah cinta....', 'Rp 109,000', '440 pages', '27 March 2024', 'Romance Novels, History, Historical Romance, romance novel, Romance, Harlequin', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94444/Fiksi_-_First_Comes_Scandal.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(243, '678230a079bd51cee772b64e', 'TeenLit: Dealova (Edisi 50 tahun GPU)', 'Dyan Nuranindya', 'TeenLit', 'Karra, cewek tomboi yang jago main basket ini memang beda. Rambutnya nggak cepak seperti kebanyakan cewek tomboi, tampangnya manis, dan orangnya nyantai banget. Tapi kalo Karra udah marah, waaah... bisa gawat.Jadi cewek seperti Karra tuh beruntung banget. Selain punya kakak cowok yang sayang banget sama dia namanya Iraz—teman-teman Iraz juga care sama Karra. Terutama Ibel, cowok jago main gitar yang suka warna biru. Bahkan waktu harus keluar negeri, Iraz malah menitipkan Karra pada Ibel.Selama ini Karra menganggap Ibel sebagai kakak, jadi dia cuek aja waktu Ibel menunjukkan perhatian. Karra malah ditaksir Dira, anak baru di sekolah yang juga jago main basket. Tampang Dira yang sok cool tapi sengak bikin Karra sebel banget sama cowok itu. Tapi katanya, batas antara cinta dan benci kan tipis banget. Iya nggak sih?', 'Rp 89,000', '312 pages', '27 March 2024', 'teenlit, Novel, novel remaja, Teen Novel, Teen Novels, Teens Novels', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94510/Dealova_50_cov.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(245, '6782302f79bd51cee772b611', 'Bukan Kekasih Impian (When a Rogue Meets His Match)', 'Elizabeth Hoyt', 'Historical Romance', 'Gideon Hawthorne yang ambisius dan licik telah menghabiskan sepanjang hidupnya merangkak ke atas hingga ke posisinya yang sekarang. Sepanjang sepuluh tahun terakhir, ia telah menjadi kaki tangan Duke of Windemere, melakukan tugas-tugas berbahaya tanpa banyak tanya. Sekarang Gideon ingin berhenti dan membangun bisnisnya sendiri. Tapi Windemere ingin Gideon menyelesaikan satu tugas terakhir, dan hadiahnya mustahil ditolak: menikahi Messalina Greycourt.Messalina Greycourt yang penuh semangat dan cerdik tak pernah kekurangan peminang. Ketika Windemere memberitahu Messalina bahwa ia harus menikah dengan Mr. Hawthorne, ia pun merasa ngeri. Tapi ia terkejut ketika Gideon menawarkan kompromi: selama Messalina berperan sebagai istri yang berbakti, ia berjanji takkan menyentuh Messalina hingga Messalina memintanya. Karena Messalina percaya dirinya takkan menginginkan apa pun dari Gideon, ia langsung menyetujui. Namun, semakin lama mereka menghabiskan waktu bersama, semakin sulit baginya untuk menjauhi pria itu.', 'Rp 119,000', '488 pages', '27 March 2024', 'Romance Novels, romance novel, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94449/Fiksi_-_Bukan_Kekasih_Impian.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(246, '6782301779bd51cee772b604', 'Si Buku Bengis Kecil #1', 'Magnus Myst', 'Middle Grade Readers', 'Aku mau mengajak kamu—ya KAMU—bertualang.Aku butuh bantuanmu. SEKARANG. Apa pun yang sedang kamu lakukan, berhentilah. Mulai baca buku ini. Nggak usah pakai tunggu-tunggu—sekaranglah saat paling pas!Bodo amat apa kata orang dewasa. Yuk bantu aku jadi nakal, bahkan bengis.Kamu berani, kan? Tenang saja, kita tidak bakal dihukum. Kita akan bersenang-senang. YAKIN!Buku Bengis ini punya mimpi dan cita-cita, tapi ia butuh bantuan KAMU, pembacanya. Di buku ini, kamu akan menemukan banyak kisah lucu yang penuh teka-teki menantang, tebak-tebakan, gambar superkeren.Yuk, langsung saja. Kamu pasti bisa!', 'Rp 119,000', '128 pages', '27 March 2024', 'Children, Childrens Books, Children Books, Children Book, novel remaja, novel anak, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94436/Anak_-_Si_Buku_Bengis_Kecil_1.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(247, '6782301979bd51cee772b605', 'Si Buku Bengis Kecil #2', 'Magnus Myst', 'Middle Grade Readers', 'Pssttt!Kamu pasti nggak percaya: aku baru saja menemukan rahasia terpenting sedunia. Serius! Mau kuberitahu? Baiklah. Tapi, ini akan jadi HAL PALING MENGERIKAN yang pernah kamu baca. Semoga kamu sanggup ya. Aku yakin kamu pemberani!Kalau kamu memang pemberani, cepat, baca aku!Kamu akan jadi pembaca beruntung yang menemukan rahasia besar SI BUKU BENGIS. Teka-teki dan permainan di dalamnya akan menantangmu. Kalau berhasil, kamu bakal jadi si paling bengis!', 'Rp 119,000', '160 pages', '27 March 2024', 'Children, Pre Teens, Teens Novels, Childrens Books, Teen Serial, Teen Novel, Teen Novels, Children Books, Children Book, novel remaja, novel anak, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94437/Anak_-_Si_Buku_Bengis_Kecil_2.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(248, '67822ed679bd51cee772b558', 'Kebun Jagal', 'Putra Hidayatullah', 'Short Stories', '“Jika ada sebuah kumcer yang ingin saya tulis, itu harusnya seperti Kebun Jagal, tempat di mana reruntuhan tragedi yang nyaris tanpa sisa berhasil disusun ulang dengan indah; dengan kekuatan naratif yang memukau.” —Azhari Aiyub, Peraih Kusala Sastra Khatulistiwa 2018 Kategori Prosa.Ketika pertama mendarat di kampung kami, Komandan dan anak buahnya berkeliling berjalan kaki. Mereka mengambil setiap ayam jago dan burung beo di rumah-rumah orang kampung dan membawanya ke markas. Mereka lalu memberi nama baru untuk burung-burung itu dengan nama-nama ayah kami.Di tubir konflik, harga manusia dan kemanusiaan terlalu murah. Berbalut keka- yaan budaya Aceh, tokoh-tokoh dalam buku ini harus menghadapi sengkarut konflik yang tidak hanya menegangkan, sesekali konyol, satir, dan menggeli- kan. Konflik dalam buku ini memang kebanyakan terjadi di Aceh, tetapi sangat mungkin kisah serupa terjadi di banyak daerah dan negara.***Putra Hidayatullah—akademisi, penulis, dan kurator seni—memotret konflik yang tumbuh di masyarakat dengan cermat. Tidak saja mengetengahkan runcingnya konflik di tengah masyarakat Aceh, tetapi juga mendedah relasi manusia dan budaya pada umumnya.', 'Rp 89,000', '146 pages', '27 March 2024', 'Kumpulan cerita pendek, Cerita Pendek, Short Stories, Cerpen', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94264/Sastra_-_Kebun_Jagal.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(249, '678230ad79bd51cee772b655', 'Dasar-Dasar Ilmu Politik (Edisi 50 Tahun GPU)', 'Miriam Budiarjo Prof.', 'Culture ,', 'Dasar-Dasar Ilmu Politik membahas konsep-konsep se- perti politik, kekuasaan, dan pembuatan keputusan. Di sini, para mahasiswa serta masyarakat umum yang berminat pada dunia ilmu politik juga bisa mempelajari fungsi undang-undang dasar, kelompok-kelompok politik, dewan perwakilan rakyat, demokrasi, serta hak-hak asasi manusia.Perbedaan signifikan edisi revisi ini dengan edisi sebelum- nya bukan hanya pada format buku, melainkan juga struk- tur isinya. Penambahan bab baru serta penggabungan bab dilakukan untuk mengakomodasi keseimbangan isi antarbab, variasi substansi, dan penyusunan alur bab, mulai dari materi konseptual sampai materi empiris.Dengan tetap mempertahankan bobot ilmiahnya, edisi revisi buku yang ditulis oleh ilmuwan politik senior ini akan lebih enak dibaca oleh siapa pun yang ingin memperoleh gambaran menyeluruh tentang ilmu politik beserta implementasinya.', 'Rp 135,000', '548 pages', '27 March 2024', 'Politic', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94517/Edisi_50TH_GPU_Dasar_dasar_Ilmu_Politik_C_1_4_2024_R_(1).jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(250, '6782303a79bd51cee772b617', 'Berpikir yang Tidak Dipikirkan Orang Lain (The Art of Being Unreasonable)', 'Eli Broad', 'Business Management & Leadership,', '“Eli Broad memberitahu kita rahasia suksesnya dalam bisnis, filantropi, dan kehidupan―dia mengajukan pertanyaan yang tepat, mencari jawaban yang benar, dan tidak pernah berhenti berusaha sampai mendapatkan hasilnya.” ―Bill Clinton, Presiden Amerika Serikat ke-42“Sebagai pencetak perusahaan sukses, Eli Broad tidak ada tandingannya, dan The Art of Being Unreasonable dengan jelas menunjukkan kenapa. Buku ini juga dengan tegas menyatakan bahwa tujuan utama kekayaan adalah pelayanan publik.” ―Bill Gates, Co-Chair Yayasan Bill & Melinda Gates dan Chairman Microsoft Corporation“Buku ini mengajari Anda menjadi sukses dengan membengkokkan kenyataan.” ―Walter Isaacson, penulis Steve Jobs dan CEO Aspen Institute', 'Rp 119,000', '250 pages', '27 March 2024', 'Self Transformation, Bisnis, buku pengembangan diri, Business Management, Business, buku bisnis, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94455/Hum_-_The_Art_of_Being_Unreasonable1.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(251, '678230a279bd51cee772b64f', 'Summer in Seoul (Edisi 50 Tahun GPU)', 'Ilana Tan', 'Romance', 'Jung Tae-Woo—penyanyi muda terkenal Seoul yang muncul kembali setelah empat tahun menghindari dunia showbiz.“Aku hanya ingin memintamu berfoto denganku sebagai pacarku,” kata Jung Tae-Woo pada gadis di hadapannya.Sandy alias Han Soon-Hee—gadis blasteran Indonesia- Korea yang sudah mengenali Jung Tae-Woo sejak awal, namun sedikit pun tidak terkesan.Sandy mengangkat wajahnya dan menatap laki-laki itu, lalu berkata, “Baiklah, asalkan wajahku tidak terlihat.”Awalnya Jung Tae-Woo tidak curiga kenapa Sandy langsung menerima tawarannya. Sementara Sandy hanya bisa berharap ia tidak akan menyesali keputusannya terlibat dengan Jung Tae-Woo. Hari-hari musim panas sebagai “kekasih” Jung Tae-Woo dimulai. Perubahan rasa itu pun ada. Namun keduanya tidak menyadari kebenaran kisah empat tahun lalu sedang mengejar mereka', 'Rp 89,000', '280 pages', '27 March 2024', 'Summer in Soul, Ilana Tan, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94511/summer_in_seoul_50_cov-1.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(252, '678230aa79bd51cee772b653', 'Blink (Edisi 50 Tahun GPU)', 'Malcolm Gladwell', 'Self-Improvement,', 'B l i n k adalah buku mengenai dua detik pertama yang sangat menentukan ketika kita mengamati sesuatu—dua detik yang akan memberikan pemahaman dalam sekejap mata, yang terbentuk berkat pilihan-pilihan yang muncul dari “komputer internal” kita, alias kemampuan bawah sadar. Kemampuan inilah yang oleh Malcolm Gladwell disebut “kemampuan berpikir tanpa berpikir”, ketika keputusan sekejap bisa didapat dari informasi yang sedikit tapi akurat melalui snap judgment dan thin slicing.Dalam Blink, kita akan melihat contoh-contoh menakjubkan kehebatan snap judgment dan thin slicing. Pakar benda seni yang mengenali barang antik palsu dalam sekali lihat, ahli cicip makanan yang mampu membedakan keripik mana adalah buatan pabrik mana dalam sekali gigit, atau gelas mana yang berisi Pepsi dan gelas mana yang berisi Coca-Cola dalam sekali sesap.Buku ini juga memberikan gambaran betapa berbahayanya membuat kesimpulan cepat: pemasar bisa memanipulasi kesan pertama konsumen, polisi bisa saja menembak mati seseorang yang tak bersalah, dan pemilih dalam pemilu bisa saja memilih calon presiden yang tampan tapi ternyata tidak mampu bekerja.Blink menyingkapkan bahwa orang yang pandai mengambil keputusan yang tepat bukanlah orang yang memproses paling banyak informasi atau yang sengaja menghabiskan waktu paling lama, tapi orang yang telah melatih diri untuk menyempurnakan seni membuat cuplikan tipis—thin slicing—yaitu menyaring sesedikit mungkin faktor terpenting dari sejumlah kemungkinan yang menggunung.', 'Rp 68,000', '326 pages', '27 March 2024', 'Malcolm Gladwell, Personal Growth, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94515/EDISI_50TH_GPU_BLINK_MALCLOM_GLADWELL_C_1_4_2024_R.jpg', '2026-02-17 07:05:51', '2026-02-17 07:07:58'),
	(253, '6782302b79bd51cee772b60f', 'Seandainya', 'Marga T', 'Slice of Life', 'ANDAINYA……Aku terlahir sebagai anak laki-laki,mungkin Mama bisa hidup lebih dari 29 tahun, SEANDAINYA….…Mama terlahir bukan dari keturunan minoritas,mungkin Mama tidak wajib melahirkan anak laki-lakipenerus nama keluarga, setelah enam anak perempuan,tradisi usang bagi leluhur yang egonya setinggi langit, SEANDAINYA…....Mama terlahir setelah Instruksi Ganti Nama 1968,mungkin aku bisa merasakan kasih sayangseorang ibu lebih dari sembilan tahun, SEANDAINYA…....Memoar ini tidak bisa terbit sebelum kita bertemu lagi,semoga Mama tidak menyesal telah melahirkanku,yang hanyalah seorang anak perempuan!MARGA T (T bukan singkatan nama keluarga Tjoa, tapi akronim nama baptisku: MARGA...re...T...ha Caecilia)', 'Rp 129,000', '520 pages', '27 March 2024', 'Motivation, Inspiration, Marga T, slice of life, Inspirational, motivasi, klasik, Novel klasik, inspirasi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94447/Fiksi_-_Seandainya.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(254, '678230a879bd51cee772b652', 'Pangeran cilik (Edisi 50 Tahun GPU)', 'Antoine de Saint-Exupery', 'Classic Books', 'Pangeran Cilik termasuk buku yang paling banyak diterjemahkan di dunia. Konon pernah disadur ke dalam 230 bahasa asing. Buku ini memang luar biasa. Tampaknya seolah cerita anak-anak, tapi sebenarnya dinikmati dan direnungkan juga oleh orang dewasa. Lewat cerita seorang anak yang mengamati dunia dengan mata naif dan lugu, Saint-Exupéry menyentuh beberapa nilai dan pengalaman manusia yang paling dasar, seperti kekuasaan, tanggung jawab, dan cinta. Dongeng yang mengharukan sekaligus amat mendalam ini termasuk karya-karya agung sastra dunia yang tidak terlupakan.', 'Rp 59,000', '120 pages', '27 March 2024', 'Classic Novels, Classic, Classic Novel, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94514/The_Little_Prince_50_cov-1.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(255, '67822ff079bd51cee772b5ef', 'Mel, Melatiku', 'Ken Terate', 'Young Adult', 'Mel atlet renang cemerlang. Suatu hari ia jatuh cinta pada cowok yang salah. Satu fotonya yang “tak pantas” tersebar, menghancurkan segalanya dalam semalam; prestasi, nama baik, keluarga, persahabatan. Mel dikeluarkan dari sekolah, dipecat dari klub, disingkirkan oleh teman-temannya.Mel depresi. Pertemuannya kembali dengan Ega mengguncang dunia murungnya. Ega juga punya catatan kelam. Ia memaksa Mel keluar dari cangkang gelap, meski Mel takut. Namun, akankah reputasi Mel yang sudah tercabik bakal utuh kembali? Apakah Ega bisa menerima Mel yang pernah tercela? Mungkinkan Mel melompat dan berenang lagi untuk menemukan cinta yang sempat pergi?', 'Rp 119,000', '384 pages', '27 March 2024', 'romance novel, Young Adult, Novel, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94415/Mel,_Melatiku-cov--1.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(256, '678230a479bd51cee772b650', 'Karmila (Edisi 50 Tahun GPU)', 'Marga T', 'Romance', 'Karmila seorang mahasiswi kedokteran yang masih hijau dalam suatu pesta mengalami kekerasan seksual. Akibatnya, rencana studi, bahkan seluruh rencana hidupnya menjadi kacau-balau.Hati Karmila terkoyak antara ikatan yang tak dikehendakinya dengan pemuda yang telah mencemarkannya di satu pihak, serta kesetiaan pada tunangan yang masih tetap mencintainya di lain pihak.Dengan gaya bahasa yang hidup, segar, dan dengan kehalusan perasaannya, Marga T melukiskan pergulatan batin Karmila. Di bawah bimbingan naluri kewanitaannya, gadis dari keluarga baik-baik ini mengolah malapetaka yang telah menimpanya, dengan caranya sendiri.', 'Rp 99,000', '416 pages', '27 March 2024', 'Marga T, Karmila, Romance, Fiction', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94512/Karmila_50_cov-1.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(258, '6782302d79bd51cee772b610', 'Kenangan Manis Takkan Pernah Habis', 'Marga T', 'Slice of Life', '“Anjing yang hina, sahabat sejati dalam hidup kita. Yang pertama-tama memberi selamat datang, yang paling gigih membela.” – Lord ByronKarya terakhir Marga T ini merekam kenangan manisnya bersama hewan-hewan kesayangannya, khususnya Chiqote, anjing rottweiler yang merupakan teman karib, penghibur yang setia di kala hidupnya terasa sepi tanpa canda-tawa, tanpa kasih sayang Ibu yang sudah lama pergi. Berkat kasih sayang Chiqote dan kawan-kawannya, Marga T berhasil melewati masa remaja yang suram…  Menuangkan kenangannya ke dalam sketsa masyarakat, Marga T berbagi cerita tentang asal-asul Chiqote, kenakalan dan kelucuannya, serta kecerdikannya mengambil hati semua orang termasuk tukang bakso. Chiqote si anjing bastar bahkan lebih pintar daripada herder yang punya stambom. Jangan pandang enteng kaum marjinal!Selamat jalan, Marga T dan Chiqote. Sampai berjumpa lagi beyond the sunset---di seberang senja....', 'Rp 69,000', '144 pages', '27 March 2024', 'Motivation, Inspiration, Marga T, slice of life, Inspirational, motivasi, klasik, Novel klasik, inspirasi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94448/Fiksi_-_Kenangan_Manis.jpg', '2026-02-17 07:05:51', '2026-02-17 07:07:58'),
	(260, '6782305479bd51cee772b625', 'The Colour of Mothers', 'Donna Sita Indria', 'Inspirational', 'From the shy little boy whose mother’s flair used to make him blush, to the little girl who found traces of her identity in her mother’s poignant letters, and even to the youngster who withstood years of abuse from her mother—these stories take you from the dusty village of Segue in Mali to Shiraz, the city of gardens, in Iran, and all the way to the rural mountainous town of Boyolali in Indonesia.Featuring the works of 22 contributors from around the world, each one sharing a unique and touching story about their remarkable mothers. This book brims with powerful stories that pays tribute to the strength of mothers who have faced unyielding obstacles, defied the odds, endured pain, and made tremendous sacrifices for their children. I hope you, like me, will be inspired by the incredible resilience of these extraordinary mothers.“Menyimak kisah bagaimana kehidupan dirawat dan dilanjutkan adalah semacam perjalanan batin yang dalam. Perempuan-perempuan yang rela merubuhkan bangunan tubuhnya sendiri demi berdirinya sebuah bangunan baru yang disebut anak. Cerita-cerita dalam buku ini menggambarkan, berbaju zirah maupun bercelemek dapur, dan di belahan dunia mana pun ia berada, seorang ibu selalu layak untuk dibanggakan. Every mother counts.”—Fauzan Mukrim, Executive Assignment Editor CNN Indonesia TV, penulis buku Dear River dan Dear Rain“The Colours of of Mothers is a real gem of a read. The collection of short writings about mothers by various narrators is both poignant and humbling. At the end of the day, we are all products of our mother and our mother, however she brought us into this world and whether we like it or not, remains the most influential person in our lives.”—Desi Anwar, Host CNN Indonesia “Insight with Desi Anwar”, author of A Simple Life, Faces & Places, Growing Pains, Offline, The Art of Solitude, Book of Everyday Things“When I was about to finish reading the last parts of this book in our bedroom, my wife asked what the most beautiful part of the short stories was. First, I told her that I remembered the tireless work of my mother to raise her six children amid our extreme poverty. But luckily, my father, an elementary school headmaster, was not an abusive husband, unlike what is often described in this book. Second? ‘I am very sure that our two sons and one daughter will have beautiful memories about you like mothers in this Riyani’s book.’ Suddenly, I felt anxious. ‘How will my children describe their father when they were asked by Ibu Riyani one day?’ Husbandsneed to learn from this book.”—Kornelius Purba, Managing Editor, The Jakarta Post', 'Rp 79,000', '120 pages', '27 March 2024', 'origin story, inspirasi, Inspirational, Inspiration', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94469/Hum_-_The_Colors_of_Mothers.jpg', '2026-02-17 07:05:51', '2026-02-17 07:05:51'),
	(261, '6782309b79bd51cee772b64b', 'Sang Pemenang Berdiri Sendirian: The Winner Stands Alone (2024)', 'Paulo Coelho', 'Novel', 'Sukses: racun yang manis Atau Sukses: racun yang menggoda Atau Berapa harga sebuah kesuksesan? " Penebusan cinta melalui kepasrahan total"Dalam Sang Pemenang Berdiri Sendirian––The Winner Stands Alone, Paulo Coelho kembali kepada tema-tema penting dari Sebelas Menit––Eleven Minutes dan The Zahir. Novel yang penuh ketegangan, cerminan dunia kita saat ini, di mana kemewahan dan sukses menjadi yang paling utama, sehingga kita sering kali menulikan telinga dari suara hati kitaDalam novel ini, Paulo Coelho membawa kita ke Festival Film Cannes, tempat berkumpul kaum super-elite––mereka yang telah sukses di dunia mode dan film. Beberapa bahkan telah sampai di puncak dan takut kehilangan posisi mereka yang bergengsi itu. Uang, kekuasaan, dan ketenaran dipertaruhkan––hal-hal yang membuat sebagian besar orang rela melakukan apa saja, berapa pun harga yang mesti dibayar. Di dunia semacam inilah kita bertemu Igor, si jutawan Rusia; Hamid, kaisar dunia mode dari Timur Tengah; Grabriella, aktris Amerika yang sangat ingin mendapatkan peran utama; Savoy, detektif kriminal yang ambisius dan berharap bisa menguak kasus yang akan membuatnya tenar; dan Yasmine, model yang hampir meraih sukses. Siapa yang akan berhasil mengenali mimpinya sendiri dan mewujudkannya, di antara sekian banyak mimpi yang bukan miliknya?Penelaahan mendalam di dunia glamor para super-elite... Dalam The Winner Stands Alone, mereka bukan hanya mencari seorang pembunuh berbahaya, melainkan juga nilai-nilai spiritual yang sejati. ––Publishers Weekly, New YorkPenjabaran menohok tentang dunia film dan mode, di mana kemewahan dan ambisi telah membuat mati rasa segala kemungkinan nilai-nilai yang sesungguhnya. ––L’Hebdo, Lausanne', 'Rp 119,000', '472 pages', '20 March 2024', 'Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94507/Sang_Pemenang_Berdiri_Sendirian.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(262, '6782301d79bd51cee772b607', 'Puasa yang Benar dan Sehat', 'dr. Hans Tandra', 'Diet & Health ,', 'Buku ini menguraikan cara hidup sehat dengan berpuasa memakai bahasa awam yang sederhana, dan jauh dari istilah kedokteran yang rumit. Apa untung ruginya berpuasa? Bagaimana mengatur jam berpuasa yang benar? Hidangan apa yang perlu dinikmati dan menu apa yang sebaiknya dihindari? Bagaimana langkah-langkah gaya hidup sehat yang harus dijalani? Semuanya akan dikupas tuntas.Puasa adalah diet yang disusun dengan peraturan waktu yang benar. Puasa untuk kesehatan tidak mendatangkan beban dan membuat sengsara. Puasa bahkan murah tanpa harus keluar ongkos. Puasa harus dijalankan dengan rasa bahagia, nikmat, dan sehat. Di sini dijelaskan pula berbagai cara berpuasa yang baik dan sehat, termasuk intermitten fasting yang kini sedang banyak diminati.Baca, pelajari, dan praktekkan buku ini. Puasa yang benar dan sehat bisa mengalahkan diabetes dan obesitas, membuat jantung dan otak semakin sehat, menghilangkan stres dan radang, menjauhi penyakit autoimun dan kanker, serta membuahkan hidup berkualitas dan umur panjang.', 'Rp 99,000', '188 pages', '20 March 2024', 'Diet & Health, Health, Healthy', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94439/Hum_-_Puasa_yang_Benar_dan_Sehat.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(263, '6782302279bd51cee772b60a', 'Menerjemahkan: Mengurai Makna, Menguntai Kata', 'Dharmawati Chen', 'Reference & Dictionary', 'Menerjemahkan bukan soal memindahkan atau mengganti kata per kata, melainkan memindahkan konsep, pengertian, dan amanat si penulis. Hal ini terutama akan terasa ketika kita menerjemahkan novel atau karya fiksi lainnya. Karena berbeda dengan penulis nonfiksi yang pada umumnya menggunakan gaya bahasa lugas, penulis fiksi lebih memiliki keleluasaan untuk menggunakan berbagai macam gaya bahasa, peribahasa dan idiom, kata-kata nonbaku, bahasa daerah, slang, bahkan menciptakan sendiri istilah-istilah baru, yang hampir mustahil diterjemahkan kata per kata. Misalnya, “You’re nuts” tidak mungkin diterjemahkan jadi “Kau kacang” atau “Don’t be salty” artinya jelas bukan “Jangan jadi asin”. kan?Konon, terjemahan dianggap bagus kalau hasilnya relatif sama dengan sumbernya, sehingga kalau dibaca tidak akan berbeda jauh dari tulisan aslinya. Pertanyaannya, bagaimana cara mencapai standar itu?Buku ini memuat prinsip-prinsip dasar penerjemahan yang perlu diketahui mereka yang berminat mengenal seluk-beluk penerjemahan. Pembaca akan diajak menganalisis materi terjemahan, mengenali sekaligus menjawab tantangan-tantangan yang ada di dalamnya. Harapannya, buku ini dapat mengantar pembaca untuk menghasilkan terjemahan berstandar bagus tadi. Semoga!', 'Rp 99,000', '130 pages', '20 March 2024', 'bahasa indonesia, tata bahasa, buku bahasa, terjemahan', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94442/Hum_-_Menerjemahkan_Mengurai_Makna,_Menguntai_Kata.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(264, '6782309979bd51cee772b64a', 'Mickey7', 'Edward Ashton', 'Novel', 'Mati memang tidak enak... tapi yah, itulah risiko pekerjaan.Mickey7 seorang Expendable: iterasi―clone―yang nyawanya tidak dianggap penting. Ia ikut ekspedisi manusia untuk tinggal di dunia es Niflheim. Jika ada misi yang sangat berbahaya, dengan taruhan nyawa, Mickey jadi andalan. Kalau ada satu iterasi mati, tubuh baru diregenerasi, lengkap dengan sebagian besar memori tubuh sebelumnya.Pada suatu misi jelajah rutin, Mickey7 hilang dan dianggap tewas. Saat ia berhasil kembali ke markas koloni, nasibnya sudah ditentukan. Ada iterasi baru, Mickey8, yang menggantikannya sebagai Expendable. Expendable ganda tidak disukai, dan kalau ketahuan, mereka akan didaur ulang menjadi protein untuk makanan koloni.Sementara itu, kehidupan di Niflheim terus memburuk. Spesies asli semakin penasaran terhadap tetangga baru mereka, menyebabkan Commander Marshall sangat ketakutan. Pada akhirnya, bertahannya kedua kehidupan akan bergantung pada Mickey7. Masalahnya, bisakah ia bertahan hidup?“Buku karya Ashton ini di awal berkesan komedi, tapi di bagian akhir terasa “mengusik” nurani.  Sebagai Expendable, Mickey7 punya hak untuk menanyakan apakah yang dimaksud sebagai manusia atau  siapakah yang berhak menghancurkan suatu tempat untuk lalu menguasainya...” ―Library Journal, starred review', 'Rp 119,000', '416 pages', '20 March 2024', 'Novels, Fantasy, Fiksi, Fiction', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94506/Mickey_7_cov_(1)-1.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(265, '6782309d79bd51cee772b64c', 'Manuskrip yang Ditemukan di Accra (2024)', 'Paulo Coelho', 'Novel', 'Apakah kesuksesan itu? Kesuksesan adalah bisa pergi tidur setiap malam dengan jiwa yang damai.1099. Gerbang-gerbang Yerusalem tengah dikepung. Di dalam tembok kota, orang-orang berkumpul untuk mendengarkan kata-kata bijak seorang lelaki misterius yang dikenal sebagai sang Guru. Mereka bertanya tentang rasa takut, musuh, kekalahan, dan perjuangan; mereka merenungkan tekad untuk berubah, kebajikan dalam kesetiaan serta kesendirian; dan mereka mengajukan pertanyaan tentang keindahan, seks dan keluwesan, cinta, kebijaksanaan, dan masa depan. Dan berabad-abad kemudian, jawaban-jawaban orang bijak itu masih tetap belaku sebagai rekam jejak nilai-nilai manusia yang tak lekang dimakan waktu.Di tangan Paulo Coelho, Manuskrip yang Ditemukan Di Accra menunjukkan siapa diri kita; ketakutan dan harapan kita untuk masa depan berasal dari pengetahuan serta keyakinan yang ada dalam diri kita, bukan dari kesulitan yang mengepung kita.', 'Rp 55,000', '208 pages', '20 March 2024', 'Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94508/Manuskrip_Yang_Ditemukan_di_Accra_cu2024_cov-1.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(266, '6782309379bd51cee772b647', 'Cocomelon: Belajar ABC', 'Moonbug Entertainment', 'Activity Books', 'Ayo belajar huruf! Buku mewarnai edukasi ini membantu mengenalkan konsep huruf pada anak.AlfabetMengenal hurufMewarnaiMenelusuri hurufDitemani karakter-karakter Cocomelon, buku ini akan membuat si kecil sibuk!', 'Rp 99,000', '96 pages', '20 March 2024', 'Activities, Activity Books, Games, Buku anak, Children Book', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94503/CCM_Belajar_ABC_cover_R.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(267, '6782309779bd51cee772b649', 'CoComelon: Belajar 123', 'Moonbug Entertainment', 'Activity Books', 'Ayo Belajar Angka!Buku mewarnai edukasi ini membantu mengenalkan konsep angka pada anak.BerhitungMengenal angkaMewarnaiMenelusuri angkaDitemani karakter-karakter Cocomelon, buku ini akan membuat si kecil sibuk!', 'Rp 99,000', '96 pages', '20 March 2024', 'Mewarnai, Buku anak, Children Book, Activity Book, Activities', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94505/CCM_Belajar_123_cover_R.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(268, '6782300579bd51cee772b5fa', 'A Good Girl\\\'s Guide to Murder: panduan Membunuh Dari Anak Baik-Baik', 'Holly Jackson', 'Mysteries & Thrillers', 'Kasusnya sudah ditutup.Lima tahun lalu, Andie Bell dibunuh pacarnya, Sal Singh. Polisi tahu dia pelakunya. Semua orang di kota tahu dia pelakunya.Pippa Fitz-Amobi tumbuh dengan kisah pembunuhan tersebut. Ketika Pip memilih kasus Andie Bell sebagai topik proyek tahun terakhirnya di SMA, ia mulai mengungkap rahasia yang sangat ingin disembunyikan seseorang. Jika pembunuh sebenarnya masih ada di luar sana, seberapa jauh mereka akan berusaha menyembunyikan kebenaran dari Pip?', 'Rp 139,000', '480 pages', '13 March 2024', 'Thriller, Mystery & Thrillers, Thrillers, novel thriller', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94426/Hum_-_A_Good_Girls_Guide_to_Murder.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(269, '6782300e79bd51cee772b5ff', 'Romansa Jentelmen Skotlandia (Devil in Disguise)', 'Lisa Kleypas', 'Historical Romance', 'Lady Merritt Sterling tak pernah membiarkan dirinya berada dalam posisi yang memungkinkan dirinya terjerat skandal. Tapi ketika ia bertemu Keir MacRae, penyuling wiski menawan dari Skotlandia, semua rencananya yang masuk akal menguap tanpa jejak. Mereka berdua sangatlah berbeda, tapi daya tarik di antara mereka sangatlah kuat dan tak terelakkan.Keir MacRae hanya punya dua tujuan di London. Satu: jangan jatuh cinta dengan Lady Merritt Sterling yang memukau namun berada di luar jangkauan. Dua: jangan terbunuh. Tak satu pun dari kedua tujuan itu mudah dicapai.Keir tidak tahu alasan seseorang mau membunuhnya hingga hubungannya dengan salah satu keluarga ternama di London terkuak. Dunianya seakan jungkir balik, dan satu-satunya yang bisa ia percaya adalah Merritt. Dengan bahaya yang mengintai, Merritt akan melakukan apa pun demi menyelamatkan pria yang ia cintai...', 'Rp 119,000', '456 pages', '13 March 2024', 'Romance Novels, Historical Romance, romance novel, Novel dewasa, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94431/Fiksi_-_Romansa_Jentelmen_Skotlandia_(Devil_in_Disguise).jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(270, '6782301079bd51cee772b600', 'Pacar Inggris Impian (Hot British Boyfriend)', 'Kristy Boyce', 'Young Adult', 'Setelah dipermalukan secara publik oleh Andy dan Crystal, Ellie melarikan diri ke luar negeri! Lebih tepatnya, Ellie mengikuti trip studi ke Inggris. Dia tidak peduli dengan prestasi akademis, tujuan utamanya adalah mendapatkan cowok Inggris menawan untuk menutup mulut semua orang yang mengolok-oloknya.Ellie nyaris pingsan ketika seorang cowok Inggris benar-benar tertarik kepadanya. Will tampan, kaya, dan sangat gentleman. Dia sempurna. Demi mendekati Will, Ellie meminta bantuan Dev dengan syarat Ellie akan membantu Dev mendekati Sage, cewek kutu buku yang menjadi teman sekamar Ellie.Di tengah kesibukannya mendekati Will dan belajar mati-matian bersama teman-teman barunya, Ellie menyadari dia memiliki lebih banyak kelebihan daripada yang dia kira. Kini dia bertanya-tanya, apakah Will pacar yang tepat untuknya?', 'Rp 119,000', '400 pages', '13 March 2024', 'Remaja, novel remaja, novel roman, Young Adult, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94432/Fiksi_-_Pacar_Inggris_Impian_(Hot_British_Boyfriend).jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(271, '6782309279bd51cee772b646', 'You’re Not Listening: Hal-Hal Penting yang Kita Lewatkan Ketika Kita Tidak Sungguh-Sungguh Mendengarkan', 'Kate Murphy', 'Self-Improvement,', 'Di tempat kerja, kita diajari untuk memimpin percakapan. Di media sosial, kita membentuk narasi pribadi kita. Di tengah pergaulan, kita mengobrol satu sama lain. Kita tidak mendengarkan. Dan, tidak ada yang mendengarkan kita.Meskipun hidup di dunia teknologi komunikasi digital yang selalu terhubung, tampaknya tidak ada orang yang benar-benar mendengarkan atau bahkan mengetahui caranya. Hal ini kadang membuat kita semakin kesepian, terisolasi, dan kurang toleran dibandingkan sebelumnya.Melalui hasil wawancaranya dengan berbagai narasumber yang mumpuni dan riset ilmiahnya, Kate Murphy sampai pada kesimpulan bahwa mendengarkan itu lebih dari sekadar mendengar apa yang dikatakan orang. Mendengarkan juga berarti memperhatikan bagaimana mereka mengatakannya dan apa yang mereka lakukan saat mengatakan itu, bagaimana konteksnya, dan sejauh mana hal yang mereka ungkapkan itu selaras dengan keyakinan kita.Jika diniatkan dan dilakukan dengan baik, mendengarkan dapat mentransformasi pemahaman kita terhadap orang lain dan dunia sekitarnya, yang pada akhirnya akan memperkaya dan meningkatkan pengalaman dan eksistensi kita. Seperti itulah cara kita mengembangkan diri menjadi bijak dan membentuk hubungan yang bermakna, dalam berupaya menjadi versi terbaik diri sendiri.', 'Rp 149,000', '304 pages', '12 March 2024', 'Self-Improvement, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94502/YOURE_NOT_LISTENING_C_1_4__(1).jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(272, '6782308879bd51cee772b641', 'Buku Mewarnai dan Aktivitas: Ayo Bertualang', 'Jess Volinski', 'Activity Books', 'Selamat datang di BUKU MEWARNAI YANG CERIA & PENUH WARNA!Dalam buku ini, ada 32 desain petualangan bertamasya yang menunggu untuk kalian warnai. Jangan lupa tambahkan pola-pola unik buatan kalian sendiri supaya gambar-gambar ini makin menggemaskan dan lain daripada yang lain.Seri Buku Mewarnai & Aktivitas memberimu kesempatan untuk bermain-main dengan warna, pola, dan bentuk. Di dalamnya juga ada sedikit penjelasan mengenai palet warna, bahkan beberapa halaman contoh yang bisa kalian gunakan sebagai sumber inspirasi. Jadi, ayo kembangkan kreativitas kalian!', 'Rp 69,000', '44 pages', '06 March 2024', 'Mewarnai, Activities, Activity Books, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94497/Buku_Mewarnai_dan_Aktivitas_-_Ayo_Bertualang!.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(273, '67822fed79bd51cee772b5ed', 'The Book of Everyday Things', 'Desi Anwar', 'Self-Improvement,', 'Buku, bantal, sepatu, bolpoin, jam tangan, mainan, uang, dan sikat gigi... Ini adalah berbagai benda yang kita gunakan dalam kehidupan sehari-hari. Semuanya begitu biasa sehingga kita menerimanya begitu saja, seolah-olah semua benda itu sudah menjadi bagian hidup kita. Pada kenyataannya, kemampuan untuk membuat benda mungkin adalah cara kita mendefinisikan spesies kita dan membuat kita berbeda dari makhluk hidup lainnya.Coba tengok keadaan di sekitar kita perhatikan jumlah benda yang ada di sekeliling yang terus bertimbun sepanjang hidup kita. Seorang manusia mungkin mengawali hidupnya hanya dengan tarikan napas pertama, kemudian tidak membawa apa-apa ke dalam kuburnya selain yang dihiaskan orang lain pada jasadnya yang sudah tak bernyawa. Padahal, selama hidupnya, dia bergantung pada berbagai benda, bukan hanya untuk memungkinkannya berfungsi, melainkan juga agar memiliki identitas dan tujuan: Berbagai benda dan barang yang diciptakan dan diproduksi oleh sesama manusia yang dapat digunakan untuk mengendalikan serta memanipulasi lingkungannya dan menentukan takdirnya. Berbagai barang yang mengisi tidak hanya ruang yang ditempatinya, tetapi juga yang pada akhirnya mengacaukan dan menyesakkan seluruh Bumi, yang sekaligus menyisakan semakin sedikit ruang bagi makhluk hidup lainnya untuk berkembang.The Book of Everyday Things adalah pengingat bahwa terlepas dari kemampuan spesies kita untuk menaklukkan alam dan menciptakan aneka benda menakjubkan untuk membuat hidup kita lebih nyaman, obsesi kita untuk memproduksi dan mengonsumsi beragam benda mungkin justru membuat kita makin tidak memahami tujuan sebenarnya keberadaan kita. Bahwa mungkin kebahagiaan sejati tidak hanya terletak pada berbagai benda buatan manusia, tetapi juga menghargai apa yang diberikan alam kepada kita.', 'Rp 149,000', '300 pages', '06 March 2024', 'Desi Anwar, Self-Improvement, humaniora, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94413/cover_-_Book_of_Everyday_Things_OK_page-0001.jpg', '2026-02-17 07:07:58', '2026-02-17 07:08:40'),
	(274, '6782308179bd51cee772b63d', 'Disney Wish: Keajaiban Mimpi', 'Disney', 'Picture Books', 'Ada sebuah negeri bernama Rosas, tempat semua impian akan diwujudkan dan tiap permohonan akan dikabulkan.Di negeri itu, tinggallah Asha dan teman-temannya. Dan mereka punya impian-impian besar. Apakah benar di Rosas semuanya akan terwujud?', 'Rp 39,000', '24 pages', '06 March 2024', 'Buku anak, disney, Picture book', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94493/Cover_Wish.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(277, '6782309079bd51cee772b645', 'Tak Apa-Apa Tak Sempurna (2024)', 'Brene Brown', 'Self-Improvement,', 'Di dalam buku terlaris menurut New York Times yang mengguncang ini, Dr. Brené Brown mengajak kita untuk belajar menerima diri apa adanya, tidak terlalu mencemaskan “apa yang orang lain pikirkan” tentang diri kita, sehingga kita bisa lebih mencintai diri sendiri. Tidak apa-apa bila kita tidak sempurna, seperti yang lainnya. Dia mengajari cara untuk menjalani hidup dengan sepenuh hati, dengan merangkul kerapuhan dan kerentanan kita, serta menumbuhkan keberanian, belas kasih, dan keterhubungan.Menjalani sepuluh pilar petunjuk kekuatan hidup dengan Sepenuh Hati—sebuah cara yang ditawarkan oleh Dr. Brené Brown untuk terlibat dengan dunia—akan membuat kita menjadi lebih sehat, lebih bahagia, dan lebih bersyukur.“Dr. Brené Brown dengan berani mengatasi emosi negatif yang menghalanginya untuk menjalani hidup dengan lebih baik. Baca buku ini dan biarkan keberanian itu menular pada kita.” —Daniel Pink', 'Rp 75,000', '248 pages', '06 March 2024', 'buku psikologi, tak apa-apa tak sempurna, brene brown, Psikologi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94501/Tak_Apa_Apa_Tak_Sempurna_C_1_4_CU12.jpg', '2026-02-17 07:07:58', '2026-02-17 07:07:58'),
	(281, '67822fc779bd51cee772b5d9', 'Pengantin Taipan Yunani (Promoted to the Greek\'s Wife)', 'Lynne Graham', 'Harlequin', 'Cleo menyembunyikan rapat-rapat ketertarikannya terhadap Ari Stefanos. Hingga satu malam penuh kenikmatan mengungkap segalanya.Setelah mengetahui rahasia kelam mendiang sang ayah, Ari menemukan penghiburan dalam dekapan Cleo. Kini, demi keberhasilan mengadopsi keponakannya, Ari harus menikah. Walaupun jurang perbedaan di antara mereka sangat dalam, Cleo sesuai dengan kriterianya. Ari akan berusaha meminang wanita itu menjadi istrinya!', 'Rp 69,000', '224 pages', '28 February 2024', 'Romance Novels, romance novel, Romance, Harlequin', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94393/Fiksi_-_Pengantin_Taipan_Yunani.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(282, '6782300a79bd51cee772b5fd', 'Seri Kumbang: Tommy Si Pengadu', 'Enid Blyton', 'Beginning Readers', 'Tommy anak yang manis, tapi ia suka sekali membual. Ia sering mengadukan hal-hal yang tidak pernah dilakukan teman-temannya kepada ibu atau gurunya. Misalnya, ia bilang Annie mengobrol terus atau Joan memukul tangannya, padahal itu tidak benar. Bagaimana caranya agar Tommy berhenti mengadukan hal yang tidak benar?', 'Rp 40,000', '192 pages', '28 February 2024', 'novel anak, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94429/Anak_-_Seri_Kumbang_Tommy_Si_Pengadu.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(283, '67822fde79bd51cee772b5e5', 'Perempuan di Rumah No. 8', 'Mutiarini', 'Mysteries & Thrillers', 'Setelah dihajar suaminya sampai keguguran, Anika melarikan diri dari rumah dan mencari tempat persembunyian. Dari rumah aman di Bogor, ia akhirnya mendapatkan pekerjaan baru di Yogyakarta. Di sana, ia menempati rumah kontrakan mungil bernomor delapan yang telah lama kosong.Tak disangka, rumah itu menyimpan rahasia. Sesosok hantu perempuan berleher patah mengganggu malam-malam Anika. Lambat laun, Anika mengetahui bahwa hantu perempuan bernama Lastri itu pun korban kekerasan dalam rumah tangga seperti dirinya.Perkenalan Anika dengan Lastri menguatkan tekadnya untuk menyudahi pernikahannya yang beracun. Anika tak ingin hidupnya berakhir tragis seperti Lastri. Ia juga ingin melepaskan diri dari Reza dan ayah suaminya yang merupakan pejabat berpengaruh.Berhasilkah Anika membebaskan diri? Bagaimana jika ia justru ditakdirkan menjadi hantu penunggu rumah nomor delapan yang berikutnya?', 'Rp 99,000', '320 pages', '28 February 2024', 'novel thriller, Thrillers, Mystery & Thrillers, Thriller', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94405/Fiksi_-_Perempuan_di_Rumah_No__8.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(285, '67822fe179bd51cee772b5e7', 'Kebiasaan Tersembunyi para Genius', 'Craig Wright', 'Self-Improvement', 'KATA GENIUS MENGINGATKAN KITA PADA TOKOH-TOKOH TERNAMA INI, YANG KONTRIBUSI BUDAYANYA TELAH MEMBENTUK MASYARAKAT SECARA PERMANEN.Namun Beethoven tidak pandai berhitung. Picasso tidak lulus ujian matematika kelas 4 SD. Dan Steve Jobs meninggalkan SMA dengan IPK 2,65. Apa yang diungkapkan hal ini mengenai cara kita mengukur kesuksesan dan pencapaian sekarang? Mengapa kita mengajar anak-anak untuk berperilaku dan bermain sesuai aturan, padahal para genius yang transformatif dalam budaya Barat justru melakukan hal sebaliknya? Dan apa sebenarnya kegeniusan itu?Profesor Craig Wright, pencipta “Kursus Genius” yang populer di Universitas Yale, mengabdikan lebih dari dua dekade untuk menyelidiki ciri-ciri seorang genius. Dengan meneliti kehidupan individu-individu transformatif seperti Marie Curie, Leonardo da Vinci, dan Einstein, Wright mengidentifikasi lebih dari selusin pendorong kegeniusan—karakteristik dan pola perilaku yang umum terdapat pada para pemikir besar sepanjang sejarah.Wright berpendapat bahwa kegeniusan bukan sekadar kecerdasan dan etos kerja—kegeniusan jauh lebih kompleks. Wawasan cemerlang yang mengubah dunia tidak datang secara tiba-tiba, tetapi merupakan hasil dari cara berpikir yang unik dan proses yang panjang. Yang terpenting, kebiasaan berpikir yang menghasilkan pemikiran dan penemuan hebat dapat dipelajari dan dikembangkan secara aktif. Buku ini tidak akan membuat Anda menjadi genius. Namun menerima kebiasaan tersembunyi dari para genius akan membuat Anda lebih strategis, kreatif, sukses, dan, pada akhirnya, lebih bahagia.', 'Rp 159,000', '345 pages', '28 February 2024', 'Self Transformation, buku pengembangan diri, Self-Improvement, Self-Acceptance, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94407/Hum_-_Kebiasaan_Tersembunyi_para_Genius.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(286, '67822f6c79bd51cee772b5a8', 'Dongeng Klasik Dunia 3 oleh Grimm Bersaudara', 'Grimm Bersaudara', 'Picture Books', 'Dongeng-dongeng dalam buku ini:Rumpelstiltskin, Peri Air, Raksasa Muda, Para Peri dan Pembuat Sepatu, Ibu Holle, Jin dalam Botol, Sang Kurcaci, Hadiah dari Orang-Orang Kerdil, Peri Air di Kolam Penggilingan, Angsa Emas, Rapunzel, Gadis Angsa di Sumur, Anak Domba dan Ikan Kecil, Enam Angsa, Putri Salju dan Tujuh Kurcaci, Jorinda dan Joringel, Anak-Anak Emas.', 'Rp 119,000', '184 pages', '28 February 2024', 'Anak-anak, Anak, Pictures Book, klasik, Novel klasik, picture books, buku anak gramedia, Literature, Picture book, Buku anak, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94344/Anak_-_Dongeng_Klasik_Dunia_3.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(287, '67822f6e79bd51cee772b5a9', 'Dongeng Klasik Dunia 4 oleh Hans Christian Andersen', 'Hans Christian Andersen', 'Picture Books', 'Dongeng-dongeng dalam buku ini:Kincir Angin, Baju Baru Kaisar, Ayam Jantan dan Baling-Baling Cuaca, Pohon Cemara Kecil, Celengan Babi, Pak Tua Selalu Benar, Gandum Kuda, Keberuntungan dalam Sebuah Kancing, Sepasang Sepatu Merah, Sang Penggembala, Thumbelina, Teko Teh, Bunga Daisy, Angsa-Angsa Liar, Siapa yang Paling Beruntung?, Tuck, Hari-Hari dalam Seminggu, Teman Bepergian.', 'Rp 119,000', '190 pages', '28 February 2024', 'Anak-anak, Anak, Classic, Pictures Book, klasik, classics, picture books, buku anak gramedia, Literature, Picture book, Buku anak, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94345/Anak_-_Dongeng_Klasik_Dunia_4.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(288, '67822fe379bd51cee772b5e8', '33 Strategi Marketing Terpenting Dekade Ini', 'Dianta Hasri N. Barus', 'Marketing & Public Relation', 'Dalam satu dekade terakhir, perkembangan teknologi dan perubahan perilaku konsumen telah mengubah wajah dunia bisnis dan pemasaran. Muncul tren-tren baru dalam pemasaran, seperti peningkatan penggunaan kecerdasan buatan dan machine learning, peningkatan fokus pada personalisasi dan pengalaman pelanggan, serta peningkatan praktik pemasaran berkelanjutan dan etis. Berbekal pengalaman selama 15 tahun berkecimpung dalam dunia pemasaran, Dianta Hasri N. Barus mencoba merangkum 33 strategi pemasaran paling berpengaruh dalam satu dekade terakhir, mungkin hingga satu dekade ke depan.Beberapa di antaranya adalah:• FOMO Marketing• Influencer Marketing• Content Marketing• SEO MarketingBuku ini hadir sebagai panduan untuk memahami perubahan dan perkembangan yang terjadi dalam dunia bisnis dan pemasaran. Dengan membaca buku ini, pemasar, pemilik perusahaan, dan masyarakat umum yang tertarik pada bisnis bisa memiliki daya saing dalam dunia pemasaran yang semakin digital.', 'Rp 204,000', '404 pages', '28 February 2024', 'nonfiksi, marketing, Self Improvement, Self-Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94408/33_STRATEGI_MARKETING_1.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(289, '67822fff79bd51cee772b5f7', 'Kecerdasan Buatan dalam Evolusi Media dan Komunikasi', 'Gregorius Genep Sukendro,', 'Social Sciences', 'Perkembangan teknologi terus berdampak pada peradaban manusia tanpa bisa dihindari. Setelah digitalisasi dan masifnya media sosial, saat ini banyak kalangan menaruh perhatian pada kehadiran kecerdasan buatan atau artificial inteligent (AI). Di wilayah komunikasi, AI memicu banyak kekhawatiran, terutama terkait konsekuensi atau dampaknya, mulai dari masalah etika, privasi, hingga ancaman hilangnya pekerjaan manusia.Di lain pihak, AI menumbuhkan harapan bahwa otomatisasi dapat meningkatkan efisiensi sehingga manusia dapat fokus pada pekerjaan yang lebih kompleks. Selain itu, AI juga mampu mengembangkan personalisasi pesan dan menyasar khalayak secara lebih akurat.Buku ini merupakan buah pemikiran dari sejumlah peneliti dan akademisi dari berbagai perguruan tinggi di Indonesia yang memiliki perhatian pada fenomena AI dan ilmu komunikasi. Ada beberapa subtema yang menjadi kajian, yakni etika penggunaan AI dalam media dan komunikasi, transformasi praktik public relations dengan kecerdasan buatan, revolusi periklanan dengan kecerdasan buatan; dan kecerdasan buatan dalam jurnalisme. Kajian dan diskusi dalam buku ini menjadi kontribusi bagi kemajuan ilmu komunikasi, baik pada tataran teori dan praktis.', 'Rp 185,000', '284 pages', '28 February 2024', 'nonfiksi, Social Sciences, Social Science, Social & sciences', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94423/Kecerdasan_buatan_--_C-1+4.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(290, '67822ff279bd51cee772b5f0', 'Katarak: Asupan Gizi, Gejala, dan Operasi', 'F. G. Winarno, M.Sc., Ph.D.', 'Diet & Health', 'Mata merupakan organ tubuh yang berfungsi untuk melihat. Meningkatnya usia menyebabkan berkurangnya kejernihan lensa mata sehingga muncul katarak. Jika tidak segera ditangani, katarak bahkan dapat menyebabkan kebutaan total. Pemicu lain dari katarak meliputi trauma atau kecelakaan, peradangan pada mata, kelainan bawaan, dan beragam kondisi lain.Katarak adalah penyebab kebutaan terbanyak di Indonesia, bahkan dunia. Karena itu, buku ini hadir untuk membantu Anda mengenali dan memahami gejala katarak sejak dini agar kesehatan mata Anda dapat terjaga dengan baik. Katarak: Asupan Gizi, Gejala, dan Operasi memuat beragam pengetahuan umum penting tentang katarak yang disajikan secara praktis.', 'Rp 140,000', '120 pages', '28 February 2024', 'nonfiksi, kesehatan, Health, Diet & Health', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94416/KATARAK_C-1+4.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(292, '67822fd179bd51cee772b5de', 'Merebut Cinta Pujaan Hati (The Bride He Stole for Christmas)', 'Caitlin Crews', 'Harlequin', 'Timoney George pernah mencintai Crete Asgar sepenuh hati. Tetapi, hatinya remuk ketika Crete mencampakkannya begitu saja, bahkan mengusirnya dari apartemen pria itu.Ia mengira selamanya ia takkan bisa mencintai orang lain lagi. Itu sebabnya ia langsung menyetujui ketika pamannya menyuruh Timoney menikah dengan relasi sang paman, yang jelas kaya dan berasal dari keluarga terpandang.Ketika mendengar Timoney akan menikah dengan pria tua bereputasi buruk, Crete mulai gelisah. Pada malam sebelum pernikahan Timoney, Crete bertekad menemui wanita itu.Tetapi, untuk apa? Dulu, Crete langsung mengakhiri hubungan mereka saat Timoney menyatakan cintanya.Kali ini, apa yang bisa Crete katakan pada wanita itu? Janji apa yang bisa diberikannya pada Timoney?', 'Rp 69,000', '224 pages', '28 February 2024', 'Harlequin, Novel dewasa, Romance, romance novel, Romance Novels', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94398/Fiksi_-_Merebut_Cinta_Pujaan_Hati.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(293, '67822fe779bd51cee772b5ea', 'Buku Mewarnai & Aktivitas: Burung, Bunga, dan Kupu-kupu', 'Jess Volinski', 'Activity Books', 'Selamat datang di BUKU MEWARNAI YANG CERIA & PENUH WARNA!Dalam buku ini ada 30 desain mode yang menunggu untuk kalian warnai. Jangan lupa tambahkan pola-pola unik buatan kalian sendiri supaya gambar-gambar ini makin keren, penuh gaya, dan lain daripada yang lain.Seri Buku Mewarnai & Aktivitas memberimu kesempatan untuk bermain-main dengan warna, pola, dan bentuk. Di dalamnya juga ada sedikit penjelasan mengenai palet warna, bahkan beberapa halaman contoh yang bisa kalian gunakan sebagai sumber inspirasi. Jadi, ayo kembangkan kreativitas kalian!', 'Rp 69,000', '48 pages', '28 February 2024', 'Mewarnai, Activities, Activity Book, Activity Books', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94410/Anak_-_Burung,_Bunga,_dan_Kupu-kupu.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(294, '678230b579bd51cee772b659', 'BTS Odyssey: 7 Anak Muda yang Menuntunku Menemukan Diriku Kembali', 'Kim Song-yeon', 'Self-Improvement,', 'Ketika aku “tersesat”, BTS memasuki hidupku seolah-olah mereka sedang menungguku dengan Map of the Soul-nya—peta jiwa yang menunjukkan jalan kepadaku untuk menemukan diriku yang hilang.Kebanyakan orang mengetahui siapa BTS, tetapi kebanyakan juga belum tahu apa kunci keberhasilan mereka. BTS tak dapat didefinisikan hanya dengan kata seperti “idola” atau “grup K-Pop”. Dari mana kekuatan unik BTS berasal? Apa rahasianya? Kim Song-yeon menemukan jawaban atas pertanyaan ini dalam pemikiran Carl Gustav Jung.Akar ketidaksadaran yang mendominasi pikiran kita tergambar dalam lirik, pesan, hingga bentuk aktivitas BTS. Jika memahami fakta ini, kita bisa mengungkap kekuatan sejati BTS yang mendominasi dunia. Kuncinya adalah “penyembuhan”. Sinergi cinta yang besar yang diberikan BTS memunculkan sumber ketidaksadaran kita yang tersimpan,Cinta dan penyembuhan didasarkan pada kekuatan mental yang tidak dapat ditukar dengan pencapaian numerik atau materi. Kekuatan ini menyelamatkan ARMY melampaui usia, gender, bahkan kebangsaan. Kim Song-yeon yang menutup pintu hatinya berhasil keluar dari dunianya yang terisolasi karena “pertemuan”-nya dengan BTS.', 'Rp 119,000', '218 pages', '28 February 2024', 'penulis korea, BTS, Self-Acceptance, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94521/BTS_ODYSSEY_C_1_4.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(295, '67822fef79bd51cee772b5ee', 'Ciuman Cinta Sang Rival (Wrong Brother, Right Kiss)', 'Joss Wood', 'Harlequin', 'Setelah perceraiannya, Tinsley memusatkan hidupnya menjadi seorang Ryder-White yang sempurna, seperti tuntutan keluarganya. Tetapi, di malam Tahun Baru itu, Tinsley begitu lelah mengurusi segala perayaan. Ketika Cody Gallant, mantan kakak iparnya, menghampiri dan mengajaknya berdansa di bawah salju yang turun, seketika Tinsley hanya ingin menjadi dirinya yang tidak sempurna.Malam Tahun Baru yang dihabiskan Cody bersama Tinsley jelas di luar dugaan semua orang. Sejak dulu, Tinsley dan Cody dikenal selalu bertengkar dan tidak pernah akur. Tapi, hanya untuk satu malam itu, Tinsley dan Cody memilih menjadi pribadi yang berbeda. Dan, mereka sama-sama berjanji, itu hanya akan terjadi satu kali.Hanya saja, pekerjaan kembali mempertemukan mereka. Bagaimana Cody dan Tinsley harus bersikap di depan semua orang?', 'Rp 69,000', '240 pages', '28 February 2024', 'Novel, Harlequin, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94414/Wrong_Brother_Right_Kiss_cov-1.jpg', '2026-02-17 07:08:40', '2026-02-17 07:08:40'),
	(298, '67822fcd79bd51cee772b5dc', 'CoComelon 500 Sticker', 'Moonbug Entertainment', 'Activity Books', 'Yuk, kita bermain bersama JJ dan  kawan-kawan di musim panas yang cerah ini! Mereka hadir dalam lembar-lembar mewarnai dan stiker lucu yang bisa ditempel di mana saja.  Ayo kita bersenang-senang dan  tumbuh bersama!', 'Rp 59,000', '24 pages', '21 February 2024', 'Anak-anak, Stiker, Aktivitas, Anak, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94396/Anak_-_CoComelon_500_Sticker.jpg', '2026-02-17 07:08:40', '2026-02-17 07:10:16'),
	(303, '678230ac79bd51cee772b654', 'Jalan Tengah Golongan Karya: Mengutamakan Persatuan dan Kesatuan demi Kemajuan Bersama', 'Erwin Aksa,', 'Politics', 'Menjelang seabad usianya, Indonesia memiliki satu agenda penting, yaitu bagaimana semangat reformasi dijalankan secara berkelanjutan, positif, dan progresif. Perubahan secara cepat, baik di level nasional maupun global, mendesak kita untuk memaknai ulang wawasan, orientasi, serta aksi dan tindakan kita. Jalan Tengah Golongan Karya menghadirkan visi pembaruan Partai Golkar sebagai partai modern yang secara politik mengembangkan pendekatan dan wawasan moderatif “mengarah ke tengah”; tidak terjebak pada beban ideologis, tetapi mampu relevan dengan dunia yang menghadapi berbagai ancaman, seperti keamanan dan kelestarian lingkungan hidup. Buku ini menjadi salah satu sumbangsih yang berharga bagi ikhtiar memajukan demokrasi di Tanah Air.', 'Rp 106,000', '130 pages', '14 February 2024', 'nonfiksi, Politic, Politics', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94516/JALAN_TENGAH_GOLKAR_C_1_4.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(304, '67822fd479bd51cee772b5e0', 'Resep Snack MPASI Cegah Stunting', 'dr. Margaret Mutiaratirta Sugondo,', 'Parenting & Family', 'Tidak terasa bayi kita sudah beranjak 1 tahun ya mom and dads. Mulai muncul drama pilih2 makanan, gerakan tutup mulut (GTM) apalagi kalau sampai kenaikan berat badan kecil tidak optimal. Di masa2 ini parents akan sangat galau bila anaknya tidak mau makan, takut anak tidak bertumbuh dengan baik,lalu terpaksa diberikan susu atau snack ultraproses sebagai pengganti nutrisi yang harusnya didapatkan dari bahan makanan alami.Kesibukan kita sebagai orang tua di jaman ini membuat minim nya waktu untuk berkreasi dengan menu-menu sehat di dapur rumah.Kami mengerti kondisi para moms dan dads yang ingin memasak untuk si kecil tapi memiliki waktu yang sedikitNah melalui buku ini ,akan kami bagikan resep2 sehat ‘quick & easy’, sebagian besar resep memiliki kalori cukup tinggi untuk membantu meningkatkan berat badan,minim gula garam dan tanpa bahan penyedap dan pastinya disukai balita.Teknik memasak yang sederhana dengan bahan-bahan yang mudah diperoleh ini juga dapat dijadikan aktivitas bermain dengan anak.What’s inside this book?Resep-resep ala chef dan dokter yang mudah dibuat untuk para millennial parents yang sangat sibuk dan merasa tidak bisa memasak.Teori singkat mengenai MPASI rekomendasi WHO yg ditekankan untuk anak usia 1-2 thn.Tips2 menangani anak GTM /susah makan.Jumlah asupan susu maksimal per hari.Resiko malnutrisi dan stunting pada anak.Buku ini akan membuat moms and dads ingin memasak di dapur rumah untuk si kecil karena bahan2nya simpel, menggunakan alat2 masak yang biasanya ada di rumah,bahan mudah didapat dan diolah serta dapat dibuat dalam waktu yg cukup singkat. Yuk kita belajar masak bersama...', 'Rp 99,000', '94 pages', '14 February 2024', 'resep mpasi, makanan bayi, mpasi, buku parenting, Parenting', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94400/BBK_-_Resep_Snack_MPASI.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(305, '67822fd279bd51cee772b5df', 'Menu Favorit Keluarga untuk Bakulan', 'Nanik Handayani', 'Culinary', 'Penulis buku ini adalah Ibu dari 4 anak dan oma dari 2 cucu. Ia juga pemilik akun instagram @mrs.wijaya berisi foto-foto masakan yang disajikannya untuk keluarga tercinta, dengan follower lebih dari 220.000. Tak sedikir followernya yang merecook dan menjadikan resep-resepnya ide untuk berjualan.Buku kedua Bunda Nanik ini - demikian para follower menyapanya Menu Favorit Keluarga untuk Berjualan berisi 75 resep andalan yang bertahun-tahun menjadi menu kegemaran keluarganya, terbagi atas 6 bab: Hidangan Ayam, Hidangan Daging, Hidangan Ikan, Hidangan Nasi & Mi, Hidangan Sayur, dan Hidangan Vegetarian Non Daging.Yuk recook resep Bunda Nanik, selain memanjakan keluarga sekaligus menambah cuan.', 'Rp 149,000', '174 pages', '14 February 2024', 'Masakan Rumahan, masakan indonesia, buku masak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94399/BBK_-_Menu_Favorti_Keluarga_untuk_Bakulan.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(306, '67822fbe79bd51cee772b5d4', 'Aktivitas Menggambar Keliling Dunia (How to Draw Cute: Around The World)', 'Angela Nguyen', 'Activity Books', 'Masuki planet imut !INGIN tantangan menggambar baru?TAMBAHKAN kesan imut pada gambar ikonis dunia!BELAJAR menggambar dengan gaya “kawaii”.AMBIL alat gambarmu, lalu kita mulai!', 'Rp 119,000', '128 pages', '14 February 2024', 'Activity Book, Activity Books', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94388/Anak_-_Aktivitas_Menggambar_Keliling_Dunia.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(307, '67822fc979bd51cee772b5da', 'CoComelon Buku Mewarnai: Teman Bertualang', 'Moonbug Entertainment', 'Activity Books', 'Ayo bergabung bersama karakter-karakter favorit CoComelon di buku mewarnai ini!Setiap halaman buku akan membawa kalian menuju berbagai petualangan seru dan menakjubkan.', 'Rp 35,000', '16 pages', '14 February 2024', 'Anak-anak, Mewarnai, Anak, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94394/Anak_-_Cocomelon_Buku_Mewarnai_Teman_Bertualang.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(308, '67822fba79bd51cee772b5d2', 'Aktivitas Menggambar Hewan Imut (How to Draw Cute: Animals)', 'Angela Nguyen', 'Activity Books', 'Masuki planet imut !INGIN tantangan menggambar baru?TAMBAHKAN kesan imut pada gambar hewan apa pun!BELAJAR menggambar dengan gaya “kawaii”.AMBIL alat gambarmu, lalu kita mulai!', 'Rp 119,000', '128 pages', '14 February 2024', 'Anak-anak, Anak, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94386/Anak_-_Aktivitas_Menggambar_Hewan_Imut.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(309, '6782301279bd51cee772b601', 'Menjalani Masa Pensiun dengan Gembira dan Produktif', 'A.M. Mangunhardjana, SJ', 'Self-Improvement', 'Menjalani Masa Pensiun dengan Gembira dan Produktif adalah panduan yang memberikan pemahaman mendalam mengapa masa pensiun adalah tahap yang penting dalam perjalanan hidup kita. Selain itu, buku ini juga memberikan kunci dan petunjuk praktis bagaimana kita menjalani tahap itu dengan sebaik-baiknya.Melalui narasi yang hangat dan inspiratif, buku ini mengeksplorasi berbagai aspek persiapan untuk masa pensiun, termasuk aspek kesehatan, sosial, dan emosional. Buku ini juga menyoroti pentingnya merencanakan kehidupan pensiun dengan cermat, membangun fondasi finansial yang kokoh, menjaga kesehatan fisik dan mental, dan membentuk hubungan sosial yang mendukung.Penulis mengajak pembaca untuk memandang masa pensiun sebagai petualangan baru yang penuh potensi, bukan akhir dari kehidupan aktif. Dengan itu, masa pensiun dimaknai secara baru. Masa pensiun tidak menjadi “waktu tersisa” dan “saat berhenti bekerja”, tetapi suatu bab baru dalam hidup yang penuh makna dan membahagiakan.', 'Rp 198,000', '320 pages', '14 February 2024', 'nonfiksi, Self-Improvement, Self Improvement, Self-Acceptance, pensiun', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94433/Cover_Menjalani_Masa_Pensiun_R.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(310, '67822f9779bd51cee772b5bf', 'Pinocchio: Mewarnai & Aktivitas: Mimpi Jadi Nyata', 'Disney', 'Activity Books', 'Potong dan PajangPetunjuk:Minta bantuan orang dewasa.Gunting mengikuti garis putus-putus.Buat lubang di atas setiap gambar karakter.Masukkan tali ke setiap lubang.Ikat tali ke gantungan baju atau kayu bertali seperti yang dicontohkan di atas.Gantung pajanganmu di atas jendela atau pintu luar. Pajanganmu akan bergoyang setiap angin bertiup.', 'Rp 59,000', '68 pages', '14 February 2024', 'Aktivitas, Activity Book, Activity Books, Mewarnai', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94367/Anak_-_Pinocchio.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(311, '67822fbc79bd51cee772b5d3', 'Aktivitas Menggambar Makanan Imut (How to Draw Cute: Food)', 'Angela Nguyen', 'Activity Books', 'Masuki planet imut !INGIN tantangan menggambar baru?TAMBAHKAN kesan imut pada gambar makanan apa pun!BELAJAR menggambar dengan gaya “kawaii”.AMBIL alat gambarmu, lalu kita mulai!', 'Rp 119,000', '128 pages', '14 February 2024', 'Anak-anak, Anak, Activity Book, Activity Books, buku anak gramedia, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94387/Anak_-_Aktivitas_Menggambar_Makanan_Imut.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(312, '67822fc079bd51cee772b5d5', 'Lelap dalam Lautan Bintang (To Sleep in A Sea of Stars)', 'Christopher Paolini', 'Science Fiction & Fantasy', 'Kira Navárez, ahli xenologi dari Bumi, bermimpi tentang hidup di dunia baru.Namun, mimpi buruklah yang dialaminya.Di tengah pekerjaannya menjelajahi galaksi, meneliti planet tak berpenghuni yang mungkin memiliki tanda-tanda kehidupan, Kira menemukan relik alien. Awalnya dia senang, tapi penemuan itu membuat dunianya runtuh.Kehilangan orang-orang terkasih, menghadapi selubung “hidup” yang melekat di tubuhnya, bertemu alien yang tak terbayangkan, semua itu menjerumuskan Kira dalam pertempuran di antara bintang-bintang.Pertempuran yang akan menentukan nasib umat manusia....', 'Rp 129,000', '424 pages', '07 February 2024', 'Novel Fantasi, Science Fiction & Fantasy, Fantasy', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94389/Fiksi_-_To_Sleep_in_a_Sea_of_Stars.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(313, '67822f6579bd51cee772b5a5', 'ADHD pada Lansia dan Cara Menanganinya', 'Kathleen Nadeau, Ph.D.', 'Self-Improvement,', 'Selain anak-anak, orang dewasa dan lansia pun dapat mengalami kondisi ADHD. Ada yang sudah didiagnosis, ada juga yang belum. Bagaimana mengenali kondisi tersebut? Berikut beberapa pola yang menjadi indikasinya:sering lupa membayar tagihan?kesulitan menyelesaikan tugas-tugas administratif?hidup di lingkungan yang tidak terorganisasi?berjuang dengan depresi dan kecemasan?menunda-nunda proyek, bahkan proyek yang awalnya membuat bersemangat?memiliki tingkat konflik yang tinggi dengan orang-orang terdekat?memiliki riwayat keluarga dan/atau anak yang didiagnosis dengan ADHD?Dampak ADHD pada orang lanjut usia akan semakin rumit dan parah apabila si penyandang tidak mendapatkan diagnosis, pengobatan, dukungan dari orang-orang terdekat, serta tidak membangun kebiasaan sehat. Buku ini menawarkan strategi untuk membangun sistem pendukung; mendapatkan kendali yang lebih baik atas kehidupan sehari-hari; menjalani kehidupan yang lebih tenang, bahagia, dan produktif; serta menciptakan masa pensiun yang lebih ramah ADHD.', 'Rp 179,000', '406 pages', '07 February 2024', 'adhd, Self-Improvement, pengembangan diri, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94341/STILL_DISTRACTED_R1.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(314, '67822fcb79bd51cee772b5db', 'Tirani Demokrasi', 'Sapardi Djoko Damono', 'Literary', '“Duduk sama rendah, berdiri lain-lain tingginya.” ‘PBB’, Taufiq IsmailBuku ini adalah peninggalan Sapardi yang paling tidak dikenal: Tirani Demokasi. Selebaran yang memberi peringatan. Seno Gumira Ajidarma, penulisDi tangan Sapardi Djoko Damono kompleksitas demokrasi bisa disampaikan dengan ringan dan sederhana. Buku ini menunjukkan dia bukan hanya begawan sastra tapi juga seorang pemikir yang sangat peduli dengan masa depan bangsanya. Iwan Esjepe, Founder & CCO Ideasphere Transformation Bureau', 'Rp 99,000', '146 pages', '07 February 2024', 'sastrawan, sastra indonesia, sastra, Sapardi Djoko Damono', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94395/Sastra_-_Tirani_Demokrasi.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(315, '67822f8e79bd51cee772b5ba', 'Rumah di Mango Street (The House on Mango Street)', 'Sandra Cisneros', 'Latin American Literature', 'Rumah di Mango Street berkisah tentang Esperanza Cordero, gadis Latina muda yang dibesarkan di Chicago, tentang kehidupan sehari-hari para penghuni Mango Street yang beraneka ragam, dan bagaimana Esperanza menemukan dirinya. Diceritakan dalam kisah pendek-pendek (vinyet), buku ini memberikan gambaran tentang masa kanak-kanak yang sering kali polos dan menggembirakan, tapi bisa juga sedih dan bahkan menyakitkan.Rumah di Mango Street adalah karya Sandra Cisneros, penulis penerima penghargaan, yang menyentuh pembaca dari seluruh generasi.', 'Rp 69,000', '176 pages', '31 January 2024', 'Sastra Amerika Latin, Latin American, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94362/Fiksi_-_Rumah_di_Mango_Street.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(316, '67822f9e79bd51cee772b5c3', 'Wish: Keajaiban Mimpi', 'Disney', 'Picture Books', 'Asha dan teman-temannya punya impian-impian besar. Apakah semuanya akan terwujud?', 'Rp 39,000', '24 pages', '31 January 2024', 'Picture book, picture books, Pictures Book, Buku anak, buku anak gramedia, Anak, Anak-anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94371/Anak_-_Wish.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(317, '67822fb579bd51cee772b5cf', 'Mommyclopedia: 99+ Resep MPASI', 'Dr. dr. Meta Hanindita, Sp.A.(K)', 'Parenting & Family,', 'Makanan Pendamping ASI (MPASI) adalah makanan padat atau makanan cair selain ASI di saat ASI saja sudah tidak dapat mencukupi kebutuhan nutrisi untuk tumbuh kembang optimal. Buku ini terdiri atas 99 lebih resep MPASI yang dibagi menjadi 3 bagian menurut kelompok usia (berdasarkan bulan). Masing-masing bagiannya terdiri atas makanan utama dan camilan.Semua bahan untuk pembuatan resepnya memakai bahan-bahan yang murah, bergizi, dan mudah didapat di pasaran. Hampir semua jenis karbohidrat dan protein yang ada di nusantara ini disajikan di sini sehingga bisa menjadi inspirasi bagi para ibu untuk mengolah makanan buah hati tercintanya.', 'Rp 129,000', '176 pages', '31 January 2024', 'dr Meta, Mommyclopedia, dr. Meta Hanindita, drmeta, buku parenting, Parenting', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94383/Hum_-_Mommyclopedia_99_Resep_MPASI.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(318, '67822faf79bd51cee772b5cc', 'Disney: Petualangan Mewarnai', 'Disney', 'Activity Books', 'Dengan buku mewarnai penuh keajaiban ini, kau bisa bertualang dan mewujudkan semua keinginan bersama karakter-karakter favoritmu!', 'Rp 39,000', '24 pages', '31 January 2024', 'Children Book, Children Books, Childrens Books, Children, Buku anak, buku anak gramedia, Anak, Anak-anak, disney', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94380/Anak_-_Petualangan_Mewarnai.jpg', '2026-02-17 07:10:16', '2026-02-17 07:10:16'),
	(319, '67822fb779bd51cee772b5d0', 'Mengokohkan Golkar sebagai Partai Tengah', 'Harimurti Kridalaksana', 'Politics', 'Menjelang seabad usianya, Indonesia memiliki satu agenda penting, yaitu bagaimana semangat reformasi dijalankan secaraberkelanjutan, positif, dan progresif. Perubahan secara cepat, baik di level nasional maupun global, serta risiko pelambatan, mendesak kita untuk memaknai ulang wawasan, orientasi, serta aksi dan tindakan kita.Mengokohkan Golkar sebagai Partai Tengah menghadirkan visi pembaruan Partai Golkar sebagai partai modern yang secara politikmengembangkan pendekatan dan wawasan moderatif “mengarah ke tengah”; tidak terjebak pada beban ideologis, tetapi mampurelevan dengan dunia yang menghadapi berbagai ancaman, seperti keamanan dan kelestarian lingkungan hidup. Buku ini, dengan demikian, menjadi salah satu sumbangsih yang berharga bagi ikhtiar memajukan demokrasi di Tanah Air kita.Posisi “partai tengah” adalah strategi untuk mencegah potensi keragaman menjadi potensi konflik horizontal. Posisi itu sekaligus menjadi penanda antropologis bahwa keragaman bangsa ini tak mungkin disatukan oleh satu ideologi politik. Di sini pentingnya Golkar menyelenggarakan kurikulum pendidikan nilai-nilai demokrasi dan hak asasi manusia, daripada sekadar memekikkan slogan-slogan patriotik.—Rocky Gerung“Golkar diharapkan menjadi kekuatan tengah yang mengawal dan mempratikkan nilai-nilai Pancasila secara murni dan konsekuen. Tampak dalam buku ini, Erwin berkomitmen mendorong inovasi dan transformasi Golkar sebagai partai tengah yang solid dan tangguh memasuki abad milenial menuju era Indonesia Emas 2045.”—Bob Randilawe', 'Rp 98,000', '166 pages', '31 January 2024', 'Politics', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94384/Hum_-_Mengokohkan_Golkar_sebagai_Partai_Tengah.jpg', '2026-02-17 07:10:16', '2026-02-17 07:11:24'),
	(321, '67822f9b79bd51cee772b5c1', 'The Case-book of Sherlock Holmes', 'Sir Arthur Conan Doyle', 'English Classics', '"When one tries to rise above Nature one is liable to fall below it."', 'Rp 79,000', '380 pages', '31 January 2024', 'English Classic, Classic Novels, English Classics, Classic, Classic Novel, classics, Sherlock Holmes', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94369/Fiksi_-_The_Case-Book_of_Sherlock_Holmes.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(323, '67822f1479bd51cee772b579', 'Live Life in Crescendo', 'Stephen R. Covey', 'Self-Improvement,', '“Stephen Covey, dalam buku kepemimpinan terakhirnya, Live Life in Crescendo, yang diselesaikan oleh putrinya Cynthia, mengusulkan perubahan paradigma seputar masa pensiun, menunjukkan bahwa meskipun kita mungkin pensiun dari pekerjaan atau karier, kita tidak pernah harus pensiun dari membuat kontribusi yang bermakna bagi orang-orang di sekitar kita. Dengan wawasan baru dan kisah-kisah pribadi yang menginspirasi, buku ini membantu kita fokus menjalani kehidupan pelayanan dengan semangat yang sama dengan yang kita bawa untuk membangun karier yang sukses.” —ARIANNA HUFFINGTON, pendiri dan CEO Thrive“Pensiun bukanlah akhir, tetapi sungguh sebuah awal. Kita memiliki lebih banyak waktu untuk membangun hubungan yang lebih kuat dan berkontribusi serta memberikan kembali kepada komunitas kita yang lebih besar. Buku yang indah dan menginspirasi ini memberi kita contoh, cerita, dan kearifan yang dibutuhkan untuk menciptakan warisan abadi yang akan hidup jauh melampaui usia kita. Terima kasih, Stephen dan Cynthia, untuk Live Life in Crescendo, buku luar biasa ini, yang merupakan penghargaan bagi Sephen R. Covey dan warisannya.” —INDRA NOOYI, mantan CEO PepsiCo dan penulis buku laris versi New York Times, My Life in Full“Apakah Anda telah menikmati kesuksesan, menghadapi kesulitan, atau merasakan stagnasi, masa- masa terbaik kita masih ada di depan. Dengan kearifan dan kehangatan khas Stephen Covey, buku penuh harapan yang menyenangkan ini menunjukkan bagaimana kehidupan benar-benar dapat terus menjadi lebih baik dan lebih baik.” —DANIEL H. PINK, penulis buku terlaris #1 New York Times, The Power of Regret, When, dan Drive“Cynthia Covey Haller melanjutkan karya mendiang Stephen Covey yang hebat dalam buku yang penuh inspirasi ini. Live Life in Crescendo akan memberi pembaca inspirasi dan harapan untuk menjalani hidup yang produktif dan bermakna, dari awal hingga akhir.” —ARTHUR C. BROOKS, guru besar Harvard Kennedy School dan Harvard Business School, penulis buku terlaris #1 New York Times, From Strength to Strength“Diktum yang saya promosikan adalah ‘Menghasil- kan uang mungkin merupakan kebahagiaan, tetapi membuat orang lain bahagia adalah kebahagiaan yang luar biasa’. Sederhananya, kebahagiaan datang dari banyak sumber, bukan hanya dari kesuksesan finansial. Saat kita berbagi dan melayani mereka yang membutuhkan, kita mengalami kebahagiaan sejati pada tingkat yang jauh lebih dalam dan memuaskan. Live Life in Crescendo mengajarkan kita bagaimana mencapai kehidupan yang bertujuan, bermakna, dan memberi sumbangsih, dengan memberi banyak dan sepenuh hati, untuk kebaikan yang lebih besar.” —PROFESOR MUHAMMAD YUNUS, pemenang Hadiah Nobel untuk Perdamaian 2006 dan pendiri Grameen Bank“Sungguh suatu godaan untuk percaya bahwa kita telah melakukan pekerjaan terbaik kita. Bahwa kita telah mencapai puncaknya. Bahwa kita sedang merosot. Bahwa hari-hari kejayaan kita telah lewat. Jadi, buku Stephen Covey dan Cynthia Covey Haller ini adalah angin segar. Ini membalikkan situasi sepenuhnya dan mengundang kita untuk percaya bahwa kontribusi besar kita selalu ada di depan kita. Membaca ini telah menjadi berkat besar bagi saya, dan juga bagi Anda. Anda tidak akan pernah memikirkan hidup Anda dengan cara yang sama lagi.”—GREG McKEOWN, penulis buku laris versi New York Times, Essentialism dan Effortless“Stephen Covey menjalani hidupnya dalam kresendo dan terus menginspirasi orang lain untuk melakukan hal sama. Dia membantu mengubah jalur karier football dan hidup saya, ketika kebetulan kami duduk bersama di pesawat. Dalam penerbangan itu, saya terinspirasi dan disegarkan. Saya berada di hadapan keagungan saat dia dengan mahir membagikan prinsip-prinsip dalam buku ini, yang mengungkapkan peluang luar biasa di hadapan saya. Warisannya bersinar melalui buku ini dan kehidupan keluarganya.” —STEVE YOUNG, pemain quarterback NFL Hall of Fame, chairman dan rekan pendiri HGGC', 'Rp 129,000', '346 pages', '24 January 2024', 'Self Transformation, buku pengembangan diri, Self-Acceptance, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94297/Live_Life_in_Crescendo_C_1_4.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(324, '67822fb979bd51cee772b5d1', 'CoComelon: Kakak Terbaik', 'Moonbug Entertainment', 'Activity Books', 'Belajar mewarnai, menulis, dan berhitung akan semakin seru dilakukan bersama kakak-kakakmu, lho! Ayo ajak mereka mengerjakan 32 halaman aktivitas di buku ini bersama-sama.', 'Rp 49,000', '32 pages', '24 January 2024', 'Activity Book, Activity Books, Mewarnai', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94385/Anak_-_Cocomelon_Kakak_Terbaik.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(325, '6782309e79bd51cee772b64d', 'Pramoedya Menggugat, Melacak Jejak Indonesia (sampul 2024)', 'Prof. Koh Young Hun', 'Literary', 'A. Teeuw pernah mengatakan bahwa Pramoedya merupakan penulis yang muncul hanya sekali dalam satu generasi, atau malah dalam satu abad. Saya yakin, pendapat itu tidak hendak melebih-lebihkan.Pramoedya adalah novelis yang tidak hanya mewakili Indonesia melainkan juga kawasan Asia. Ia penulis yang mencurahkan pemikiran di bawah naungan humanisme. Kemanusiaan merupakan satu dasar pemikiran dan landasan penciptaan karya Pramoedya. Falsafah ini bersumber dari pandangan bahwa manusia yang hakiki melepaskan diri dari segala belenggu, seperti penolakan atas warisan budaya yang kolot, perlawanan atas ketidakadilan kekuasaan kolonial, atau semangat membangun kebebasan dan kesejahteraan dalam lingkup kesatuan bangsa. Sikap ini tentu saja bukan tanpa risiko. Ia harus meringkuk di penjara selama tujuh belas setengah tahun masing-masing pada zaman Belanda, Orde Lama, dan Orde Baru.Dalam buku ini, saya memberi tanggapan terhadap Bumi Manusia, Arus Balik, Arok Dedes, dan Gadis Pantai. Saya menganalisis dan menguraikan dunia Pramoedya melalui karya-karyanya. Saya tidak hanya menjunjung tinggi dan mengungkapkan kedalaman makna serta pesan tematik novel-novel Pramoedya, melainkan, sebagai seorang sarjana yang berkecimpung dalam bidang kritik sastra, saya berusaha membuktikan keunggulannya sekaligus.Prof. Koh Young Hun', 'Rp 179,000', '466 pages', '24 January 2024', 'sastra, sastra indonesia, nonfiksi, Non-Fiction', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94509/pramudia_menggugat_C_1_4_CU_2024_(1).jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(326, '6782309579bd51cee772b648', '12 Peraturan Hidup: Suatu Penangkal Kekacauan', 'Jordan B. Peterson', 'Self-Improvement,', 'APA HAL TERPENTING YANG PERLU DIKETAHUI OLEH SEMUA ORANG?Psikolog klinis terkemuka Jordan B. Peterson telah memberikan pengaruh besar terhadap pemahaman modern tentang kepriba- dian. Saat ini dia adalah salah satu pemikir publik paling populer di dunia.Ceramah-ceramahnya yang membahas berbagai tema, dari kitab suci, hubungan romantis, sampai mitologi, telah menarik perha- tian puluhan juta orang. Pada era perubahan yang belum pernah terjadi dan politik yang terkotak-kotak ini, pesannya yang jujur dan menyegarkan tentang nilai-nilai tanggung jawab individu serta kebijaksanaan kuno telah menggema ke seluruh dunia.Di buku ini, dia menyampaikan dua belas prinsip yang praktis dan mendalam tentang cara menjalani kehidupan yang bermakna.Buku yang ditulis berdasarkan contoh nyata dari praktik dan kehi- dupan pribadinya serta pelajaran dari kisah-kisah dan mitos-mitos kuno bertema kemanusiaan ini menawarkan penangkal untuk kekacauan dalam hidup kita; kebenaran abadi yang bisa diterapkan pada permasalahan modern yang kita hadapi.', 'Rp 139,000', '432 pages', '17 January 2024', 'Personal Growth, Non-Fiction, Self-Improvement, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94504/PANDUAN_12_PERATURAN_HIDUP.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(327, '67822fb379bd51cee772b5ce', 'Leaders LEAD: Langkah-Langkah Strategis Menjadi Impactful Leader', 'Atok R. Aryanto', 'Business Management & Leadership', 'Pusaran tornado perubahan bergerak begitu cepat. Disrupsi teknologi dan perubahan pola perilaku sosial generasi muda telah mengubah lanskap peradaban manusia. Organisasi bisnis pun tak lepas dari hempasan angin besar perubahan ini.Bagi Anda para Leader, strategi terpenting adalah beradaptasi dengan gaya kepemimpinan yang pas di era perubahan, yang bisa menopang Anda agar semakin solid menapaki jenjang karier, membawa perusahaan terus tumbuh, serta memberi kemanfaatan bagi banyak orang.Inilah Impactful Leadership, sebuah konsep kepemimpinan yang dibangun dengan empat pilar: Embrace Novelty, Create Legacy, Raise Collaboration, dan Build Dynasty yang ditopang oleh dua fondasi penting: Performance dan Lead Capability. Kuasai konsep ini dan Anda akan menjadi Impactful Leader.“Di era disruptif ini, semua pemimpin dituntut untuk berpikir kembali. Semua bisa berubah dan menjadi tak bernilai. Pemimpin yang mau selalu berpikir atau memikirkannya kembalilah yang menjadi pemimpin yang sebenarnya. Temukanlah dalam buku Leaders LEAD ini.”—Prof. Rhenald Kasali, Ph.D, Pakar Manajemen, Guru Besar Fakultas Ilmu dan Bisnis Universitas Indonesia“Perubahan bisnis saat ini terjadi dalam situasi yang sangat cepat. Begitu juga dengan lingkungan dan karakter tim. Buku ini memberikan solusi dan warna baru dalam gaya kepemimpinan Anda.”—Supranoto Tirtodidjojo, CEO PT Astra International, Tbk. Daihatsu“Leaders LEAD adalah buku yang hadir pada waktu yang tepat. Saat kita menunggangi gelombang cepat society 5.0 yang didorong oleh revolusi AI, buku ini adalah kompas Anda. Saatnya membawa tim Anda menuju masa depan yang lebih baik!”—Dr. Indrawan Nugroho, CEO dan Co-founder CIAS“Keberhasilan organisasi untuk survive di era disrupsi tidak bisa dilepaskan dari peran pemimpin. Kualitas pemimpin masa kini terkristalisasi dan tertuang dengan sangat baik dalam buku Leaders LEAD.”—Wiko Migantoro, Direktur Utama, Pertamina Hulu Energi“Kemampuan utama leader sejatinya menggerakkan orang lain untuk mencapai tujuan organisasi (leader getting things done through others), dan kompetensi utama dalam memotivasi orang lain adalah influencing others dan inspirational motivation. Buku ini dapat menjadi referensi utama para leader untuk belajar secara komprehensif terkait strategi motivasi dan memahami dinamika psikologisnya.”—Wisnoe Satrijono, Direktur MHCA PLN Indonesia Power', 'Rp 145,000', '276 pages', '17 January 2024', 'Pemimpin, Leadirship, Bisnis, Leader, leadership, buku bisnis', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94382/Hum_-_Leaders_Lead.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(328, '67822fb179bd51cee772b5cd', 'Tragedi Pedang Keadilan', 'Keigo Higashino', 'AsianLit - Japan', 'Sejak istrinya meninggal, Nagamine Shigeki hidup hanya berdua dengan putrinya, Ema. Suatu malam, Ema pergi menonton festival musim panas. Tetapi ia tidak pernah pulang sampai mayatnya ditemukan di sungai.Dalam hari-hari kelam menunggu proses penyelidikan, Nagamine menerima telepon dari seseorang yang memberikan informasi tentang para pelaku dan lokasi pembunuhan Ema. Nagamine menyusup ke apartemen yang disebut. Di sana ia menemukan kaset video berisi rekaman peristiwa pemerkosaan dan pembunuhan putrinya.Semakin terpuruk dalam duka dan kini diselimuti amarah, ditambah keyakinan bahwa para pelaku hanya akan dihukum ringan karena masih di bawah umur, Nagamine memutuskan mengadili mereka dengan tangannya sendiri. Apakah Nagamine akan berhasil? Kepada siapakah hukum akan memihak?', 'Rp 129,000', '464 pages', '17 January 2024', 'Thriller, Mystery & Thrillers, Thrillers, novel thriller, Keigo Higashino', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94381/Fiksi_-_Tragedi_Pedang_Keadilan.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(329, '67822fab79bd51cee772b5ca', 'Akhir Antara Kita (It Ends With Us)', 'Colleen Hoover', 'Romance', 'Orang yang mencintaimu terkadang bisa menjadi orang yang paling menyakitimu.Hidup Lily tidak selalu mudah. Itu sebabnya ia selalu gigih memperjuangkan segala hal yang ia idamkan. Ketika tak sengaja bertemu Ryle Kincaid, dokter bedah saraf tampan yang langsung membuatnya jatuh cinta pada pertemuan pertama, segala sesuatu dalam hidup Lily terasa nyaris sempurna.Di balik ketampan dan kecerdasannya, Ryle sosok yang keras, sedikit sombong, serta sangat ambisius. Demi menjadi ahli bedah saraf terbaik, Ryle menetapkan aturan untuk dirinya: tidak akan menjalin hubungan dengan perempuan mana pun. Hanya Lily yang mampu membuatnya luluh dan melanggar aturan tersebut.Ketika cinta dan obsesi membelit Lily dan Ryle semakin dalam dan menyesakkan, sosok Atlas Corrigan muncul. Pria itu mengingatkan Lily tentang cinta pertamanya yang nyaman dan membebaskan. Atlas adalah sahabat pelindungnya, belahan jiwanya. Namun, bagaimana jika kehadiran Atlas justru membuat segala yang dibangun Lily bersama Ryle terancam runtuh?', 'Rp 119,000', '480 pages', '17 January 2024', 'romance novel, romantis, novel roman, Roman, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94378/Fiksi_-_It_Ends_With_Us.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(330, '67822f8479bd51cee772b5b5', 'Take Command', 'Michael Crom,', 'Self-Improvement,', 'Pegang kendali masa depan Anda dengan buku terlaris menurut Wall Street Journal, dari para ahli yang mengenalkan Anda pada How to Win Friends and Influence People.Take Command menawarkan cara ampuh dan metode yang telah teruji waktu untuk membantu Anda menjalani kehidupan yang direncanakan dengan mengubah cara Anda mendekati pikiran, emosi, relasi, dan masa depan. Dipenuhi dengan kisah sehari-hari dan berdasarkan penelitian para ahli serta wawancara dengan lebih dari seratus pemimpin berkinerja tinggi, Take Command memberi Anda strategi yang Anda perlukan untuk membuka potensi penuh Anda dan menciptakan kehidupan yang Anda inginkan.Ditulis oleh Joe Hart (CEO) dan Michael Crom (Anggota Dewan) Dale Carnegie & Associates, Take Command adalah manual modern untuk pengembangan pribadi yang akan membantu siapa pun di usia berapa pun. Buku ini disusun berdasarkan pertanyaan yang ditujukan untuk mendorong refleksi diri, seperti:- Bagaimana kita menggunakan kekuatan pola pikir untuk mengatasi stres dan kecemasan, mendapatkan perspektif tentang emosi negatif, dan membangun ketahanan?- Setelah memahami kehidupan batin kita, bagaimana kita menciptakan relasi yang memperkaya, bermanfaat, dan bertahan lama?- Bagaimana kita menghadapi orang-orang sulit dan mengelola konflik?- Setelah menguasai pikiran dan relasi kita, bagaimana kita hidup dengan berani dan tekun membangun visi yang akan menghasilkan sisi terbaik dalam diri kita dan orang lain?Selama lebih dari seratus tahun, kebijaksanaan dalam buku How to Win Friends and Influence People karya Dale Carnegie telah memberi orang-orang di seluruh dunia hubungan yang lebih kaya, lebih memuaskan, dan cara hidup yang lebih bahagia. Kini, Take Command menggabungkan pelatihan Dale Carnegie yang telah memenangkan penghargaan selama puluhan tahun dan prinsip-prinsip abadi—yang telah mengubah kehidupan pribadi dan profesional jutaan orang—menjadi sebuah teks utama yang memberitahu Anda segala hal yang perlu Anda ketahui tentang seni hubungan antarmanusia.', 'Rp 129,000', '352 pages', '17 January 2024', 'Personal Growth, Self-Improvement, pengembangan diri, nonfiksi, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94357/_Take_Command_C_1_4.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(331, '67822f6279bd51cee772b5a3', 'Ho Sit! Enak-enak: Jajanan dan Street Food Khas Pontianak', 'Vianney Lim', 'Culinary', 'Kelezatan kuliner Pontianak telah melegenda. Perpaduan cita rasa tionghoa dan melayu yang telah berlangsung berabad, menghasilkan suatu kekayaan kuliner yang tak ternilai. Yang pernah mencicipi akan rindu makanan dari Pontianak. Sedangkan mereka yang baru mendengar namanya, biasanya penasaran akan kelezatan yang melegenda ini. Resep-resep aneka makanan tersebut dihadirkan melalui seri buku Kuliner Pontianak karya Vianney Lim ini.Buku Hosit - Enak-enak Jajanan dan Street Food Populer Pontianak ini memuat resep aneka kue khas Pontianak dalam citarasa Tionghoa dan Melayu tradisional maupun modern, serta dessert terkenal. Semua resep jajanan populer dan street food, halal maupun non halal yang jadi favorit banyak orang. Sebut saja yang bercita rasa tionghoa seperti choipan/chai kue, guek piah (kue bulan), ou kue (kue talam talas), kaloci, pengkang, ou ie (bola keladi), luak kue, dan lain-lain. Bercita rasa melayu layaknya lempok durian, kue bingke, pisang goreng kipas khas Ponti, doko-doko berendam, putu songkok, hingga seri muka. Ada pula kue kekinian seperti tar susu, nastar, dan lapis legit. Dessert segar populer seperti ce hun tiau, lek tau ko/sari kacang hijau, tau suan /bubur gunting, hingga es bongko juga ada.Yang juga menarik dari buku ini adalah Vianney Lim menuliskan resepnya dengan detail, rinci, namun ringkas dan jelas. Banyak tipsnya pula. Pembaca tidak akan mengalami kesulitan dalam mempraktikkan resep-resep ini. Jadikan buku ini sebagai sarana menjajaki kuliner Pontianak, yang juga jadikan sumber inspirasi untuk usaha kuliner.', 'Rp 79,000', '64 pages', '17 January 2024', 'Masakan Rumahan, Culinary, masakan indonesia, buku masak, Jajanan', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94339/BBK_-_Ho_Sit!_Enak-enak_Aneka_Jajanan_Populer_Street_Food_Khas_Pontianak.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(332, '67822fa879bd51cee772b5c8', 'Tanpa Daya (Hopeless) (Cetak Ulang 2024)', 'Colleen Hoover', 'Romance', 'Terkadang mengetahui kebenaran lebih membuat putus asa ketimbang meyakini kebohongan…Itu yang Sky sadari begitu ia bertemu Dean Holder.Dikenal gara-gara reputasi buruknya di sekolah, hanya Holder yang sanggup membuat jantung Sky berdebar-debar. Membuat gadis tujuh belas tahun itu takut sekaligus terpesona pada sikapnya yang tak mudah ditebak. Tapi Holder sumber masalah. Apalagi sejak kehadiran cowok itu, kenangan lama yang lebih baik terpendam kembali menghantui.Masalahnya, Holder terus mendekat. Memaksa ingin mengenal Sky lebih jauh. Sky pun akhirnya menyerah. Menyambut cowok itu memasuki hidupnya. Hanya untuk mengetahui kebenaran, bahwa Holder tidak seperti yang dia katakan. Bahwa ada rahasia yang dia sembunyikan. Dan ketika rahasia itu tersingkap, hidup Sky tak pernah sama lagi.', 'Rp 119,000', '496 pages', '17 January 2024', 'Romance Novels, romance novel, romantis, novel roman, Roman, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94376/Fiksi_-_Hopeless.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(333, '67822f6479bd51cee772b5a4', 'Hociak! Enak-enak: Masakan Populer Khas Pontianak', 'Vianney Lim', 'Culinary', 'Kelezatan kuliner Pontianak telah melegenda. Perpaduan cita rasa Tionghoa dan Melayu yang telah berlangsung berabad, menghasilkan suatu kekayaan kuliner yang tak ternilai. Yang pernah mencicipi akan rindukan makanan dari Pontianak. Sedangkan mereka yang baru mendengar namanya, akan penasaran pada kelezatan yang melegenda ini. Resep-resep aneka makanan tersebut dihadirkan melalui seri buku Kuliner Pontianak karya Vianney Lim ini.Buku Hociak! Enak-enak Aneka Masakan Populer Khas Pontianak ini memuat resep aneka masakan khas Pontianak dalam citarasa Tionghoa dan Melayu tradisional maupun modern, yang halal maupun non halal. Semua resep masakan yang jadi favorit banyak orang, jadi semacam signature khas dari kota khatulistiwa ini.Sebut saja makanan yang bercita rasa Tionghoa seperti nasi campur komplit (koi peng) dan nasi tim ayam ala Pontianak, kwe cap yang segar, hekeng, nasi ketan gurih (cut bi peng), siomay babi, bakwan Pontianak, ang bun tou bak (daging babi masak merah), dan lain-lain. Bercita rasa Melayu layaknya gulai jantung pisang, batang keladi tumis pedas, ikan asam pedas, hingga selade Pontianak yang segar. Ada pula masakan seafood yang unik dan lezat seperti ikan hiu masak jahe atau udang asam garam.Yang juga menarik dari buku ini adalah Vianney Lim menuliskan resepnya dengan detail, rinci, namun ringkas dan jelas. Banyak tipsnya pula. Pembaca tidak akan mengalami kesulitan dalam mempraktikkan resep-resep ini. Jadikan buku ini menjajaki kuliner khas Pontianak, yang bisa juga jadikan umber inspirasi untuk usaha kuliner.', 'Rp 79,000', '64 pages', '17 January 2024', 'Masakan Rumahan, Chinese Food, Food, Food & Beverages, Culinary, masakan indonesia, buku masak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94340/BBK_-_Ho_Ciak!_Aneka_Makanan_Populer_Khas_Pontianak.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(334, '67822faa79bd51cee772b5c9', 'Awal Antara Kita (It Starts With Us)', 'Colleen Hoover', 'Romance', 'Usai bercerai dan mengakhiri ikatan pernikahan bertabur racun, Lily berusaha kembali menata kehidupannya sebagai orangtua tunggal. Ia mulai mengurus bisnis yang keteteran sembari menyesuaikan diri dengan ritme pengasuhan putrinya bersama sang mantan suami, Ryle Kincaid.Ketika Lily tanpa sengaja bertemu Atlas Corrigan setelah hampir dua tahun berpisah, ia begitu gembira. Kini, semesta seakan berpihak pada mereka. Ingatan tentang cinta pertama dan segala kenyamanan yang pernah ia rasakan bersama Atlas, membuat Lily langsung setuju saat pria itu mengajaknya berkencan  dan merengkuh kesempatan kedua sebagai dua orang dewasa.Sayangnya, kegembiraan Lily tak bertahan lama. Perceraian dengan Ryle ternyata tak serta-merta membuat Lily bebas menentukan jalan hidupnya. Bagaimanapun, Ryle ayah kandung putrinya, dan mereka  terikat seumur hidup sebagai orangtua. Bagaimana jika kehadiran Atlas justru membuat Ryle semakin posesif dan bertekad menyingkirkan pria itu dari kehidupan mantan istri dan putrinya?', 'Rp 109,000', '400 pages', '17 January 2024', 'Romance Novels, romance novel, romantis, novel roman, Roman, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94377/Fiksi_-_It_Starts_With_Us.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(335, '67822f9d79bd51cee772b5c2', 'Nothing Solid', 'Risma Ridha Annisa', 'Young Adult', 'Nugraha : “Bahu gue cedera di saat karier balap gue lagi bagus-bagusnya.”Tyas : “Beasiswa gue terancam dicabut. Tiba-tiba gue didatangin debt collector pinjol.”Gilang : “Seantero kampus iri sama gue. Gue dibilang keturunan sultan, good looking sejak dini. Padahal saat di rumah, gue dianggap sampah.”Felix : “Mimpi gue kuat, tujuan hidup gue jelas. Tapi kenapa penyakit sialan ini mendatangi gue?”Levi : “Kalo IPK gue anjlok, gue bakal dipaksa kawin sama cowok berpangkat pilihan Papa. Somebody help me!”Bagaimana kalau dua di antara kelima sahabat tersebut terlibat friendzone? Bagaimana pula kalau datang cowok baru, yang mengacaukan pertemanan mereka? Apakah persahabatan mereka akan tetap solid?', 'Rp 119,000', '368 pages', '10 January 2024', 'Remaja, novel remaja, Young Adult', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94370/Fiksi_-_Nothing_Solid.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(336, '67822f9379bd51cee772b5bd', 'The Great Gatsby', 'F. Scott Fitzgerald', 'English Classics', '"Let us learn to show our friendship for a man when he is alive and not after he is dead."', 'Rp 49,000', '208 pages', '10 January 2024', 'English Classic, Classic Novels, English Classics, Classic, Classic Novel, klasik, classics, Novel klasik', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94365/Fiksi_-_The_Great_Gatsby.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(337, '67822f9579bd51cee772b5be', 'Tales of The Jazz Age', 'F. Scott Fitzgerald', 'English Classics', '"Everybody\'s youth is a dream, a form of chemical madness."', 'Rp 79,000', '376 pages', '10 January 2024', 'English Classic, Classic Novels, English Classics, Classic, Classic Novel, classics', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94366/Fiksi_-_Tales_of_The_Jazz_Age.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(338, '67822fa479bd51cee772b5c6', 'Saat untuk Membunuh (A Time to Kill)', 'John Grisham', 'Mysteries & Thrillers', 'Ketika penduduk Clanton mendengar seorang pria kulit hitam membunuh dua orang kulit putih, gemparlah kota itu. Massa yang marah bertekad akan merusak, membakar, dan menghancurkan apa pun dan siapa pun yang menentang mereka.Hanya pengacara muda Jake Brigance yang berani membela Carl Lee Hailey, si terdakwa. Di tengah kerusuhan rasial yang melanda, ia bertekad akan memenangkan kasus ini—kasus yang merupakan taruhan bagi kariernya, sekaligus mengancam keselamatan dirinya dan keluarganya.', 'Rp 189,000', '748 pages', '10 January 2024', 'Thriller, Mystery & Thrillers, Thrillers, novel thriller', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94374/Fiksi_-_A_Time_to_Kill.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(339, '67822f9979bd51cee772b5c0', 'Tales of Terror and Mystery', 'Sir Arthur Conan Doyle', 'English Classics', '"When the impossible has been eliminated the residuum, however improbable, must contain the truth."', 'Rp 59,000', '304 pages', '10 January 2024', 'English Classic, Classic Novels, English Classics, Classic, Classic Novel, classics', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94368/Fiksi_-_Tales_of_Terror_and_Mystery.jpg', '2026-02-17 07:11:24', '2026-02-17 07:11:24'),
	(341, '67822f8a79bd51cee772b5b8', 'Ratu Adil', 'Sindhunata', 'Social Sciences,', 'Ratu Adil, Ramalan Jayabaya & Sejarah Perlawanan Wong Cilik adalah kisah pergulatan dan perlawanan wong cilik. Karya monumental ini, dengan merujuk ke berbagai literatur penting, mampu menerobos dan menguak dalam kepingan-kepingan sejarah yang terabaikan di Jawa pada abad ke-19 hingga awal abad ke-20.Kepingan-kepingan sejarah itu juga ditampilkan dalam sapuan kuas Budi Ubrux. Lebih dari lima puluh lukisan yang menggambarkan perlawanan nasib wong cilik mewarnai buku ini dengan memukau.Ratu Adil, Ramalan Jayabaya & Sejarah Perlawanan Wong Cilik adalah sebuah persembahan terhadap kekayaan hati yang terpendam dalam kebisuan wong cilik.Ketika ditanya siapakah Ratu Adil, jagonya berkokok memanggil matahari di pagi hari lalu pergi mengais nasi. Mana yang lebih dahulu terbangun, jagonya atau matahari tiada ia peduli. Ia hanya mau orang mengerti, harapannya adalah matahari, dan jagonya adalah penderitaannya sendiri. Ia percaya Ratu Adilnya tak lain hanyalah manunggalnya penderitaan dan harapan laksana manunggaling kawula lan Gusti, yang membangkitkannya untuk melawan nasib ketika kebebasannya dibelenggu derita yang tak tertanggungkan lagi.', 'Rp 299,000', '678 pages', '10 January 2024', 'Sindhunata, Social Science, nonfiksi, Social Sciences', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94360/Ratu_Adil.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(342, '6782308579bd51cee772b63f', 'Buku Panduan Matematika Terapan (Sampul 2024)', 'Triskaidekaman', 'Novel', 'Pertanyaan P-NP (sesuatu yang bisa diperhitungkan-sesuatu yang tidak bisa diperhitungkan) muncul setelah Prima didatangi oleh hantu yang mengajarinya cara berhitung dan berbagai teori matematika di dalam mimpi. Teka-teki itu semakin mengusiknya ketika ia bertemu Tarsa—si cerdas yang juga memiliki pertanyaan sama tentang P-NP. Namun, meski telah mencurahkan seluruh hidupnya, Prima tak juga mampu menemukan jawabannya. Tentu. Karena, siapa pula manusia di dunia ini yang bisa menjawab kapan ia akan dimatikan?', 'Rp 119,000', '366 pages', '03 January 2024', 'novel sastra, sastra, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94495/Buku_panduan_mtk_terapan_2024.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(343, '67822f5e79bd51cee772b5a1', 'Disney 100 Years of Wonder: Kumpulan Dongeng Terbaik', 'Disney', 'Picture Books', '100 Tahun Keajaiban!Buku ini berisi kumpulan dongeng penuh keajaiban, dari kisah klasik Snow White dan Lion King sampai Finding Nemo, Encanto, serta Frozen, pembaca dewasa dan muda akan bertualang ke dunia ajaib bersama dongeng-dongeng yang tak lekang oleh waktu.', 'Rp 279,000', '304 pages', '03 January 2024', 'Pictures Book, disney, picture books, Picture book', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94337/Anak---100-Years-of-Wonder.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(347, '67822f8179bd51cee772b5b3', 'Selangkah di Belakang Mbak Tutut (Buku Kedua)', 'Donna Sita Indria,', 'Biography', 'Ada suatu momen jenaka di Monako pada 1993. Masa itu kedua kalinya Mbak Tutut terpilih sebagai Presiden Federasi Internasional Organisasi Donor Darah (FIODS) yang sebagian besar anggotanya berasal dari negara-negara Eropa. “Karena mobil operasional cuma satu maka usai meeting FIODS kami menunggu taksi di pinggir jalan. Berhenti sebuah mobil mewah, pengendaranya anak salah seorang pejabat tinggi Indonesia. Ia turun dan menawarkan tumpangan namun Mbak Tutut menolak dengan halus, mengatakan bahwa ia bersama kami semua. Setelah mobil itu berlalu seorang teman saya spontan bercanda, “Ini yang anak presiden yang mana... yang anak pembantunya presiden yang mana ya?” cerita Judith J. Dipodiputro.Setelah Presiden Soeharto menyatakan berhenti pada 1998, Mbak Tutut juga harus mengalami hari-hari yang tidak biasa.“Suatu malam di tahun 1999 kami sedang pengajian, datang orang-orang berseragam dari suatu instansi pemerintah, katanya hendak memeriksa rumah Mbak Tutut. Mereka tanpa senyum walau juga tidak membentak-bentak. Mungkin kalau orang lain akan tersinggung dan bertanya, “Bapak mau ngapain? Saya tidak mengundang kenapa datang?” Tetapi Mbak Tutut senyum, “Silakan masuk Pak, silakan duduk.” Lantas ia berikan minuman. Setelah itu, “Silakan Bapak periksa.” Itu Mbak Tutut seperti itu. Mereka yang semula tanpa senyum berubah jadi respek. Buat saya itu luar biasa,” cerita guru pengajiannya, KH. Najamuddin Siddiq.', 'Rp 291,000', '424 pages', '27 December 2023', 'bio, biografi, Biography, Politics, Politic, Busines, Business, Business Management', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94355/Hum_-_Selangkah_di_Belakang_Mbak_Tutut_Buku_2.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(348, '67822f8679bd51cee772b5b6', 'Knowledge Management Capability', 'Elidjen', 'Business Management & Leadership', 'Effective knowledge management dapat dibangun dari perspektif organization capability. Perspektif ini menunjukkan bahwa Knowledge Management Capability (KMC) dapat dibangun dari Knowledge Infrastructure Capabilty dan Knowledge Process Capability. KMC adalah kapabilitas organisasi yang sangat penting dan merupakan prasyarat untuk manajemen pengetahuan yang efektif guna mewujudkan organisasi yang berbasis pada pengetahuan (knowledge based-organization) yang tangguh. Organisasi ini dapat membangun dan mempertahankan keunggulan bersaing yang berkelanjutan.Selain membahas tentang strategi, buku ini dilengkapi dengan KMC assessment tools, yang dapat diakses melalui link atau QR code, guna mendapatkan gambaran lengkap KMC organisasi melalui KMC radar diagaram. Karya ini dapat menjadi referensi untuk membangun atau mengembangkan a knowledge-based organization yang tangguh.', 'Rp 155,000', '133 pages', '27 December 2023', 'Business, Business Management', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94358/Hum_-_Knowledge_Management.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(351, '67822f8879bd51cee772b5b7', 'Hijab and Make-up for the Brides', 'Nia Hernawati', 'Fashion & Beauty', 'Tata rias dan hijab pengantin muslimah di Indonesia begitu “hidup” dan rancak. Para make-up artist dan hijab stylist Indonesia sangat kreatif dalam memadukan tata rias, hijab, dan aksesoris hingga tercipta tampilan akhir pengantin yang memukau. Nia Hernawati dari Nia Wedding adalah salah satu make-up artist yang mampu menghadirkan riasan secantik itu, dengan tata hijab yang serasi. Tak heran, ribuan pengantin telah mempercayakan tata rias mereka kepadanya. Dia juga menjadi rujukan para MUA dalam belajar merias maupun membuat kreasi hijab yang elegan dan indah.Dalam buku ini Nia Hernawati berbagi inspirasi dan kreasi tata rias pengantin dan paduan hijab yang serasi. Nia menghadirkan wajah-wajah pengantin dalam berbagai bentuk wajah, warna kulit, bentuk mata, dan sebagainya. Tujuannya adalah agar menginspirasi para MUA dan calon pengantin bahwa dengan riasan yang tepat dan hijab yang sesuai, semua pengantin akan terlihat cantik memesona di hari bahagianya.Kreasi dalam buku meliputi style modifikasi pengantin Nusantara maupun elegan modern. Di dalamnya disajikan foto-foto cantik setiap step merias, menata hijab, dan memasang aksesoris dalam petunjuk yang ringkas namun rinci. Buku ini akan mengajak para MUA berkreasi dan menciptakan riasan terbaik bagi para pengantin yang mereka tangani.', 'Rp 169,000', '108 pages', '27 December 2023', 'Tata Rias, Beauty', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94359/BBK_-_Make_Up_and_Hijab_for_The_Brides.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(353, '67822f7f79bd51cee772b5b2', 'Selangkah di Belakang Mbak Tutut (Buku Pertama)', 'Donna Sita Indria,', 'Biography', 'Putri Presiden Soeharto yang akrab dipanggil “Mbak Tutut” ini termasuk yang melaksanakan panggilan jiwanya melintasi tataran internasional. Seperti diungkapkan Fidel V. Ramos, Presiden Filipina 1992-1998 ketika ia meminta Mbak Tutut membangun layang tol pertama Filipina di ibukota Manila. “Waktu itu pemerintah Filipina tidak bisa mendapatkan investor karena masih berutang kepada IMF, maka Ibu Tutut mengambil alih tanggung jawab pendanaan. November 1994 saya datang ke New York menyaksikan Ibu Tutut menandatangani perjanjian pendanaan antara perusahaannya Citra Lamtoro Gung Persada dengan American International Group’s Asian Infrastructure Fund selaku investor untuk membiayai pembangunan Metro Manila Skyway Tahap I.”Banyak hal luar biasa yang dilakukan Mbak Tutut justru kita ketahui dari orang lain, seperti Sosrobahu - teknologi besutan bangsa sendiri yang dengan yakin dipilih Mbak Tutut menjadi tulang punggung jalan layang tol pertama di Jakarta dan Manila. “Seandainya waktu itu Mbak Tutut tidak memutuskan menggunakan Sosrabahu, maka teknologi itu tidak akan pernah muncul,” kata Ir. Tjokorda Raka Sukawati, penemunya.“Saya melihat banyak tugas strategis dipercayakan Pak Harto kepada Mbak Tutut,” kata Try Sutrisno, Wakil Presiden RI 1993-1998. Sementara Tun Dr. Mahathir Mohamad, Perdana Menteri Malaysia 1982-2003 dan 2018-2020 mengatakan, “Ada hal yang menarik darinya bahwa sehingga sekarang kita tidak pernah mendengar cerita-cerita yang tidak baik dari Ibu Tutut. Hingga di saat ini ia menghormati presiden yang ada. Tidak ada bercandaan, olok-olok atau menjelek-jelekkan pemimpin Indonesia yang sedang berkuasa.”', 'Rp 338,000', '536 pages', '27 December 2023', 'biografi, bio, Biography, Politic, Politics, Busines, Business, Business Management', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94354/Hum_-_Selangkah_di_Belakang_Mbak_Tutut.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(356, '67822f7479bd51cee772b5ac', 'Kenal Diri, Sadar Diri, Tahu Diri', 'Suhana Lim', 'Self-Improvement', 'Kenal Diri, Sadar Diri, Tahu Diri adalah esensi dari semua hal yang selama berpuluh-puluh tahun Suhana Lim serap, cerna, rangkum, dan satukan ke dalam buku. Buku ini adalah inti sari perjalanan kehidupan secara umum, terutama kiprah serta pengalaman Suhana Lim di jalur feng shui.Tulisan Suhana yang penuh warna serta gaya bahasanya yang penuh dinamika membuat buku ini tidak saja bermanfaat, tetapi juga menarik dan seru bagi siapa pun yang ingin mendapatkan tambahan esensi, pengalaman, dan wawasan dari kiprah Suhana Lim di jalurfeng shui.Buku kedelapan Suhana Lim ini juga memaparkan Thick Black Theory (厚黑學), yakni ilmu pengetahuan Tiongkok kuno yang sangat langka yang bermanfaat untuk mengoptimalkan wawasan serta kepribadian diri. Buku ini juga berisi informasi mengenai WISE, sebuahorganisasi sosial kemasyarakatan yang lahir berkat hikmah dari pandemi. Dalam waktu singkat, WISE berhasil mendapatkan rekor MURI dan mendapatkan dukungan dari Drs. Purnomo, Hans Wibowo Sianturi, dan Gunawan Widjaja. Ketiganya adalah individu-individuhebat, berprestasi, dan sukses dalam bidang masing-masing.', 'Rp 125,000', '201 pages', '27 December 2023', 'Self Improvement, Self-Improvement, Self-Acceptance, Self Transformation', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94348/Hum_-_Kenal_Diri_Sadar_Diri_Tahu_Diri.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(357, '67822f7d79bd51cee772b5b1', 'Bukan Pengikutmu yang Sempurna', 'Annisa Ihsani', 'Young Adult', 'Alex selalu bersyukur dia terlahir dan tumbuh besar di Dingley, dalam komunitas yang dipimpin oleh Paman Manwel. Memang benar mereka punya banyak peraturan, tetapi Alex percaya semuanya dibuat untuk kebaikan mereka sendiri. Bagaimanapun, Paman Manwel hanya ingin melindungi para pengikutnya dari dunia luar yang berbahaya.Namun, usaha Alex untuk senantiasa patuh dan menghindari masalah sering kali terhalang oleh Sophie. Adik kembarnya itu tak henti-hentinya membangkang dan melanggar peraturan. Tak jarang Alex terpaksa berbohong demi melindungi Sophie. Sampai suatu hari Sophie tertangkap basah melanggar peraturan dan Alex tidak bisa melindunginya lagi.Konsekuensi yang mengikuti tindakan Sophie membuat Alex mempertanyakan semua yang diyakininya. Satu per satu kejadian mulaimengusik pikirannya, dan untuk pertama kalinya, Alex meragukan ajaran Paman Manwel. Bagaimana jika segala keyakinan yang dianutnya selama ini salah? Apakah masih ada tempat untuknya di Dingley? Atau haruskah dia meninggalkan semua yang dikenalnya sepanjang hidupnya?', 'Rp 79,000', '248 pages', '27 December 2023', 'Literatures, lokal, Novel, novel remaja, Young Adult', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94353/Fiksi_-_Bukan_Pengikutmu_yang_Sempurna.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(358, '6782300179bd51cee772b5f8', 'Selling Easily and Smartly (2023)', 'Hingdranata Nikolay', 'Business Management & Leadership', 'Semua orang bisa menjual. Dan semua bisa belajar MENJUAL DENGAN MUDAH DAN CERDAS.Menjual adalah sebuah skill. Skill yang bisa dipelajari dan dimahiri. Buku ini ditulis untuk siapa pun yang ingin belajar dan meningkatkan pengetahuan dan skill untuk bisa menjual. Entah Anda menjual produk, jasa, atau ide, entah Anda berada di tingkat nol, pemula, atau mahir, entah Anda bekerja di profesi menjual atau tidak, berbagai prinsip dan teknik yang ada di buku ini bisa memberi Anda tambahan sumber daya untuk membantu Anda menjual dengan mudah dan cerdas."Hingdranata Nikolay has written the comprehensive book on selling with NLP. Hing is one of the few who actually understands and then clearly explains how to integrate NLP into sales situations. This book will help you sell more, faster." (Hingdranata Nikolay telah menulis sebuah buku yang lengkap tentang menjual dengan NLP. Hing adalah satu dari sekelompok kecil orang yang benar-benar memahaminya dan dengan jelas mengulas bagaimana mengintegrasikan NLP ke dalam situasi penjualan. Buku ini akan membantu Anda menjual lebih banyak, lebih cepat.) Kevin Hogan, Penulis buku best seller PSYCHOLOGY OF PERSUASIONHINGDRANATA NIKOLAY adalah orang pertama dari Indonesia dan Asia Tenggara yang terpilih dan dianugerahi gelar kehormatan Licensed Master Trainer of NLP langsung oleh Dr. Richard Bandler (co-creator of NLP) dan The Society of NLP, USA. la adalah pendiri, CEO dan Master Trainer dari NLP INDONESIA dan INSPIRASI INDONESIA Hingdranata mempunyai pengalaman lebih dari 20 tahun di dunia bisnis praktis, dari penjualan, manajemen dan pengembangan SDM, sampai manajemen tertinggi, la adalah pelopor pengajaran NLP klasik dan terkini dari Dr. Richard Bandler di Indonesia, la memiliki kepakaran aplikasi dan pendalaman NLP selama lebih dari 20 tahun.', 'Rp 126,000', '380 pages', '13 December 2023', 'Management, Business Management, Bussines & Management, nonfiksi, Manajemen', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94424/623203022.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(359, '67822f7079bd51cee772b5aa', 'Seorang Pria yang Melalui Duka dengan Mencuci Piring', 'dr. Andreas Kurniawan, Sp.KJ', 'Self-Improvement,', '“Buku ini akan membantu menuntun kita di proses penerimaan dan perubahan agar arahnya tidak menuju keterpurukan, melainkan menuju pribadi yang lebih kuat dalam menjalani kehidupan dan menikmatinya seapa-adanya.” —Kunto Aji, MusisiKetika menyambut pasien yang sedang berduka, seorang psikiater akan menggali keilmuan yang dimiliki. Dia akan mengulik semua teori duka yang pernah dipelajari di masa kuliah dulu dan mengingat pengalaman dari pasien-pasien sebelumnya. Kemudian, dia menyintesis itu untuk membantu pasien yang sedang berduka di hadapannya.Tapi, ketika Andreas—seorang psikiater—kehilangan anaknya, dia melakukan hal yang berbeda. Dia melemparkan semua teori tersebut ke luar jendela dan memutuskan untuk mencari makna tentang mengapa ini semua terjadi. Dalam pengalamannya, dia menemukan bahwa duka bisa dilalui dengan mencuci piring kotor yang menumpuk di dapur.Buku ini adalah proses Andreas memaknai kehilangan besar dalam hidupnya. Diceritakan santai dengan tambahan sedikit bumbu humor gelap, buku ini memuat panduan bermanfaat yang langsung bisa diaplikasikan dalam hidup, seperti: “Tutorial Mencuci Piring”, “Tutorial Menyusun Puzzle”, dan tentunya “Tutorial Menerima Kematian Seorang Anak”.“Hampir semua orang mempertanyakan: apa hubungannya antara duka dan mencuci piring? Jawaban saya adalah duka itu seperti mencuci piring, tidak ada orang yang mau melakukannya, tapi pada akhirnya seseorang perlu melakukannya.”dr. Andreas Kurniawan, SP.KJ (@dr.ndreamon di Instagram dan @ndreamon di X) adalah seorang psikiater lulusan Universitas Indonesia yang di media sosial dikenal sebagai “psikiater yang suka bercanda”. Pengalaman kehilangan ayah dan anaknya membuat dr. Andreas menyelami psikoterapi untuk kedukaan dan kehilangan. Buku ini adalah sebuah renungan yang menjadi caranya untuk memaknai kehilangan.', 'Rp 95,000', '208 pages', '13 December 2023', 'Self Transformation, buku pengembangan diri, Self-Improvement, Self-Acceptance, pengembangan diri, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94346/6232210651.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(360, '67822fa079bd51cee772b5c4', 'Manajemen Logistik Tol Laut Indonesia', 'Ricky Virona Martono', 'Business Management & Leadership', 'Manajemen logistik yang efisien akan dapat memaksimalkan kepuasan pelanggan dan mengurangi biaya, sehingga meningkatkan profit perusahaan. Buku ini memaparkansecara komprehensif manajemen logistik sebagai sebuah sistem yang terintegrasi, mulai dari persiapan bahan mentah, pengolahan bahan mentah menjadi barang jadi,pengiriman, sampai barang jadi tersebut diterima oleh konsumen.Di sini Anda akan mempelajari manajemen rantai pasok (supply chain management) yang menjadi payung manajemen logistik, konsep logistik, serta bauran distribusisecara mendetail. Tidak hanya itu, penulis juga membahas masalah-masalah utama logistik di Indonesia serta solusi pemerintah untuk menurunkan biaya logistik nasionalmelalui konsep Tol Laut Indonesia.Buku ini sangat bermanfaat sebagai referensi bagi praktisi di perusahaan manufaktur, ritel, distributor maupun akademisi dan mahasiswa di perguruan tinggi, serta siapa pun yang menggeluti bidang logistik.', 'Rp 138,000', '254 pages', '06 December 2023', 'Busines, Business, Business Management', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94372/Hum_-_Manajemen_Logistik_Tol_Laut_Indonesia.jpg', '2026-02-17 07:12:57', '2026-02-17 07:12:57'),
	(361, '67822e0579bd51cee772b4e8', 'Wanita Pemalu di Pesta (Shy Innocent in the Spotlight)', 'Melanie Milburne', 'Harlequin', 'Elspeth dan Elodie Campbell memang kembar identik yang sulit sekali dibedakan dari segi fisik, tapi kepribadian mereka berdua benar-benar bertolak belakang. Elspeth yang pemalu dan pendiam bekerja sebagai petugas arsip perpustakaan, sementara Elodie yang ceria dan gampang bergaul adalah model pakaian dalam yang sudah terkenal di banyak negara. Semua masalah dimulai ketika Elodie mengusulkan agar mereka bertukar tempat.Elspeth terpaksa berpura-pura jadi kembarannya dan menghadiri pernikahan seorang sosialita. Awalnya semua berjalan lancar, sampai Mack MacDiarmid yang gagah dan tampan muncul dan mulai mengendus sesuatu yang tidak wajar. Lelaki itu terlalu cerdas untuk dibodohi dan Elspeth diam-diam mulai tertarik. Tapi, apakah Mack juga menyukai dirinya yang sebenarnya? Bagaimana Elspeth bisa terus berpura-pura ketika lelaki rupawan itu membawanya pergi ke tempat terpencil, jauh dari hiruk-pikuk pesta?', 'Rp 69,000', '238 pages', '28 June 2023', 'Romance, romance novel, Romance Novels, Harlequin, Novel dewasa', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94152/Fiksi_-_Wanita_Pemalu_di_Pesta.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(362, '67822e7179bd51cee772b522', 'MetroPop: Salju di Pantai, Cinta di Scheveningen', 'Janita Jaya', 'MetroPop', '“Seperti salju di pantai… Sangat jarang terjadi, sehingga semua orang menatapnya dengan keheranan, dipenuhi pertanyaan dalam benak mereka.”Nadia baru tiba di Den Haag untuk melanjutkan kuliah bachelor double degree ketika bertemu Anjani, mantan kakak kelasnya yang juga melanjutkan studi master di kampus yang sama. Henri- Philippe, mahasiswa asal Prancis yang tinggal satu flat dengan Nadia, ternyata juga teman Anjani. Dengan cepat ketiganya menjadi akrab. Henri-Philippe dan Anjani dengan senang hati mengenalkan pada Nadia seluk-beluk studi dan kehidupan mahasiswa di Eropa.Di tengah dinamika studi, Nadia kedapatan menjalin hubungan dengan salah satu dosen di kampusnya. Terkuaknya informasi ini ke kalangan civitas academica di universitas membuat Nadia menanggung malu karena dianggap melanggar peraturan.Bocornya skandal ini memengaruhi persahabatan ketiga orang tersebut. Kini, pertemanan Nadia, Anjani, dan Henri-Philippe tengah diuji dan kehormatan menjadi taruhannya. Hidup terus bergulir, tetapi ketiganya harus memilih apakah cinta lebih berharga daripada persahabatan dan kehormatan....', 'Rp 99,000', '312 pages', '28 June 2023', 'Novel, Metropop, Fiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94210/623171002.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(363, '67822e0e79bd51cee772b4ed', 'Menulis Karya Ilmiah: Artikel, Skripsi, Tesis, dan Disertasi', 'Prof. Etty Indriati, Ph.D', 'Reference & Dictionary', 'Menulis karya ilmiah pada dasarnya adalah cara ilmuwan berkomunikasi satu sama lain. Komunikasi yang baik bisa membuat yang diajak berkomunikasi mengerti apa yang dimaksud oleh komunikator. Sama halnya penulis yang baik harus bisa membuat pembaca mengerti apa yang dimaksudkannya tanpa arti ganda. Dengan demikian, penulis harus lebih dahulu memahami apa yang akan disampaikan kepada pembaca sebelum menuangkan gagasannya ke atas kertas.Buku Menulis Karya Ilmiah ini disusun untuk membantu pembaca menyampaikan ide atau gagasan dalam bentuk tulisan ilmiah. Materi yang dibahas dalam buku ini meliputi: langkah-langkah menyiapkan bahan tulisan, cara menyusun kerangka dan isi tulisan, penulisan kalimat dan paragraf yang efektif serta koheren, tata cara penulisan tabel dan penyajian gambar, serta latihan-latihan yang mendorong pembaca masuk ke dalam praktik penulisan.Selain itu, buku ini juga mengulas secara ringkas cara pembuatan bahan presentasi lisan dan poster untuk seminar ilmiah, karena keduanya merupakan bagian integral dari karya ilmiah itu sendiri.', 'Rp 119,000', '188 pages', '28 June 2023', 'Reference, humaniora, nonfiksi, kamus, Dictionary, tata bahasa, buku bahasa', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94157/623217003.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(364, '67822de979bd51cee772b4d9', 'Cinta Kala Fajar (Another Dawn)', 'Sandra Brown', 'Romance', 'Tepat di hari pernikahannya, Banner Coleman baru tahu sang calon suami mengkhianatinya. Namun, alih-alih meratapi kegagalan pernikahannya, Banner justru melakukan sesuatu yang berpotensi menimbulkan skandal.Ketika Banner mendekatinya, Jake Langston tahu wanita muda itu hanya mencari penghiburan. Namun, saat menghadapi Banner yang cantik dan bukan lagi gadis ingusan, pertahanan Jake pun runtuh.Karena sadar peristiwa yang tidak seharusnya terjadi itu dapat menghancurkan persahabatan keluarga mereka, Jake dan Banner menyimpan hal tersebut rapat-rapat. Hanya saja, keduanya tak berdaya menghentikan ketertarikan yang tumbuh di antara mereka. Akan tetapi, bukan hanya mereka yang menyimpan rahasia. Dan rahasia yang lama terpendam itu akan terbongkar, dipicu oleh hasrat untuk balas dendam…', 'Rp 129,000', '568 pages', '28 June 2023', 'novel lama, novel roman, Novel dewasa, Thrilers Novel, Novel', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94137/623184003.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(366, '67822e1879bd51cee772b4f2', 'Malam Seribu Jahanam', 'Intan Paramaditha', 'Literary ,', 'Revolusi selalu dimulai oleh saudara tiri buruk rupa. Entah apa yang mengendap di kepala adik kita, yang tak buruk rupa maupun revolusioner, saat ia melilitkan bom di pinggang dan meledakkan tubuhnya.Di tahun 1991, Hajjah Victoria binti Haji Tjek Sun meramal ketiga cucunya: satu cucu berkelana, satu menjaga, dan satu lagi menjadi pengantin. Ketika salah seorang berkhianat, dara yang tersisa terperangkap dan menoleh ke belakang, menelusuri dapur berisi kuali-kuali raksasa dan sumur terlarang di Rumah Victoria (kata orang jalan menuju rumah Nenek tak berujung), berhadapan dengan rahasia dan mimpi-mimpi yang macet di tengah jalan. Saat perjalanan dan kitab suci tidak lagi memberi perlindungan, dara yang lain hadir. Ia tak diundang dan menuntut penjelasan.Malam Seribu Jahanam adalah novel kedua dari Intan Paramaditha. Mengolah kisah-kisah Islami dan mitos nusantara, novel ini merupakan dongeng gelap tentang sesal, malu, dan hantu—sebuah renungan tentang praktik beragama, retakan dan reruntuhan kelas menengah, serta rapuhnya persaudaraan.***Tentang karya-karya Intan Paramaditha“Referensi Paramaditha secara cerdas meramu mitologi, dongeng, legenda dan budaya populer Indonesia… dengan lihai menjungkirbalikkan nilai-nilai patriarki yang mengakar dalam kisah-kisah tergelap budaya kita.” —The Guardian“… memintal yang absurd, gothic, dan menubuh.” —Strange Horizons', 'Rp 139,000', '364 pages', '28 June 2023', 'Horror, Novel, novel sastra, novel misteri', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94162/623202026.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(367, '678113d31e0f1c11c617c9fc', 'Contagious: Rahasia di Balik Produk dan Gagasan yang Viral', 'Jonah Berger', 'Business Management & Leadership', 'APA YANG MENJADIKAN SESUATU VIRAL?Kalau menurut Anda iklan, coba pikir lagi. Orang tidak mendengarkan iklan; mereka mendengarkan teman. Namun, kenapa orang bicara lebih banyak tentang produk dan gagasan tertentu dibanding yang lain? Kenapa sebagian cerita dan rumor lebih cepat menyebar? Dan, apa yang menjadikan konten online viral?Jonah Berger mengungkapkan ilmu rahasia di balik getok tular dan transmisi sosial. Anda bisa menemukan enam prinsip dasar yang berkontribusi pada semua hal yang menjadi viral, seperti bagaimana steakhouse yang mewah mendapat popularitas lewat cheese-steak biasa, mengapa iklan antinarkoba bisa jadi malah meningkatkan penggunaan narkoba, dan mengapa lebih dari 200 juta orang berbagi video tentang produk biasa yang tidak istimewa: blender.Entah Anda manajer di perusahaan besar, pemilik usaha kecil yang berusaha membuat produk Anda makin dikenal, politisi yang membutuhkan suara dari pemilih, atau petugas kesehatan yang berusaha mengampanyekan suatu program, buku ini akan menunjukkan kepada Anda cara membuat produk atau gagasan Anda tersimpan di benak orang.• • •“Mengapa beberapa ide bisa menyebar dengan cepat dalam satu malam sedangkan yang lain menghilang? Jonah Berger tahu jawabannya, dan berkat Contagious, sekarang kita juga tahu.” —Charles Duhigg, penulis The Power of Habit“Jonah Berger itu kreatif dan bijaksana, sekaligus berani dan suka bermain-main.” —Dan Ariely, penulis Predictably Irrational“Contagious berisi fakta dan wawasan yang menarik—dan berlawanan dengan intuisi.” —Boston Globe“Jika ada tombol ‘like’ untuk buku ini, Anda pasti sudah mengekliknya.” —Los Angeles Times', 'Rp 120,000', '308 pages', '28 June 2023', 'Management, nonfiksi, buku bisnis, Bisnis, marketing, Business, Business Management', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93950/623203001.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(368, '678113d61e0f1c11c617c9fd', 'The Catalyst: Cara Mengubah Pikiran Siapa pun', 'Jonah Berger', 'Business Management & Leadership', '"Saya bersyukur menjadi salah satu dari banyak orang yang belajar dari guru besar ini." —Jim Collins, penulis Good to GreatSetiap orang memiliki sesuatu yang ingin mereka ubah. Pemasar ingin mengubah pikiran pelanggan dan pemimpin ingin mengubah organisasi. Perusahaan rintisan ingin mengubah industri dan organisasi nirlaba ingin mengubah dunia. Namun, perubahan itu sulit. Sering kali, kita membujuk dan menekan dan mendorong, tetapi tidak ada yang bergerak. Mungkinkah ada cara yang lebih baik?Buku ini mengambil pendekatan berbeda. Agen perubahan yang sukses tahu bahwa ini bukan tentang mendorong lebih keras, atau memberikan lebih banyak informasi; ini tentang menjadi katalisator. Katalisator menghilangkan hambatan dan mengurangi hambatan untuk berubah. Alih-alih bertanya, "Bagaimana saya bisa mengubah pikiran seseorang?", mereka mengajukan pertanyaan berbeda: "Mengapa mereka belum berubah? Apa yang menghentikan mereka?"Buku ini dirancang bagi siapa saja yang ingin mengatalisasi perubahan. Buku ini menawarkan cara berpikir yang kuat dan berbagai teknik yang dapat menghasilkan hasil yang luar biasa. Entah itu mencoba mengubah satu orang, mengubah organisasi, atau mengubah cara seluruh industri menjalankan bisnis, buku ini akan mengajari Anda cara menjadi katalisator.• • •"Bacaan yang menarik dan perangkat yang ampuh untuk membantu kita mengubah pikiran, organisasi, dan bahkan dunia." —Arianna Huffington, pendiri dan CEO, Thrive Global"Semua komunikator bisa mendapatkan manfaat dari kumpulan kebijaksanaan ini." —Robert Cialdini, penulis Pre-suasion"Ini buku bisnis langka yang rasanya kita ingin segera selesaikan baca." —Daniel Pink, penulis To Sell Is Human', 'Rp 120,000', '306 pages', '28 June 2023', 'Management, nonfiksi, Business, Business Management, marketing, buku bisnis, Bisnis', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93951/623203002.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(369, '67822e6d79bd51cee772b520', 'Rilakkuma Meets Honey - Buku Stiker & Aktivitas', 'San-X', 'Activity Books', 'Ayo jadi lebih pintar dan kreatif bersama Rilakkuma dan teman-teman. Dalam buku ini kau bisa menempelkan stiker, mencari rute, mencari perbedaan, mewarnai, dan berbagai aktivitas lainnya. Seru, kan?', 'Rp 69,000', '24 pages', '28 June 2023', 'Buku anak, buku anak gramedia, Children Book, Children Books, Childrens Books, Children, Activity Book, Mewarnai', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94208/623120003.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(370, '67822e6f79bd51cee772b521', 'Rilakkuma Aloha - Buku Mewarnai', 'San-X', 'Activity Books', 'Aloha! Rilakkuma sedang liburan nih. Ayo ikutan bersantai dan bergembira bersama Rilakkuma, Korilakkuma, dan Kiiroitori. Warnai gambar-gambar seru dalam buku ini dan mainkan stikernya!', 'Rp 49,000', '24 pages', '28 June 2023', 'Buku anak, buku anak gramedia, Anak, Activity Books, Activity Book, Aktivitas, Mewarnai', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94209/623120004.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(371, '67822dd579bd51cee772b4ce', 'Masa Depan Industri Televisi', 'Irwan Setyawan', 'Media & Communication', 'Dalam abad 21 ini, generasi milenial dan generasi Z tampaknya tidak tertarik menonton televisi. Mereka lebih menikmati tontonan di Youtube atau Netflix melalui layar ponsel atau laptop. Tak hanya itu, mereka juga mendengarkan musik, mencari informasi, membaca berita, dan sibuk bermedia sosial melalui smartphone. Singkatnya, nyaris semua aktivitas kehidupan anak muda menggunakan sarana internet lewat aneka gawai terbaru.Perkembangan teknologi informasi serta kehadiran internet tak pelak memengaruhi industri media penyiaran. Kejayaan bisnis televisi meredup. Di Amerika Serikat, bisnis industri ini menurun sejak 2016. Bahkan pada 2017, belanja iklan digital di sejumlah negara sudah mengalahkan iklan televisi. Bagaimana masa depan industri televisi?Irwan Setyawan menangkap dan mencatat fenomena perubahan yang begitu cepat dalam industri televisi dan internet. Di sini ia mengupas bagaimana pengelola media menghadapi perubahan yang terjadi, terutama menghadapi era teknologi informasi dan disrupsi dalam industri media. Kombinasi pengamatan, pengalaman, serta gagasannya sangat bermanfaat sebagai rujukan mereka yang tertarik mengkaji media dan televisi, juga merupakan kontribusi yang penting bagi perkembangan konsep dan industri media dan televisi di tanah air.', 'Rp 135,000', '194 pages', '28 June 2023', 'humaniora, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94126/Hum_-_Masa_Depan_Televisi.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(372, '67822de479bd51cee772b4d6', 'Rampokan (Cetak Ulang 2023)', 'Peter Van Dongen', 'Graphic Novel', '1946.Indonesia baru saja merdeka. Ratusan relawan dari Belanda kembali ke Indonesia dengan semangat patriotisme untuk mempertahankan harga diri bangsa. Dua di antaranya adalah Johan Knevel dan Erik Verhagen, yang lahir di Hindia Belanda dan pulang ke negeri itu dengan benak penuh angan-angan dan ilusi.Johan memimpikan kembalinya “tempo doeloe”, surga masa kecil, dan Ninih, pengasuhnya. Namun Erik lalu tenggelam ditelan ombak dan Johan dihantui rasa bersalah.Ia lantas memakai identitas Erik dan pergi ke Makassar, ke tanah kelahirannya. Karena Erik komunis, tentara Belanda pun memburunya.Penceritaan roman sejarah dan psikologis tentang kehilangan masa lalu dan identitas ini disampaikan dengan gambaran tentang Rampokan, tradisi adu macan di Jawa. Bencanalah bagi negeri apabila macan, simbol kejahatan dan Belanda penjajah, bisa lolos.', 'Rp 159,000', '168 pages', '28 June 2023', 'Graphic Novel, History, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94134/623193003.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(373, '67822db779bd51cee772b4be', 'Bicara pada Kertas Putih', 'Kristin Samah', 'Self-Improvement', 'Bicara pada Kertas Putih adalah buku yang berisi kumpulan pengalaman orang-orang yang pernah mengalami kesepian, berada pada titik terendah kehidupannya.Seperti dipublikasikan The National Intelligence Council mengenai Global Trends 2040, More Contested World (Maret 2021), pandemi Covid-19 membawa pengaruh jangka panjang minimal sampai 2040 terhadap kesehatan jiwa. Gangguan kesehatan jiwa terutama terjadi di kalangan generasi muda usia 15 sampai 34 tahun.Nadir Podcast menyediakan ruang bicara bagi siapa saja yang ingin berbagi kisah dan pengalaman. Semua orang bisa bicara tanpa penghakiman. Sebab, setiap kisah adalah pembelajaran, semangat, dan motivasi untuk melanjutkan hidup dengan optimis dan gembira Buku ini mengupas dengan lebih mendalam sejarah, perkembangan, serta potensi masa depan berbagai produk fermentasi beras dan nira di Nusantara yang bisa kita jumpai dalam kehidupan sehari-hari, juga beberapa contoh minuman hasil fermentasi dari luar negeri.', 'Rp 128,000', '178 pages', '28 June 2023', 'nonfiksi, Self-Improvement, buku pengembangan diri', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94110/Bicara_Pada_Kertas_Putih_C-1+4.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(374, '67822ded79bd51cee772b4db', '7 Rahasia Berinvestasi ala Warren Buffett: Panduan Sederhana untuk Pemula', 'Mary Buffett,', 'Business & Economic', 'PANDUAN LENGKAP UNTUK INVESTOR PEMULA YANG INGIN MEMAHAMI CARA BERINVESTASI SEPERTI WARREN BUFFETTHasil yang berkelanjutan sering kali datang dari perubahan gaya hidup dan kebiasaan; karenanya, buku ini membahas kebiasaan yang perlu diadopsi seseorang untuk dapat berinvestasi seperti Warren Buffett, dan mempersiapkan kita untuk melakukan perjalanan seumur hidup dalam membangun kekayaan.Mary Buffett dan Sean Seah mendorong kita untuk mengikuti aturan pertama Warren Buffett dalam berinvestasi: “Jangan Pernah Rugi”, dan menjelaskan tiga langkah penting yang secara signifikan menurunkan risiko:• Pilih saham bagus dengan risiko rendah.• Beli saham saat harga bagus dengan margin keamanan.• Diversifikasi saham ke dalam beberapa keranjang.Buku ini juga dilengkapi kuesioner, bagan, dan grafik yang akan membantu menjelaskan teknik dan kebiasaan berinvestasi secara sederhana.', 'Rp 119,000', '258 pages', '21 June 2023', 'Bisnis, Business Management, Business, buku bisnis, Ekonomi, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94139/623203012.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(375, '67822e0079bd51cee772b4e5', 'Sukses Lewat Kongsi', 'Selly Fatmawati,', 'Self-Improvement,', 'Kongsi bisa menjadi salah satu jalan terbaik untuk memulai bisnis. Berkongsi saat memulai bisnis bisa sangat menjanjikan dan menghasilkan banyak keuntungan. Perusahaan besar seperti Google dan Apple bahkan dimulai dari kongsi.Jika kamu ingin memulai bisnis dan tertarik untuk menjalankan bisnis dengan berkongsi, buku ini sangat cocok untukmu. Buku ini menawarkan berbagai informasi mengenai bisnis kongsi, seperti:• Tahapan memulai bisnis kongsi• Cara membangun partnership yang baik• Tantangan dalam bisnis kongsi serta solusinya• Berbagai pengalaman dari para praktisi yang pernah menjalankan bisnis kongsiJadi tunggu apa lagi? Mantapkan dirimu untuk memulai bisnis kongsi yang kamu inginkan!', 'Rp 114,000', '96 pages', '21 June 2023', 'Bisnis, Ekonomi, Economic, Business, nonfiksi, Self Improvement, Self-Improvement, humaniora', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94149/623221031.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(376, '67822de779bd51cee772b4d8', 'Aku Bisa Fokus', 'Disney', 'Picture Books', 'Para keponakan Donald, Daisy, Mickey, dan Goofy mendapat tugas prakarya dari sekolah. Bukannya segera mengerjakan, mereka malah sibuk melakukan hal lain, misalnya bermain dan mencari camilan. Mereka tidak bisa fokus! Apa yang harus dilakukan Donald, Daisy, Mickey, dan Goofy?Dalam cerita ini, karakter-karakter klasik Disney akan berbagi cara menerapkan mindfulness, termasuk berlatih “pernapasan kelinci” agar anak tenang dan fokus pada apa yang sedang dikerjakan.', 'Rp 49,000', '24 pages', '21 June 2023', 'Anak-anak, Anak, Pictures Book, picture books, buku anak gramedia, Picture book, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94136/623110010.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(377, '67822e6b79bd51cee772b51f', 'Perihal Gendis (Cover 2023)', 'Sapardi Djoko Damono', 'Poetry', 'GENDIS:Oke, tapi siapa namamu? Aku suka nama yang kalau diucapkan menjelma percikan api menjelma makna menghangatkan malam.BURUNG:Tidak tahukah kau, Gendis, bahwa burung tidak memerlukan nama? Tidak tahukah kau sebabnya, Gendis? Nama selalu bergeser-geser tafsirnya kalau diucapkanPerihal Gendis adalah kumpulan puisi Sapardi Djoko Damono tentang seorang gadis yang beranjak dewasa dan mempertanyakan banyak hal di sekelilingnya. Kadang ia bercakap-cakap dengan mawar, burung, ulat, dan dirinya sendiri. Sebuah kumpulan puisi yang bisa mengajak pembaca untuk mengingat kembali arti rumah, keluarga, dan orang-orang terdekat kita.', 'Rp 69,000', '60 pages', '21 June 2023', 'sastra, Literary, Sapardi Djoko Damono, Puisi, buku puisi, Poetry', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94207/623202024.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(378, '67822da979bd51cee772b4b7', 'Kota Elemen, Kota untuk Semua Orang', 'Disney', 'Picture Books', 'Ember Lumen bekerja di toko milik keluarganya di Firetown. Suatu hari, ia menerima pesanan khusus yang mengharuskannya pergi ke Kota Elemen. Tapi ada satu masalah: Kota Elemen. Sebagai elemen Api, Ember merasa tidak cocok berada di kota sibuk—dan “mudah terbakar”—itu.Tetapi Ember siap untuk menghadapi tantangan dan petualangan. Ia menghadapi rintangan yang tidak terduga, bertemu teman lama dan baru, juga berhasil menemukan hal-hal menakjubkan dari Kota Elemen. Walaupun perjalanannya tidak mudah, Ember perlahan menyadari: mungkin ada tempat untuknya di Kota Elemen.', 'Rp 59,000', '36 pages', '21 June 2023', 'Picture book, Children, Childrens Books, Children Books, Children Book, buku anak gramedia, Buku anak, Literatures', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94103/623110007.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(379, '67822db379bd51cee772b4bc', 'Ngider Makan Dari Halte ke Halte', 'Dari Halte Ke Halte,', 'Graphic Novel,', 'Cukup dengan menyusuri halte-halte di Jakarta, ternyata kita bisa menikmati hidangan khas berbagai daerah di Nusantara.Berawal dari dua orang yang blusukan mencari makanan di sekitaran halte kemudian menceritakannya di akun Instagram @darihalte_kehalte, unggahan mereka lantas viral dan menjadi panduan warga Jakarta pengguna transportasi umum.Buku ini menampilkan beberapa tempat unik dan kadang tersembunyi di belantara kota Jakarta.Dengan ilustrasi menawan dari kelompok Jakarta Food Sketchers, serta dilengkapi peta lokasi, buku ini dapat dibawa-bawa sebagai panduan.Yuk ngider makan!', 'Rp 129,000', '160 pages', '21 June 2023', 'Graphic Novel, Novel Grafis, Reference, Pictures Book, Culinary, picture books, Picture book', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94108/623193002.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(380, '67822dad79bd51cee772b4b9', 'Nikel Indonesia: Kunci Perdagangan International', 'Elisa Sugito', 'Social Sciences', 'Kita sedang berada pada era perang dagang (trade war), di mana komoditas-komoditas krusial dunia diperebutkan oleh negara berkembang dan negara maju. Tak kalah mengejutkan, perang dagang yang terjadi antara Indonesia vs Uni Eropa (UE) patut diapresiasi sebagai keberanian Indonesia membela kepentingan nasional di kancah perdagangan internasional.Pada 22 November 2019, UE mengajukan konsultasi (gugatan) ke Dispute Settlement Body WTO atas kebijakan Indonesia terkait pelarangan ekspor bahan mentah nikel (DS 592). Pada tahun yang sama, tepatnya 9 Desember 2019, Indonesia membalas dengan menggugat UE atas kebijakan terkait RED II dan Delegated Act, atau sederhananya, Indonesia menentang kebijakan Uni Eropa yang melarang sawit (CPO) Indonesia masuk ke Benua Biru.Buku ini mengupas kasus pelarangan ekspor bijih nikel Indonesia dalam dimensi hukum perdagangan internasional serta implikasi politik dan ekonomi. Bagaimana sebenarnya negara-negara anggota WTO terikat dengan WTO Rules, tetapi masih mengabaikan, dan bahkan sering dengan sengaja memberikan pembatasan atau pelarangan ekspor/impor demi kepentingan nasionalnya.Nikel Indonesia: Kunci Perdagangan Internasional juga memberikan gambaran bagaimana nikel memiliki nilai penting dalam perdagangan global karena merupakan logam yang elastis, kuat, tahan korosi, sangat mudah dibentuk, memiliki titik lebur yang sangat tinggi, dan mudah dipadukan dengan logam lainnya. Selain itu, sifat magnetik dan kimianya bermanfaat bagi baterai kendaraan listrik. Nikel sangat menjanjikan bagi masa depan dunia yang eco-friendly dan rendah emisi.', 'Rp 275,000', '268 pages', '21 June 2023', 'Tambang, Sciences & Nature, Science & Nature, science, Social Science, Social Sciences, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94105/623222013.jpg', '2026-02-19 03:57:30', '2026-02-19 03:57:30'),
	(384, '678112251e0f1c11c617c934', 'TeenLit: Vision', 'Cindy Jessica', 'TeenLit', 'Amanda punya indra keenam. Kelihatannya keren ya? Kenyataannya, keluarga Amanda sempat khawatir dia bakal dicap aneh sama orang lain. Mereka berusaha supaya nggak ada yang tahu tentang kemampuan Amanda yang sering dapat penglihatan tak terduga. Apalagi, penglihatan itu selalu tentang orang lain, nggak satu pun tentang Amanda sendiri.Saat baru saja naik kelas XII, Amanda mulai mengenal Utha. Hidupnya jadi kayak permen asam manis. Cowok paling resek itu bikin Amanda mengalami banyak hal konyol. Mulai dari balas dendam ke mantan pacar yang selingkuh, dikejar Raden Inu Kertapati abal-abal, sampai ditangkap satpam bank gara-gara kelamaan mengadem di ATM.Pelan-pelan, Amanda menyadari bahwa dia menyukai Utha. Lalu tiba-tiba muncul penglihatan tentang masa depannya bersama Wira. Aduh, nggak mungkin kan dia menikah dengan pamannya Utha yang ganteng selangit itu?', 'Rp 73,000', '256 pages', '25 May 2022', 'Cindy Jessica, Remaja, teenlit, Titipo: Buku Mewarnai 1, Cindy Jessica, Remaja, teenlit, Titipo: Buku Mewarnai 1, Vision, Cindy Jessica, teenlit, Remaja', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93745/622150004.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(385, '678112271e0f1c11c617c935', 'Trilingual Thematic Smart Book (TTS) (English-Arabic-Indonesian) - Book 1', 'Edutivity', 'Activity Books', 'TTS (Trilingual Thematic Smart) Book adalah buku panduan bagi orangtua dalam mengenalkan kosakata bahasa asing (Inggris dan Arab) sejak dini kepada buah hati.TTS Book 1 dan TTS Book 2 berisi berbagai tema yang sangat dekat dengan kehidupan anak.TTS Book dapat digunakan untuk melatih dan mengajarkan kemampuan berbahasa asing, suatu keterampilan yang semakin diperlukan di zaman modern agar mampu bersaing di dunia global.TTS Book dikemas dengan sangat apik serta dilengkapi latihan yang menarik dan menyenangkan untuk buah hati tercinta di tahun-tahun pertama kehidupannya.', 'Rp 115,000', '148 pages', '25 May 2022', 'TTS, Trilingual Thematic Smart Book, Buku anak, TTS, Trilingual Thematic Smart Book, Buku anak, Trilingual Thematic Smart Book, TTS, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93746/622123006.jpg', '2026-02-19 05:07:39', '2026-04-22 08:21:39'),
	(387, '678112291e0f1c11c617c936', 'Trilingual Thematic Smart Book (TTS) (English-Arabic-Indonesian) - Book 2', 'Edutivity', 'Activity Books', 'TTS (Trilingual Thematic Smart) Book adalah buku panduan bagi orangtua dalam mengenalkan kosakata bahasa asing (Inggris dan Arab) sejak dini kepada buah hati.TTS Book 1 dan TTS Book 2 berisi berbagai tema yang sangat dekat dengan kehidupan anak.TTS Book dapat digunakan untuk melatih dan mengajarkan kemampuan berbahasa asing, suatu keterampilan yang semakin diperlukan di zaman modern agar mampu bersaing di dunia global.TTS Book dikemas dengan sangat apik serta dilengkapi latihan yang menarik dan menyenangkan untuk buah hati tercinta di tahun-tahun pertama kehidupannya.', 'Rp 115,000', '148 pages', '25 May 2022', 'TTS, A Man Called Ove, Buku anak, TTS, A Man Called Ove, Buku anak, Trilingual Thematic Smart Book, TTS, Buku anak', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93747/622123007.jpg', '2026-02-19 05:07:39', '2026-04-22 08:21:28'),
	(388, '678112361e0f1c11c617c93c', 'Epigram 60', 'Joko Pinurbo', 'Poetry', 'IBU KAMISaban malam ibu kami yang jelatamembersihkan pikiran anak-anaknyadari godaan kiat sukses dan kayadengan mudah, cepat, dan celaka.', 'Rp 66,000', '76 pages', '25 May 2022', 'Miles Kelly, Joko Pinurbo, Puisi, Miles Kelly, Joko Pinurbo, Puisi, Epigram 60, Joko Pinurbo, Puisi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93753/622202012.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(389, '6781129a1e0f1c11c617c96c', 'Baking At Home', 'Luvita Ho', 'Culinary', 'Yang terpenting dibalik kesuksesan seseorang adalah talent dan passion. Hal ini dibuktikan Luvita Ho, juara 1 MasterChef Season 4 tahun 2015 yang secara konsisten menapaki karier di dunia pastry. Sukses dengan usaha online, kini Luvita produktif sebagai youtube content creator.Buku Baking at Home-50 Resep Simpel & Antigagal ala Luvita Ho ini berisi resep andalannya yang terbagi atas 4 kategori yaitu: Roti Pastry & Choux, Cookies, Bolu & Cake, Dessert/No Bake, serta Pelengkap. Ada 50 resep favorit dan kekinian yang selalu dicari penikmat pastry seperti Garlic Twist Bread, Double Chocolate Bomboloni, Chocolate Choux au Craquelin, Almond Tart, Lidah Kucing Cokelat, Nanas Thumbprint, Bolu Ketan Pandan Keju, Cookies & Cream Ogura, Apple Crumble Muffin, Tres Leches Cake, Mini Baked Cheese Cake, Chocolate Panacotta, No Baked Coffee Cheese Cake, dan lainnya.Seperti Luvita Ho, ayo buktikan passion Anda dengan mempraktikkan resep simpel dan antigagal di buku ini.', 'Rp 118,000', '125 pages', '25 May 2022', 'Delicious Lips, Zulfairy, Baking at Home, Luvita Ho, Cooking, Culinary', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93801/622205017.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(390, '678112231e0f1c11c617c933', 'Love Your Life', 'Sophie Kinsella', 'Romance', 'Menurut Ava, cinta harus ditemukan di dunia nyata, bukannya pada filter aplikasi kencan yang mengatur tinggi cowok, pekerjaan, hobi, dan sebagainya. Ava memutuskan undur diri sejenak dari ingar bingar hidup serta cinta, lalu mengikuti retret menulis di tempat terpencil yang indah di Italia. Semua peserta memakai nama samaran dan tidak saling mengungkap kehidupan pribadi. Di sana, Ava yang memakai nama Aria bertemu cowok yang nyaris sempurna, Dutch, salah satu peserta retret bela diri yang dibatalkan dan masuk ke retret menulis.Mereka menjalin hubungan tanpa bawa-bawa masa lalu. Segalanya terasa tepat. Namun, Ava dan Matt harus kembali ke kehidupan nyata. Selagi fantasi memudar, mereka menyadari bahwa hidup mereka sangat bertolak belakang. Mulai dari perbedaan makanan kesukaan, kebiasaan yang menyebalkan, dan banyak hal lain yang nyatanya sulit ditoleransi. Belum lagi mantan pacar Matt yang masih “berkeliaran”. Ava sadar kehidupan memunculkan filternya sendiri. Walau mereka saling mencintai, tampaknya mereka tidak bisa saling mencintai kehidupan yang lain. Bisakah mereka bertahan? Ataukah lebih baik menyerah?', 'Rp 99,000', '400 pages', '18 May 2022', 'Trilingual Thematic Smart Book, Sophie Kinsella, Romance, Trilingual Thematic Smart Book, Sophie Kinsella, Romance, Love Your Life, Sophie Kinsella, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93744/622183001.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(391, '678112211e0f1c11c617c932', 'MetroPop: Harga Teman: Design, Resign, Redesign', 'Debora Danisa', 'MetroPop', 'Hanya gara-gara kesalahan kecil, Uji dipecat dari kantornya yang mentereng bahkan sebelum masa percobaannya selesai. Kini Uji tidak punya sumber pendapatan selain jasa desain lepas di Twitter. Masalahnya, permintaan klien kerap kali ajaib, mulai dari minta selesai satu malam sampai minta harga teman, padahal nggak kenal.Beruntung Uji punya dua teman yang suportif, Julian dan Boshi. Mengikuti jejak Uji, dua cowok tersebut keluar dari kantor mereka demi mengejar mimpi baru: buka usaha social media strategist bareng. Begitulah MercusuArt lahir.Namun, usaha ini mengundang masalah baru. Seperti biasa, banyak klien minta harga teman. Pertemanan mereka diuji karena buka usaha bareng menyebabkan mereka sering bergesekan. Pandemi membuat MercusuArt terancam layu sebelum berkembang. Belum lagi orangtua Uji kurang sreg melihat putri mereka tidak kerja kantoran.Akankah Uji terbebas dari jebakan harga teman sambil tetap mempertahankan persahabatannya?', 'Rp 107,000', '400 pages', '18 May 2022', 'Harga Teman Design Resign Redesign, Harga Teman, Debora Danisa, Love Your Life, Harga Teman Design Resign Redesign, Harga Teman, Debora Danisa, Love Your Life, Harga Teman Design Resign Redesign, Harga Teman, Debora Danisa', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93743/622171005.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(392, '678112181e0f1c11c617c92e', 'Aliansi Monyet Putih', 'Ramayda Akmal', 'Literary', '“Aku adalah orang asing yang belajar di sini. Meskipun aku bicara bahasa selancar mereka, bekerja dengan mereka, bercanda dan tertawa akan hal-hal yang juga lucu bagi mereka, aku tetap orang asing. Mereka yakin, orang asing selalu kesulitan menyesuaikan diri. Selalu berbicara dengan logat yang berwarna. Selaludimaklumi jika salah, atau bahkan selalu dianggap salah. Selalu mendapat nilai tambahan sebagai pemakluman karena nilai kami tidak bisa disamakan dengan nilai orang sini.”—Kisah-kisah dalam buku ini adalah potret para pendatang di Jerman. Mereka menghadapi kehidupan serbasulit dan tidak memiliki kesempatan berkompetisi secara adil. Di sisi lain, banyak juga yang kerap mendapatkan pemakluman sebab dianggap lemah dan warga kelas dua yang tidak menjadi masalah bila sesekali salah. Ketika dunia sudah tanpa pagar, mengapa kemanusiaan masih harus dipagari warna kulit, etnis, dan asal negara.', 'Rp 75,000', '132 pages', '18 May 2022', 'Aliansi Monyet Putih, Ramayda Akmal, Kumcer, sastra, Aliansi Monyet Putih, Ramayda Akmal, Kumcer, sastra, Aliansi Monyet Putih, Ramayda Akmal, Kumcer, sastra', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93739/622202008.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(393, '678112121e0f1c11c617c92b', 'Andromeda', 'Elnov', 'Self-Improvement', 'Andromeda merupakan sekuel trilogi #MemoarSeorangBipolar. Dalam buku ini, Elnov melanjutkan kisah nyata perjuangan hidupnya sebagai ODB (Orang dengan Bipolar), jatuh bangun melawan gangguan mental yang dialaminya. Dengan kejujuran dan kepiawaian menulis, Elnov makin dalam mengajak kita menyelami dua kutub konflik dalam dirinya. Tak sekadar merasakan ledakan kebahagiaan dan langit depresi yang kelam, Elnov seolah juga menggenggam tangan pembaca seraya menuntun terbang bertemu bintang-bintang. Terinspirasi dari legenda seorang putri Yunani yang juga digunakan sebagai penamaan salah satu rasi bintang, apakah Andromeda merupakan jawaban atas pertanyaan-pertanyaan Elnov tentang hidupnya? ***“Membaca Andromeda membuat kita belajar bahwa setiap jiwa pasti memiliki keunikan masing-masing. Apakah penjelasan kedokteran modern seharusnya lebih ilmiah dan lebih tepat mendeskripsikan kita? Ya. Ataukah penjelasan dunia spiritual lebih mampu menggambarkan secara penuh sekaligus menenangkan jiwa ini? Bisa jadi. Tidak perlu terlalu terobsesi mencari jawaban absolut karena mungkin malah perjalanan mencari jawaban itulah yang lebih penting. Semoga kisah perjalanan Elnov mampu menginspirasi jiwa-jiwa lain yang juga sedang mengembara.” —Nago Tejena, M.Psi., Psikolog“Kesehatan mental adalah suatu hal yang perlu diusahakan. Siapa pun, baik yang dianggap sehat secara mental maupun yang sedang berjuang dalam kondisi mentalnya, membutuhkan dukungan dari orang-orang terdekat dan lingkungan yang sehat untuk tumbuh. Pada sebagian kasus, memang dibutuhkan intervensi psikoterapi yang disesuaikan dengan kondisi tiap-tiap orang untuk mencapai kesejahteraan psikologisnya. Lewat tulisannya, izinkan Elnov membantu Anda yang sedang berjuang dalam masalah kesehatan mental untuk menyadari bahwa Anda mampu, bahwa Anda berharga, dan bahwa Anda pun bisa menginspirasi orang lain.” —Alexandra Gabriella A., M.Psi., Psikolog, C.Ht., C.ESt.', 'Rp 89,000', '264 pages', '18 May 2022', 'Self Improvement, Inspiration, Elnov, Berbantalkan Rumput, Self Improvement, Inspiration, Elnov, Berbantalkan Rumput, Self Improvement, Inspiration, Elnov, Andromeda', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93736/622221030.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(394, '678112101e0f1c11c617c92a', 'Merawat Luka Batin', 'dr. Jiemi Ardian, Sp.KJ', 'Self-Improvement', '“You are what you think,” begitu kata banyak orang. Padahal, ketika saya berpikir saya kaya, uang dalam rekening saya tidak otomatis bertambah. Akan lebih tepat jika kutipan ini sedikit diubah menjadi “You are how you think”, karena perasaan dan diri kita bergantung pada bagaimana cara kita berpikir.Buku ini berisi tentang proses berpikir, bukan sekadar berpikir dengan positif. Saat perasaan sedang tidak baik-baik saja, terlebih pada keadaan depresi, proses pikir kita biasanya ikut andil dalam memperburuk keadaan. Namun, sulit bagi kita untuk menyadari proses berpikir yang bermasalah ini karena kita menganggapnya sebagai cara kita melihat realitas. Menyadari pikiran yang keliru saat hal itu muncul bukanlah hal yang mudah.Buku ini memuat beberapa pola untuk membentuk cara berpikir yang tepat. Tak hanya orang-orang yang sedang merawat luka batin, para caregiver dan penyintas depresi juga bisa menarik manfaat dari buku ini. Semoga buku ini juga bisa menghapus stigma tentang depresi dan menunjukkan bahwa gangguan kejiwaan, termasuk depresi, bisa dialami siapa saja.dr. Jiemi Ardian, Sp.KJ menamatkan pendidikan kedokteran dan spesialis kedokteran jiwa di Universitas Sebelas Maret. Ia juga tersertifikasi sebagai pengajar Mindfulness Based Stress Reduction (MBSR) dan Mindfulness Based Cognitive Therapy (MBCT) dari Mindful Academy Solterreno, Spanyol dan Bangor University, Wales. Ia aktif di media sosial Instagram, Twitter, dan TikTok dengan nama @jiemiardian.', 'Rp 98,000', '326 pages', '18 May 2022', 'Personal Growth, Self Improvement', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93735/622221027.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(395, '6781121f1e0f1c11c617c931', 'Lavender', 'Luna Torashyngu', 'TeenLit', 'Kehidupan baru Joy yang tenang terusik saat dia harus menolong Samantha, sahabatnya saat masih menjadi pembunuh profesional. Mereka berdua berusaha melepaskan diri dari kejaran mafia Italia, suruhan seorang miliarder kaya dan pintar yang punya ambisi menguasai teknologi informasi di seluruh dunia. Bukan hanya itu, organisasi kejahatan yang dulu memberi perintah pada Samantha, sekarang malah berusaha melenyapkan gadis itu.Berusaha mengeluarkan sahabatnya dari kesulitan, Joy jadi ikut terlibat. Dia terpaksa kembali ke dunia lamanya untuk menyelamatkan nyawa banyak orang.Ini adalah cerita awal dari rangkaian Luna Story Universe Gen-2.', 'Rp 73,000', '256 pages', '18 May 2022', 'Lavender, Luna Torashyngu, Luna Story Universe, Lavender, Luna Torashyngu, Luna Story Universe, Lavender, Luna Torashyngu, Luna Story Universe', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93742/622150003.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(399, '678112141e0f1c11c617c92c', 'Menuju Zaman Renewable Energy', 'Cyrillus Harinowo Ph.D', 'Social Sciences', 'Dunia menghadapi babak baru dalam “perang” menghadapi pemanasan global yang berdampak pada perubahan iklim dan cuaca ekstrem. Lewat Perjanjian Paris yang berlangsung pada 2015, dunia sepakat untuk mulai mengurangi penggunaan sumber energi yang menghasilkan emisi gas rumah kaca serta mulai memanfaatkan energi baru dan terbarukan (renewable energy).Indonesia pun tidak mau ketinggalan. Sebagai salah satu negara yang meratifikasi Perjanjian Paris 2015, Indonesia juga tengah berjuang untuk bisa mengurangi emisi gas rumah kaca, terutama dari segi pembangkit listrik. Saat ini, Presiden Joko Widodo gencar mempromosikan pembangunan sumber-sumber pembangkit listrik yang berasal dari energi terbarukan, seperti Pembangkit Listrik Tenaga Angin (PLTA) dan Pembangkit Listrik Tenaga Bayu (PLTB) di seluruh pelosok negeri.Di sisi lain, penggunaan sumber energi baru dan terbarukan di seluruh dunia mendorong tumbuhnya industri-industri baru berbasis renewable energy. Industri mobil listrik dan baterai penyimpanan energi (energy storage system) menjadi bidang industri baru yang banyak diminati konsumen. Tesla, raksasa mobil listrik dari Amerika, telah membuat industri ini berkembang secara cepat dan masif.Indonesia punya potensi besar untuk menjadi raksasa baru dalam industri energi baru dan terbarukan. Sebab, Indonesia memiliki kandungan nikel—yang menjadi bahan baku utama dalam pengembangan industri mobil listrik dan baterai penyimpanan energi—terbesar di dunia.Rentetan perkembangan energi baru dan terbarukan di dunia, termasuk Indonesia, disulam dengan baik oleh Cyrillus Harinowo, Ph.D. dan Ika Maya Sari Khaidir, S.E., M.M. lewat Menuju Zaman Renewable Energy. Buku ini berusaha menjelaskan secara rinci keterkaitan antara tren penggunaan energi baru dan terbarukan di dunia, perkembangan industri mobil listrik dan energy storage system, dan prospek perekonomian Indonesia ke depan. Pada akhirnya, Menuju Zaman Renewable Energy adalah jawaban lengkap atas pertanyaan tentang kesiapan Indonesia menyongsong era baru pemanfaatan energi dan sumber daya alam.', 'Rp 89,000', '364 pages', '27 April 2022', 'Social Sciences, Grass for His Pillow, Lian Hearn, Social Sciences, Grass for His Pillow, Lian Hearn, Social Sciences, Manajemen, Energy', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93737/622222012.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(400, '678112161e0f1c11c617c92d', 'Cantik Tanpa Ketergantungan', 'Alberthiene Endah', 'Fashion & Beauty', 'Siapa di antara kita yang mengalami stres memikirkan kulit wajah? Bolak-balik ganti merek skin care karena merasa tak mendapatkan apa yang diharapkan. Kecewa pada klinik kecantikan. Depresi menatap kulit yang tak kunjung indah. Panik mendapati kulit rusak setelah menggunakan produk keras yang menjanjikan glowing seketika.Jangan putus asa. Kulit sehat dan indah bisa diraih dengan cara yang rasional dan proporsional. Boleh jadi di hari-hari kemarin cara yang dijalankan jauh dari ideal, tanpa disadari. Mulai sekarang bukalah lembaran baru merawat kesehatan kulit dengan aman dan nyaman. Tak perlu mempertaruhkan kesehatan kulit hanya karena ingin selekasnya jadi kinclong. Kulit punya rule sendiri yang perlu dimengerti.Buku ini membantu mencerahkan mindset kita menuju kulit cantik.', 'Rp 150,000', '200 pages', '27 April 2022', 'Buku Pertamaku Hewan, Klan Otor, Photography, Cosmetology, Art, Beauty, Alberthiene Endah', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/93738/622232005.jpg', '2026-02-19 05:07:39', '2026-02-19 05:07:39'),
	(401, '67822dcb79bd51cee772b4c9', 'Bilang Begini, Maksudnya Begitu (Cover 2023)', 'Sapardi Djoko Damono', 'Poetry', 'Puisi adalah hasil yang dicapai jika seseorang mampu bermain-main dengan bahasanya. Apa yang ditulis penyair tidak serta-merta bisa diartikan secara harfiah. Gerimis bukan berarti hujan, dan bunga belum tentu berarti kembang. Kerap penyair bilang begini, tapi maksudnya begitu. Lalu bagaimana caranya bisa menikmati puisi dan menangkap pesan atau makna yang ingin disampaikan oleh penyair?Buku ini bukan buku teori sastra tetapi semacam ajakan dari Sapardi Djoko Damono untuk mengapresiasi puisi dengan pengenalan akan sejumlah alat kebahasaan yang dimanfaatkan penyair untuk menyampaikan sesuatu yang bisa saja berupa cerita, gagasan, sikap, suasana, dan sebagainya. Sejumlah alat atau muslihat atau gaya yang biasa digunakan penyair dalam puisinya dijelaskan dengan menampilkan sejumlah contoh. Pemahaman atas alat-alat itu diharapkan bisa membantu tumbuhnya apresiasi dan kritik puisi yang lebih baik.', 'Rp 59,000', '142 pages', '05 April 2023', 'Puisi, buku puisi, sastra, Sapardi Djoko Damono, Literary, Poetry', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94121/623202015.jpg', '2026-02-19 05:11:12', '2026-02-19 05:11:12'),
	(402, '67822d1879bd51cee772b469', 'Cahaya Mentari Pagi', 'Maria A. Sardjono', 'Romance', 'Kunti yakin bahwa percintaannya dengan Hari akan berjalan mulus. Nyatanya, harus kandas di tengah jalan. Bahkan, Kunti terpaksa meninggalkan kuliahnya di fakultas kedokteran. Semua dilakukannya demi Hari, kekasih yang amat sangat dicintainya.Keduanya terpaksa menempuh hidup masing-masing, menikah dengan pasangan yang menjadi jodoh mereka. Namun, rupanya mereka sama-sama tak bahagia dalam ikatan itu. Kunti dikhianati suaminya saat ia tengah mengandung, sementara Hari “terjebak” menjadi suami dari perempuan yang obsesif dan menguasainya.Dengan membawa luka, Hari dan Kunti dipertemukan kembali oleh semesta. Mereka masih saling mencintai, tetapi keadaan sudah telanjur pelik. Mereka ragu apakah cinta itu dapat menjadi satu dalam pernikahan.', 'Rp 89,000', '280 pages', '29 March 2023', 'romance novel, novel roman, Novel, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94025/623172002.jpg', '2026-02-19 05:11:12', '2026-02-19 05:11:12'),
	(403, '67822d1079bd51cee772b465', 'Nikel Indonesia Menuju Transisi Energi', 'Prof. Dr. Ir. Irwandy Arif, M. Sc', 'Science & Nature', 'Dewasa ini, isu pemanasan global serta risiko yang mengikutinya memberikan kekhawatiran akan kelangsungan hidup di bumi pada masa depan. Menghentikan penggunaan energi fosil sebagai salah satu penyebab utama pemanasan global akibat emisi karbon yang dihasilkan digadang-gadang menjadi salah satu solusi konkret bersamaan dengan intensifikasi transisi menuju energi yang lebih bersih, baru, dan terbarukan (EBT).Di masa transisi energi seperti saat ini, nikel dianggap sebagai komoditas strategis karena kegunaan dan fleksibilitasnya untuk diaplikasikan pada berbagai produk yang berkaitan dengan industri masa depan, seperti paduan pada stainless steel, katoda baterai untuk industri electric vehicle (EV), komponen pada energy storage system (ESS), hingga paduan untuk superalloy pada industri yang membutuhkan resistansi terhadap temperatur tinggi. Sebagai pemilik cadangan serta produsen nikel nomor satu di dunia, Indonesia amat berpotensi menjadi pemain utama dalam pasar nikel dunia.Buku Nikel Indonesia Menuju Transisi Energi membahas nikel secara mendetail, mulai dari genesa, metode dan proses pertambangan, kebijakan-kebijakan yang berkaitan, hingga prospek hilirisasi dan pemanfaatan nikel sebagai green metals pada era transisi energi.', 'Rp 205,000', '520 pages', '29 March 2023', 'Sciences & Nature, Science & Nature, science, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94021/623220001.jpg', '2026-02-19 05:11:12', '2026-02-19 05:11:12'),
	(404, '67822d4779bd51cee772b482', 'Mommyclopedia: 234 Fakta tentang Masalah Makan pada Anak', 'Dr. dr. Meta Hanindita, Sp.A.(K)', 'Parenting & Family', '• Porsi makan anak saya sedikit sekali. Bagaimana saya tahu perkembangannya masih normal?• Bagaimana mengatasi anak yang picky eater?• Adakah vitamin atau suplemen penambah nafsu makan anak?• Bagaimana mengatasi anak yang kesulitan naik tekstur makanan?• Kapan bayi dapat diajarkan minum dari cangkir atau gelas?• Sepenting apa kursi makan anak?Salah satu masalah yang sering dikeluhkan para orangtua terkait pengasuhan anak adalah masalah makan. Masalah makan dapat meningkatkan risiko terjadinya malnutrisi pada anak. Buku ini akan membahas tuntas mengenai apa sebenarnya yang dimaksud dengan makan, bagaimana proses yang terjadi saat seorang anak sedang makan, apa tujuannya, apa penyebab masalah makan, hingga tips untuk mengatasi atau menghadapi anak yang susah makan.', 'Rp 89,000', '168 pages', '29 March 2023', 'Mommyclopedia, dr. Meta Hanindita, buku parenting, Parenting, nonfiksi', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94050/623214001.jpg', '2026-02-19 05:11:12', '2026-02-19 05:11:12'),
	(406, '67822d3679bd51cee772b479', 'Tempurung', 'Oka Rusmini', 'Literary ,', 'Ikatan pernikahan bukan semata mahligai berlabur kebahagiaan. Ia menyimpan rahasia dan kisah yang tidak hanya penuh kejutan, sesekali absurd, aneh, dan tidak masuk akal. Perempuan-perempuan dalam Tempurung terjebak dalam ikatan suci yang ganjil. Mereka berhadapan dengan kemerdekaan atas tubuhnya, persoalan agama, budaya, dan norma masyarakat. Perempuan-perempuan yang berhadapan dengan banyak ironi: mereka menginginkan ketenangan, anak, dan suami di tengah kejengahan institusi keluarga; mereka mencari cinta, kasih sayang di antara ambiguitas dan kegamangan hidup; mereka ingin merdeka menentunkan hidup dan impian di antara hal-hal yang membuatnya takut akan hidup itu sendiri.', 'Rp 132,000', '150 pages', '29 March 2023', 'sastra, Kumcer, Kumpulan cerita pendek', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94041/TEMPURUNG_1.jpeg', '2026-02-19 05:11:12', '2026-02-19 05:11:12'),
	(409, '67822d5d79bd51cee772b48e', 'S1ngle', 'Anna Narmina', 'Romance', 'Lupa sikat gigi sebelum ke dokter gigi? Duh, musibah banget, apalagi dokternya ganteng dan berlesung pipi kayak Dokter Edwin. Hancur sudah kesan pertama Ria di mata si dokter tampan!Bukan cuma pusing mikirin gigi, Ria juga dibuat senewen oleh keluarganya yang berlomba-lomba mencarikan dia blind date. Ria dituntut nikah, secepatnya! Dan entah jodoh, entah lelucon semesta, salah satu blind date-nya ternyata Dokter Edwin yang itu.Curhat dan minta tips pada Arga, sahabatnya yang playboy cap buaya, juga nggak membantu. Apakah akhirnya Ria bisa lepas dari status single tanpa membuat hatinya penuh tambalan seperti nasib giginya?', 'Rp 89,000', '232 pages', '30 March 2023', 'Romance Novels, romance novel, Romance', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94062/623171004.jpg', '2026-02-19 05:11:12', '2026-04-23 17:59:17'),
	(411, '67822d3d79bd51cee772b47d', 'Alien', 'Lee Chanhyuk', 'Picture Books', 'Ibuku bilang, aku ini alien. Aku dikirim ke Bumi karena kekuatan superku terlalu besar untuk planet asalku. Di sinilah seluruh kekuatan superku akan digunakan untuk menyelamatkan Bumi!Alien bercerita tentang anak istimewa yang tidak pernah kehilangan cahayanya. Buku ini layaknya mercusuar bagi semua anak untuk menjadi diri sendiri, mengarungi lautan, dan terus melaju dengan penuh percaya diri.', 'Rp 79,000', '36 pages', '29 March 2023', 'Children, Childrens Books, Children Books, Children Book, Pictures Book, picture books, Picture book', 'Gramedia Pustaka Utama', 'https://gpu.id/data-gpu/images/img-book/94045/623119001.jpg', '2026-02-19 05:11:12', '2026-04-29 05:46:32');
